class Offer(BaseModel):
    model_config = ConfigDict(extra="ignore")
    id: str = Field(default_factory=lambda: str(uuid.uuid4()))
    name: str
    price: float
    thumbnail: Optional[str] = ""
    videoUrl: Optional[str] = ""
    description: Optional[str] = ""
    keywords: Optional[str] = ""  # Mots-clés pour la recherche (invisible)
    visible: bool = True
    images: List[str] = []  # Support multi-images (max 5)
    # v159: Cours liés à cette offre (many-to-many)
    # Liste d'IDs de courses appartenant au MÊME coach_id (validation backend)
    # Si vide → l'offre accepte tous les cours du coach (backward compat)
    # Si rempli → seuls ces cours sont proposés quand on clique l'offre
    linked_course_ids: List[str] = []
    # v159: Position d'affichage (drag & drop reorder) — plus petit = plus haut
    position: Optional[int] = None
    # E-commerce fields
    category: Optional[str] = ""  # Ex: "service", "tshirt", "shoes", "supplement"
    isProduct: bool = False  # True = physical product, False = service/course
    variants: Optional[dict] = None  # { sizes: ["S","M","L"], colors: ["Noir","Blanc"], weights: ["0.5kg","1kg"] }
    tva: float = 0.0  # TVA percentage
    shippingCost: float = 0.0  # Frais de port
    stock: int = -1  # -1 = unlimited
    # V224: metadonnees d'activite affichees sur les cartes publiques.
    # Chaque ligne se masque cote client quand sa valeur est absente.
    duration_minutes: Optional[int] = None
    location: Optional[str] = ""
    max_participants: Optional[int] = None
    coach_id: Optional[str] = None  # v19: Ownership — email du coach propriétaire
    # v59: Durée de validité & prolongation automatique
    duration_value: Optional[int] = None  # ex: 2 (nombre)
    duration_unit: Optional[str] = None   # "days", "weeks", "months"
    is_auto_prolong: bool = True          # prolongation automatique à l'expiration
    created_at: Optional[str] = None      # ISO datetime de création
    expiration_date: Optional[str] = None # ISO datetime d'expiration calculée
    last_reminded_date: Optional[str] = None   # date dernier rappel J-7
    last_prolonged_date: Optional[str] = None  # date dernière prolongation
    # v132: Compte à rebours
    countdown_enabled: bool = False
    countdown_date: Optional[str] = None
    countdown_time: Optional[str] = None
    countdown_text: Optional[str] = None
    # V223: Prix progressif 3 paliers — référence temporelle = countdown_date
    progressive_pricing: bool = False
    price_early_bird: Optional[float] = None
    price_standard: Optional[float] = None
    price_last_minute: Optional[float] = None
    early_bird_days_before: int = 7
    standard_hours_before: int = 24
    # V223: Pack de crédits (remplace la déduction par regex sur le nom produit)
    pack_sessions: Optional[int] = None
    # V225: libelles personnalises des paliers. Obligatoirement symetrique entre
    # Offer et OfferCreate : PUT /offers fait `$set: offer.model_dump()` sur
    # OfferCreate en extra="ignore", donc un champ absent ici serait efface en
    # base a chaque sauvegarde d'offre.
    label_early_bird: Optional[str] = None
    label_standard: Optional[str] = None
    label_last_minute: Optional[str] = None
    # V223: Calculés à la lecture. DOIVENT être déclarés ici, sinon le
    # response_model=List[Offer] de GET /offers les filtrerait silencieusement.
    active_price: Optional[float] = None
    active_tier: Optional[str] = None
    # V252: prochaine date de cours liee a l'offre, calculee a la lecture
    # (idem : a declarer ici sinon filtree par le response_model).
    next_date: Optional[str] = None        # ISO datetime de la prochaine occurrence
    next_date_label: Optional[str] = None  # libelle court FR pret a afficher
    # V256: lien vers un site partenaire, affiche en bouton secondaire sur la
    # carte publique. Meme regle de symetrie que les libelles de paliers
    # ci-dessus : ces trois champs DOIVENT exister a l'identique dans
    # OfferCreate, sinon le `$set: offer.model_dump()` de PUT /offers les
    # effacerait a chaque sauvegarde d'offre.
    external_link_url: Optional[str] = None
    external_link_label: Optional[str] = None
    external_link_enabled: bool = False
    # V260: prix a payer quand le client REFUSE de faire la preuve sociale.
    # N'a de sens que sur une offre a 0 CHF : `price == 0` + ce champ > 0 =
    # l'offre propose le choix « gratuit contre preuve » ou « payer ce prix ».
    # None ou 0 => comportement inchange (gratuit direct, ou payant normal).
    social_proof_price: Optional[float] = None

class OfferCreate(BaseModel):
    model_config = ConfigDict(extra="ignore")
    name: str
    price: float
    thumbnail: Optional[str] = ""
    videoUrl: Optional[str] = ""
    description: Optional[str] = ""
    keywords: Optional[str] = ""  # Mots-clés pour la recherche
    visible: bool = True
