    isProduct: bool = False
    variants: Optional[dict] = None
    tva: float = 0.0
    shippingCost: float = 0.0
    stock: int = -1
    # V224: obligatoirement symetrique avec Offer. PUT /offers fait
    # `$set: offer.model_dump()` sur ce modele en extra="ignore" : un champ
    # absent ici est efface en base a chaque sauvegarde d'offre.
    duration_minutes: Optional[int] = None
    location: Optional[str] = ""
    max_participants: Optional[int] = None
    # V223: Prix progressif 3 paliers
    progressive_pricing: bool = False
    price_early_bird: Optional[float] = None
    price_standard: Optional[float] = None
    price_last_minute: Optional[float] = None
    early_bird_days_before: int = 7
    standard_hours_before: int = 24
    pack_sessions: Optional[int] = None
    # V225: libelles personnalises des paliers. Obligatoirement symetrique entre
    # Offer et OfferCreate : PUT /offers fait `$set: offer.model_dump()` sur
    # OfferCreate en extra="ignore", donc un champ absent ici serait efface en
    # base a chaque sauvegarde d'offre.
    label_early_bird: Optional[str] = None
    label_standard: Optional[str] = None
    label_last_minute: Optional[str] = None
    coach_id: Optional[str] = None  # v19: Ownership
    # v61: Durée de validité — accepte int ou string pour tolérance frontend
    duration_value: Optional[Union[int, str]] = None
    duration_unit: Optional[str] = None
    is_auto_prolong: Union[bool, str] = True
    # v132: Compte à rebours
    countdown_enabled: Union[bool, str] = False
    countdown_date: Optional[str] = None
    countdown_time: Optional[str] = None
    countdown_text: Optional[str] = None
    # V256: lien partenaire (voir le commentaire de symetrie dans Offer).
    # `Union[bool, str]` pour le toggle, comme countdown_enabled juste au-dessus :
    # le frontend peut envoyer "true"/"false" en chaine selon le controle utilise.
    external_link_url: Optional[str] = None
    external_link_label: Optional[str] = None
    external_link_enabled: Union[bool, str] = False
    # V260: prix alternatif sans preuve sociale. DOIT figurer ici aussi, sinon
    # le `$set: offer.model_dump()` de PUT /offers l'effacerait a chaque
    # sauvegarde d'offre (meme piege que les libelles de paliers, V225).
    social_proof_price: Optional[float] = None

