# === FONCTION UTILITAIRE: Formatage unifie des messages ===
def format_message_for_frontend(m: dict) -> dict:
    """Convertit un message MongoDB vers le format attendu par le frontend."""
    return {
        "id": m.get("id"), "type": "user" if m.get("sender_type") == "user" else ("coach" if m.get("sender_type") == "coach" else "ai"),
        "text": m.get("content", "") or m.get("text", ""), "sender": (m.get("sender_name") or m.get("sender", "")).replace("💪 ", ""),
        "senderId": m.get("sender_id") or m.get("senderId", ""), "sender_type": m.get("sender_type", "ai"),
        "created_at": m.get("created_at"), "media_url": m.get("media_url"), "media_type": m.get("media_type"),
        # V352 : l'echeance part au client pour qu'il affiche le compte a rebours,
        # et `media_expired` pour qu'il dise « Media expire » plutot que rien.
        "media_expires_at": m.get("media_expires_at"), "media_expired": bool(m.get("media_expired")),
        "cta_type": m.get("cta_type"), "cta_text": m.get("cta_text"), "cta_link": m.get("cta_link"),
        "broadcast": m.get("broadcast", False), "scheduled": m.get("scheduled", False)
    }

# ROUTES
@api_router.get("/")
async def root():
    return {"message": "Afroboost API"}

@api_router.get("/courses", response_model=List[Course])
async def get_courses(request: Request, scope: str = ""):
    # V237 — meme opt-in `?scope=mine` que /offers, et pour la meme raison :
    # cet endpoint sert aussi bien la vitrine publique que le dashboard.
    base_filter = {"archived": {"$ne": True}}
    if scope == "mine":
        caller_email = request.headers.get("x-user-email", "").strip().lower()
        if is_super_admin(caller_email):
            scoped_filter = dict(base_filter)
        elif caller_email:
            scoped_filter = dict(base_filter)
            scoped_filter["coach_id"] = caller_email
        else:
            return []
        courses_scoped = await db.courses.find(scoped_filter, {"_id": 0}).to_list(100)
        # Meme normalisation `location` que le chemin public ci-dessous, a
        # l'identique : le frontend lit ce champ, et une regle differente ici
        # ferait diverger l'affichage du dashboard de celui de la vitrine.
        out = []
        for course in courses_scoped:
            course_copy = dict(course)
            if "locationName" in course_copy:
                course_copy["location"] = course_copy["locationName"]
            out.append(course_copy)
        return out

    courses_raw = await db.courses.find(base_filter, {"_id": 0}).to_list(100)
    if not courses_raw:
        # V241: meme correctif que pour les offres par defaut — sans `coach_id`
        # ces cours amorces seraient invisibles a tout coach.
        _seed_owner_c = SUPER_ADMIN_EMAILS[0]
        default_courses = [
            {"id": str(uuid.uuid4()), "name": "Afroboost Silent – Session Cardio", "weekday": 3, "time": "18:30", "locationName": "Rue des Vallangines 97, Neuchâtel", "mapsUrl": "", "coach_id": _seed_owner_c},
            {"id": str(uuid.uuid4()), "name": "Afroboost Silent – Sunday Vibes", "weekday": 0, "time": "18:30", "locationName": "Rue des Vallangines 97, Neuchâtel", "mapsUrl": "", "coach_id": _seed_owner_c}
        ]
        await db.courses.insert_many(default_courses)
        courses_raw = default_courses
    
    # === FIX: Ajouter "location" comme alias de "locationName" pour le frontend ===
    # Créer une copie des cours pour ajouter le champ location
    courses = []
    for course in courses_raw:
        course_copy = dict(course)
        if "locationName" in course_copy:
            course_copy["location"] = course_copy["locationName"]
        courses.append(course_copy)
    
    return courses

@api_router.post("/courses", response_model=Course)
async def create_course(course: CourseCreate, request: Request):
    # Sécurité : vérifier que l'utilisateur est authentifié
    require_auth(request)
    # v19: Auto-set coach_id depuis le header d'authentification
    user_email = request.headers.get("X-User-Email", "").lower().strip()
    course_data = course.model_dump()
    if user_email and not course_data.get("coach_id"):
        course_data["coach_id"] = user_email
    course_obj = Course(**course_data)
    await db.courses.insert_one(course_obj.model_dump())
    return course_obj

@api_router.put("/courses/{course_id}")
async def update_course(course_id: str, course_update: dict, request: Request):
    """Update a course - supports partial updates including playlist and audio_tracks"""
    # Sécurité : vérifier que l'utilisateur est authentifié
    require_auth(request)
    # Récupérer le cours existant
    existing = await db.courses.find_one({"id": course_id}, {"_id": 0})
    if not existing:
        raise HTTPException(status_code=404, detail="Cours non trouvé")
    
    # Fusionner les données (mise à jour partielle)
    update_data = {k: v for k, v in course_update.items() if v is not None}
    
    await db.courses.update_one({"id": course_id}, {"$set": update_data})
    updated = await db.courses.find_one({"id": course_id}, {"_id": 0})
    return updated

@api_router.put("/courses/{course_id}/archive")
async def archive_course(course_id: str, request: Request):
    """Archive a course instead of deleting it"""
    # Sécurité : vérifier que l'utilisateur est authentifié
    require_auth(request)
    await db.courses.update_one({"id": course_id}, {"$set": {"archived": True}})
    updated = await db.courses.find_one({"id": course_id}, {"_id": 0})
    return {"success": True, "course": updated}

@api_router.delete("/courses/{course_id}")
async def delete_course(course_id: str, request: Request):
    """
    HARD DELETE - Supprime PHYSIQUEMENT un cours de toutes les tables.
    Aucune trace ne doit rester dans la base de données.
    """
    # Sécurité : vérifier que l'utilisateur est authentifié
    require_auth(request)
    deleted_counts = {
        "course": 0,
        "reservations": 0,
        "sessions": 0
    }
    
    # 1. Supprimer le cours (y compris les archivés)
    result = await db.courses.delete_one({"id": course_id})
    deleted_counts["course"] = result.deleted_count
    
    # 2. Supprimer TOUTES les réservations liées à ce cours
    result = await db.reservations.delete_many({"courseId": course_id})
    deleted_counts["reservations"] = result.deleted_count
    
    # 3. Supprimer les sessions/références potentielles liées au cours
    # (au cas où des sessions de chat sont liées à un cours spécifique)
    result = await db.chat_sessions.delete_many({"courseId": course_id})
    deleted_counts["sessions"] = result.deleted_count
    
    total_deleted = sum(deleted_counts.values())
    logger.info(f"[HARD DELETE] Cours {course_id} - Supprimé: cours={deleted_counts['course']}, réservations={deleted_counts['reservations']}, sessions={deleted_counts['sessions']}")
    
    # 4. ÉMETTRE UN ÉVÉNEMENT SOCKET.IO pour synchronisation temps réel
    # Socket.IO désactivé en mode Vercel Serverless
    logger.debug(f"[SOCKET.IO] Événement course_deleted (disabled in Vercel Serverless) pour {course_id}")
    
    return {
        "success": True, 
        "hardDelete": True,
        "deleted": deleted_counts,
        "total": total_deleted
    }

@api_router.delete("/courses/purge/archived")
async def purge_archived_courses(request: Request):
    """
    PURGE TOTAL - Supprime tous les cours archivés et leurs données liées.
    Utilisé pour nettoyer la base de données des cours obsolètes.
    """
    # Sécurité : vérifier que l'utilisateur est authentifié
    require_auth(request)
    # Trouver tous les cours archivés
    archived_courses = await db.courses.find({"archived": True}, {"id": 1}).to_list(1000)
    archived_ids = [c["id"] for c in archived_courses]
    
    if not archived_ids:
        return {"success": True, "message": "Aucun cours archivé à purger", "purged": 0}
    
    # Supprimer les cours archivés
    deleted_courses = await db.courses.delete_many({"archived": True})
    
    # Supprimer les réservations liées
    deleted_reservations = await db.reservations.delete_many({"courseId": {"$in": archived_ids}})
    
    logger.info(f"[PURGE] Supprimé {deleted_courses.deleted_count} cours archivés et {deleted_reservations.deleted_count} réservations")
    
    # Émettre un événement pour rafraîchir tous les clients
    # Socket.IO désactivé en mode Vercel Serverless
    logger.debug(f"[SOCKET.IO] Événement courses_purged (disabled in Vercel Serverless)")
    
    return {
        "success": True,
        "purgedCourses": deleted_courses.deleted_count,
        "purgedReservations": deleted_reservations.deleted_count,
        "purgedIds": archived_ids
    }

# --- v59: Helper calcul date expiration ---
def calculate_expiration_date(from_date_str: str, duration_value: int, duration_unit: str) -> str:
    """Calcule la date d'expiration à partir d'une date + durée"""
    from_date = datetime.fromisoformat(from_date_str.replace('Z', '+00:00')) if isinstance(from_date_str, str) else from_date_str
    if duration_unit == "months":
        delta = timedelta(days=duration_value * 30)
    elif duration_unit == "weeks":
        delta = timedelta(weeks=duration_value)
    elif duration_unit == "days":
        delta = timedelta(days=duration_value)
    else:
        return None
    return (from_date + delta).isoformat()

# --- Offers ---
# V223: enrichit une liste d'offres avec le prix actif calculé à la lecture
# (évite une requête /active-price supplémentaire par carte côté frontend).
def _enrich_offers_with_active_price(offers_list):
    for _o in offers_list:
        _p = compute_active_price(_o)
        _o["active_price"] = _p["price"]
        _o["active_tier"] = _p["tier"]
    return offers_list

_V252_MONTHS_FR = ["janv.", "fevr.", "mars", "avr.", "mai", "juin",
                   "juil.", "aout", "sept.", "oct.", "nov.", "dec."]

async def _enrich_offers_with_next_date(offers_list):
    """V252 FIX 3 : pose `next_date` / `next_date_label` sur chaque offre a partir
    de la prochaine occurrence de ses cours LIES (`linked_course_ids`).

    Non-bloquant : toute erreur laisse simplement l'offre sans next_date (la carte
    vitrine masque la ligne quand le champ est absent). Une seule requete DB pour
    tous les cours de toutes les offres, puis calcul en memoire — pas de N+1.
    Seules les offres a cours lies sont enrichies : sans lien, « prochaine date »
    n'a pas de sens univoque (tous les cours du coach) et resterait ambigu.
    """
    try:
        all_ids = []
        for _o in offers_list:
            for _cid in (_o.get("linked_course_ids") or []):
                if _cid and _cid not in all_ids:
                    all_ids.append(_cid)
        if not all_ids:
            return offers_list
        rows = await db.courses.find({"id": {"$in": all_ids}}, {"_id": 0}).to_list(500)
        by_id = {r.get("id"): r for r in rows}
        for _o in offers_list:
            try:
                occ = []
                for _cid in (_o.get("linked_course_ids") or []):
                    c = by_id.get(_cid)
                    if c:
                        occ.extend(_v184_next_occurrences(c, days_ahead=60))
                if not occ:
                    continue
                occ.sort(key=lambda x: x.get("datetime", ""))
                nxt = occ[0]
                _o["next_date"] = nxt.get("datetime")
                try:
                    _dt = datetime.fromisoformat(nxt["datetime"])
                    _o["next_date_label"] = "%s. %d %s" % (
                        _V184_WEEKDAY_LABELS_FR[_dt.weekday()][:3], _dt.day,
                        _V252_MONTHS_FR[_dt.month - 1])
                except Exception:
                    _o["next_date_label"] = nxt.get("weekday_label") or ""
            except Exception:
                continue
    except Exception as _e:
        logger.info(f"[V252] next_date enrichment skipped: {_e}")
    return offers_list

@api_router.get("/sessions/agenda")
async def sessions_agenda(days: int = 60):
    """Agenda public : les occurrences qu'un visiteur peut voir et reserver.

    UNE SEULE SOURCE D'HORAIRES. Le calendrier ne recalcule rien de son cote et
    ne relit surtout pas ce qui est affiche sur les cartes d'offres : il
    consomme les MEMES documents `courses`, via le MEME
    `_v184_next_occurrences` que `_enrich_offers_with_next_date`. Changer le
    jour d'un cours change donc les cartes, « prochaine seance » et le
    calendrier au meme instant, par construction, sans aucune resaisie.

    UNE SEANCE N'APPARAIT QUE SI LE VISITEUR PEUT Y ACCEDER. La condition
    NECESSAIRE est donc qu'au moins une offre PUBLIQUE y mene. Sessions decrit
    les activites reellement accessibles, pas un panneau d'affichage : montrer
    une seance que personne ne peut reserver serait une impasse, et les offres
    masquees ne doivent jamais fuir par ce biais.

    Cette condition ne suffit pas seule. Le cours doit en plus etre, SOIT

      1. publie — `visible` vrai et non archive ; SOIT

      2. marque `agenda_abonne`. C'est la regle V426, deja ecrite pour l'espace
         abonne (`_v426_recurrents_de_loffre`) : une activite recurrente
         rattachee a un forfait reste a l'agenda meme si elle est archivee.
         C'est exactement le cas des seances du mercredi et du dimanche, et
         c'est pourquoi les cartes d'offres annoncent deja leurs horaires alors
         que `GET /courses`, qui filtre `archived`, les ignore. Sans ce second
         terme, le calendrier contredirait les cartes.

    Une occurrence n'apparait QU'UNE FOIS, meme si plusieurs offres y donnent
    acces : la cle est (cours, instant), jamais l'offre. Les offres qui
    l'ouvrent sont listees a cote, pour que l'ecran sache quoi proposer.
    """
    try:
        _jours = max(1, min(int(days), 180))
    except (TypeError, ValueError):
        _jours = 60
    try:
        _offres = await db.offers.find(
            {"visible": {"$ne": False}},
            {"_id": 0, "id": 1, "name": 1, "linked_course_ids": 1}).to_list(200)
    except Exception as _e:
        logger.warning("[AGENDA] offres illisibles : %s", _e)
        _offres = []

    _lies = []
    _offres_par_cours = {}
    for _o in _offres:
        for _cid in (_o.get("linked_course_ids") or []):
            if not _cid:
                continue
            if _cid not in _lies:
                _lies.append(_cid)
            _offres_par_cours.setdefault(_cid, []).append(
                {"id": _o.get("id"), "name": _o.get("name")})

    if not _lies:
        return {"occurrences": [], "jours": _jours}
    _filtre = {"id": {"$in": _lies}, "$or": [
        {"visible": {"$ne": False}, "archived": {"$ne": True}},
        {"agenda_abonne": True},
    ]}
    try:
        _cours = await db.courses.find(_filtre, {"_id": 0}).to_list(300)
    except Exception as _e:
        logger.warning("[AGENDA] cours illisibles : %s", _e)
        return {"occurrences": [], "jours": _jours}

    _vues = set()
    _sorties = []
    for _c in _cours:
        for _occ in _v184_next_occurrences(_c, days_ahead=_jours):
            _cle = (_occ.get("course_id"), _occ.get("datetime"))
            if _cle in _vues:
                continue
            _vues.add(_cle)
            _occ["offers"] = _offres_par_cours.get(_c.get("id"), [])
            _occ["recurrent"] = not bool(_c.get("date"))
            _sorties.append(_occ)
    _sorties.sort(key=lambda x: x.get("datetime") or "")
    return {"occurrences": _sorties, "jours": _jours}


@api_router.get("/offers", response_model=List[Offer])
async def get_offers(request: Request, scope: str = ""):
    # V237 — isolation par coach, en OPT-IN explicite (`?scope=mine`).
    #
    # POURQUOI PAS LA SEULE PRESENCE DU HEADER
    # Cet endpoint sert la vitrine publique (App.js ~l.4515) ET le dashboard
    # coach (CoachDashboard.js ~l.1536). Or l'intercepteur axios global
    # (App.js l.5-24) ajoute `X-User-Email` a TOUTE requete des qu'un coach est
    # connecte, et la vitrine ne refiltre rien cote client. Filtrer sur la
    # presence du header ferait donc disparaitre de la vitrine les offres de
    # tous les autres coachs — pour le coach connecte seulement, ce qui est
    # exactement le genre de bug qu'on ne reproduit pas en navigation privee.
    #
    # Sans `scope=mine`, le comportement est donc STRICTEMENT celui d'avant.
    if scope == "mine":
        caller_email = request.headers.get("x-user-email", "").strip().lower()
        # Admin : voit tout. Coach : ses offres. Pas d'email : rien plutot que
        # tout — demander explicitement « les miennes » sans etre identifie ne
        # doit pas retourner le catalogue entier.
        if is_super_admin(caller_email):
            query = {}
        elif caller_email:
            query = {"coach_id": caller_email}
        else:
            return []
        scoped = await db.offers.find(query, {"_id": 0}).to_list(100)
        return await _enrich_offers_with_next_date(_enrich_offers_with_active_price(scoped))

    offers = await db.offers.find({}, {"_id": 0}).to_list(100)
    if not offers:
        # V241: `coach_id` pose des la creation. Ce bloc d'amorcage s'execute sur
        # un GET (potentiellement anonyme, sans header) quand la collection est
        # vide : il ne peut donc pas deduire de proprietaire. Sans cette ligne il
        # produisait des offres a `coach_id: null`, invisibles a tout coach une
        # fois l'isolation V237 active — exactement le defaut que V238 avait du
        # rattraper a la main.
        # SUPER_ADMIN_EMAILS[0] plutot que DEFAULT_COACH_ID : ce dernier
        # (`bassi_default`) n'est l'email d'aucun compte, donc invisible partout.
        _seed_owner = SUPER_ADMIN_EMAILS[0]
        default_offers = [
            {"id": str(uuid.uuid4()), "name": "Cours à l'unité", "price": 30, "thumbnail": "", "videoUrl": "", "description": "", "visible": True, "coach_id": _seed_owner},
            {"id": str(uuid.uuid4()), "name": "Carte 10 cours", "price": 150, "thumbnail": "", "videoUrl": "", "description": "", "visible": True, "coach_id": _seed_owner},
            {"id": str(uuid.uuid4()), "name": "Abonnement 1 mois", "price": 109, "thumbnail": "", "videoUrl": "", "description": "", "visible": True, "coach_id": _seed_owner}
        ]
        await db.offers.insert_many(default_offers)
        return _enrich_offers_with_active_price(default_offers)  # V223
    return await _enrich_offers_with_next_date(_enrich_offers_with_active_price(offers))  # V223 + V252

# V223: Prix actif d'une offre — utilisé par la page activité
@api_router.get("/offers/{offer_id}/active-price")
async def get_offer_active_price(offer_id: str):
    offer = await db.offers.find_one({"id": offer_id}, {"_id": 0})
    if not offer:
        raise HTTPException(status_code=404, detail="Offre introuvable")
    return compute_active_price(offer)

def _v256_normalize_external_link(data: dict) -> None:
    """V256: normalise le lien partenaire d'une offre, EN PLACE.

    GARDE XSS — c'est la raison d'etre de cette fonction. L'URL est saisie a la
    main par le coach dans le wizard, puis rendue en `href` sur la carte
    PUBLIQUE. Une valeur `javascript:...` y serait executable par n'importe quel
    visiteur. On n'accepte donc que http(s) ; toute autre valeur desactive le
    lien plutot que d'etre stockee. Meme regle que le garde-fou deja applique a
    `mapsUrl` cote client (App.js, V225).

    Normalise aussi le toggle en vrai booleen (le frontend peut envoyer la
    chaine "true"/"false", cf. `Union[bool, str]` dans OfferCreate) et coupe les
    espaces. Un lien active sans URL exploitable est ramene a desactive : la
    carte n'affichera jamais un bouton qui ne mene nulle part.
    """
    raw_url = data.get("external_link_url")
    url = raw_url.strip() if isinstance(raw_url, str) else ""
    # `startswith` et non une regex : `re` n'est pas importe au niveau module
    # dans ce fichier (il l'est localement dans chaque fonction qui s'en sert).
    if not url.lower().startswith(("http://", "https://")):
        url = ""
    raw_label = data.get("external_link_label")
    label = raw_label.strip() if isinstance(raw_label, str) else ""
    enabled = data.get("external_link_enabled")
    enabled = enabled not in (False, "false", "0", 0, None, "")
    data["external_link_url"] = url or None
    data["external_link_label"] = label or None
    data["external_link_enabled"] = bool(enabled and url)


@api_router.post("/offers", response_model=Offer)
async def create_offer(offer: OfferCreate, request: Request):
    require_auth(request)
    user_email = request.headers.get("X-User-Email", "").lower().strip()
    offer_data = offer.model_dump()
    # v61: Blindage conversion durée — accepte string, int, vide, null
    raw_dv = offer_data.get("duration_value")
    if raw_dv is not None and raw_dv != "" and raw_dv is not False:
        try:
            offer_data["duration_value"] = int(raw_dv)
        except (ValueError, TypeError):
            offer_data["duration_value"] = None
    else:
        offer_data["duration_value"] = None
    if not offer_data.get("duration_unit") or offer_data["duration_unit"] == "":
        offer_data["duration_unit"] = None
    # Normaliser is_auto_prolong
    iap = offer_data.get("is_auto_prolong")
    offer_data["is_auto_prolong"] = iap not in (False, "false", "0", 0, None)
    # V256: lien partenaire — garde XSS + normalisation du toggle
    _v256_normalize_external_link(offer_data)
    print(f"[V61 DEBUG] POST /offers duration_value={offer_data.get('duration_value')} duration_unit={offer_data.get('duration_unit')} is_auto_prolong={offer_data.get('is_auto_prolong')}")
    if user_email and not offer_data.get("coach_id"):
        offer_data["coach_id"] = user_email
    # v59: Calculer expiration si durée définie
    now_iso = datetime.utcnow().isoformat()
    offer_data["created_at"] = now_iso
    if offer_data.get("duration_value") and offer_data.get("duration_unit"):
        offer_data["expiration_date"] = calculate_expiration_date(now_iso, offer_data["duration_value"], offer_data["duration_unit"])
    # v159: Validation linked_course_ids — doivent appartenir au même coach_id
    linked_ids = offer_data.get("linked_course_ids") or []
    if linked_ids:
        offer_coach_id = offer_data.get("coach_id")
        # Ne garder que les IDs de cours appartenant au même coach_id
        valid_courses = await db.courses.find(
            {"id": {"$in": linked_ids}, "coach_id": offer_coach_id},
            {"_id": 0, "id": 1}
        ).to_list(length=500)
        valid_ids = {c["id"] for c in valid_courses}
        offer_data["linked_course_ids"] = [cid for cid in linked_ids if cid in valid_ids]
        if len(offer_data["linked_course_ids"]) != len(linked_ids):
            logger.warning(f"[OFFER] v159: Filtré {len(linked_ids) - len(offer_data['linked_course_ids'])} cours non-autorisés (isolation coach_id)")
    offer_obj = Offer(**offer_data)
    await db.offers.insert_one(offer_obj.model_dump())
    return offer_obj

@api_router.put("/offers/{offer_id}", response_model=Offer)
async def update_offer(offer_id: str, offer: OfferCreate, request: Request):
    require_auth(request)
    update_data = offer.model_dump()
    # v61: Blindage conversion durée
    raw_dv = update_data.get("duration_value")
    if raw_dv is not None and raw_dv != "" and raw_dv is not False:
        try:
            update_data["duration_value"] = int(raw_dv)
        except (ValueError, TypeError):
            update_data["duration_value"] = None
    else:
        update_data["duration_value"] = None
    if not update_data.get("duration_unit") or update_data["duration_unit"] == "":
        update_data["duration_unit"] = None
    iap = update_data.get("is_auto_prolong")
    update_data["is_auto_prolong"] = iap not in (False, "false", "0", 0, None)
    # V256: lien partenaire — garde XSS + normalisation du toggle
    _v256_normalize_external_link(update_data)
    print(f"[V61 DEBUG] PUT /offers/{offer_id} duration_value={update_data.get('duration_value')} duration_unit={update_data.get('duration_unit')}")
    # v59: Recalculer expiration si durée modifiée
    if update_data.get("duration_value") and update_data.get("duration_unit"):
        existing = await db.offers.find_one({"id": offer_id}, {"_id": 0})
        created_at = (existing or {}).get("created_at") or datetime.utcnow().isoformat()
        update_data["created_at"] = created_at
        update_data["expiration_date"] = calculate_expiration_date(created_at, update_data["duration_value"], update_data["duration_unit"])
        # Reset rappels si durée changée
        if existing and (existing.get("duration_value") != update_data["duration_value"] or existing.get("duration_unit") != update_data["duration_unit"]):
            update_data["last_reminded_date"] = None
            update_data["last_prolonged_date"] = None
    else:
        update_data["expiration_date"] = None
    # v159 + V254: Validation ET protection anti-ecrasement de linked_course_ids.
    #
    # Deux mecanismes effacaient les liens a CHAQUE sauvegarde d'offre :
    #  (1) le wizard renvoie parfois [] alors que l'offre a des liens (cours
    #      absents de sa prop `courses`) ;
    #  (2) la validation par coach_id retirait TOUS les ids quand le coach_id de
    #      l'offre ne correspond pas a celui des cours — typiquement une offre a
    #      coach_id absent (donnee ancienne) dont les cours appartiennent au coach
    #      reel : le filtre `{"coach_id": None}` ne matchait rien -> [].
    #
    # On recupere l'offre existante UNE fois et on preserve les liens en place
    # quand l'entrant les effacerait sans intention claire. Delier entierement
    # une offre se fait via l'endpoint admin /admin/link-offer-courses.
    existing_offer = await db.offers.find_one({"id": offer_id}, {"_id": 0})
    existing_linked = (existing_offer or {}).get("linked_course_ids") or []
    incoming_linked = update_data.get("linked_course_ids") or []
    if incoming_linked:
        offer_coach_id = (existing_offer or {}).get("coach_id") or update_data.get("coach_id")
        if offer_coach_id:
            valid_courses = await db.courses.find(
                {"id": {"$in": incoming_linked}, "coach_id": offer_coach_id},
                {"_id": 0, "id": 1}
            ).to_list(length=500)
            valid_ids = {c["id"] for c in valid_courses}
            filtered = [cid for cid in incoming_linked if cid in valid_ids]
            if filtered:
                update_data["linked_course_ids"] = filtered
            elif existing_linked:
                # V254: la validation a tout retire alors que l'offre avait des
                # liens -> mismatch coach_id, pas une volonte de delier. Preserver.
                update_data["linked_course_ids"] = existing_linked
                logger.info(f"[V254] linked_course_ids preserve (mismatch coach) offre {offer_id}: {existing_linked}")
            else:
                update_data["linked_course_ids"] = []
        else:
            # Offre sans coach_id : impossible de valider par coach. On accepte les
            # ids entrants tels quels (deja verifies a la creation du lien).
            update_data["linked_course_ids"] = incoming_linked
    elif existing_linked:
        # V254: body vide alors que des liens existent -> preserver (anti-wipe).
        update_data["linked_course_ids"] = existing_linked
        logger.info(f"[V254] linked_course_ids preserve (body vide) offre {offer_id}: {existing_linked}")
    # else: aucun lien entrant ni existant -> reste []
    await db.offers.update_one({"id": offer_id}, {"$set": update_data})
    updated = await db.offers.find_one({"id": offer_id}, {"_id": 0})
    return updated

@api_router.delete("/offers/{offer_id}")
async def delete_offer(offer_id: str, request: Request):
    """v20: Supprime une offre avec vérification d'ownership + nettoyage codes promo"""
    require_auth(request)
    user_email = request.headers.get("X-User-Email", "").lower().strip()

    # v20: Vérifier que l'offre existe
    offer = await db.offers.find_one({"id": offer_id})
    if not offer:
        raise HTTPException(status_code=404, detail="Offre non trouvée")

    # v20: Vérifier l'ownership — Super Admin peut tout supprimer, sinon uniquement ses propres offres
    if not is_super_admin(user_email):
        offer_owner = (offer.get("coach_id") or "").lower()
        if offer_owner and offer_owner != user_email:
            raise HTTPException(status_code=403, detail="Vous ne pouvez supprimer que vos propres offres")

    # 1. Supprimer l'offre
    result = await db.offers.delete_one({"id": offer_id})
    logger.info(f"[DELETE-OFFER] {offer_id} supprimée par {user_email}, deleted_count={result.deleted_count}")

    # 2. Nettoyer les références dans les codes promo
    await db.discount_codes.update_many(
        {"courses": offer_id},
        {"$pull": {"courses": offer_id}}
    )

    return {"success": True, "message": "Offre supprimée et références nettoyées"}

