# --- Users ---
@api_router.get("/users", response_model=List[User])
async def get_users(request: Request):
    # V309 (FUITE 1 fermée) : la liste des clients (name/email/whatsapp) était
    # PUBLIQUE — un anonyme (X-User-Email vide) passait le filtre et récupérait
    # les 109 fiches. Désormais RÉSERVÉE au coach/admin authentifié (403 sinon).
    coach_email = await _v309_require_coach_or_admin(request)
    # V289 : exclure les documents incomplets (créés par d'anciens upserts
    # birthday/photo qui n'avaient ni name ni email — ils cassaient la validation
    # Pydantic et renvoyaient une 500 qui plantait tout le dashboard admin).
    base_filter = {"name": {"$exists": True, "$ne": ""}, "email": {"$exists": True, "$ne": ""}}
    if coach_email and not is_super_admin(coach_email):
        # V311c : FUITE CORRIGÉE. Un coach ne voit QUE ses propres utilisateurs
        # (coach_id == son email). Les fiches HÉRITÉES (sans coach_id, données
        # pré-multi-coach) ne sont PLUS incluses ici : elles fuyaient vers
        # n'importe quel compte coach (l'inscription étant ouverte, un inconnu
        # pouvait s'enregistrer coach et lire 101 fiches clients). Ces fiches
        # héritées restent visibles UNIQUEMENT du super-admin (branche else).
        query = {"$and": [base_filter, {"coach_id": coach_email}]}
    else:
        query = base_filter
    users = await db.users.find(query, {"_id": 0}).to_list(1000)
    for user in users:
        if isinstance(user.get('createdAt'), str):
            user['createdAt'] = datetime.fromisoformat(user['createdAt'].replace('Z', '+00:00'))
    return users

@api_router.post("/users", response_model=User)
async def create_user(user: UserCreate):
    user_obj = User(**user.model_dump())
    doc = user_obj.model_dump()
    doc['createdAt'] = doc['createdAt'].isoformat()
    await db.users.insert_one(doc)
    return user_obj

@api_router.get("/users/{user_id}", response_model=User)
async def get_user(user_id: str):
    user = await db.users.find_one({"id": user_id}, {"_id": 0})
    if not user:
        raise HTTPException(status_code=404, detail="User not found")
    if isinstance(user.get('createdAt'), str):
        user['createdAt'] = datetime.fromisoformat(user['createdAt'].replace('Z', '+00:00'))
    return user

@api_router.put("/users/{user_id}", response_model=User)
async def update_user(user_id: str, user: UserCreate):
    """Update an existing user/contact"""
    existing = await db.users.find_one({"id": user_id}, {"_id": 0})
    if not existing:
        raise HTTPException(status_code=404, detail="User not found")
    
    update_data = user.model_dump()
    await db.users.update_one({"id": user_id}, {"$set": update_data})
    updated = await db.users.find_one({"id": user_id}, {"_id": 0})
    if isinstance(updated.get('createdAt'), str):
        updated['createdAt'] = datetime.fromisoformat(updated['createdAt'].replace('Z', '+00:00'))
    return updated

@api_router.delete("/users/{user_id}")
async def delete_user(user_id: str, request: Request):
    """Supprime un utilisateur/contact et nettoie les références dans les codes promo"""
    # V432 : cette route SUPPRIMAIT un contact sans demander la moindre identité.
    # Un simple `curl -X DELETE` suffisait. Même garde que les autres endpoints
    # touchant des données personnelles (V309) : `require_auth` accepte le JWT
    # signé ET le repli `X-User-Email` de la transition V265 — c'est ce repli que
    # le tableau de bord emprunte, il ne casse donc pas.
    _v432_appelant = require_auth(request)
    if not await _v309_is_coach_or_admin(_v432_appelant):
        logger.warning(f"[V432] DELETE /users/{user_id} refusé pour {_v432_appelant or 'anonyme'}")
        raise HTTPException(status_code=403, detail="Accès refusé")

    # 1. Récupérer l'email de l'utilisateur avant suppression
    user = await db.users.find_one({"id": user_id}, {"_id": 0})
    if not user:
        raise HTTPException(status_code=404, detail="User not found")
    
    user_email = user.get("email")
    
    # 2. Supprimer l'utilisateur
    await db.users.delete_one({"id": user_id})
    
    # 3. Nettoyer les références dans les codes promo (retirer l'email des assignedEmail)
    #
    # V431 : ce nettoyage vidait `assignedEmail` SANS CONDITION. Supprimer un
    # contact rendait donc son code encore valide utilisable par n'importe qui —
    # la suppression d'une donnée personnelle ouvrait un droit d'accès payé.
    # Désormais on épargne les codes encore utilisables ; les autres sont nettoyés
    # comme avant. La suppression du contact lui-même n'est pas touchée.
    _v431 = {"vides": 0, "proteges": 0}
    if user_email:
        from api.routes.shared import purger_assigned_email as _v431_purger
        _v431 = await _v431_purger(
            db, {"assignedEmail": user_email}, motif=f"suppression du contact {user_id}"
        )

    return {"success": True, "message": "Contact supprimé et références nettoyées",
            "codes_liberes": _v431["vides"], "codes_proteges": _v431["proteges"]}

# === V413 : LES MÉDIAS VONT SUR LE DISQUE, PLUS DANS MONGODB ===
#
# POURQUOI. Jusqu'ici chaque fichier était un document MongoDB portant son binaire
# dans un champ `data`. Trois plafonds en découlaient :
#   1. 16 Mo par document (limite DURE de MongoDB) — une vidéo un peu longue ne
#      pouvait tout simplement pas être stockée ;
#   2. une lecture à froid depuis Atlas plafonne à ~75 Ko/s (mesuré) : 12,7 Mo
#      mettaient 178 s et dépassaient la limite de 100 s de Cloudflare -> 524 ;
#   3. l'espace d'Atlas est précieux et payant, celui du disque ne l'est pas.
#
# CE QUI NE CHANGE PAS. Les fichiers DÉJÀ en base y restent et continuent d'être
# servis exactement comme avant : les URL existantes ne peuvent pas casser. Le
# disque est essayé d'abord, MongoDB reste le repli — dans les deux sens (lecture
# ET écriture : si le disque est absent ou non inscriptible, on retombe sur le
# comportement historique plutôt que de perdre un envoi).
#
# LES MÉTADONNÉES RESTENT EN BASE (sans le binaire) : le type de contenu, le nom
# d'origine et le propriétaire servent au reste de l'application. Seuls les octets
# déménagent.
_V413_MEDIA_DIR = os.environ.get("MEDIA_DIR", "/app/media")
# `file_id` et `filename` viennent de l'URL publique : un `..` y ouvrirait tout le
# système de fichiers. On n'accepte donc qu'un identifiant simple, et on retire
# toute composante de chemin du nom.
_V413_ID_VALIDE = re.compile(r"^[A-Za-z0-9_-]{1,64}$")


def _v412_plage(entete_range: str, taille: int):
    """V412/V413 — interprète un en-tête `Range`. Renvoie :
         None          -> pas de plage demandée (ou illisible) : servir tout ;
         416           -> plage hors du fichier ;
         (debut, fin)  -> bornes INCLUSES à servir.

    Factorisé pour que le chemin DISQUE et le chemin MONGODB partagent exactement
    la même interprétation. En V413 la branche disque court-circuitait ce calcul
    et retombait sur un 200 : les vidéos servies depuis le disque perdaient donc
    l'avance rapide que V412 venait d'apporter. D'où cette mise en commun."""
    e = (entete_range or "").strip()
    if not e.lower().startswith("bytes=") or taille <= 0:
        return None
    spec = e[6:].strip()
    if "," in spec:          # multi-plages : on sert le fichier entier (réponse valide)
        return None
    debut_txt, _, fin_txt = spec.partition("-")
    debut_txt, fin_txt = debut_txt.strip(), fin_txt.strip()
    debut = fin = None
    try:
        if debut_txt == "" and fin_txt:
            longueur = int(fin_txt)          # `bytes=-n` : les n derniers octets
            if longueur > 0:
                debut, fin = max(0, taille - longueur), taille - 1
        elif debut_txt:
            debut = int(debut_txt)
            fin = int(fin_txt) if fin_txt else taille - 1
    except ValueError:
        return None
    if debut is None or fin is None:
        return None
    fin = min(fin, taille - 1)
    if debut > fin or debut >= taille:
        return 416
    return (debut, fin)


def _v413_chemin(file_id: str, filename: str):
    """Chemin disque d'un média, ou None si l'identifiant est suspect."""
    if not _V413_ID_VALIDE.match(file_id or ""):
        return None
    nom = os.path.basename((filename or "").replace("\\", "/")).strip()
    if not nom or nom in (".", ".."):
        return None
    return os.path.join(_V413_MEDIA_DIR, file_id, nom)


def _v413_disque_pret() -> bool:
    """Le disque est-il réellement utilisable ? On ne se fie pas à l'existence du
    dossier : sans droit d'écriture, l'envoi serait perdu en silence."""
    try:
        os.makedirs(_V413_MEDIA_DIR, exist_ok=True)
        return os.access(_V413_MEDIA_DIR, os.W_OK)
    except Exception:
        return False


def _v413_ecrire(file_id: str, filename: str, data: bytes) -> bool:
    """Écrit le binaire sur le disque. Renvoie False si quoi que ce soit empêche
    l'écriture — l'appelant retombe alors sur MongoDB, sans perdre le fichier."""
    chemin = _v413_chemin(file_id, filename)
    if not chemin or not _v413_disque_pret():
        return False
    try:
        os.makedirs(os.path.dirname(chemin), exist_ok=True)
        # Écriture en deux temps : un lecteur ne peut jamais tomber sur un fichier
        # à moitié écrit, et un plantage en cours ne laisse pas de média tronqué.
        provisoire = chemin + ".part"
        with open(provisoire, "wb") as f:
            f.write(data)
        os.replace(provisoire, chemin)
        logger.info(f"[V413] media ecrit sur disque : {chemin} ({len(data)} o)")
        return True
    except Exception as e:
        logger.error(f"[V413] ecriture disque impossible ({type(e).__name__}: {e}) "
                     f"-> repli MongoDB")
        return False


async def _v413_enregistrer_media(file_id: str, filename: str, data: bytes,
                                  base_doc: dict) -> dict:
    """Range un média : disque si possible, MongoDB sinon. Renvoie le document
    inséré (le binaire n'y figure QUE dans le cas du repli)."""
    from bson.binary import Binary  # importé localement, comme partout ailleurs ici
    doc = dict(base_doc)
    doc["size"] = len(data)
    if _v413_ecrire(file_id, filename, data):
        doc["storage"] = "disk"          # marqueur explicite, lisible en base
    else:
        doc["storage"] = "mongo"
        doc["data"] = Binary(data)
    await db.uploaded_files.insert_one(doc)
    return doc


# --- Photo de profil (MOTEUR D'UPLOAD RÉEL) ---
@api_router.post("/users/upload-photo")
async def upload_user_photo(file: UploadFile = File(...), participant_id: str = Form(...)):
    """
    v75: MOTEUR D'UPLOAD PHOTO PROFIL — Stockage MongoDB (compatible Vercel)
    1. Reçoit l'image via UploadFile
    2. Redimensionne à 200x200 max
    3. Sauvegarde dans MongoDB collection 'uploaded_files' (pas le filesystem éphémère)
    4. Met à jour photo_url dans 'users' ET 'chat_participants'
    5. Retourne l'URL /api/files/{file_id}/{filename} pour synchronisation
    """
    from PIL import Image
    import io
    import uuid
    from bson.binary import Binary

    # Validation du type MIME
    if not file.content_type or not file.content_type.startswith("image/"):
        raise HTTPException(status_code=400, detail="Type de fichier non supporté. Envoyez une image.")

    # Lire le contenu du fichier
    contents = await file.read()

    # Vérifier la taille (max 2MB)
    if len(contents) > 2 * 1024 * 1024:
        raise HTTPException(status_code=400, detail="Fichier trop volumineux (max 2MB)")

    try:
        # Ouvrir et traiter l'image
        img = Image.open(io.BytesIO(contents))

        # Convertir en RGB si nécessaire (RGBA, P modes)
        if img.mode in ('RGBA', 'P'):
            img = img.convert('RGB')

        # Redimensionner à max 200x200 en conservant les proportions
        img.thumbnail((200, 200), Image.LANCZOS)

        # Sauvegarder en mémoire (pas sur le filesystem Vercel éphémère)
        buf = io.BytesIO()
        img.save(buf, "JPEG", quality=85)
        file_bytes = buf.getvalue()

        # Générer un identifiant unique pour MongoDB
        file_id = uuid.uuid4().hex[:16]
        filename = f"profile_{participant_id}_{file_id}.jpg"

        # V413 : disque si possible, MongoDB en repli (le binaire n'est plus
        # placé ici — `_v413_enregistrer_media` s'en charge selon la destination).
        file_doc = await _v413_enregistrer_media(file_id, filename, file_bytes, {
            "file_id": file_id,
            "filename": filename,
            "original_name": file.filename or "profile.jpg",
            "content_type": "image/jpeg",
            "asset_type": "profile_photo",
            "participant_id": participant_id,
            "created_at": datetime.utcnow()
        })

        # URL publique via le endpoint /api/files/ existant
        photo_url = f"/api/files/{file_id}/{filename}"

        # === MISE À JOUR BASE DE DONNÉES ===
        # 1. Mettre à jour dans la collection 'users' (par participant_id OU email)
        update_result_users = await db.users.update_one(
            {"$or": [{"id": participant_id}, {"participant_id": participant_id}]},
            {"$set": {"photo_url": photo_url, "photoUrl": photo_url}},
            upsert=False
        )

        # 2. Mettre à jour dans 'chat_participants' si existe
        update_result_participants = await db.chat_participants.update_one(
            {"id": participant_id},
            {"$set": {"photo_url": photo_url, "photoUrl": photo_url}},
            upsert=False
        )

        logger.info(f"[UPLOAD] ✅ v75 Photo profil MongoDB: {filename} ({len(file_bytes)} bytes) | users={update_result_users.modified_count}, participants={update_result_participants.modified_count}")

        return {
            "success": True,
            "url": photo_url,
            "filename": filename,
            "participant_id": participant_id,
            "db_updated": {
                "users": update_result_users.modified_count,
                "participants": update_result_participants.modified_count
            }
        }

    except Exception as e:
        logger.error(f"[UPLOAD] ❌ Erreur traitement image: {str(e)}")
        raise HTTPException(status_code=500, detail=f"Erreur traitement image: {str(e)}")

# === v17.5: UPLOAD ISOLÉ PAR COACH — MONGODB STORAGE (Vercel-compatible) ===
@api_router.post("/coach/upload-asset")
async def upload_coach_asset(
    request: Request,
    file: UploadFile = File(...),
    asset_type: str = Form("image")  # "image", "video", "logo", "audio"
):
    """
    Upload d'assets pour les coaches - Stockage MongoDB (compatible Vercel read-only FS)
    v17.5: Stocke les fichiers binaires dans MongoDB collection 'uploaded_files'
    """
    import io
    import uuid
    import base64

    coach_email = request.headers.get('X-User-Email', '').lower().strip()
    if not coach_email:
        raise HTTPException(status_code=401, detail="Email coach requis")

    # Validation du type MIME
    allowed_types = {
        "image": ["image/jpeg", "image/png", "image/webp", "image/gif"],
        "video": ["video/mp4", "video/webm", "video/quicktime"],
        "logo": ["image/jpeg", "image/png", "image/webp", "image/svg+xml"],
        "audio": ["audio/mpeg", "audio/mp3", "audio/wav", "audio/ogg", "audio/aac", "audio/mp4"]
    }

    if asset_type not in allowed_types:
        raise HTTPException(status_code=400, detail=f"Type d'asset invalide: {asset_type}")

    if file.content_type not in allowed_types[asset_type]:
        raise HTTPException(status_code=400, detail=f"Type MIME non autorisé pour {asset_type}: {file.content_type}")

    contents = await file.read()

    # V415 : PLAFONDS RELEVES. Les anciennes valeurs (video 15 Mo) venaient de la
    # limite DURE de 16 Mo par document MongoDB — contrainte DISPARUE depuis que
    # les medias vont sur le disque (V413). Elles condamnaient la moindre video de
    # telephone sans aucune raison technique restante.
    #
    # Marge verifiee avant de relever : 14 Go libres sur le disque, 12 Mo de
    # medias stockes. Meme cent videos de 100 Mo tiendraient.
    #
    # PLAFOND REEL EN AMONT : Cloudflare refuse les corps de requete au-dela de
    # 100 Mo sur ce plan. Annoncer davantage cote serveur ne servirait a rien —
    # l'envoi serait coupe avant de nous atteindre. 100 Mo est donc le maximum
    # utile, pas une valeur choisie au hasard.
    max_sizes = {"image": 25*1024*1024, "video": 100*1024*1024,
                 "logo": 5*1024*1024, "audio": 50*1024*1024}
    if len(contents) > max_sizes.get(asset_type, 5*1024*1024):
        raise HTTPException(status_code=400, detail=f"Fichier trop volumineux (max {max_sizes[asset_type]//1024//1024}MB)")

    try:
        # Extension basée sur le type MIME
        ext_map = {
            "image/jpeg": ".jpg", "image/png": ".png", "image/webp": ".webp", "image/gif": ".gif",
            "video/mp4": ".mp4", "video/webm": ".webm", "video/quicktime": ".mov",
            "image/svg+xml": ".svg",
            "audio/mpeg": ".mp3", "audio/mp3": ".mp3", "audio/wav": ".wav",
            "audio/ogg": ".ogg", "audio/aac": ".aac", "audio/mp4": ".m4a"
        }
        ext = ext_map.get(file.content_type, ".bin")

        file_id = uuid.uuid4().hex[:16]
        filename = f"{asset_type}_{file_id}{ext}"

        # Pour les images, optimiser en mémoire
        file_bytes = contents
        if asset_type in ["image", "logo"] and file.content_type.startswith("image/") and file.content_type != "image/svg+xml":
            from PIL import Image
            img = Image.open(io.BytesIO(contents))
            if img.mode in ('RGBA', 'P'):
                img = img.convert('RGB')
            max_dim = 1920 if asset_type == "image" else 400
            img.thumbnail((max_dim, max_dim), Image.LANCZOS)
            buf = io.BytesIO()
            img.save(buf, "JPEG" if ext == ".jpg" else "PNG", quality=85)
            file_bytes = buf.getvalue()

        # V413 : disque si possible, MongoDB en repli.
        file_doc = await _v413_enregistrer_media(file_id, filename, file_bytes, {
            "file_id": file_id,
            "filename": filename,
            "original_name": file.filename,
            "content_type": file.content_type,
            "asset_type": asset_type,
            "coach_email": coach_email,
            "created_at": datetime.utcnow()
        })

        # URL publique via API endpoint
        asset_url = f"/api/files/{file_id}/{filename}"

        logger.info(f"[COACH-UPLOAD] ✅ Asset stocké MongoDB pour {coach_email}: {filename} ({asset_type}, {len(file_bytes)} bytes)")

        return {
            "success": True,
            "url": asset_url,
            "filename": filename,
            "asset_type": asset_type,
            "coach_id": coach_email
        }

    except Exception as e:
        logger.error(f"[COACH-UPLOAD] ❌ Erreur: {str(e)}")
        raise HTTPException(status_code=500, detail=f"Erreur upload: {str(e)}")

# === v58: Upload en chunks pour fichiers > 4MB (contourne limite Vercel 4.5MB body) ===
@api_router.post("/coach/upload-chunk")
async def upload_chunk(
    request: Request,
    file: UploadFile = File(...),
    upload_id: str = Form(...),
    chunk_index: int = Form(...),
    total_chunks: int = Form(...),
    original_name: str = Form("audio.mp3"),
    content_type: str = Form("audio/mpeg"),
    asset_type: str = Form("audio")
):
    """Upload un fichier PAR MORCEAUX. Le dernier morceau declenche l'assemblage.

    === V420 : POURQUOI CETTE ROUTE DEVIENT LE CHEMIN NORMAL DES VIDEOS ===

    Un envoi MONOBLOC ne peut pas marcher pour une video longue. Mesure faite en
    production sur un fichier de 199,8 Mo (2 min) :

      via Cloudflare  -> 413 Payload Too Large apres 1,5 Mo envoyes (0,96 s).
                         Cloudflare refuse des qu'il lit `Content-Length` : sa
                         limite de corps de requete est de 100 Mo sur ce plan.
      origine directe -> 499 Client Closed Request apres 92 Mo et 60,4 s.
                         Coupure a ~44 % du fichier, sur un delai d'environ 60 s.

    Deux murs INDEPENDANTS, aucun contournable depuis le client. Decoupe en
    morceaux de quelques Mo, chaque requete dure une seconde ou deux : elle ne
    s'approche ni de la limite de taille, ni du delai. C'est la seule voie fiable.

    Une compression cote navigateur (ffmpeg.wasm) aurait ete l'autre option :
    ecartee, elle ajoute ~25 Mo de telechargement, s'effondre en memoire sur
    iOS, et ne garantit RIEN — une video de 5 min compressee peut encore
    depasser 100 Mo. Elle reste un confort possible plus tard, pas une solution.

    === V420 : LES MORCEAUX VONT SUR LE DISQUE, PLUS DANS MONGODB ===

    Ils etaient stockes en base. Une video de 200 Mo y aurait donc transite
    integralement — sur un cluster dont l'espace total est de 512 Mo, et dont
    78,9 Mo sont deja pris. Deux envois simultanes suffisaient a le saturer.
    Et l'assemblage concatenait tout EN MEMOIRE (`file_bytes += ...`), soit
    200 Mo de RAM par envoi.

    Desormais chaque morceau est un fichier dans `<MEDIA>/.uploads/<id>/`, et
    l'assemblage RECOPIE morceau par morceau vers la destination : la memoire
    utilisee ne depasse jamais la taille d'un morceau. Repli MongoDB conserve
    si le disque est indisponible — on ne perd jamais un envoi.
    """
    import uuid
    import shutil
    from bson.binary import Binary

    coach_email = request.headers.get('X-User-Email', '').lower().strip()
    if not coach_email:
        raise HTTPException(status_code=401, detail="Email coach requis")

    # `upload_id` vient du client et sert de NOM DE DOSSIER : sans ce filtre, un
    # `../` y ouvrirait le systeme de fichiers. Meme regle que pour `file_id`.
    if not _V413_ID_VALIDE.match(upload_id or ""):
        raise HTTPException(status_code=400, detail="Identifiant d'envoi invalide")
    if total_chunks < 1 or chunk_index < 0 or chunk_index >= total_chunks:
        raise HTTPException(status_code=400, detail="Indice de morceau invalide")

    contents = await file.read()
    logger.info(f"[CHUNK-UPLOAD] morceau {chunk_index + 1}/{total_chunks} "
                f"pour {upload_id} ({len(contents)} o)")

    dossier = os.path.join(_V413_MEDIA_DIR, ".uploads", upload_id)
    sur_disque = _v413_disque_pret()
    if sur_disque:
        try:
            os.makedirs(dossier, exist_ok=True)
            with open(os.path.join(dossier, f"{chunk_index:06d}.part"), "wb") as f:
                f.write(contents)
        except Exception as e:
            logger.error(f"[CHUNK-UPLOAD] disque indisponible ({e}) -> repli MongoDB")
            sur_disque = False

    if not sur_disque:
        await db.upload_chunks.update_one(
            {"upload_id": upload_id, "chunk_index": chunk_index},
            {"$set": {
                "upload_id": upload_id,
                "chunk_index": chunk_index,
                "total_chunks": total_chunks,
                "data": Binary(contents),
                "coach_email": coach_email,
                "original_name": original_name,
                "content_type": content_type,
                "asset_type": asset_type,
                "created_at": datetime.utcnow()
            }},
            upsert=True
        )

    # Tous les morceaux sont-ils arrives ?
    if sur_disque:
        recus = len([n for n in os.listdir(dossier) if n.endswith(".part")])
    else:
        recus = await db.upload_chunks.count_documents({"upload_id": upload_id})
    if recus < total_chunks:
        return {"success": True, "status": "chunk_received",
                "received": recus, "total": total_chunks}

    # === ASSEMBLAGE ===
    ext_map = {
        "audio/mpeg": ".mp3", "audio/mp3": ".mp3", "audio/wav": ".wav",
        "audio/ogg": ".ogg", "audio/aac": ".aac", "audio/mp4": ".m4a",
        "image/jpeg": ".jpg", "image/png": ".png", "image/webp": ".webp",
        # V420 : `.mov` et `.webm` MANQUAIENT. Un envoi de ce type recevait
        # l'extension `.bin`, et le frontend — qui reconnait une video a son
        # extension — ne l'affichait plus comme une video. Bug silencieux.
        "video/mp4": ".mp4", "video/quicktime": ".mov", "video/webm": ".webm"
    }
    ext = ext_map.get(content_type, ".bin")
    file_id = uuid.uuid4().hex[:16]
    filename = f"{asset_type}_{file_id}{ext}"

    # Plafond applique sur le TOTAL assemble : sans lui, la decoupe en morceaux
    # permettrait de contourner la limite de `/coach/upload-asset`.
    plafond = {"image": 25*1024*1024, "video": 200*1024*1024,
               "logo": 5*1024*1024, "audio": 50*1024*1024}.get(asset_type, 25*1024*1024)

    if sur_disque:
        morceaux = sorted(n for n in os.listdir(dossier) if n.endswith(".part"))
        total = sum(os.path.getsize(os.path.join(dossier, n)) for n in morceaux)
        if total > plafond:
            shutil.rmtree(dossier, ignore_errors=True)
            raise HTTPException(status_code=400,
                                detail=f"Fichier trop volumineux (max {plafond//1024//1024} Mo)")
        cible = _v413_chemin(file_id, filename)
        os.makedirs(os.path.dirname(cible), exist_ok=True)
        provisoire = cible + ".part"
        # Recopie morceau par morceau : la memoire ne depasse jamais un morceau.
        with open(provisoire, "wb") as sortie:
            for n in morceaux:
                with open(os.path.join(dossier, n), "rb") as entree:
                    shutil.copyfileobj(entree, sortie, 1024 * 1024)
        os.replace(provisoire, cible)
        shutil.rmtree(dossier, ignore_errors=True)
        await db.uploaded_files.insert_one({
            "file_id": file_id, "filename": filename,
            "original_name": original_name, "content_type": content_type,
            "asset_type": asset_type, "coach_email": coach_email,
            "size": total, "storage": "disk", "created_at": datetime.utcnow()
        })
        taille = total
    else:
        chunks = await db.upload_chunks.find(
            {"upload_id": upload_id}).sort("chunk_index", 1).to_list(length=total_chunks)
        file_bytes = b"".join(bytes(c["data"]) for c in chunks)
        await db.upload_chunks.delete_many({"upload_id": upload_id})
        if len(file_bytes) > plafond:
            raise HTTPException(status_code=400,
                                detail=f"Fichier trop volumineux (max {plafond//1024//1024} Mo)")
        await _v413_enregistrer_media(file_id, filename, file_bytes, {
            "file_id": file_id, "filename": filename,
            "original_name": original_name, "content_type": content_type,
            "asset_type": asset_type, "coach_email": coach_email,
            "created_at": datetime.utcnow()
        })
        taille = len(file_bytes)

    asset_url = f"/api/files/{file_id}/{filename}"
    logger.info(f"[CHUNK-UPLOAD] assemble : {filename} ({taille} o, "
                f"{total_chunks} morceaux, {'disque' if sur_disque else 'mongo'})")

    return {
        "success": True,
        "status": "complete",
        "url": asset_url,
        "filename": filename,
        "asset_type": asset_type,
        "size": taille
    }


# === v44: CRUD PISTES AUDIO AUTONOMES (indépendant des cours) ===
# Collection MongoDB: audio_tracks — chaque piste est un document indépendant

@api_router.get("/audio-tracks")
async def list_audio_tracks(request: Request):
    """Liste toutes les pistes audio d'un coach"""
    email = require_auth(request)
    tracks = await db.audio_tracks.find(
        {"coach_email": email},
        {"_id": 0}
    ).sort("order", 1).to_list(500)
    return {"tracks": tracks, "count": len(tracks)}

@api_router.post("/audio-tracks")
async def create_audio_track(request: Request):
    """Crée une nouvelle piste audio"""
    email = require_auth(request)
    body = await request.json()

    track_id = f"track-{uuid.uuid4().hex[:12]}"
    # Compter les pistes existantes pour l'ordre
    count = await db.audio_tracks.count_documents({"coach_email": email})

    track_doc = {
        "id": track_id,
        "coach_email": email,
        "url": body.get("url", ""),
        "title": body.get("title", "Sans titre"),
        "cover_url": body.get("cover_url"),
        "description": body.get("description", ""),
        "price": float(body.get("price", 0)),
        "preview_duration": int(body.get("preview_duration", 30)),
        "duration": body.get("duration"),
        "order": body.get("order", count),
        "visible": body.get("visible", True),
        "created_at": datetime.utcnow().isoformat()
    }

    await db.audio_tracks.insert_one(track_doc)
    del track_doc["_id"]  # Remove MongoDB _id before returning
    logger.info(f"[AUDIO] ✅ Piste créée: {track_doc['title']} pour {email}")
    return {"success": True, "track": track_doc}

class ReorderRequest(BaseModel):
    """v48: Schéma Pydantic strict pour le reorder — empêche les erreurs de type"""
    model_config = ConfigDict(extra="ignore")
    track_ids: List[str] = Field(..., min_length=0, description="Liste ordonnée des IDs de pistes")

@api_router.put("/audio-tracks/reorder")
async def reorder_audio_tracks(request: Request):
    """v48: Réordonne les pistes audio — DOIT être AVANT {track_id} pour éviter conflit de route"""
    email = require_auth(request)
    try:
        body = await request.json()
        reorder_data = ReorderRequest(**body)
    except Exception as e:
        logger.error(f"[AUDIO-REORDER] ❌ Validation error: {str(e)}")
        raise HTTPException(status_code=422, detail=f"Format invalide: {str(e)}")

    track_ids = reorder_data.track_ids
    updated = 0
    for i, tid in enumerate(track_ids):
        result = await db.audio_tracks.update_one(
            {"id": tid, "coach_email": email},
            {"$set": {"order": i}}
        )
        if result.modified_count > 0:
            updated += 1

    logger.info(f"[AUDIO-REORDER] ✅ {email} — {updated}/{len(track_ids)} pistes réordonnées")
    return {"success": True, "reordered": len(track_ids), "updated": updated}

@api_router.put("/audio-tracks/{track_id}")
async def update_audio_track(track_id: str, request: Request):
    """Met à jour une piste audio (titre, prix, visible, etc.)"""
    email = require_auth(request)
    body = await request.json()

    existing = await db.audio_tracks.find_one({"id": track_id, "coach_email": email})
    if not existing:
        raise HTTPException(status_code=404, detail="Piste non trouvée")

    update_data = {k: v for k, v in body.items() if v is not None and k not in ("id", "coach_email", "_id")}
    if "price" in update_data:
        update_data["price"] = float(update_data["price"])

    await db.audio_tracks.update_one({"id": track_id}, {"$set": update_data})
    updated = await db.audio_tracks.find_one({"id": track_id}, {"_id": 0})
    logger.info(f"[AUDIO] ✏️ Piste modifiée: {track_id} — champs: {list(update_data.keys())}")
    return {"success": True, "track": updated}

@api_router.delete("/audio-tracks/{track_id}")
async def delete_audio_track(track_id: str, request: Request):
    """Supprime une piste audio"""
    email = require_auth(request)
    result = await db.audio_tracks.delete_one({"id": track_id, "coach_email": email})
    if result.deleted_count == 0:
        raise HTTPException(status_code=404, detail="Piste non trouvée")
    logger.info(f"[AUDIO] 🗑️ Piste supprimée: {track_id} par {email}")
    return {"success": True, "deleted": track_id}

# === v44: PISTES AUDIO PUBLIQUES (pour la vitrine) ===
@api_router.get("/public/audio-tracks/{coach_email}")
async def get_public_audio_tracks(coach_email: str):
    """Liste les pistes audio visibles d'un coach (pour la vitrine publique)"""
    tracks = await db.audio_tracks.find(
        {"coach_email": coach_email.lower().strip(), "visible": True},
        {"_id": 0, "coach_email": 0}
    ).sort("order", 1).to_list(100)
    return {"tracks": tracks, "count": len(tracks)}

# === v18.1: DIAGNOSTIC FICHIERS UPLOADÉS (doit être AVANT la route dynamique) ===
@api_router.get("/files/check/{file_id}")
async def check_uploaded_file(file_id: str):
    """Diagnostic: vérifie si un fichier existe dans MongoDB sans le charger"""
    try:
        file_doc = await db.uploaded_files.find_one(
            {"file_id": file_id},
            {"file_id": 1, "filename": 1, "content_type": 1, "size": 1, "original_name": 1, "asset_type": 1, "created_at": 1, "coach_email": 1}
        )
        if not file_doc:
            return {"exists": False, "file_id": file_id}

        return {
            "exists": True,
            "file_id": file_doc.get("file_id"),
            "filename": file_doc.get("filename"),
            "original_name": file_doc.get("original_name"),
            "content_type": file_doc.get("content_type"),
            "size": file_doc.get("size"),
            "asset_type": file_doc.get("asset_type"),
            "created_at": str(file_doc.get("created_at", "")),
            "coach_email": file_doc.get("coach_email")
        }
    except Exception as e:
        return {"exists": False, "error": str(e)}

# === v18.3: FASTSTART MP4 — déplace moov avant mdat pour streaming instantané ===
def mp4_faststart(data: bytes) -> bytes:
    """
    Réorganise un MP4 pour placer l'atome moov AVANT mdat (faststart).
    Permet au navigateur de commencer la lecture sans attendre le téléchargement complet.
    Retourne les données originales si déjà faststart ou si le format n'est pas MP4.
    """
    import struct
    try:
        # Parse les atomes top-level
        atoms = []
        pos = 0
        while pos < len(data) - 8:
            size = struct.unpack('>I', data[pos:pos+4])[0]
            atom_type = data[pos+4:pos+8].decode('ascii', errors='replace')
            if size < 8:
                break
            if size == 1 and pos + 16 <= len(data):
                size = struct.unpack('>Q', data[pos+8:pos+16])[0]
            atoms.append({'type': atom_type, 'offset': pos, 'size': size})
            pos += size
            if pos > len(data):
                break

        # Trouver moov et mdat
        moov = next((a for a in atoms if a['type'] == 'moov'), None)
        mdat = next((a for a in atoms if a['type'] == 'mdat'), None)

        if not moov or not mdat:
            return data  # Pas un MP4 standard

        # Déjà faststart ? (moov avant mdat)
        if moov['offset'] < mdat['offset']:
            logger.info("[FASTSTART] ✅ Déjà faststart")
            return data

        logger.info(f"[FASTSTART] 🔄 Réorganisation: moov@{moov['offset']} → avant mdat@{mdat['offset']}")

        # Calculer le décalage: moov va être inséré avant mdat
        moov_data = bytearray(data[moov['offset']:moov['offset'] + moov['size']])
        moov_size = moov['size']

        # Ajuster les offsets stco et co64 dans moov
        # Les chunk offsets pointent dans mdat — ils doivent être décalés de +moov_size
        def adjust_offsets(box_data, box_offset, parent_end):
            """Parcourt récursivement moov pour ajuster stco/co64"""
            pos = box_offset + 8  # Skip size + type
            while pos < parent_end - 8:
                child_size = struct.unpack('>I', box_data[pos:pos+4])[0]
                child_type = box_data[pos+4:pos+8].decode('ascii', errors='replace')
                if child_size < 8 or pos + child_size > parent_end:
                    break

                if child_type == 'stco':
                    # stco: 4 bytes version/flags + 4 bytes count + 4 bytes per entry
                    entry_count = struct.unpack('>I', box_data[pos+12:pos+16])[0]
                    for i in range(entry_count):
                        off = pos + 16 + i * 4
                        if off + 4 <= parent_end:
                            old_val = struct.unpack('>I', box_data[off:off+4])[0]
                            struct.pack_into('>I', box_data, off, old_val + moov_size)

                elif child_type == 'co64':
                    entry_count = struct.unpack('>I', box_data[pos+12:pos+16])[0]
                    for i in range(entry_count):
                        off = pos + 16 + i * 8
                        if off + 8 <= parent_end:
                            old_val = struct.unpack('>Q', box_data[off:off+8])[0]
                            struct.pack_into('>Q', box_data, off, old_val + moov_size)

                elif child_type in ('trak', 'mdia', 'minf', 'stbl', 'edts', 'dinf'):
                    adjust_offsets(box_data, pos, pos + child_size)

                pos += child_size

        adjust_offsets(moov_data, 0, moov_size)

        # Reconstruire: [atoms avant mdat] + [moov ajusté] + [mdat] + [atoms après moov]
        result = bytearray()
        for a in atoms:
            if a['type'] == 'mdat':
                result.extend(moov_data)  # Insérer moov avant mdat
                result.extend(data[a['offset']:a['offset'] + a['size']])
            elif a['type'] == 'moov':
                pass  # Skip — déjà inséré avant mdat
            else:
                result.extend(data[a['offset']:a['offset'] + a['size']])

        logger.info(f"[FASTSTART] ✅ Réorganisé: {len(data)} → {len(result)} bytes")
        return bytes(result)

    except Exception as e:
        logger.warning(f"[FASTSTART] ⚠️ Erreur faststart, retour original: {e}")
        return data

# === v17.5: SERVING FICHIERS DEPUIS MONGODB ===
@api_router.get("/files/{file_id}/{filename}")
async def serve_uploaded_file(file_id: str, filename: str, request: Request):
    """
    Sert un fichier uploadé depuis MongoDB.
    v18.3: Faststart MP4 automatique + StreamingResponse pour gros fichiers
    Cache-Control: 1 an (les fichiers sont immutables via leur ID unique)
    V412: répond aux requêtes par plages (Range -> 206), cf. bloc plus bas.
    """
    from fastapi.responses import Response, StreamingResponse
    import io

    try:
        logger.info(f"[FILE-SERVE] Requête fichier: file_id={file_id}, filename={filename}")

        file_doc = await db.uploaded_files.find_one({"file_id": file_id})

        if not file_doc:
            logger.warning(f"[FILE-SERVE] ❌ Fichier non trouvé: {file_id}")
            raise HTTPException(status_code=404, detail="Fichier non trouvé")

        # === V413 : LE DISQUE D'ABORD ===
        #
        # `FileResponse` gère les requêtes par plages NATIVEMENT (206, Content-Range,
        # reprise) et diffuse depuis le disque local au lieu de tirer le fichier
        # entier depuis Atlas à ~75 Ko/s. C'est ce qui lève d'un coup la limite des
        # 16 Mo et celle des 100 s de Cloudflare.
        #
        # On teste l'EXISTENCE du fichier, pas seulement le marqueur `storage` : un
        # document mal étiqueté (ou un média copié à la main) doit quand même être
        # servi. Et si le fichier n'est pas là, on retombe sur MongoDB juste en
        # dessous — les URL déjà en circulation ne peuvent pas casser.
        _chemin_disque = _v413_chemin(file_id, filename)
        if _chemin_disque and os.path.isfile(_chemin_disque):
            from fastapi.responses import FileResponse as _FR
            _ct = file_doc.get("content_type", "application/octet-stream")
            _nom = (file_doc.get("original_name") or filename)
            _nom = _nom.encode('ascii', 'replace').decode('ascii').replace('?', '_')
            _entetes = {
                "Cache-Control": "public, max-age=31536000, immutable",
                "Content-Disposition": f'inline; filename="{_nom}"',
                "Accept-Ranges": "bytes",
            }
            _taille = os.path.getsize(_chemin_disque)
            _p = _v412_plage(request.headers.get("range"), _taille)

            if _p == 416:
                return Response(status_code=416,
                                headers={"Content-Range": f"bytes */{_taille}",
                                         "Accept-Ranges": "bytes"})
            if _p:
                # PLAGE : on ne lit QUE le morceau demandé (seek + read), sans
                # charger le fichier entier — c'est tout l'intérêt du disque.
                # `FileResponse` de cette version de Starlette IGNORE `Range` et
                # renverrait 200 : mesuré en production avant ce correctif.
                _debut, _fin = _p
                with open(_chemin_disque, "rb") as _f:
                    _f.seek(_debut)
                    _morceau = _f.read(_fin - _debut + 1)
                logger.info(f"[FILE-SERVE] disque 206 {_debut}-{_fin}/{_taille}")
                _entetes["Content-Range"] = f"bytes {_debut}-{_fin}/{_taille}"
                return Response(content=_morceau, status_code=206,
                                media_type=_ct, headers=_entetes)

            logger.info(f"[FILE-SERVE] disque -> {_chemin_disque} ({_taille} o)")
            return _FR(_chemin_disque, media_type=_ct, headers=_entetes)

        # Extraire les données binaires
        raw_data = file_doc.get("data")
        if raw_data is None:
            logger.error(f"[FILE-SERVE] ❌ Champ 'data' manquant pour {file_id}")
            raise HTTPException(status_code=500, detail="Données fichier manquantes")

        # Convertir BSON Binary en bytes de manière sûre
        if hasattr(raw_data, 'read'):
            file_bytes = raw_data.read()
        elif isinstance(raw_data, bytes):
            file_bytes = raw_data
        else:
            file_bytes = bytes(raw_data)

        content_type = file_doc.get("content_type", "application/octet-stream")

        # v29.4: mp4_faststart DÉSACTIVÉ — corrompait les fichiers MP4
        # Le moov atom est généralement déjà en position correcte pour les vidéos modernes
        # if content_type.startswith('video/') and len(file_bytes) < 50 * 1024 * 1024:
        #     file_bytes = mp4_faststart(file_bytes)

        # Sanitize filename pour header HTTP (latin-1 safe)
        raw_name = file_doc.get("original_name", filename)
        original_name = raw_name.encode('ascii', 'replace').decode('ascii').replace('?', '_')
        file_size = len(file_bytes)

        logger.info(f"[FILE-SERVE] ✅ Servant {original_name}: {file_size} bytes, type={content_type}")

        # === V412 : REQUÊTES PAR PLAGES (Range) -> 206 Partial Content ===
        #
        # POURQUOI. Un navigateur qui lit une vidéo n'envoie pas un GET simple : il
        # demande des PLAGES d'octets (`Range: bytes=...`) et attend un `206`. Cette
        # route répondait invariablement 200 avec le fichier ENTIER, tout en
        # annonçant `Accept-Ranges: bytes` — elle promettait donc une capacité
        # qu'elle n'avait pas. Conséquences : pas d'avance rapide, et pour un
        # fichier lourd une réponse qui n'aboutit jamais dans le délai imparti.
        #
        # Le 206 observé sur les anciennes vidéos venait de CLOUDFLARE, depuis sa
        # copie en cache — jamais de l'application (vérifié en interrogeant
        # l'origine en direct : 200 + Range ignoré, pour TOUS les fichiers). Ce
        # repli disparaît dès que le cache expire : c'est cette dépendance qu'on
        # supprime ici.
        #
        # PRUDENCE — RÈGLE DE NON-RÉGRESSION : SANS en-tête `Range`, le
        # comportement est INCHANGÉ (200 + corps complet, mêmes en-têtes, mêmes
        # deux branches qu'avant). Les images et les vidéos qui fonctionnent
        # aujourd'hui empruntent exactement le même chemin qu'avant cette version.
        _p = _v412_plage(request.headers.get("range"), file_size)
        if _p == 416:
            # Plage hors du fichier -> 416, comme l'exige la norme.
            return Response(
                status_code=416,
                headers={"Content-Range": f"bytes */{file_size}",
                         "Accept-Ranges": "bytes"},
            )
        if _p:
            debut, fin = _p
            morceau = file_bytes[debut:fin + 1]
            logger.info(f"[FILE-SERVE] mongo 206 {debut}-{fin}/{file_size} "
                        f"({len(morceau)} o) pour {file_id}")
            return Response(
                content=morceau,
                status_code=206,
                media_type=content_type,
                headers={
                    "Cache-Control": "public, max-age=31536000, immutable",
                    "Content-Disposition": f'inline; filename="{original_name}"',
                    "Content-Range": f"bytes {debut}-{fin}/{file_size}",
                    "Content-Length": str(len(morceau)),
                    "Accept-Ranges": "bytes",
                },
            )

        # Pour les fichiers > 3MB, utiliser StreamingResponse
        if file_size > 3 * 1024 * 1024:
            return StreamingResponse(
                io.BytesIO(file_bytes),
                media_type=content_type,
                headers={
                    "Cache-Control": "public, max-age=31536000, immutable",
                    "Content-Disposition": f'inline; filename="{original_name}"',
                    "Content-Length": str(file_size),
                    "Accept-Ranges": "bytes"
                }
            )

        return Response(
            content=file_bytes,
            media_type=content_type,
            headers={
                "Cache-Control": "public, max-age=31536000, immutable",
                "Content-Disposition": f'inline; filename="{original_name}"',
                "Content-Length": str(file_size),
                "Accept-Ranges": "bytes"
            }
        )
    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"[FILE-SERVE] ❌ Erreur servant {file_id}: {type(e).__name__}: {str(e)}")
        raise HTTPException(status_code=500, detail=f"Erreur lecture fichier: {type(e).__name__}: {str(e)}")

# === v9.3.1: VÉRIFICATION PARTENAIRE (CÔTÉ SERVEUR) ===
@api_router.get("/check-partner/{email}")
async def check_if_partner(email: str):
    """
    Vérifie si un utilisateur est un partenaire inscrit (a un profil coach)
    Utilisé par le frontend pour afficher le bon bouton dans le chat
    v9.5.6: Super Admin a toujours accès
    """
    email = email.lower().strip()
    
    # v9.5.6: Super Admin a toujours accès illimité
    if is_super_admin(email):
        return {
            "is_partner": True,
            "email": email,
            "name": "Super Admin",
            "has_credits": True,
            "credits": -1,
            "unlimited": True,
            "is_super_admin": True
        }
    
    # Vérifier si l'email a un profil coach
    coach = await db.coaches.find_one({"email": email}, {"_id": 0, "email": 1, "name": 1, "credits": 1})
    
