def _v306_avatar_url(name: str) -> str:
    """V306 : avatar GÉNÉRÉ (DiceBear) au nom de la personne. Garantit que
    `photo_url` n'est JAMAIS vide et n'est JAMAIS une base64 périmée. La couleur de
    marque (D91CD2) est une valeur de secours portée dans l'URL de l'API externe."""
    import urllib.parse
    seed = (name or "Membre").strip() or "Membre"
    return "https://api.dicebear.com/7.x/initials/svg?seed=" + urllib.parse.quote(seed) + "&backgroundColor=D91CD2"


@api_router.get("/users/{participant_id}/profile")
async def get_user_profile(participant_id: str):
    """
    Récupère le profil utilisateur depuis la DB (PAS localStorage).
    Cherche dans 'users' puis 'chat_participants'.
    """
    # V292 : si l'identifiant est un email (coach), on prépare la photo du coach
    # depuis coach_profiles — c'est LÀ que vit sa photo, pas dans `users`. Sans
    # ça, le mini-profil coach ouvert côté client s'affichait SANS photo.
    _coach_cp = None
    if "@" in participant_id:
        _coach_cp = await db.coach_profiles.find_one({"email": participant_id}, {"_id": 0, "photo_url": 1, "display_name": 1, "bio": 1, "passions": 1})
    _coach_photo = (_coach_cp or {}).get("photo_url") or None

    # 1. Chercher dans la collection 'users'
    # V279b : on matche AUSSI par email — un profil de coach (identifie par son
    # email) doit etre trouvable pour le mini-profil ouvert depuis une publication.
    user = await db.users.find_one(
        {"$or": [{"id": participant_id}, {"participant_id": participant_id}, {"email": participant_id}]},
        {"_id": 0}
    )

    if user:
        _email_l = ((user.get("email") or (participant_id if "@" in participant_id else "")) or "").lower().strip()
        photo_url = user.get("photo_url") or user.get("photoUrl") or _coach_photo  # V292 : repli coach_profiles
        bio = user.get("bio") or ""
        age = user.get("age")
        passions = user.get("passions") or ""

        # V299 : TOUJOURS préférer une photo Cloudinary à une photo data:base64
        # (vestige lourd et périmé). Vrai pour tout le monde, pas que les coachs.
        if _email_l and ((not photo_url) or str(photo_url).startswith("data:")):
            if _coach_photo and not str(_coach_photo).startswith("data:"):
                photo_url = _coach_photo
            else:
                _cand = await db.chat_participants.find_one(
                    {"email": _email_l, "$or": [{"photo_url": {"$regex": "^https?://"}}, {"photoUrl": {"$regex": "^https?://"}}]},
                    {"_id": 0, "photo_url": 1, "photoUrl": 1}
                )
                if _cand and (_cand.get("photo_url") or _cand.get("photoUrl")):
                    photo_url = _cand.get("photo_url") or _cand.get("photoUrl")

        # V301/V306 : ne JAMAIS renvoyer une photo data:base64 (vestige périmé).
        if photo_url and str(photo_url).startswith("data:"):
            photo_url = ""
        # V306 (RÈGLE CENTRALE) : photo_url JAMAIS vide. Si aucune photo Cloudinary
        # -> avatar GÉNÉRÉ au nom réel de la personne (jamais un trou dans l'UI).
        if not photo_url:
            photo_url = _v306_avatar_url(user.get("name") or user.get("username") or (_email_l.split("@")[0] if _email_l else "Membre"))

        # V299 : compléter bio/passions manquants depuis le profil coach UNIQUEMENT
        # si l'email est un compte coach/admin CONNU (jamais de fusion entre
        # personnes différentes). On n'écrase jamais une valeur déjà présente.
        if _email_l and (not bio or not passions):
            _cp = _coach_cp
            if _cp is None:
                _cp = await db.coach_profiles.find_one({"email": _email_l}, {"_id": 0, "bio": 1, "passions": 1})
            _known = (_email_l in [e.lower() for e in SUPER_ADMIN_EMAILS]) or bool(_cp)
            if not _known:
                _ck = await db.coaches.find_one({"email": _email_l}, {"_id": 1})
                if not _ck:
                    _ck = await db.coach_auth.find_one({"email": _email_l}, {"_id": 1})
                _known = bool(_ck)
            if _known and _cp:
                if not bio and _cp.get("bio"):
                    bio = _cp.get("bio")
                if not passions and _cp.get("passions"):
                    passions = _cp.get("passions")

        return {
            "success": True,
            "source": "users",
            "participant_id": participant_id,
            "name": user.get("name") or user.get("username"),
            "email": user.get("email") or (participant_id if "@" in participant_id else None),
            "photo_url": photo_url,
            # V279 : champs mini-profil (optionnels).
            "bio": bio,
            "age": age,
            "passions": passions,
        }

    # V292 : coach identifié par email SANS doc `users` (il n'a rempli que sa
    # photo dans coach_profiles) -> renvoyer au moins photo + nom.
    if _coach_cp or (_coach_photo and "@" in participant_id):
        _cp_name = (_coach_cp or {}).get("display_name") or participant_id.split("@")[0]
        _cp_photo = _coach_photo or ""
        if str(_cp_photo).startswith("data:"):
            _cp_photo = ""
        if not _cp_photo:  # V306 : jamais vide
            _cp_photo = _v306_avatar_url(_cp_name)
        return {
            "success": True,
            "source": "coach_profiles",
            "participant_id": participant_id,
            "name": _cp_name,
            "email": participant_id,
            "photo_url": _cp_photo,
            "bio": "",
            "age": None,
            "passions": "",
        }

    # 2. Fallback: chercher dans 'chat_participants'
    participant = await db.chat_participants.find_one(
        {"id": participant_id},
        {"_id": 0}
    )

    if participant:
        _p_name = participant.get("name") or participant.get("username")
        photo_url = participant.get("photo_url") or participant.get("photoUrl") or ""
        if str(photo_url).startswith("data:"):
            photo_url = ""
        if not photo_url:  # V306 : jamais vide
            photo_url = _v306_avatar_url(_p_name or "Membre")
        return {
            "success": True,
            "source": "chat_participants",
            "participant_id": participant_id,
            "name": _p_name,
            "email": participant.get("email"),
            "photo_url": photo_url,
            # V279 : champs mini-profil (optionnels).
            "bio": participant.get("bio") or "",
            "age": participant.get("age"),
            "passions": participant.get("passions") or "",
        }

    # 3. Aucun profil trouvé -> V306 : on renvoie tout de même un avatar affichable.
    _nf_name = participant_id.split("@")[0] if "@" in participant_id else (participant_id or "Membre")
    return {
        "success": False,
        "participant_id": participant_id,
        "photo_url": _v306_avatar_url(_nf_name),
        "bio": "",
        "age": None,
        "passions": "",
        "message": "Profil non trouvé"
    }


@api_router.patch("/users/{participant_id}/profile")
async def update_user_mini_profile(participant_id: str, request: Request):
    """V279 : met a jour les champs du mini-profil (bio, age, passions).

    Champs OPTIONNELS et libres. `bio` plafonnee a 200 caracteres, `passions` a
    200 aussi. `age` doit etre un entier plausible (0-120) sinon ignore. On ecrit
    dans `users` (upsert par participant_id) — la meme collection que le GET lit
    en priorite. Aucune donnee supprimee.
    """
    # V279b (fix IDOR) : sans garde, N'IMPORTE QUI pouvait ecraser le profil de
    # N'IMPORTE QUEL participant en devinant/relevant un participant_id (ils
    # transitent dans les listes de sessions, les messages...), y compris le
    # profil d'un coach ou d'un super admin. On verrouille donc les profils
    # RATTACHES A UN COMPTE (email) ou a un admin : seuls ce compte ou un super
    # admin peuvent les editer. Les participants ANONYMES (aucun email lie)
    # restent auto-editables — c'est le modele « capability » deja en place dans
    # tout le chat (le participant_id EST l'identite du visiteur sans compte).
    existing = await db.users.find_one(
        {"$or": [{"id": participant_id}, {"participant_id": participant_id}, {"email": participant_id}]},
        {"_id": 0, "email": 1}
    )
    linked_email = ((existing or {}).get("email") or "").strip()
    # participant_id peut LUI-MEME etre un email (profil d'un coach).
    if not linked_email and "@" in participant_id:
        linked_email = participant_id.strip()
    if linked_email:
        caller = await _v263_authenticated_coach(request)  # email authentifie ou '' (sans lever)
        allowed = bool(caller) and (caller.strip().lower() == linked_email.lower() or is_super_admin(caller))
        if not allowed:
            raise HTTPException(status_code=403, detail="Accès refusé")

    body = await request.json()
    update = {}
    if "bio" in body:
        update["bio"] = (str(body.get("bio") or "")).strip()[:200]
    if "passions" in body:
        update["passions"] = (str(body.get("passions") or "")).strip()[:200]
    if "age" in body:
        try:
            _age = int(body.get("age"))
            if 0 <= _age <= 120:
                update["age"] = _age
        except (TypeError, ValueError):
            pass
    if "display_name" in body:
        update["name"] = (str(body.get("display_name") or "")).strip()[:60]
    if not update:
        return {"status": "ok", "updated": {}}
    # V291 : matcher aussi par email -> profil coach UNIFIÉ PC + mobile (le coach
    # passe son email comme identifiant au lieu d'un participantId propre à l'appareil).
    # L'autorisation est vérifiée plus haut (fix IDOR V279b) : un profil rattaché à
    # un email/admin n'est éditable QUE par ce compte ou un super admin.
    # V291b (revue sécu) : `participant_id` n'est plus écrasé sur un doc existant
    # (il partait en $set) — on ne l'écrit qu'à la CRÉATION ($setOnInsert), pour ne
    # pas remplacer le participant_id réel d'un utilisateur retrouvé par email.
    await db.users.update_one(
        {"$or": [{"id": participant_id}, {"participant_id": participant_id}, {"email": participant_id}]},
        {"$set": update, "$setOnInsert": {"participant_id": participant_id}},
        upsert=True,
    )
    return {"status": "ok", "updated": update}


# === V285 : ANNIVERSAIRES (le frontend V160 appelait ces endpoints, absents) ===
@api_router.api_route("/chat/participants/{participant_id}/birthday", methods=["PUT", "POST"])
async def save_participant_birthday(participant_id: str, request: Request):
    """V160/V285 : enregistre la date de naissance (format MM-DD) d'un participant.

    Le frontend V160 utilise PUT ; le formulaire abonné (V285) utilise POST — on
    accepte les DEUX. L'age n'est PAS public par defaut (`show_age_public`).
    """
    body = await request.json()
    birthday = (body.get("birthday") or "").strip()  # "MM-DD"
    if not birthday or len(birthday) != 5 or birthday[2] != "-":
        raise HTTPException(status_code=400, detail="Format attendu: MM-DD")

    update = {
        "birthday": birthday,
        "show_age_public": bool(body.get("show_age_public", False)),
        "birthday_updated_at": datetime.now(timezone.utc).isoformat(),
    }
    # chat_participants d'abord (l'identite chat), puis users en repli/complement.
    res = await db.chat_participants.update_one({"id": participant_id}, {"$set": update})
    await db.users.update_one(
        {"$or": [{"id": participant_id}, {"participant_id": participant_id}]},
        {"$set": update}
    )
    if res.matched_count == 0:
        # V289 : NE PLUS faire d'upsert dans db.users — ça créait des documents
        # sans name/email qui cassaient GET /users (erreur 500 -> dashboard mort).
        # Update simple : on complète si le doc existe, sinon on ne crée rien
        # (l'anniversaire reste dans chat_participants).
        await db.users.update_one(
            {"participant_id": participant_id},
            {"$set": {**update, "participant_id": participant_id}}
        )
    logger.info(f"[V285] Anniversaire enregistre: {participant_id} -> {birthday}")
    return {"success": True, "birthday": birthday}


@api_router.post("/admin/cleanup-ghost-users")
async def cleanup_ghost_users(request: Request):
    """V289 : supprime les documents `users` fantômes (sans name NI email) créés
    par d'anciens upserts birthday/photo. À appeler une seule fois après déploiement."""
    user_email = require_auth(request)
    if not is_super_admin(user_email):
        raise HTTPException(status_code=403, detail="Admin only")
    result = await db.users.delete_many({
        "$and": [
            {"$or": [{"name": {"$exists": False}}, {"name": ""}, {"name": None}]},
            {"$or": [{"email": {"$exists": False}}, {"email": ""}, {"email": None}]},
        ]
    })
    logger.info(f"[V289] Nettoyage: {result.deleted_count} documents fantômes supprimés de db.users")
    return {"status": "ok", "deleted": result.deleted_count}


@api_router.post("/admin/fix-publication-photos")
async def fix_publication_photos(request: Request):
    """V289 : migration — remplit `author_photo` des publications existantes en
    cherchant la photo dans users puis coach_profiles."""
    user_email = require_auth(request)
    if not is_super_admin(user_email):
        raise HTTPException(status_code=403, detail="Admin only")
    pubs = await db.publications.find(
        {"author_id": {"$ne": ""},
         "$or": [{"author_photo": ""}, {"author_photo": None}, {"author_photo": {"$exists": False}}]}
    ).to_list(length=500)
    fixed = 0
    for pub in pubs:
        aid = pub.get("author_id", "")
        if not aid:
            continue
        _au = await db.users.find_one({"email": aid}, {"_id": 0, "photo_url": 1, "photoUrl": 1})
        photo = (_au or {}).get("photo_url") or (_au or {}).get("photoUrl") or ""
        if not photo:
            _cp = await db.coach_profiles.find_one({"email": aid}, {"_id": 0, "photo_url": 1})
            photo = (_cp or {}).get("photo_url") or ""
        if photo:
            await db.publications.update_one({"id": pub["id"]}, {"$set": {"author_photo": photo}})
            fixed += 1
    return {"status": "ok", "fixed": fixed, "total_checked": len(pubs)}


@api_router.post("/v290-fix-publication-photos")
async def v290_fix_publication_photos():
    """V290 : migration PUBLIQUE (one-shot) — remplit `author_photo` des
    publications existantes en cherchant la photo dans users, coach_profiles puis
    chat_participants.

    Public à dessein : c'est un enrichissement IDEMPOTENT et sans entrée
    utilisateur (aucune injection, borné à 500 docs), pour pouvoir être lancé au
    curl sans buter sur l'auth admin.

    SÉCURITÉ : on n'attribue la photo qu'a l'AUTEUR RÉEL. V297 corrige le trou :
    pour une publication d'ABONNÉ (subscriber_code = un CODE), on résout l'email de
    CET abonné (subscriptions/discount_codes) puis SA propre photo — jamais celle du
    coach propriétaire. Chemin coach : `author_id`, ou `subscriber_code` s'il est un
    email de coach. (Avant V297 ces publications abonné étaient sautées -> initiales.)
    """
    pubs = await db.publications.find(
        {"$or": [{"author_photo": {"$exists": False}}, {"author_photo": ""}, {"author_photo": None}]},
        {"_id": 1, "id": 1, "coach_id": 1, "subscriber_code": 1, "author_id": 1}
    ).to_list(500)
    fixed = 0
    for pub in pubs:
        # E-mail de l'AUTEUR (jamais du coach propriétaire).
        _had_author_id = bool((pub.get("author_id") or "").strip())
        author_email = (pub.get("author_id") or "").strip()
        if not author_email:
            _sc = (pub.get("subscriber_code") or "").strip()
            if "@" in _sc:  # le chemin coach stocke l'email dans subscriber_code
                author_email = _sc
            elif _sc:
                # V297 : chemin ABONNÉ (subscriber_code = un CODE, pas un email).
                # On résout l'email de CET abonné (sa PROPRE identité), depuis
                # subscriptions/discount_codes -> sa propre photo. On ne colle JAMAIS
                # la photo du coach : author_email est celle de l'abonné, pas du coach.
                _code = _sc.strip().upper()
                _s = await db.subscriptions.find_one({"code": _code, "status": "active"}, {"_id": 0, "email": 1})
                _em = (_s or {}).get("email") or ""
                if not _em:
                    _d = await db.discount_codes.find_one({"code": _code, "active": True}, {"_id": 0, "assignedEmail": 1})
                    _em = (_d or {}).get("assignedEmail") or ""
                author_email = (_em or "").strip()
        if not author_email:
            continue  # aucun email résoluble -> initiales, on saute (pas de plantage)
        author_email = author_email.lower()  # emails stockés en minuscules
        photo = ""
        _u = await db.users.find_one({"email": author_email}, {"_id": 0, "photo_url": 1, "photoUrl": 1})
        photo = (_u or {}).get("photo_url") or (_u or {}).get("photoUrl") or ""
        if not photo:
            _cp = await db.coach_profiles.find_one({"email": author_email}, {"_id": 0, "photo_url": 1})
            photo = (_cp or {}).get("photo_url") or ""
        if not photo:
            _ch = await db.chat_participants.find_one({"email": author_email}, {"_id": 0, "photo_url": 1, "photoUrl": 1})
            photo = (_ch or {}).get("photo_url") or (_ch or {}).get("photoUrl") or ""
        if photo:
            _upd = {"author_photo": photo}
            # V297 : rendre AUSSI l'avatar cliquable (author_id résoluble par
            # GET /users/{id}/profile) quand il manquait — cas des publications abonné.
            if not _had_author_id:
                _upd["author_id"] = author_email
            await db.publications.update_one({"_id": pub["_id"]}, {"$set": _upd})
            fixed += 1
    return {"status": "ok", "fixed": fixed, "total_checked": len(pubs)}


@api_router.post("/v299-fix-legacy-profile-photos")
async def v299_fix_legacy_profile_photos():
    """V299 : migration PUBLIQUE (one-shot, idempotente) — remplace les photos de
    profil `data:image/...;base64,...` (vestiges lourds/périmés) par une photo
    Cloudinary trouvée pour le MÊME email (coach_profiles / users / chat_participants),
    et complète bio/passions si vides. NE SUPPRIME RIEN, ne fusionne JAMAIS deux
    personnes (recherche par email exact uniquement). Bornée à 500 docs.

    Publique à dessein (aucune entrée utilisateur, idempotente), lançable au curl.
    """
    users = await db.users.find(
        {"photo_url": {"$regex": "^data:"}},
        {"_id": 1, "email": 1, "bio": 1, "passions": 1}
    ).to_list(500)
    fixed = 0
    for u in users:
        email = (u.get("email") or "").lower().strip()
        if not email:
            continue
        # Chercher une VRAIE photo (http/https) pour cet email.
        cloud = ""
        _cp = await db.coach_profiles.find_one(
            {"email": email, "photo_url": {"$regex": "^https?://"}}, {"_id": 0, "photo_url": 1, "bio": 1, "passions": 1}
        )
        if _cp:
            cloud = _cp.get("photo_url") or ""
        if not cloud:
            _ou = await db.users.find_one(
                {"email": email, "photo_url": {"$regex": "^https?://"}}, {"_id": 0, "photo_url": 1}
            )
            cloud = (_ou or {}).get("photo_url") or ""
        if not cloud:
            _ch = await db.chat_participants.find_one(
                {"email": email, "photo_url": {"$regex": "^https?://"}}, {"_id": 0, "photo_url": 1}
            )
            cloud = (_ch or {}).get("photo_url") or ""
        set_fields = {}
        if cloud:
            set_fields["photo_url"] = cloud
            set_fields["photoUrl"] = cloud
        # Compléter bio/passions vides depuis coach_profiles (même personne).
        if _cp:
            if not (u.get("bio") or "") and _cp.get("bio"):
                set_fields["bio"] = _cp.get("bio")
            if not (u.get("passions") or "") and _cp.get("passions"):
                set_fields["passions"] = _cp.get("passions")
        if set_fields:
            await db.users.update_one({"_id": u["_id"]}, {"$set": set_fields})
            fixed += 1
    return {"status": "ok", "fixed": fixed, "total_checked": len(users)}


async def _v301_find_cloud_photo(email: str) -> str:
    """V301 : cherche une photo Cloudinary (http/https) pour un email, dans
    coach_profiles PUIS users PUIS chat_participants (photo_url ou photoUrl)."""
    email = (email or "").lower().strip()
    if not email:
        return ""
    for coll in (db.coach_profiles, db.users, db.chat_participants):
        d = await coll.find_one(
            {"email": email, "$or": [{"photo_url": {"$regex": "^https?://"}}, {"photoUrl": {"$regex": "^https?://"}}]},
            {"_id": 0, "photo_url": 1, "photoUrl": 1},
        )
        if d:
            p = d.get("photo_url") or d.get("photoUrl") or ""
            if p and str(p).startswith("http"):
                return p
    return ""


@api_router.post("/v301-fix-legacy-profile-photos")
async def v301_fix_legacy_profile_photos(request: Request):
    """V301 : migration (idempotente) — corrige la V299 qui ne balayait que
    `users.photo_url`. Elle balaie maintenant users, chat_participants ET
    coach_profiles, sur `photo_url` ET `photoUrl` (camelCase — c'est là que vivait
    souvent la base64). Pour chaque photo `data:` : si une photo Cloudinary existe
    pour le MÊME email -> on la substitue ; sinon on retire la base64 périmée (mise à
    "" -> avatar généré côté client). Aucune fusion entre emails DIFFÉRENTS.

    SÉCURITÉ (V301) : contrairement aux migrations d'enrichissement (v290/v299, en
    lecture-écriture idempotente sans perte), celle-ci peut RETIRER des photos
    (blanchiment des base64). Elle est donc réservée au SUPER ADMIN authentifié
    (JWT signé ou repli X-User-Email), pour qu'un tiers ne puisse pas la déclencher
    en boucle. Le propriétaire la lance avec son en-tête d'identité (voir bilan)."""
    _caller = await _v263_authenticated_coach(request)
    if not _caller or not is_super_admin(_caller):
        raise HTTPException(status_code=403, detail="Réservé au super admin")
    total = 0
    fixed = 0
    blanked = 0
    for coll in (db.users, db.chat_participants, db.coach_profiles):
        docs = await coll.find(
            {"$or": [{"photo_url": {"$regex": "^data:"}}, {"photoUrl": {"$regex": "^data:"}}]},
            {"_id": 1, "email": 1},
        ).to_list(2000)
        for d in docs:
            total += 1
            email = (d.get("email") or "").lower().strip()
            cloud = await _v301_find_cloud_photo(email) if email else ""
            if cloud:
                await coll.update_one({"_id": d["_id"]}, {"$set": {"photo_url": cloud, "photoUrl": cloud}})
                fixed += 1
            else:
                # Pas de Cloudinary pour cet email -> on retire la base64 (jamais
                # affichée) ; le client génère un avatar. On ne supprime pas le doc.
                await coll.update_one({"_id": d["_id"]}, {"$set": {"photo_url": "", "photoUrl": ""}})
                blanked += 1
    return {"status": "ok", "fixed": fixed, "blanked": blanked, "total_checked": total}


@api_router.post("/v306-fix-empty-profile-photos")
async def v306_fix_empty_profile_photos(request: Request):
    """V306 : remplit `photo_url` là où il est VIDE ou `data:` (régression V305 qui
    blanchissait sans rien remettre). Chaîne de repli STRICTE, toujours non vide :
    photo Cloudinary du MÊME email (users/coach_profiles/chat_participants,
    photo_url ET photoUrl) -> sinon avatar GÉNÉRÉ (DiceBear) au nom de la personne.
    JAMAIS de base64, JAMAIS de vide. Aucune fusion entre emails différents.

    Réservée au SUPER ADMIN (comme la migration v301, elle écrit en base)."""
    _caller = await _v263_authenticated_coach(request)
    if not _caller or not is_super_admin(_caller):
        raise HTTPException(status_code=403, detail="Réservé au super admin")
    total = 0
    fixed = 0
    for coll in (db.users, db.chat_participants, db.coach_profiles):
        docs = await coll.find(
            {"$or": [
                {"photo_url": {"$in": [None, ""]}},
                {"photo_url": {"$regex": "^data:"}},
                {"photo_url": {"$exists": False}},
            ]},
            {"_id": 1, "email": 1, "name": 1, "username": 1, "display_name": 1, "photo_url": 1, "photoUrl": 1},
        ).to_list(3000)
        for d in docs:
            total += 1
            # 1) Cloudinary du même email
            email = (d.get("email") or "").lower().strip()
            cloud = await _v301_find_cloud_photo(email) if email else ""
            # 2) sinon avatar généré au nom réel
            if cloud:
                new_photo = cloud
            else:
                name = d.get("name") or d.get("username") or d.get("display_name") or (email.split("@")[0] if email else "Membre")
                new_photo = _v306_avatar_url(name)
            await coll.update_one({"_id": d["_id"]}, {"$set": {"photo_url": new_photo, "photoUrl": new_photo}})
            fixed += 1
    return {"status": "ok", "fixed": fixed, "total_checked": total}


@api_router.get("/birthdays/today")
async def get_today_birthdays():
    """V160/V285 : participants dont c'est l'anniversaire aujourd'hui (par MM-DD)."""
    today = datetime.now(timezone.utc)
    today_mm_dd = f"{today.month:02d}-{today.day:02d}"
    birthdays = []
    seen = set()

    async for p in db.chat_participants.find(
        {"birthday": today_mm_dd},
        {"_id": 0, "id": 1, "name": 1, "username": 1, "photo_url": 1, "photoUrl": 1}
    ):
        pid = p.get("id")
        if pid and pid in seen:
            continue
        if pid:
            seen.add(pid)
        birthdays.append({
            "id": pid,
            "name": p.get("name") or p.get("username") or "Membre",
            "photo_url": p.get("photo_url") or p.get("photoUrl"),
        })

    async for u in db.users.find(
        {"birthday": today_mm_dd},
        {"_id": 0, "id": 1, "participant_id": 1, "name": 1, "username": 1, "photo_url": 1, "photoUrl": 1}
    ):
        uid = u.get("id") or u.get("participant_id")
        if uid and uid in seen:
            continue
        if uid:
            seen.add(uid)
        birthdays.append({
            "id": uid,
            "name": u.get("name") or u.get("username") or "Membre",
            "photo_url": u.get("photo_url") or u.get("photoUrl"),
        })

    return {"birthdays": birthdays, "count": len(birthdays)}


# === V292 : traduction de messages à la demande (réutilise l'IA OpenAI) ===
# V302 : noms de langue PRÉCIS avec code ISO 639-3 -> lèvent l'ambiguïté (« bassa »
# désigne aussi une langue du Liberia ; sans ISO, l'IA se trompait de langue).
_V292_LANGS = {
    "fr": "français", "en": "anglais", "de": "allemand",
    "it": "italien", "es": "espagnol", "pt": "portugais",
    "ln": "lingala (lingála), langue bantoue du Congo — ISO 639-3 : lin",
    "wo": "wolof (wolof làkk), langue du Sénégal — ISO 639-3 : wol",
    "sw": "kiswahili (swahili standard) — ISO 639-3 : swh",
    "bm": "bambara (bamanankan), langue mandingue du Mali — ISO 639-3 : bam",
    "bas": "bàsàa (basaa), langue bantoue A43 du Cameroun, régions du Centre et du Littoral — code ISO 639-3 : bas",
    "ht": "kreyòl ayisyen (créole haïtien) — ISO 639-3 : hat",
}


def _v299_norm_lang(s: str) -> str:
    """V299 : normalise une chaîne de langue (minuscules, sans accents, compacte)
    pour comparer indifféremment « Wolof », « wolof », « wo », « Kiswahili »…"""
    import unicodedata
    s = (s or "").strip().lower()
    s = "".join(c for c in unicodedata.normalize("NFD", s) if unicodedata.category(c) != "Mn")
    return s


# V299 : index inverse NOM -> code (en plus des codes eux-mêmes) + quelques
# endonymes/alias envoyés par le frontend (name affiché) que _V292_LANGS ne liste
# pas tel quel. Toute valeur reconnue ici renvoie un code valide -> plus de 400
# pour une langue de la liste du site.
_V299_LANG_INDEX = {}
for _c, _n in _V292_LANGS.items():
    _V299_LANG_INDEX[_v299_norm_lang(_c)] = _c
    _V299_LANG_INDEX[_v299_norm_lang(_n)] = _c
for _alias, _c in {
    "english": "en", "deutsch": "de", "kiswahili": "sw", "swahili": "sw",
    "kreyol": "ht", "creole": "ht", "creole haitien": "ht", "haitien": "ht",
    "bassa": "bas", "bassa (cameroun)": "bas", "italiano": "it", "espanol": "es",
    "espanol ": "es", "portugues": "pt", "francais": "fr",
}.items():
    _V299_LANG_INDEX[_v299_norm_lang(_alias)] = _c


def _v299_resolve_lang(raw: str):
    """Renvoie (code, nom_complet) pour un code OU un nom de langue, sinon (None, None)."""
    key = _v299_norm_lang(raw)
    code = _V299_LANG_INDEX.get(key)
    if not code:
        return None, None
    return code, _V292_LANGS[code]


# ============================================================================
# V302 — QUALITÉ DES TRADUCTIONS EN LANGUES AFRICAINES
# ============================================================================
# Les modèles d'IA ont TRÈS PEU de données sur le bàsàa, le bambara, le wolof ou
# le lingala. On ne peut pas garantir une qualité de locuteur natif, mais on
# améliore nettement avec : (1) un LEXIQUE VÉRIFIÉ (recherche web documentée) qui
# fait AUTORITÉ — correspondance directe SANS IA quand le texte correspond, et
# injection dans le prompt sinon ; (2) des consignes strictes ; (3) un modèle plus
# capable (gpt-4o) pour ces langues.
#
# ⚠️ ENRICHISSABLE : ce lexique est destiné à être complété par le coach et sa
# communauté — ce sont EUX les locuteurs, pas l'IA. Une future version exposera
# une interface d'ajout/correction (cf. FIX 5, non implémenté ici). Clé = français
# normalisé (minuscules, sans accents ni ponctuation) ; valeur = traduction de
# référence, orthographe et tons CONSERVÉS TELS QUELS (ɓ, ŋ, ɛ, ɔ, è, é, ô, à…).
#
# Orthographe : en cas de divergence entre sources, on privilégie Wikipédia et
# Resulam (ex. « mɛ̀ ǹyega », « i ŋkɛ laa ? ») au blog « Apprendre le Bassa »
# (qui reconnaît lui-même une orthographe approximative).

def _v302_norm(s: str) -> str:
    """Normalise un texte français pour la correspondance de lexique :
    minuscules, sans accents, sans ponctuation, espaces compactés."""
    import unicodedata
    import re as _re
    s = (s or "").strip().lower()
    s = "".join(c for c in unicodedata.normalize("NFD", s) if unicodedata.category(c) != "Mn")
    s = _re.sub(r"[^\w\s]", " ", s)
    s = _re.sub(r"\s+", " ", s).strip()
    return s


