# --- Concept ---
# v9.3.0: Isolation par coach_id - chaque coach a sa propre configuration
@api_router.get("/concept", response_model=Concept)
async def get_concept(request: Request):
    user_email = request.headers.get('X-User-Email', '').lower().strip()
    is_admin = is_super_admin(user_email)  # v9.5.6

    # Si pas d'email (visiteur sur la vitrine App.js), charger le concept admin
    if not user_email:
        is_admin = True

    # Super Admin: concept global, Coach: concept personnel
    concept_id = "concept" if is_admin else f"concept_{user_email}"
    
    concept = await db.concept.find_one({"id": concept_id}, {"_id": 0})
    if not concept:
        # Créer un concept par défaut pour ce coach
        default_concept = Concept().model_dump()
        default_concept["id"] = concept_id
        default_concept["coach_id"] = user_email if not is_admin else None
        await db.concept.insert_one(default_concept)
        return default_concept
    return concept

@api_router.put("/concept")
async def update_concept(concept: ConceptUpdate, request: Request):
    # V262: ecriture -> identite verifiee. Auparavant un en-tete vide creait un
    # concept « concept_ » fantome, et un en-tete falsifie ecrivait chez autrui.
    user_email = require_auth(request)
    is_admin = is_super_admin(user_email)  # v9.5.6
    
    # Super Admin: concept global, Coach: concept personnel
    concept_id = "concept" if is_admin else f"concept_{user_email}"
    
    try:
        updates = {k: v for k, v in concept.model_dump().items() if v is not None}
        # V259: l'affiche evenement est un popup impose a TOUS les visiteurs des
        # l'arrivee — sa gestion est reservee a l'administration. Le masquage
        # cote dashboard (ConceptEditor) n'est qu'un confort d'interface : sans
        # ce filtre, un PUT direct la reactiverait.
        # Union avec `is_admin` (SUPER_ADMIN_EMAILS) pour la meme raison que
        # cote front : la liste ci-dessous ne recouvre pas SUPER_ADMIN_EMAILS,
        # et s'y tenir seule retirerait l'acces a un super admin en place.
        # Les champs sont RETIRES de la mise a jour, pas rejetes en erreur : le
        # reste du formulaire (logo, couleurs, CGV...) doit continuer de
        # s'enregistrer normalement pour un coach ordinaire.
        V259_POSTER_ADMIN_EMAILS = ["contact.artboost@gmail.com", "contact@afroboosteur.com"]
        if not (is_admin or user_email in V259_POSTER_ADMIN_EMAILS):
            for _f in ("eventPosterEnabled", "eventPosterMediaUrl",
                       "eventPosterReserveLabel", "eventPosterOffersLabel"):
                updates.pop(_f, None)
        updates["coach_id"] = user_email if not is_admin else None
        result = await db.concept.update_one({"id": concept_id}, {"$set": updates}, upsert=True)
        updated = await db.concept.find_one({"id": concept_id}, {"_id": 0})
        return updated
    except Exception as e:
        logger.error(f"Error updating concept: {e}")
        raise HTTPException(status_code=500, detail=str(e))

