@api_router.get("/og/{username}")
async def get_og_meta(username: str, request: Request):
    """v17.1: HTML OpenGraph pour crawlers (WhatsApp, Instagram, Facebook)"""
    from starlette.responses import HTMLResponse

    # Trouver le coach — même logique que coach/vitrine
    SUPER_ADMIN_EMAILS = ['contact.artboost@gmail.com', 'afroboost.bassi@gmail.com']
    # v65: Redirection 301 pour "artboost" → "bassi"
    if username.lower() == "artboost":
        from starlette.responses import RedirectResponse as RR
        return RR(url="/api/og/bassi", status_code=301)
    if username.lower() in ["bassi", "afroboost"]:
        coach = {"name": "Bassi - Afroboost", "email": "contact.artboost@gmail.com", "platform_name": "Afroboost"}
    else:
        coach = await db.coaches.find_one(
            {"$or": [
                {"username": username.lower()},
                {"name": {"$regex": f"^{re.escape(username)}$", "$options": "i"}},
                {"email": username.lower()},
                {"id": username}
            ]},
            {"_id": 0}
        )

    if not coach:
        return HTMLResponse("<html><head><title>Afroboost</title></head><body>Coach not found</body></html>", status_code=404)

    title = coach.get("meta_title") or f"{coach.get('platform_name') or coach.get('name', username)} | Afroboost"
    description = coach.get("meta_description") or f"Découvrez les cours et services de {coach.get('name', username)} sur Afroboost"
    image = coach.get("logo_url") or "https://afroboost-v11-dev-pm7l.vercel.app/logo192.png"
    url = f"https://afroboost-v11-dev-pm7l.vercel.app/coach/{username}"
    accent = coach.get("accent_color", "#D91CD2")

    html = f"""<!DOCTYPE html>
<html lang="fr">
<head>
    <meta charset="utf-8"/>
    <title>{title}</title>
    <meta name="description" content="{description}"/>
    <meta name="theme-color" content="{accent}"/>

    <!-- OpenGraph -->
    <meta property="og:type" content="website"/>
    <meta property="og:title" content="{title}"/>
    <meta property="og:description" content="{description}"/>
    <meta property="og:image" content="{image}"/>
    <meta property="og:url" content="{url}"/>
    <meta property="og:site_name" content="Afroboost"/>

    <!-- Twitter Card -->
    <meta name="twitter:card" content="summary_large_image"/>
    <meta name="twitter:title" content="{title}"/>
    <meta name="twitter:description" content="{description}"/>
    <meta name="twitter:image" content="{image}"/>

    <meta http-equiv="refresh" content="0;url={url}"/>
</head>
<body>
    <h1>{title}</h1>
    <p>{description}</p>
    <a href="{url}">Voir la page</a>
</body>
</html>"""
    return HTMLResponse(html)

@api_router.get("/share/offer/{offer_id}")
async def share_offer_page(offer_id: str):
    """V278 : page de partage d'une offre avec balises Open Graph.

    Quand un visiteur partage une offre (WhatsApp, Facebook...), le crawler du
    reseau charge CETTE page et lit les balises og:* pour composer l'apercu
    (image de l'offre + titre + prix). Un vrai navigateur, lui, est redirige
    aussitot vers le site. Tout est ECHAPPE (html.escape) : le nom et la
    description viennent de la base, on ne les injecte jamais bruts dans le HTML.
    """
    from starlette.responses import HTMLResponse
    import html as _html

    FRONT = "https://afroboost.com"
    offer = await db.offers.find_one({"id": offer_id}, {"_id": 0})
    if not offer:
        from starlette.responses import RedirectResponse as RR
        return RR(url=FRONT, status_code=302)

    def _abs(u):
        u = (u or "").strip()
        if not u:
            return f"{FRONT}/logo192.png"
        if u.startswith("http://") or u.startswith("https://"):
            return u
        if u.startswith("/"):
            return FRONT + u
        return f"{FRONT}/logo192.png"

    name = offer.get("name") or "Offre Afroboost"
    price = offer.get("price")
    title = f"{name} - {price} CHF" if price not in (None, "", 0) else name
    description = (offer.get("description") or "Découvrez cette offre sur Afroboost")[:200]
    # Image : miniature, sinon 1re image du tableau, sinon logo.
    img_src = offer.get("thumbnail") or ""
    if not img_src and isinstance(offer.get("images"), list) and offer["images"]:
        img_src = offer["images"][0]
    image = _abs(img_src)

    # Echappement pour usage en attribut HTML (quote=True protege " et ').
    e_title = _html.escape(title, quote=True)
    e_desc = _html.escape(description, quote=True)
    e_image = _html.escape(image, quote=True)
    e_url = _html.escape(f"{FRONT}/share/offer/{offer_id}", quote=True)

    html_page = f"""<!DOCTYPE html>
<html lang="fr">
<head>
    <meta charset="utf-8"/>
    <title>{e_title}</title>
    <meta name="description" content="{e_desc}"/>
    <meta property="og:type" content="product"/>
    <meta property="og:title" content="{e_title}"/>
    <meta property="og:description" content="{e_desc}"/>
    <meta property="og:image" content="{e_image}"/>
    <meta property="og:url" content="{e_url}"/>
    <meta property="og:site_name" content="Afroboost"/>
    <meta name="twitter:card" content="summary_large_image"/>
    <meta name="twitter:title" content="{e_title}"/>
    <meta name="twitter:description" content="{e_desc}"/>
    <meta name="twitter:image" content="{e_image}"/>
    <meta http-equiv="refresh" content="0;url={FRONT}"/>
</head>
<body>
    <h1>{e_title}</h1>
    <p>{e_desc}</p>
    <a href="{FRONT}">Voir sur Afroboost</a>
</body>
</html>"""
    return HTMLResponse(html_page)

@api_router.get("/sitemap.xml")
async def get_sitemap():
    """v17.1: Sitemap XML dynamique"""
    from starlette.responses import Response

    base_url = "https://afroboost-v11-dev-pm7l.vercel.app"
    now = datetime.now(timezone.utc).strftime('%Y-%m-%d')

    urls = [
        f'  <url><loc>{base_url}/</loc><lastmod>{now}</lastmod><priority>1.0</priority></url>',
        f'  <url><loc>{base_url}/devenir-coach</loc><lastmod>{now}</lastmod><priority>0.8</priority></url>'
    ]

    # Ajouter toutes les vitrines de coachs actifs
    coaches = await db.coaches.find(
        {"is_active": {"$ne": False}},
        {"_id": 0, "username": 1, "name": 1}
    ).to_list(200)

    for c in coaches:
        slug = c.get("username") or c.get("name", "").lower().replace(" ", "-")
        if slug:
            urls.append(f'  <url><loc>{base_url}/coach/{slug}</loc><lastmod>{now}</lastmod><priority>0.7</priority></url>')

    xml = f"""<?xml version="1.0" encoding="UTF-8"?>
<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">
{chr(10).join(urls)}
</urlset>"""

    return Response(content=xml, media_type="application/xml")


