    body = await request.json()
    email = request.headers.get('X-User-Email', '').lower().strip()
    if not email:
        raise HTTPException(status_code=401, detail="Email requis")

    updates = {}
    for field in ["question", "answer", "category", "order"]:
        if field in body:
            updates[field] = body[field]
