# --- v17.3: Import Auto Contacts ---
@api_router.post("/contacts/check-duplicates")
async def check_duplicate_contacts(request: Request):
    """Vérifie les doublons dans la liste de contacts importés"""
    body = await request.json()
    phones = [p.strip() for p in body.get("phones", []) if p.strip()]
    emails = [e.strip().lower() for e in body.get("emails", []) if e.strip()]
    coach_email = request.headers.get('X-User-Email', '').lower().strip()

    if not coach_email:
        raise HTTPException(status_code=401, detail="Email requis")

    existing_phones = set()
    existing_emails = set()

    # v68: Isolation multi-tenant — ne chercher les doublons que dans les contacts du coach
    coach_filter = {} if is_super_admin(coach_email) else {"coach_id": coach_email}

    if phones:
        phone_query = {**coach_filter, "phone": {"$in": phones}}
        cursor = db.chat_participants.find(phone_query, {"_id": 0, "phone": 1})
        async for doc in cursor:
            if doc.get("phone"):
                existing_phones.add(doc["phone"])

    if emails:
        email_query = {**coach_filter, "email": {"$in": emails}}
        cursor = db.chat_participants.find(email_query, {"_id": 0, "email": 1})
        async for doc in cursor:
            if doc.get("email"):
                existing_emails.add(doc["email"].lower())

    return {
        "existing_phones": list(existing_phones),
        "existing_emails": list(existing_emails),
        "total_checked": len(phones) + len(emails)
    }


# ============================================================
# CONTACTS UNIFIÉS — v18: Merge participants + users + groupes
# ============================================================

@api_router.post("/contacts/deduplicate")
async def deduplicate_contacts(request: Request):
    """v104: Nettoie les doublons existants dans chat_participants.
    Fusionne par email (case-insensitive) ou phone normalisé.
    Garde le contact le plus ancien (created_at), met à jour avec les infos des doublons."""
    caller_email = request.headers.get("X-User-Email", "").lower().strip()
    if not caller_email:
        raise HTTPException(status_code=401, detail="Email requis")

    try:
        # Récupérer tous les contacts du coach
        query = {} if is_super_admin(caller_email) else {"coach_id": caller_email}
        all_contacts = await db.chat_participants.find(query, {"_id": 0}).to_list(10000)

        # Grouper par email normalisé
        email_groups = {}
        phone_groups = {}
        for c in all_contacts:
            email = (c.get("email") or "").strip().lower()
            phone = (c.get("whatsapp") or c.get("phone") or "").replace(" ", "").replace("-", "").replace("+", "")
            if email:
                email_groups.setdefault(email, []).append(c)
            elif phone:
                phone_groups.setdefault(phone, []).append(c)

        merged = 0
        deleted_ids = []

        # Fusionner les doublons email
        for email, contacts in email_groups.items():
            if len(contacts) <= 1:
                continue
            # Garder le plus ancien
            contacts.sort(key=lambda x: x.get("created_at", ""))
            keeper = contacts[0]
            for dup in contacts[1:]:
                # Transférer les infos manquantes du doublon vers le keeper
                updates = {}
                if not keeper.get("whatsapp") and dup.get("whatsapp"):
                    updates["whatsapp"] = dup["whatsapp"]
                if not keeper.get("phone") and dup.get("phone"):
                    updates["phone"] = dup["phone"]
                if not keeper.get("name") or keeper["name"] == "Sans nom":
                    if dup.get("name") and dup["name"] != "Sans nom":
                        updates["name"] = dup["name"]
                # Fusionner tags
                keeper_tags = set(keeper.get("tags", []))
                dup_tags = set(dup.get("tags", []))
                if dup_tags - keeper_tags:
                    updates["tags"] = list(keeper_tags | dup_tags)
                if updates:
                    await db.chat_participants.update_one({"id": keeper["id"]}, {"$set": updates})
                    keeper.update(updates)
                # Supprimer le doublon
                await db.chat_participants.delete_one({"id": dup["id"]})
                deleted_ids.append(dup["id"])
                merged += 1

        # Fusionner les doublons phone (ceux sans email)
        for phone, contacts in phone_groups.items():
            if len(contacts) <= 1:
                continue
            contacts.sort(key=lambda x: x.get("created_at", ""))
            keeper = contacts[0]
            for dup in contacts[1:]:
                updates = {}
                if not keeper.get("email") and dup.get("email"):
                    updates["email"] = dup["email"]
                if not keeper.get("name") or keeper["name"] == "Sans nom":
                    if dup.get("name") and dup["name"] != "Sans nom":
                        updates["name"] = dup["name"]
                keeper_tags = set(keeper.get("tags", []))
                dup_tags = set(dup.get("tags", []))
                if dup_tags - keeper_tags:
                    updates["tags"] = list(keeper_tags | dup_tags)
                if updates:
                    await db.chat_participants.update_one({"id": keeper["id"]}, {"$set": updates})
                    keeper.update(updates)
                await db.chat_participants.delete_one({"id": dup["id"]})
                deleted_ids.append(dup["id"])
                merged += 1

        # Mettre à jour les sessions qui référencent les contacts supprimés
        if deleted_ids:
            logger.info(f"[DEDUP] {merged} doublons fusionnés, IDs supprimés: {deleted_ids[:10]}...")

        return {
            "success": True,
            "merged": merged,
            "deleted_ids": deleted_ids,
            "total_before": len(all_contacts),
            "total_after": len(all_contacts) - merged
        }
    except Exception as e:
        logger.error(f"[DEDUP] Erreur: {e}")
        return {"success": False, "error": str(e)}

@api_router.get("/contacts/all")
async def get_all_contacts_unified(request: Request):
    """
    Endpoint unifié qui fusionne chat_participants, users, et groupes
    pour la sélection de destinataires dans les campagnes.
    Dédupliqué par email/phone. Retourne groupes + contacts individuels.
    """
    # V311h — GROUPE 1 : JWT-strict. X-User-Email n'accorde plus aucun droit ici.
    caller_email = _v311_coach_email_from_jwt(request)
    if not caller_email or not await _v309_is_coach_or_admin(caller_email):
        raise HTTPException(status_code=403, detail="Authentification coach requise — reconnectez-vous")

    try:
        contacts = []
        seen_emails = set()
        seen_phones = set()

        # =============================================================
        # P1-A.2 — LES SIX LECTURES PARTENT ENSEMBLE
        # =============================================================
        #
        # Elles etaient AWAITEES l'une apres l'autre, dispersees dans la
        # fonction : le temps total valait leur SOMME. Or aucune ne consomme le
        # resultat d'une autre — verifie argument par argument :
        #
        #   chat_sessions      aucun argument variable
        #   chat_participants  filtre sur `caller_email` (venu du JWT)
        #   users              aucun argument
        #   subscriber_infos   filtre `_si_query`, derive de `caller_email` par
        #                      `is_super_admin()` — fonction PURE, aucune lecture
        #   subscriptions      `c2_index_abonnements()`  — ZERO argument
        #   subscribers        `c2_index_consentements()` — ZERO argument
        #
        # Le temps devient donc leur MAXIMUM. L'ORDRE DU TRAITEMENT, lui, est
        # rigoureusement conserve plus bas : groupes, puis participants (source
        # PRIORITAIRE pour la deduplication), puis users. Paralleliser les
        # lectures ne change pas qui gagne un doublon.
        #
        # `return_exceptions=True` preserve la degradation gracieuse existante :
        # un echec sur `subscriber_infos` ou sur les index Contacts V2 doit
        # seulement PRIVER DE L'ENRICHISSEMENT, comme avant, pas vider la liste.
        # Les trois lectures structurantes, elles, remontent leur exception au
        # `except` global — comportement inchange lui aussi.
        # P1-A.1 — NE FAIRE DESCENDRE QUE CE QU'ON LIT.
        #
        # Cette lecture ramenait le document ENTIER (`{"_id": 0}` n'exclut que
        # `_id`). Mesure sur la base reelle : 667 Ko pour 1 353 fiches, dont
        # 398 Ko (60 %) de champs que cette fonction ne lit JAMAIS. Le cout etant
        # PROPORTIONNEL AUX OCTETS (debit constant vers Atlas, ~75 Ko/s), cette
        # seule lecture pesait 6,8 s sur les 8,5 s de la fonction.
        #
        # La liste ci-dessous est EXACTEMENT celle des huit champs lus plus bas
        # (`p.get(...)`). Chaque champ ecarte l'a ete apres verification :
        #   - photo_url / photoUrl / created_at / last_seen_at / updated_at /
        #     link_token : jamais lus ici ;
        #   - coach_id : sert au FILTRE, pas a la reponse ;
        #   - birthday / code / subscriptionCode : la reponse les tire de
        #     `subscriber_infos` (enrichissement V300 plus bas) ;
        #   - isSubscriber : `c2_index_abonnements` refuse deliberement de s'y fier ;
        #   - categories / contact_type_set_at / contact_type_set_by / objectifs /
        #     show_age_public / birthday_updated_at : jamais recopies dans la fiche.
        #
        # CONTACTS V2 EST INTACT : `contact_type` est conserve, et les quatre
        # dimensions derivees se calculent depuis `email`, `whatsapp` et `phone`.
        _P1A_CHAMPS_CONTACT = {
            "_id": 0, "id": 1, "name": 1, "email": 1, "whatsapp": 1,
            "phone": 1, "source": 1, "contact_type": 1, "tags": 1,
        }

        _si_query = {} if is_super_admin(caller_email) else {"coach_id": caller_email}
        _filtre_participants = {} if is_super_admin(caller_email) else {"coach_id": caller_email}

        (
            sessions, participants, all_users, infos, _abos, _cons,
        ) = await asyncio.gather(
            db.chat_sessions.find(
                {"is_deleted": {"$ne": True}},
                {"_id": 0, "id": 1, "mode": 1, "title": 1, "participant_ids": 1, "updated_at": 1}
            ).sort("updated_at", -1).to_list(500),
            db.chat_participants.find(_filtre_participants, _P1A_CHAMPS_CONTACT).to_list(5000),
            db.users.find({}, {"_id": 0, "id": 1, "name": 1, "email": 1, "created_at": 1}).to_list(5000),
            db.subscriber_infos.find(
                _si_query, {"_id": 0, "email": 1, "whatsapp": 1, "birthday": 1, "code": 1}
            ).to_list(5000),
            c2_index_abonnements(),
            c2_index_consentements(),
            return_exceptions=True,
        )

        # Les trois lectures STRUCTURANTES : une exception se comporte comme avant,
        # c'est-a-dire qu'elle remonte au `except` global de la fonction.
        for _lecture in (sessions, participants, all_users):
            if isinstance(_lecture, BaseException):
                raise _lecture

        # 1. GROUPES — Sessions avec titre ou mode groupe

        for session in sessions:
            title = (session.get("title") or "").strip()
            mode = session.get("mode", "user")
            if title or mode in ["community", "vip", "promo", "group"]:
                mode_names = {"community": "Communauté", "vip": "VIP", "promo": "Offres Spéciales", "group": "Groupe"}
                contacts.append({
                    "id": session.get("id", ""),
                    "name": title or mode_names.get(mode, f"Groupe {mode}"),
                    "type": "group",
                    "category": mode,
                    "phone": None,
                    "email": None,
                    "source": "session",
                    "member_count": len(session.get("participant_ids", []))
                })

        # Groupes standards si manquants
        existing_ids = set(c["id"] for c in contacts)
        for gid, gname in [("community", "Communauté Générale"), ("vip", "Groupe VIP"), ("promo", "Offres Spéciales")]:
            if gid not in existing_ids:
                contacts.append({
                    "id": gid, "name": gname, "type": "group",
                    "category": gid, "phone": None, "email": None,
                    "source": "default", "member_count": 0
                })

        # v108: Construction d'un index ID→email pour déduplication cohérente
        # chat_participants est la source PRIORITAIRE (CRM du coach)
        seen_ids = set()

        # 2. CHAT_PARTICIPANTS — Contacts CRM (imports, stripe, chat) — SOURCE PRIORITAIRE
        #
        # P1-A.1 — NE FAIRE DESCENDRE QUE CE QU'ON LIT.
        #
        # Cette lecture ramenait le document ENTIER (`{"_id": 0}` n'exclut que
        # `_id`). Mesure sur la base reelle : 667 Ko pour 1 353 fiches, dont
        # 398 Ko (60 %) de champs que cette fonction ne lit JAMAIS.
        #
        # Or le cout est PROPORTIONNEL AUX OCTETS, pas au nombre d'allers-retours :
        # le debit mesure vers Atlas est constant, ~75 Ko/s, projection ou non.
        # Cette seule lecture pesait donc 6,8 s sur les 8,5 s de la fonction, et
        # c'est elle qui explique le TTFB de 7,73 s observe en production.
        #
        # La projection ci-dessous liste EXACTEMENT les huit champs lus plus bas
        # (`p.get(...)`), ni plus ni moins. Chaque champ ecarte l'a ete apres
        # verification qu'aucune ligne de cette fonction ne le lit :
        #   - photo_url / photoUrl / created_at / last_seen_at / updated_at /
        #     link_token : jamais lus ici ;
        #   - coach_id : sert au FILTRE de la requete (ci-dessous), pas a la
        #     reponse — filtrer n'exige pas de rapatrier le champ ;
        #   - birthday / code / subscriptionCode : la reponse les tire de
        #     `subscriber_infos` (enrichissement V300 plus bas), jamais d'ici ;
        #   - isSubscriber : `c2_index_abonnements` refuse deliberement de s'y
        #     fier (drapeau jamais remis a faux) et lit `subscriptions` ;
        #   - categories / contact_type_set_at / contact_type_set_by /
        #     objectifs / show_age_public / birthday_updated_at : jamais recopies
        #     dans la fiche renvoyee — verifie sur le dictionnaire construit.
        #
        # CONTACTS V2 EST INTACT : `contact_type` est conserve, et les quatre
        # dimensions derivees (statut_abonnement, pays/zone, canaux, consentement)
        # se calculent a partir de `email`, `whatsapp` et `phone`, tous conserves.
        # P1-A.2 : la lecture elle-meme est desormais lancee plus haut, avec les
        # cinq autres. La projection et le filtre d'isolation sont INCHANGES.

        for p in participants:
            pid = p.get("id", "")
            email = (p.get("email") or "").strip().lower()
            phone = (p.get("whatsapp") or p.get("phone") or "").strip()
            # Dedup par ID d'abord, puis email/phone
            if pid and pid in seen_ids:
                continue
            if email and email in seen_emails:
                continue
            if phone and phone in seen_phones:
                continue
            if pid:
                seen_ids.add(pid)
            if email:
                seen_emails.add(email)
            if phone:
                seen_phones.add(phone)

            contacts.append({
                "id": pid,
                "name": p.get("name") or email or phone or "Sans nom",
                "type": "user",
                "category": p.get("source", "import"),
                "phone": phone or None,
                "email": email or None,
                "source": p.get("source", "import"),
                # ESSAI-5a-2 : la classification EXPLICITE posee par le coach.
                # `category` juste au-dessus est l'ORIGINE du contact, pas sa
                # relation a Afroboost — les confondre reviendrait a deduire
                # « participant » d'une source marketing.
                "contact_type": p.get("contact_type") or None,
                "tags": p.get("tags", [])
            })

        # 3. USERS — Utilisateurs de l'app (ceux pas déjà dans participants)
        # v108: Dedup par ID ET email pour éviter les doublons cross-collections
        # P1-A.2 : `all_users` est deja arrive (lecture lancee en tete avec les
        # cinq autres). L'ordre de traitement, lui, est INCHANGE : les users sont
        # fusionnes APRES les participants, qui restent la source prioritaire.
        for u in all_users:
            uid = u.get("id", "")
            email = (u.get("email") or "").strip().lower()
            if uid and uid in seen_ids:
                continue
            if email and email in seen_emails:
                continue
            if uid:
                seen_ids.add(uid)
            if email:
                seen_emails.add(email)
            contacts.append({
                "id": uid,
                "name": u.get("name") or email or "Sans nom",
                "type": "user",
                "category": "app_user",
                "phone": None,
                "email": email or None,
                "source": "app",
                # Un utilisateur de l'app n'est pas classe : `chat_participants`
                # est la seule collection qui porte `contact_type`.
                "contact_type": None,
                "tags": []
            })

        # V300 : enrichir les fiches contact (LECTURE SEULE) avec WhatsApp + date de
        # naissance + code abonné, depuis subscriber_infos (V294), joint par EMAIL.
        # Champs AJOUTÉS uniquement ; aucun champ existant modifié. Isolation coach :
        # un coach partenaire ne voit que ses abonnés (coach_id), l'admin voit tout.
        try:
            # P1-A.2 : `infos` est deja arrive (lecture lancee en tete). Si cette
            # lecture-la a echoue, on saute l'enrichissement — exactement comme
            # le faisait le `except` ci-dessous auparavant.
            if isinstance(infos, BaseException):
                raise infos
            info_by_email = {}
            for _info in infos:
                _em = (_info.get("email") or "").strip().lower()
                if _em and _em not in info_by_email:
                    info_by_email[_em] = _info
            for c in contacts:
                if c.get("type") == "group":
                    continue
                _em = (c.get("email") or "").strip().lower()
                if not _em:
                    continue
                _info = info_by_email.get(_em)
                if not _info:
                    continue
                _wa = _info.get("whatsapp") or c.get("phone") or None
                if not c.get("phone") and _wa:
                    c["phone"] = _wa
                c["whatsapp"] = _wa
                c["birthday"] = _info.get("birthday") or None
                c["subscriber_code"] = _info.get("code") or None
        except Exception as _e:
            logger.warning(f"[V300] enrichissement subscriber_infos ignoré: {_e}")

        # CONTACTS V2 — les quatre dimensions derivees, en DEUX lectures
        # groupees, quel que soit le nombre de contacts. Aucune ecriture.
        try:
            # P1-A.2 : les deux index sont deja arrives. Un echec sur l'un d'eux
            # prive de l'enrichissement, sans jamais vider la liste — inchange.
            if isinstance(_abos, BaseException):
                raise _abos
            if isinstance(_cons, BaseException):
                raise _cons
            for c in contacts:
                if c.get("type") != "group":
                    c2_enrichir(c, _abos, _cons)
        except Exception as _c2err:
            # L'enrichissement est un confort : s'il echoue, la liste doit
            # rester utilisable telle qu'avant.
            logger.warning("[C2] enrichissement ignore : %s", _c2err)

        # Sort: groupes d'abord, puis contacts par nom
        contacts.sort(key=lambda x: (0 if x["type"] == "group" else 1, (x.get("name") or "").lower()))

        groups_count = len([c for c in contacts if c["type"] == "group"])
        users_count = len([c for c in contacts if c["type"] == "user"])

        # CONTACTS V2 — des compteurs REELS, calcules sur l'ensemble et non
        # sur ce que l'ecran affiche. Ils remplacent le plafond muet de 200.
        _u = [c for c in contacts if c.get("type") != "group"]
        _compteurs = {
            "tous": len(_u),
            "participants": sum(1 for c in _u if c.get("contact_type") == "participant"),
            "prospects": sum(1 for c in _u if c.get("contact_type") == "prospect"),
            "partenaires": sum(1 for c in _u if c.get("contact_type") == "partner"),
            "autres": sum(1 for c in _u if c.get("contact_type") == "other"),
            "non_classes": sum(1 for c in _u if not c.get("contact_type")),
            "abonnes_actifs": sum(1 for c in _u if c.get("statut_abonnement") == "actif"),
            "anciens_abonnes": sum(1 for c in _u if c.get("statut_abonnement") == "ancien"),
            "non_abonnes": sum(1 for c in _u if c.get("statut_abonnement") == "non_abonne"),
            "par_zone": {_z: sum(1 for c in _u if c.get("zone") == _z) for _z in C2_ZONES},
            "avec_email": sum(1 for c in _u if (c.get("canaux") or {}).get("email")),
            "avec_whatsapp": sum(1 for c in _u if (c.get("canaux") or {}).get("whatsapp")),
            "avec_telephone": sum(1 for c in _u if (c.get("canaux") or {}).get("telephone")),
            "consentement_email": {_e: sum(1 for c in _u if (c.get("consentement") or {}).get("email") == _e) for _e in C2_CONSENTEMENTS},
            "consentement_whatsapp": {_e: sum(1 for c in _u if (c.get("consentement") or {}).get("whatsapp") == _e) for _e in C2_CONSENTEMENTS},
        }
        return {
            "success": True,
            "contacts": contacts,
            "total": len(contacts),
            "groups_count": groups_count,
            "users_count": users_count,
            "compteurs": _compteurs,
        }
    except Exception as e:
        logger.error(f"[CONTACTS-ALL] Erreur: {e}")
        return {"success": False, "contacts": [], "error": str(e)}


@api_router.post("/contacts/bulk-import")
async def bulk_import_contacts(request: Request):
    """
    Import en masse de contacts dans chat_participants.
    Accepte un tableau de {name, phone, email, source, tags}.
    Déduplique par phone/email. Retourne le nombre importé.
    """
    caller_email = request.headers.get("X-User-Email", "").lower().strip()
    if not caller_email:
        raise HTTPException(status_code=401, detail="Email requis")

    body = await request.json()
    contacts_list = body.get("contacts", [])
    source = body.get("source", "import")

    if not contacts_list:
        return {"imported": 0, "duplicates": 0, "errors": 0}

    imported = 0
    duplicates = 0
    errors = 0

    for c in contacts_list:
        try:
            email = (c.get("email") or "").strip().lower()
            phone = (c.get("phone") or c.get("whatsapp") or "").strip()
            name = (c.get("name") or "").strip()

            if not email and not phone:
                errors += 1
                continue

            # Check duplicate
            dup_query = {"$or": []}
            if email:
                dup_query["$or"].append({"email": {"$regex": f"^{re.escape(email)}$", "$options": "i"}})
            if phone:
                import re as re_dup
                clean = phone.replace(" ", "").replace("-", "")
                escaped = re_dup.escape(clean)
                dup_query["$or"].append({"whatsapp": {"$regex": escaped}})
                dup_query["$or"].append({"phone": {"$regex": escaped}})

            if dup_query["$or"]:
                existing = await db.chat_participants.find_one(dup_query, {"_id": 0})
                if existing:
                    # Update name if better
                    if name and not existing.get("name"):
                        await db.chat_participants.update_one(
                            {"id": existing["id"]},
                            {"$set": {"name": name, "last_seen_at": datetime.now(timezone.utc).isoformat()}}
                        )
                    duplicates += 1
                    continue

            # Insert new
            new_participant = {
                "id": str(uuid.uuid4()),
                "name": name or email or phone,
                "email": email or None,
                "whatsapp": phone or None,
                "phone": phone or None,
                "source": source,
                "coach_id": caller_email if not is_super_admin(caller_email) else DEFAULT_COACH_ID,
                "tags": c.get("tags", []),
                "created_at": datetime.now(timezone.utc).isoformat(),
                "last_seen_at": datetime.now(timezone.utc).isoformat()
            }
            await db.chat_participants.insert_one(new_participant)
            imported += 1

        except Exception as err:
            logger.warning(f"[BULK-IMPORT] Erreur contact: {err}")
            errors += 1

    return {
        "success": True,
        "imported": imported,
        "duplicates": duplicates,
        "errors": errors,
        "total_processed": len(contacts_list)
    }


# ============================================================
# GOOGLE CONTACTS SYNC — v18: OAuth2 + People API
# ============================================================

GOOGLE_CONTACTS_CLIENT_ID = os.environ.get("GOOGLE_CONTACTS_CLIENT_ID", "")
GOOGLE_CONTACTS_CLIENT_SECRET = os.environ.get("GOOGLE_CONTACTS_CLIENT_SECRET", "")
GOOGLE_CONTACTS_SCOPES = "https://www.googleapis.com/auth/contacts.readonly"

@api_router.get("/google-contacts/auth-url")
async def get_google_contacts_auth_url(request: Request):
    """Génère l'URL d'autorisation Google pour la sync contacts"""
    caller_email = request.headers.get("X-User-Email", "").lower().strip()
    if not caller_email:
        raise HTTPException(status_code=401, detail="Email requis")

    if not GOOGLE_CONTACTS_CLIENT_ID:
        raise HTTPException(status_code=503, detail="Google Contacts non configuré (GOOGLE_CONTACTS_CLIENT_ID manquant)")

    # Redirect URI = notre callback
    base_url = os.environ.get("VERCEL_URL", "afroboost-v11-dev-pm7l.vercel.app")
    redirect_uri = f"https://{base_url}/api/google-contacts/callback"

    import urllib.parse
    params = urllib.parse.urlencode({
        "client_id": GOOGLE_CONTACTS_CLIENT_ID,
        "redirect_uri": redirect_uri,
        "response_type": "code",
        "scope": GOOGLE_CONTACTS_SCOPES,
        "access_type": "offline",
        "prompt": "consent",
        "state": caller_email  # Pour identifier le coach
    })

    return {
        "auth_url": f"https://accounts.google.com/o/oauth2/v2/auth?{params}",
        "configured": True
    }


@api_router.get("/google-contacts/callback")
async def google_contacts_callback(code: str = "", state: str = "", error: str = ""):
    """Callback OAuth2 Google — échange le code contre un token"""
    from fastapi.responses import HTMLResponse
    import httpx

    if error:
        return HTMLResponse(f"<html><body><h2>Erreur: {error}</h2><script>window.close()</script></body></html>")

    if not code or not state:
        return HTMLResponse("<html><body><h2>Code manquant</h2><script>window.close()</script></body></html>")

    coach_email = state.lower().strip()
    base_url = os.environ.get("VERCEL_URL", "afroboost-v11-dev-pm7l.vercel.app")
    redirect_uri = f"https://{base_url}/api/google-contacts/callback"

    try:
        # Exchange code for tokens
        async with httpx.AsyncClient() as client:
            token_resp = await client.post("https://oauth2.googleapis.com/token", data={
                "client_id": GOOGLE_CONTACTS_CLIENT_ID,
                "client_secret": GOOGLE_CONTACTS_CLIENT_SECRET,
                "code": code,
                "grant_type": "authorization_code",
                "redirect_uri": redirect_uri
            })
            tokens = token_resp.json()

        if "error" in tokens:
            return HTMLResponse(f"<html><body><h2>Erreur token: {tokens.get('error_description', tokens['error'])}</h2><script>setTimeout(()=>window.close(),3000)</script></body></html>")

        # Store refresh token for the coach
        await db.google_tokens.update_one(
            {"coach_email": coach_email},
            {"$set": {
                "coach_email": coach_email,
                "access_token": tokens.get("access_token"),
                "refresh_token": tokens.get("refresh_token"),
                "expires_at": datetime.now(timezone.utc).isoformat(),
                "updated_at": datetime.now(timezone.utc).isoformat()
            }},
            upsert=True
        )

        return HTMLResponse("""
        <html><body style="background:#1a1025;color:#fff;font-family:sans-serif;display:flex;align-items:center;justify-content:center;height:100vh;margin:0">
        <div style="text-align:center">
            <h2 style="color:#22c55e">✅ Google Contacts connecté !</h2>
            <p>Vous pouvez fermer cette fenêtre et cliquer sur "Synchroniser".</p>
            <script>setTimeout(()=>window.close(),2000)</script>
        </div>
        </body></html>
        """)

    except Exception as e:
        logger.error(f"[GOOGLE-CONTACTS] Callback error: {e}")
        return HTMLResponse(f"<html><body><h2>Erreur: {str(e)}</h2><script>setTimeout(()=>window.close(),3000)</script></body></html>")


@api_router.get("/google-contacts/status")
async def google_contacts_status(request: Request):
    """Vérifie si le coach a connecté Google Contacts"""
    caller_email = request.headers.get("X-User-Email", "").lower().strip()
    token_doc = await db.google_tokens.find_one({"coach_email": caller_email}, {"_id": 0})
    return {
        "connected": bool(token_doc and token_doc.get("refresh_token")),
        "last_sync": token_doc.get("last_sync") if token_doc else None,
        "configured": bool(GOOGLE_CONTACTS_CLIENT_ID)
    }


@api_router.post("/google-contacts/sync")
async def sync_google_contacts(request: Request):
    """
    Synchronise les contacts Google dans chat_participants.
    Utilise le refresh_token stocké pour obtenir un access_token frais.
    """
    caller_email = request.headers.get("X-User-Email", "").lower().strip()
    if not caller_email:
        raise HTTPException(status_code=401, detail="Email requis")

    token_doc = await db.google_tokens.find_one({"coach_email": caller_email}, {"_id": 0})
    if not token_doc or not token_doc.get("refresh_token"):
        raise HTTPException(status_code=400, detail="Google non connecté. Cliquez sur 'Connecter Google' d'abord.")

    import httpx

    try:
        # 1. Refresh the access token
        async with httpx.AsyncClient() as client:
            token_resp = await client.post("https://oauth2.googleapis.com/token", data={
                "client_id": GOOGLE_CONTACTS_CLIENT_ID,
                "client_secret": GOOGLE_CONTACTS_CLIENT_SECRET,
                "refresh_token": token_doc["refresh_token"],
                "grant_type": "refresh_token"
            })
            tokens = token_resp.json()

        if "error" in tokens:
            raise HTTPException(status_code=400, detail=f"Token refresh failed: {tokens.get('error_description', tokens['error'])}")

        access_token = tokens["access_token"]

        # 2. Fetch contacts from Google People API (paginated)
        all_contacts = []
        next_page_token = None
        page_count = 0

        async with httpx.AsyncClient() as client:
            while page_count < 10:  # Max 10 pages (10000 contacts)
                params = {
                    "personFields": "names,emailAddresses,phoneNumbers",
                    "pageSize": 1000,
                    "sources": "READ_SOURCE_TYPE_CONTACT"
                }
                if next_page_token:
                    params["pageToken"] = next_page_token

                resp = await client.get(
                    "https://people.googleapis.com/v1/people/me/connections",
                    headers={"Authorization": f"Bearer {access_token}"},
                    params=params
                )

                if resp.status_code != 200:
                    logger.error(f"[GOOGLE-SYNC] API error: {resp.status_code} {resp.text[:200]}")
                    break

                data = resp.json()
                connections = data.get("connections", [])

                for person in connections:
                    names = person.get("names", [])
                    emails = person.get("emailAddresses", [])
                    phones = person.get("phoneNumbers", [])

                    name = names[0].get("displayName", "") if names else ""
                    email = emails[0].get("value", "") if emails else ""
                    phone = phones[0].get("value", "") if phones else ""

                    if email or phone:
                        all_contacts.append({
                            "name": name,
                            "email": email.lower().strip() if email else None,
                            "phone": phone.strip() if phone else None,
                            "source": "google",
                            "tags": ["google"]
                        })

                next_page_token = data.get("nextPageToken")
                if not next_page_token:
                    break
                page_count += 1

        # 3. Bulk import with dedup
        imported = 0
        duplicates = 0

        for c in all_contacts:
            email = c.get("email")
            phone = c.get("phone")

            dup_query = {"$or": []}
            if email:
                dup_query["$or"].append({"email": {"$regex": f"^{re.escape(email)}$", "$options": "i"}})
            if phone:
                clean = (phone or "").replace(" ", "").replace("-", "").replace("(", "").replace(")", "")
                if clean:
                    dup_query["$or"].append({"whatsapp": {"$regex": clean}})
                    dup_query["$or"].append({"phone": {"$regex": clean}})

            if dup_query["$or"]:
                existing = await db.chat_participants.find_one(dup_query, {"_id": 0, "id": 1})
                if existing:
                    duplicates += 1
                    continue

            await db.chat_participants.insert_one({
                "id": str(uuid.uuid4()),
                "name": c["name"] or c["email"] or c["phone"],
                "email": c.get("email"),
                "whatsapp": c.get("phone"),
                "phone": c.get("phone"),
                "source": "google",
                "coach_id": caller_email if not is_super_admin(caller_email) else DEFAULT_COACH_ID,
                "tags": ["google"],
                "created_at": datetime.now(timezone.utc).isoformat(),
                "last_seen_at": datetime.now(timezone.utc).isoformat()
            })
            imported += 1

        # Update last sync time
        await db.google_tokens.update_one(
            {"coach_email": caller_email},
            {"$set": {"last_sync": datetime.now(timezone.utc).isoformat()}}
        )

        return {
            "success": True,
            "imported": imported,
            "duplicates": duplicates,
            "total_google": len(all_contacts),
            "message": f"✅ {imported} nouveaux contacts importés ({duplicates} doublons ignorés)"
        }

    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"[GOOGLE-SYNC] Error: {e}")
        raise HTTPException(status_code=500, detail=str(e))


@api_router.post("/contacts/add-tags")
async def add_tags_to_contacts(request: Request):
    """Ajoute des tags à une liste de contacts (pour grouper/catégoriser)"""
    caller_email = request.headers.get("X-User-Email", "").lower().strip()
    body = await request.json()
    contact_ids = body.get("contact_ids", [])
    tags = body.get("tags", [])

    if not contact_ids or not tags:
        return {"updated": 0}

    updated = 0
    for cid in contact_ids:
        result = await db.chat_participants.update_one(
            {"id": cid},
            {"$addToSet": {"tags": {"$each": tags}}}
        )
        if result.modified_count:
            updated += 1

    return {"success": True, "updated": updated}


