# === FEATURE FLAGS API (Super Admin Only) ===
# Business: Seul le Super Admin peut activer/désactiver les services globaux

@api_router.get("/feature-flags")
async def get_feature_flags():
    """
    Récupère la configuration des feature flags
    Par défaut, tous les services additionnels sont désactivés
    """
    flags = await db.feature_flags.find_one({"id": "feature_flags"}, {"_id": 0})
    if not flags:
        # Créer la config par défaut (tout désactivé)
        default_flags = {
            "id": "feature_flags",
            "AUDIO_SERVICE_ENABLED": False,
            "VIDEO_SERVICE_ENABLED": False,
            "STREAMING_SERVICE_ENABLED": False,
            "SUBSCRIBER_STRICT_ENTRY": False,  # V315 : défaut OFF (zéro friction)
            "REQUIRE_COACH_JWT": False,        # V319 : défaut OFF (comportement actuel)
            "PAWAPAY_ENABLED": False,          # V325 : défaut OFF (PawaPay invisible)
            "PUBLICATIONS_NO_EXPIRY": False,   # V333 : défaut OFF (48 h pour tout le monde)
            "SUPERADMIN_JWT_STRICT": False,    # V344 : défaut OFF (repli X-User-Email encore accepté)
            "CHAT_READ_STRICT": False,         # V349 : défaut OFF (lecture du chat encore ouverte)
            "POSTHOG_IDENTIFY_ENABLED": False, # C9-B : défaut OFF (aucune identification)
            "updatedAt": None,
            "updatedBy": None
        }
        await db.feature_flags.insert_one(default_flags.copy())  # .copy() pour éviter mutation
        # Retourner sans _id
        return {k: v for k, v in default_flags.items() if k != "_id"}
    # V319 : un drapeau AJOUTÉ APRÈS la création du document n'existe pas en base — il
    # était donc ABSENT de la réponse (ni lisible par le dashboard, ni vérifiable par
    # curl : impossible de prouver qu'une version est bien déployée). On complète à la
    # lecture avec la valeur par défaut du modèle, SANS jamais écraser ce qui est en base.
    for _k, _default in (("AUDIO_SERVICE_ENABLED", False), ("VIDEO_SERVICE_ENABLED", False),
                         ("STREAMING_SERVICE_ENABLED", False), ("SUBSCRIBER_STRICT_ENTRY", False),
                         ("REQUIRE_COACH_JWT", False), ("PAWAPAY_ENABLED", False),
                         ("PUBLICATIONS_NO_EXPIRY", False), ("SUPERADMIN_JWT_STRICT", False),
                         ("CHAT_READ_STRICT", False), ("BOT_MENU_ENABLED", False),
                         ("POSTHOG_IDENTIFY_ENABLED", False)):
        if _k not in flags:
            flags[_k] = _default
    return flags

@api_router.put("/feature-flags")
async def update_feature_flags(update: FeatureFlagsUpdate, request: Request):
    """
    Met à jour les feature flags — SUPER ADMIN uniquement.
    V315 : cette route n'avait AUCUNE auth (n'importe qui basculait un interrupteur).
    Un kill-switch que tout le monde peut actionner n'est pas un contrôle : on exige
    désormais un JWT super-admin signé (non falsifiable).
    """
    caller = _v311_coach_email_from_jwt(request)
    if not caller or not is_super_admin(caller):
        raise HTTPException(status_code=403, detail="Super-admin requis")
    update_data = {k: v for k, v in update.model_dump().items() if v is not None}
    update_data["updatedAt"] = datetime.now(timezone.utc).isoformat()
    update_data["updatedBy"] = caller

    await db.feature_flags.update_one(
        {"id": "feature_flags"}, 
        {"$set": update_data}, 
        upsert=True
    )
    return await db.feature_flags.find_one({"id": "feature_flags"}, {"_id": 0})

