# --- WhatsApp Webhook (Twilio) ---
@api_router.post("/webhook/whatsapp")
async def handle_whatsapp_webhook(webhook: WhatsAppWebhook):
    """
    Webhook pour recevoir les messages WhatsApp entrants via Twilio
    Répond automatiquement avec l'IA si activée
    """
    import time
    start_time = time.time()
    
    # Récupérer la config IA
    ai_config = await db.ai_config.find_one({"id": "ai_config"}, {"_id": 0})
    if not ai_config or not ai_config.get("enabled"):
        logger.info(f"AI disabled, ignoring message from {webhook.From}")
        return {"status": "ai_disabled"}
    
    # Extraire le numéro de téléphone
    from_phone = webhook.From.replace("whatsapp:", "")
    incoming_message = webhook.Body
    
    logger.info(f"Incoming WhatsApp from {from_phone}: {incoming_message}")
    
    # Chercher le client dans les réservations
    client_name = None
    normalized_phone = from_phone.replace("+", "").replace(" ", "")
    reservations = await db.reservations.find({}, {"_id": 0}).to_list(1000)
    
    for res in reservations:
        res_phone = (res.get("whatsapp") or res.get("phone") or "").replace("+", "").replace(" ", "").replace("-", "")
        if res_phone and normalized_phone.endswith(res_phone[-9:]):
            client_name = res.get("userName") or res.get("name")
            break
    
    # Construire le contexte
    context = ""
    if client_name:
        context += f"\n\nLe client qui te parle s'appelle {client_name}. Utilise son prénom dans ta réponse."
    
    last_media = ai_config.get("lastMediaUrl", "")
    if last_media:
        context += f"\n\nNote: Tu as récemment envoyé un média à ce client: {last_media}. Tu peux lui demander s'il l'a bien reçu."
    
    full_system_prompt = ai_config.get("systemPrompt", "") + context
    
    # Appeler l'IA
    try:
        from openai import OpenAI

        openai_key = os.environ.get("OPENAI_API_KEY")
        if not openai_key:
            logger.error("OPENAI_API_KEY not configured")
            return {"status": "error", "message": "AI key not configured"}

        client = OpenAI(api_key=openai_key)
        model_name = ai_config.get("model", "gpt-4o-mini")

        response = await asyncio.to_thread(
            client.chat.completions.create,
            model=model_name,
            messages=[
                {"role": "system", "content": full_system_prompt},
                {"role": "user", "content": incoming_message}
            ],
            max_tokens=1000
        )
        ai_response = response.choices[0].message.content
        
        response_time = time.time() - start_time
        
        # Sauvegarder le log
        log_entry = AILog(
            fromPhone=from_phone,
            clientName=client_name,
            incomingMessage=incoming_message,
            aiResponse=ai_response,
            responseTime=response_time
        ).model_dump()
        await db.ai_logs.insert_one(log_entry)
        
        logger.info(f"AI responded to {from_phone} in {response_time:.2f}s")
        
        # Retourner la réponse (Twilio attend un TwiML ou un JSON)
        # Pour une réponse automatique, Twilio utilise TwiML
        return {
            "status": "success",
            "response": ai_response,
            "clientName": client_name,
            "responseTime": response_time
        }
        
    except Exception as e:
        logger.error(f"AI error: {str(e)}")
        return {"status": "error", "message": str(e)}

# --- Meta WhatsApp Cloud API Webhook (V161) ---
# GET = vérification webhook par Meta | POST = messages entrants
# Ne touche PAS au webhook Twilio existant ci-dessus

@api_router.get("/webhook/whatsapp-meta")
async def verify_meta_whatsapp_webhook(request: Request):
    """
    Vérification du webhook par Meta (GET).
    Meta envoie hub.mode, hub.verify_token et hub.challenge.
    On vérifie le token et renvoie hub.challenge.
    """
    params = request.query_params
    mode = params.get("hub.mode")
    token = params.get("hub.verify_token")
    challenge = params.get("hub.challenge")

    logger.info(f"[META-WEBHOOK] Verification request: mode={mode}, token={'***' if token else 'None'}")

    if mode == "subscribe" and token == META_WHATSAPP_VERIFY_TOKEN:
        logger.info("[META-WEBHOOK] ✅ Webhook vérifié avec succès")
        from starlette.responses import PlainTextResponse
        return PlainTextResponse(content=challenge, status_code=200)
    else:
        logger.warning(f"[META-WEBHOOK] ❌ Vérification échouée (token mismatch)")
        raise HTTPException(status_code=403, detail="Verification failed")


# =====================================================================
# === V440 (M1) : LE FLUX WHATSAPP SAIT ENFIN QUI IL EST ==============
# =====================================================================
#
# CE QUI N'ALLAIT PAS. L'appel OpenAI du webhook recevait
# `system = ai_config.systemPrompt + context`, avec un `systemPrompt` VIDE en
# base et un `context` réduit au prénom du client. `messages` ne portait qu'UN
# tour, sans historique. Le modèle était donc un assistant générique, amnésique,
# ignorant Afroboost. Mesuré le 13/08/2026 dans `ai_logs` :
#   « Puis-je payer par twint? »  -> « je ne suis pas capable de traiter les
#                                     paiements … vérifiez auprès de la plateforme »
#   « Je peut te twinter »        -> « contacte-moi par TWITTER »
# Ces réponses sont CORRECTES pour un assistant sans contexte : le défaut n'est
# pas la formulation, c'est l'absence d'informations. On corrige donc le
# contexte, jamais une phrase.
#
# CE QUI EST HORS PÉRIMÈTRE, ET VOLONTAIREMENT.
#   - `ai_config.systemPrompt` n'est PAS modifié en base. Le bloc métier est
#     AJOUTÉ à `context`, exactement comme la ligne « Le client s'appelle … »
#     le fait déjà. V433 avait touché la base, V434 l'a intégralement annulé.
#   - Le chat du SITE (`/chat`, `/chat/ai-response`) n'est pas touché.
#   - Le checkout n'est pas touché : on ne crée aucune session de paiement, on
#     donne un lien qui ouvre la carte de l'offre. Un lien ne doit jamais
#     déclencher un paiement tout seul.
#
# ⚠️ MONO-COACH ASSUMÉ (arbitrage du 14/08/2026, option b). Ce flux répond pour
# UN SEUL coach : `AUTHORIZED_COACH_EMAIL`, dont la boîte est `admin_afroboost`
# en dur dans `_save_whatsapp_conversation`. Les offres lues ci-dessous ne sont
# donc filtrées par AUCUN `coach_id` — ce serait un faux-semblant de
# multi-tenant. `v440_offres_visibles` porte cette hypothèse de façon EXPLICITE
# et TESTABLE (cf. `V440_MONO_COACH`) : le jour où un vrai coach partenaire
# existera, ce point échouera bruyamment au lieu de servir en silence les offres
# d'autrui. Le vrai multi-coach est un chantier séparé.
import unicodedata as _v440_ud

# Marqueur d'hypothèse. Tant qu'il vaut True, ce flux est mono-coach ASSUMÉ.
V440_MONO_COACH = True

V440_MAX_HISTORIQUE = 8      # tours relus — la fenêtre Meta est de 24 h de toute façon
V440_SEUIL_SCORE = 3         # en dessous : aucune offre n'est « certaine »
V440_MARGE_SCORE = 2         # écart minimal avec la 2ᵉ, sinon c'est une égalité
V440_SITE = "https://afroboost.com"

# Mots trop courants pour désigner une offre. Sans ce filtre, « cours » élirait
# une offre au hasard parmi les quatre qui le portent dans leurs mots-clés.
V440_MOTS_IGNORES = frozenset((
    "pour", "avec", "dans", "cette", "cette", "mon", "ton", "son", "les", "des",
    "une", "aux", "par", "que", "qui", "est", "sur", "pas", "plus", "bien",
    "bonjour", "salut", "merci", "svp", "stp", "payer", "paye", "paiement",
    "twint", "twinter", "carte", "prix", "combien", "possible", "aimerais",
    "voudrais", "veux", "peux", "puis", "comment", "quand", "reserver",
    "reservation", "samedi", "dimanche", "lundi", "mardi", "mercredi", "jeudi",
    "vendredi",
))


def v440_normaliser(texte) -> str:
    """Minuscules sans accents — « Casque » et « casqué » doivent se rejoindre."""
    if not isinstance(texte, str):
        return ""
    _d = _v440_ud.normalize("NFD", texte.lower())
    return "".join(_c for _c in _d if _v440_ud.category(_c) != "Mn")


def v440_singulier(mot: str) -> str:
    """Forme canonique : « casques » et « casque » doivent se rejoindre.

    Sans cela, le cas reel echouait — la cliente ecrit « 3 casques », l'offre
    s'appelle « … du casque Silent ». Le pluriel n'est retire qu'a partir de 5
    lettres, pour ne pas transformer « cours » en « cour » cote message et le
    laisser intact cote offre : la regle s'applique aux DEUX cotes, donc la
    comparaison reste juste quelle que soit la forme choisie.
    """
    if len(mot) >= 5 and mot[-1] in "sx":
        return mot[:-1]
    return mot


def v440_mots(texte) -> set:
    """Mots utiles d'un texte : au moins 4 lettres, hors mots trop courants.

    La mise au singulier precede le filtre : « reservations » doit etre ecarte
    comme « reservation ».
    """
    _brut = re.split(r"[^a-z0-9]+", v440_normaliser(texte))
    _mots = {v440_singulier(_m) for _m in _brut if len(_m) >= 4}
    return {_m for _m in _mots
            if _m not in V440_MOTS_IGNORES and v440_singulier(_m) not in V440_MOTS_IGNORES}


def v440_score_offre(mots: set, offre: dict) -> int:
    """Score d'appariement entre les mots d'un fil et une offre.

    Le NOM pèse 3, les mots-clés 1. C'est délibéré : sur les offres réelles, 4
    des 5 partagent des mots-clés IDENTIQUES (« cours, danse, fitness … »), qui
    ne distinguent donc rien. Seul le nom porte l'information — « casque »,
    « t-shirt » — et c'est lui qui doit décider.
    """
    _score = 0
    _noms = v440_mots(offre.get("name") or "")
    _cles = v440_mots(offre.get("keywords") or "")
    for _m in mots:
        if _m in _noms:
            _score += 3
        elif _m in _cles:
            _score += 1
    return _score


def v440_offre_certaine(texte: str, offres: list):
    """L'offre dont il est question, ou None — et le motif, toujours.

    ABSTENTION PAR DÉFAUT. On ne retient une offre que si elle est nettement
    devant : score suffisant ET écart d'au moins `V440_MARGE_SCORE` avec la
    suivante. Une égalité, un score faible, une liste vide -> None. C'est la
    règle « plusieurs offres possibles -> aucune sélection arbitraire », et elle
    est plus importante que de trouver une réponse : un mauvais lien coûte plus
    cher qu'une question.
    """
    _mots = v440_mots(texte)
    # V440b : une offre INVISIBLE ne peut jamais être élue. Il en existe (un
    # doublon « Silent … Lac de Vidy » à 25 CHF, masqué) : le proposer enverrait
    # un client sur une offre que le coach a délibérément retirée.
    _utilisables = [_o for _o in (offres or []) if v440_visible(_o)]
    if not _mots or not _utilisables:
        return None, "aucun mot exploitable"
    _classement = sorted(
        ((v440_score_offre(_mots, _o), _o) for _o in _utilisables),
        key=lambda _p: (-_p[0], str(_p[1].get("id") or "")),
    )
    _meilleur, _offre = _classement[0]
    if _meilleur < V440_SEUIL_SCORE:
        return None, "score insuffisant (%d < %d)" % (_meilleur, V440_SEUIL_SCORE)
    _second = _classement[1][0] if len(_classement) > 1 else 0
    if (_meilleur - _second) < V440_MARGE_SCORE:
        return None, "égalité entre plusieurs offres (%d vs %d)" % (_meilleur, _second)
    return _offre, "offre identifiée (score %d)" % _meilleur


def v440_visible(offre: dict) -> bool:
    """Une offre invisible n'existe pas pour le bot.

    Même convention que la vitrine et le chat du site (`visible: {$ne: False}`) :
    un champ ABSENT vaut visible. La garde est répétée ici, en pur, parce que la
    requête base ne protège que l'appel nominal — un appelant futur qui passerait
    une liste non filtrée ne doit pas pouvoir proposer un brouillon.
    """
    return (offre or {}).get("visible") is not False


def v440_prix_actif(offre: dict, maintenant=None):
    """Prix RÉELLEMENT payé aujourd'hui, en CHF — ou None si indéterminable.

    ⚠️ NE JAMAIS LIRE `offre["price"]` POUR DÉCIDER SI UNE OFFRE EST PAYANTE.
    Sur une offre à prix progressif, le champ plat est une SENTINELLE à 0.0 et le
    vrai prix vit dans `price_early_bird` / `price_standard` / `price_last_minute`.
    Mesuré le 14/08/2026 sur « Afroboost Silent … casque Silent » (LAAF Festival) :
    `price` valait 0.0 alors que le billet était à 10 CHF. Annoncer « gratuit »
    aurait été une fausse promesse commerciale.

    La source de vérité est `compute_active_price` (api/pricing.py, V223) — le
    MÊME calcul que celui du site et du checkout. On ne recopie aucun palier ici.

    `maintenant` est injectable pour les tests ; en production il vaut None, donc
    le palier est recalculé à CHAQUE message. Aucun cache, aucun prix périmé.

    None (et non 0.0) en cas d'échec : confondre « je ne sais pas » avec
    « gratuit » est exactement l'erreur qu'on corrige.
    """
    try:
        _p = compute_active_price(offre or {}, maintenant)
        return float(_p.get("price") or 0)
    except Exception as _e:
        logger.warning("[V440] prix actif indéterminable : %s", _e)
        return None


def v440_urls_autorisees(offres: list) -> set:
    """Les SEULES URL qu'une réponse a le droit de contenir.

    Rien n'est fabriqué ici : chaque lien d'offre sort de `v440_lien_offre`,
    l'unique fabrique du dépôt, à partir d'un `offers.id` réel.
    """
    _ok = {V440_SITE, V440_SITE + "/"}
    for _o in offres or []:
        if not v440_visible(_o):      # V440b : une offre masquée n'a pas de lien
            continue
        _l = v440_lien_offre(_o)
        if _l:
            _ok.add(_l)
    return _ok


def v440_garde_urls(texte: str, autorisees: set):
    """Garde de SORTIE : neutralise toute URL absente de l'ensemble autorisé.

    Le contexte a beau interdire d'inventer, un modèle peut passer outre — et
    c'est précisément ce qu'il a fait en envoyant la cliente vers « Twitter ».
    On ne fait donc pas confiance à la consigne : on relit le texte SORTANT.

    Une URL interdite est REMPLACÉE par la racine du site, jamais simplement
    effacée : retirer un lien au milieu d'une phrase produirait « Voici le lien
    pour ton offre :  » — une promesse vide. `https://afroboost.com` est
    toujours vrai, toujours sûr, et ne mène chez aucun tiers.
    """
    if not isinstance(texte, str) or not texte:
        return texte, []
    _retirees = []

    def _remplacer(_m):
        _url = _m.group(0)
        # La ponctuation finale appartient à la phrase, pas à l'URL.
        _fin = ""
        while _url and _url[-1] in ".,;:!?)»\"'":
            _fin = _url[-1] + _fin
            _url = _url[:-1]
        if _url in autorisees:
            return _url + _fin
        _retirees.append(_url)
        return V440_SITE + _fin

    _propre = re.sub(r"https?://[^\s<>\"'`]+", _remplacer, texte)
    # Les URL écrites sans protocole (« afroboost.com/?offre=… », « twint.ch »)
    # échappent au motif ci-dessus et resteraient cliquables sur WhatsApp.
    _propre = re.sub(
        r"(?<![/\w.])(?:www\.)?[a-z0-9-]+(?:\.[a-z0-9-]+)+/[^\s<>\"'`]*",
        _remplacer, _propre, flags=re.IGNORECASE)
    return _propre, _retirees


def v440_prix_lisible(valeur) -> str:
    """« 10 CHF », « 59.99 CHF » — sans décimale inutile."""
    _v = float(valeur)
    return ("%d CHF" % _v) if _v == int(_v) else ("%.2f CHF" % _v)


def v440_contexte_metier(offres: list, offre_ciblee: dict, motif: str = "",
                         maintenant=None, twint_disponible: bool = True) -> str:
    """Le bloc métier ajouté au prompt système. Construit ENTIÈREMENT en Python.

    Tout ce que le modèle a le droit de dire d'une offre — nom, prix, lien —
    figure ici, calculé depuis la base. Le modèle rédige ; il n'invente pas les
    faits, et surtout pas les URL ni les prix.

    V440b : les prix viennent de `v440_prix_actif`, donc de `compute_active_price`
    — le même calcul que le site. `maintenant` n'est injecté que par les tests ;
    en production il vaut None et le palier est réévalué à chaque message.

    `twint_disponible` reflète la configuration RÉELLE du site : si le coach
    retire son moyen de paiement, le bot cesse de promettre TWINT.
    """
    _c = [
        "Tu es l'assistant WhatsApp d'Afroboost, le studio de fitness afrobeat "
        "de Coach Bassi à Neuchâtel (Suisse). Tu réponds en français, de façon "
        "chaleureuse et brève, comme dans une conversation WhatsApp.",
        "",
        "PAIEMENT — CE QUI EST VRAI :",
    ]
    if twint_disponible:
        _c += [
            "- Les offres PAYANTES se règlent sur le site Afroboost, et TWINT y "
            "est accepté (en CHF). TWINT fonctionne, c'est un moyen de paiement "
            "normal du site.",
            "- Tu ne traites pas la transaction toi-même, mais cela ne veut PAS "
            "dire que TWINT est indisponible : tu donnes le lien de l'offre sur "
            "le site, et le paiement se fait là, dans le parcours de réservation.",
            "- N'envoie JAMAIS quelqu'un chercher sur l'application ou le site "
            "TWINT, et ne donne jamais d'adresse twint.ch : le point d'entrée "
            "est TOUJOURS la page Afroboost de l'offre.",
        ]
    else:
        _c += [
            "- ATTENTION : aucun moyen de paiement en ligne n'est configuré en "
            "ce moment. Ne promets NI TWINT NI carte. Si la personne veut payer, "
            "dis que tu fais suivre à Coach Bassi pour organiser le paiement.",
        ]
    _c.append("")

    _visibles = [_o for _o in (offres or []) if v440_visible(_o)]
    _prix = {id(_o): v440_prix_actif(_o, maintenant) for _o in _visibles}
    _payantes = [_o for _o in _visibles if (_prix[id(_o)] or 0) > 0]
    _gratuites = [_o for _o in _visibles if _prix[id(_o)] == 0]
    if _payantes:
        _c.append("OFFRES PAYANTES ET LEURS LIENS (les seuls liens autorisés) :")
        for _o in _payantes:
            _c.append("- %s — %s — %s"
                      % (str(_o.get("name") or "Offre").strip(),
                         v440_prix_lisible(_prix[id(_o)]), v440_lien_offre(_o)))
        _c.append("")
    if _gratuites:
        _c.append("OFFRES GRATUITES (aucun paiement, donc AUCUNE mention de TWINT) :")
        for _o in _gratuites:
            _c.append("- %s — gratuit — %s"
                      % (str(_o.get("name") or "Offre").strip(), v440_lien_offre(_o)))
        _c.append("")

    if offre_ciblee is not None and v440_visible(offre_ciblee):
        _nom = str(offre_ciblee.get("name") or "cette offre").strip()
        _p = v440_prix_actif(offre_ciblee, maintenant)
        if _p is None:
            # « Je ne sais pas » n'est PAS « gratuit » : on ne promet rien.
            _c += [
                "OFFRE CONCERNÉE PAR CETTE CONVERSATION : %s, mais son PRIX EST "
                "INDÉTERMINÉ." % _nom,
                "N'annonce donc AUCUN prix et ne promets aucun paiement. Donne "
                "ce lien pour qu'elle voie le tarif à jour : %s"
                % v440_lien_offre(offre_ciblee),
                "",
            ]
        elif _p > 0:
            _c += [
                "OFFRE CONCERNÉE PAR CETTE CONVERSATION : %s, au tarif actuel de %s."
                % (_nom, v440_prix_lisible(_p)),
                ("Si la personne parle de payer, confirme que TWINT est possible "
                 "et donne EXACTEMENT ce lien : %s" % v440_lien_offre(offre_ciblee))
                if twint_disponible else
                ("Ne promets aucun moyen de paiement en ligne. Donne ce lien et "
                 "propose de faire suivre à Coach Bassi : %s" % v440_lien_offre(offre_ciblee)),
                "",
            ]
        else:
            _c += [
                "OFFRE CONCERNÉE PAR CETTE CONVERSATION : %s, et elle est GRATUITE." % _nom,
                "Ne propose donc PAS de paiement ni TWINT. Dis simplement qu'il "
                "n'y a rien à payer et donne ce lien pour réserver : %s"
                % v440_lien_offre(offre_ciblee),
                "",
            ]
    else:
        _c += [
            "AUCUNE OFFRE N'A PU ÊTRE IDENTIFIÉE AVEC CERTITUDE (%s)." % (motif or "indéterminé"),
            "Tu ne dois donc donner AUCUN lien d'offre. Demande gentiment de "
            "quelle offre ou de quel cours il s'agit."
            + (" Tu peux confirmer que le paiement par TWINT existe sur le site, "
               "sans donner de lien précis." if twint_disponible else ""),
            "",
        ]

    _c += [
        "RÈGLES ABSOLUES :",
        "- N'invente JAMAIS une adresse web. N'écris que les liens listés "
        "ci-dessus, copiés au caractère près. Si le lien dont tu aurais besoin "
        "n'y figure pas, n'en mets aucun et pose une question.",
        "- N'invente ni prix, ni horaire, ni offre absente de cette liste.",
        "- Ne demande jamais de coordonnées bancaires.",
        "- Si tu ne sais pas, dis-le et propose de faire suivre à Coach Bassi.",
    ]
    return "\n".join(_c)


async def v440_twint_configure() -> bool:
    """Le site peut-il RÉELLEMENT encaisser en ligne aujourd'hui ?

    Mesuré le 14/08/2026 : `concept.paymentTwint` et `paymentCreditCard` sont
    tous deux à False, et le vrai encaissement passe par le lien TWINT direct
    résolu par la route `/payment-links` (V222 : repli sur
    `partner_payment_config.twint_direct_url`). Promettre TWINT sans vérifier
    reviendrait à promettre au hasard.

    On ne peut PAS appeler `get_payment_links` : c'est une route FastAPI, et
    elle ÉCRIT (`insert_one` quand le document manque). On refait donc ici ses
    deux LECTURES, et rien d'autre.
    """
    try:
        _l = await db.payment_links.find_one({"id": "payment_links"},
                                             {"_id": 0, "twint": 1}) or {}
        if (_l.get("twint") or "").strip():
            return True
        for _admin in SUPER_ADMIN_EMAILS:
            _cfg = await db["partner_payment_config"].find_one(
                {"coach_email": _admin}, {"_id": 0, "twint_direct_url": 1})
            if _cfg and (_cfg.get("twint_direct_url") or "").strip():
                return True
        _cpt = await db.concept.find_one(
            {"id": "concept"}, {"_id": 0, "paymentTwint": 1, "paymentCreditCard": 1}) or {}
        # Le Checkout Stripe du site propose `['card', 'twint']` en CHF : si le
        # parcours carte est ouvert, TWINT l'est aussi.
        return bool(_cpt.get("paymentTwint") or _cpt.get("paymentCreditCard"))
    except Exception as _e:
        logger.warning("[V440] configuration de paiement illisible : %s", _e)
        return False        # dans le doute, on ne promet rien


async def v440_offres_visibles() -> list:
    """Offres visibles. ⚠️ AUCUN filtre `coach_id` — mono-coach assumé, cf. en-tête.

    V440b : on remonte AUSSI les champs de tarification progressive — sans eux,
    `compute_active_price` retomberait sur le prix plat, c'est-à-dire sur le bug
    même que ce lot corrige.
    """
    try:
        return await db.offers.find(
            {"visible": {"$ne": False}},
            {"_id": 0, "id": 1, "name": 1, "price": 1, "keywords": 1, "isProduct": 1,
             "visible": 1, "progressive_pricing": 1, "countdown_date": 1,
             "countdown_time": 1, "early_bird_days_before": 1,
             "standard_hours_before": 1, "price_early_bird": 1,
             "price_standard": 1, "price_last_minute": 1},
        ).to_list(50)
    except Exception as _e:
        logger.warning("[V440] offres illisibles : %s", _e)
        return []


async def v440_historique_fil(from_phone: str, limite: int = V440_MAX_HISTORIQUE):
    """Derniers tours du fil WhatsApp, au format `messages` d'OpenAI.

    C'est ce qui manquait pour que « Puis-je payer par Twint ? » garde le
    contexte des « 3 casques » demandés deux minutes plus tôt. Lecture seule.
    Le message COURANT n'y figure pas : il n'est enregistré qu'après la réponse.
    """
    _pid = "whatsapp_" + str(from_phone or "").replace("+", "")
    try:
        _conv = await db.private_conversations.find_one(
            {"$or": [{"participant_1_id": _pid}, {"participant_2_id": _pid}]},
            {"_id": 0, "id": 1})
        if not _conv:
            return []
        _msgs = await db.private_messages.find(
            {"conversation_id": _conv["id"], "is_deleted": {"$ne": True}},
            {"_id": 0, "sender_id": 1, "content": 1, "created_at": 1},
        ).sort("created_at", -1).to_list(limite)
    except Exception as _e:
        logger.warning("[V440] historique illisible : %s", _e)
        return []
    _tours = []
    for _m in reversed(_msgs):
        _texte = (_m.get("content") or "").strip()
        if not _texte:
            continue
        _tours.append({"role": "user" if _m.get("sender_id") == _pid else "assistant",
                       "content": _texte[:1000]})
    return _tours


@api_router.post("/webhook/whatsapp-meta")
async def handle_meta_whatsapp_webhook(request: Request):
    """
    Webhook pour recevoir les messages WhatsApp entrants via Meta Cloud API.
    Format Meta: { object, entry: [{ changes: [{ value: { messages: [...] } }] }] }
    Réutilise le MÊME flux IA + conversation que le webhook Twilio existant.
    """
    import time

    try:
        body = await request.json()
    except Exception:
        logger.error("[META-WEBHOOK] ❌ JSON invalide")
        return {"status": "error", "message": "Invalid JSON"}

    # Meta envoie toujours object = "whatsapp_business_account"
    if body.get("object") != "whatsapp_business_account":
        logger.info(f"[META-WEBHOOK] Objet ignoré: {body.get('object')}")
        return {"status": "ignored"}

    # Parcourir les entrées (peut y avoir plusieurs messages)
    entries = body.get("entry", [])
    processed = 0

    for entry in entries:
        changes = entry.get("changes", [])
        for change in changes:
            value = change.get("value", {})
            messages = value.get("messages", [])
            contacts = value.get("contacts", [])

            # === V378 : ENREGISTREMENT DES STATUTS DE LIVRAISON ===
            #
            # Meta envoie ici, dans le MÊME webhook que les messages entrants, le sort
            # de chaque message sorti : sent -> delivered -> read, ou failed avec un
            # code. Ce bloc les IGNORAIT (`if not messages: continue`), si bien que
            # les 26 campagnes du 3 août affichaient « sent » sans qu'on sache jamais
            # qu'elles n'étaient pas distribuées — et sans jamais voir le motif, que
            # Meta ne donne QUE par cette voie.
            #
            # On écrit dans `whatsapp_statuts` (collection neuve, rien d'autre n'en
            # dépend). Aucun envoi, aucune réponse : on enregistre et on continue.
            _statuses = value.get("statuses", []) or []
            for _st in _statuses:
                try:
                    _erreurs = []
                    for _e in (_st.get("errors") or []):
                        _erreurs.append({
                            "code": _e.get("code"),
                            "title": _e.get("title"),
                            "message": _e.get("message"),
                            "details": ((_e.get("error_data") or {}).get("details")),
                            "href": _e.get("href"),
                        })
                    await db.whatsapp_statuts.insert_one({
                        "wamid": _st.get("id"),
                        "statut": _st.get("status"),
                        "destinataire": _st.get("recipient_id"),
                        "horodatage_meta": _st.get("timestamp"),
                        "conversation": _st.get("conversation"),
                        "tarification": _st.get("pricing"),
                        "erreurs": _erreurs,
                        "recu_le": datetime.now(timezone.utc).isoformat(),
                    })
                    if _erreurs:
                        logger.error(f"[META-STATUT] ❌ {_st.get('status')} vers "
                                     f"…{str(_st.get('recipient_id'))[-4:]} : {_erreurs}")
                    else:
                        logger.info(f"[META-STATUT] {_st.get('status')} vers "
                                    f"…{str(_st.get('recipient_id'))[-4:]}")
                except Exception as _e_st:
                    logger.warning(f"[META-STATUT] enregistrement ignoré : {_e_st}")

            # Ignorer les statuts de livraison (pas de messages)
            if not messages:
                continue

            for msg in messages:
                msg_type = msg.get("type", "")
                from_phone = msg.get("from", "")  # Format: 41767639928 (sans +)
                bouton_clique = ""                # V369 : rempli si clic sur un bouton

                # Extraire le texte selon le type de message
                if msg_type == "text":
                    incoming_message = msg.get("text", {}).get("body", "")
                elif msg_type == "image":
                    incoming_message = msg.get("image", {}).get("caption", "") or "[Image reçue]"
                elif msg_type == "video":
                    incoming_message = msg.get("video", {}).get("caption", "") or "[Vidéo reçue]"
                elif msg_type == "audio":
                    incoming_message = "[Message vocal reçu]"
                elif msg_type == "document":
                    incoming_message = msg.get("document", {}).get("caption", "") or "[Document reçu]"
                elif msg_type == "location":
                    incoming_message = "[Localisation reçue]"
                elif msg_type == "sticker":
                    incoming_message = "[Sticker reçu]"
                elif msg_type == "interactive":
                    # V369 : un CLIC sur un bouton ou une ligne de liste revient ici.
                    # Sans ce cas, le clic tombait dans le fourre-tout ci-dessous et
                    # devenait « [Message interactive reçu] » : le bot ne pouvait pas
                    # savoir ce que la personne avait choisi.
                    _inter = msg.get("interactive", {}) or {}
                    _reponse = _inter.get("button_reply") or _inter.get("list_reply") or {}
                    bouton_clique = _reponse.get("id", "")
                    incoming_message = _reponse.get("title", "") or "[Choix du menu]"
                elif msg_type == "reaction":
                    # Ignorer les réactions
                    continue
                else:
                    incoming_message = f"[Message {msg_type} reçu]"

                if not incoming_message or not from_phone:
                    continue

                # V332 : « STOP » (et variantes) = désabonnement AUTOMATIQUE, traité
                # AVANT tout le reste. Le message ne doit surtout pas partir dans le
                # flux IA : répondre à un « STOP » par une réponse marketing serait
                # exactement l'inverse de ce que la personne demande, et illégal.
                # `_v332_stop_whatsapp` renvoie True si le message était une commande.
                try:
                    if await _v332_stop_whatsapp(from_phone, incoming_message):
                        processed += 1
                        continue
                except Exception as _v332_err:
                    # Un souci ici ne doit jamais faire échouer la réception du message.
                    logger.error(f"[V332] Traitement STOP ignoré: {_v332_err}")

                # Ajouter le + au numéro pour normaliser
                if not from_phone.startswith("+"):
                    from_phone = f"+{from_phone}"

                # Récupérer le nom du contact Meta (si disponible)
                meta_contact_name = None
                for contact in contacts:
                    if contact.get("wa_id") == msg.get("from"):
                        profile = contact.get("profile", {})
                        meta_contact_name = profile.get("name")
                        break

                logger.info(f"[META-WEBHOOK] 📩 Message de {from_phone} ({meta_contact_name}): {incoming_message[:80]}")

                # === V369b : BOT À MENU DE BOUTONS ===
                #
                # PLACEMENT : APRÈS la résolution de `meta_contact_name`. En V369 ce
                # bloc était placé plus haut, AVANT que cette variable existe : chaque
                # message levait un NameError, avalé par le `except` ci-dessous, et le
                # flux IA reprenait la main. Le bot semblait actif (drapeau ON) mais
                # n'était JAMAIS exécuté — symptôme observé le 3 août : l'IA répondait
                # au lieu du menu.
                #
                # Placé APRÈS le STOP (V332), qui reste prioritaire sur tout, et AVANT
                # le flux IA, qu'il remplace quand il est actif — décision du coach :
                # menu seul, jamais d'IA (son `systemPrompt` est vide).
                #
                # TROIS VERROUS avant qu'un message parte :
                #   1. drapeau BOT_MENU_ENABLED (défaut OFF -> tout ce bloc est ignoré) ;
                #   2. liste blanche de numéros (phase de test : le coach, et lui seul) ;
                #   3. la pause « coach » de la personne, qui impose le silence.
                # Aucun de ces chemins ne touche aux campagnes : ni template, ni
                # launch_campaign, ni la boucle V328.
                try:
                    from api.routes.bot_whatsapp_routes import (
                        bot_actif as _bot_actif, numero_autorise as _bot_numero_ok,
                        decider_reponse as _bot_decider, envoyer_payload as _bot_envoyer)
                    if await _bot_actif() and _bot_numero_ok(from_phone):
                        _reponse_bot, _notif = await _bot_decider(
                            from_phone, incoming_message, bouton_clique, meta_contact_name)
                        if _reponse_bot:
                            # V372 : le bot peut renvoyer PLUSIEURS messages (fiche
                            # complète puis boutons) — le corps d'un message à boutons
                            # est plafonné à 1024 caractères par WhatsApp.
                            for _msg_bot in (_reponse_bot if isinstance(_reponse_bot, list)
                                             else [_reponse_bot]):
                                await _bot_envoyer(from_phone, _msg_bot)
                            await _save_whatsapp_conversation(
                                from_phone=from_phone,
                                contact_name=meta_contact_name,
                                incoming_message=incoming_message,
                                ai_response=((_reponse_bot[0] if isinstance(_reponse_bot, list)
                                              else _reponse_bot).get("text", {}) or {}).get("body")
                                            or "[menu WhatsApp]")
                            if _notif:
                                # Le coach est prévenu : notification + trace écrite.
                                try:
                                    await send_push_by_email(
                                        AUTHORIZED_COACH_EMAIL,
                                        _notif["push"]["titre"], _notif["push"]["corps"])
                                except Exception as _e_push:
                                    logger.warning(f"[BOT-WA] push coach échouée: {_e_push}")
                                try:
                                    await _save_whatsapp_conversation(
                                        from_phone=from_phone,
                                        contact_name=meta_contact_name,
                                        incoming_message="[demande de rappel]",
                                        ai_response=_notif["message_messagerie"])
                                except Exception as _e_msg:
                                    logger.warning(f"[BOT-WA] trace messagerie échouée: {_e_msg}")
                        # `None` = la personne est en pause : on n'envoie RIEN, et on
                        # n'enchaîne pas non plus sur l'IA. Le silence est voulu.
                        processed += 1
                        continue
                except Exception as _e_bot:
                    # Un souci du bot ne doit JAMAIS empêcher la réception du message.
                    # V369b : on GARDE la dernière erreur en mémoire et on l'expose dans
                    # /api/bot-whatsapp/apercu. Sans accès aux logs du conteneur, une
                    # exception avalée ici est invisible — c'est ce qui a masqué le
                    # NameError de V369 pendant tout un test.
                    logger.error(f"[BOT-WA] traitement ignoré ({type(_e_bot).__name__}: {_e_bot}) — flux habituel")
                    try:
                        import api.routes.bot_whatsapp_routes as _mod_bot
                        _mod_bot.DERNIERE_ERREUR = {
                            "type": type(_e_bot).__name__, "message": str(_e_bot)[:300],
                            "quand": datetime.now(timezone.utc).isoformat()}
                    except Exception:
                        pass

                # === RÉUTILISER LE MÊME FLUX QUE LE WEBHOOK TWILIO ===
                start_time = time.time()

                # 1. Vérifier si l'IA est activée
                ai_config = await db.ai_config.find_one({"id": "ai_config"}, {"_id": 0})
                if not ai_config or not ai_config.get("enabled"):
                    logger.info(f"[META-WEBHOOK] AI disabled, saving message but not responding")
                    # Sauvegarder le message entrant même si l'IA est désactivée
                    await _save_whatsapp_conversation(
                        from_phone=from_phone,
                        contact_name=meta_contact_name,
                        incoming_message=incoming_message,
                        ai_response=None
                    )
                    processed += 1
                    continue

                # 2. Chercher le client dans les réservations
                client_name = meta_contact_name  # Utiliser le nom Meta par défaut
                normalized_phone = from_phone.replace("+", "").replace(" ", "")
                reservations = await db.reservations.find({}, {"_id": 0}).to_list(1000)

                for res in reservations:
                    res_phone = (res.get("whatsapp") or res.get("phone") or "").replace("+", "").replace(" ", "").replace("-", "")
                    if res_phone and normalized_phone.endswith(res_phone[-9:]):
                        client_name = res.get("userName") or res.get("name") or meta_contact_name
                        break

                # 3. Construire le contexte
                context = ""
                if client_name:
                    context += f"\n\nLe client qui te parle s'appelle {client_name}. Utilise son prénom dans ta réponse."

                last_media = ai_config.get("lastMediaUrl", "")
                if last_media:
                    context += f"\n\nNote: Tu as récemment envoyé un média à ce client: {last_media}. Tu peux lui demander s'il l'a bien reçu."

                # === V440 : contexte métier + historique + offre résolue en Python ===
                #
                # L'offre est cherchée sur le fil ENTIER (historique + message
                # courant), pas sur le seul message : c'est ce qui fait que
                # « Puis-je payer par Twint ? » garde les « 3 casques » demandés
                # juste avant. La résolution est faite ICI, jamais par le modèle.
                _v440_offres, _v440_hist, _v440_ciblee, _v440_motif = [], [], None, "non calculé"
                try:
                    _v440_offres = await v440_offres_visibles()
                    _v440_hist = await v440_historique_fil(from_phone)
                    _v440_twint = await v440_twint_configure()
                    _v440_fil = " ".join([_t["content"] for _t in _v440_hist] + [incoming_message])
                    _v440_ciblee, _v440_motif = v440_offre_certaine(_v440_fil, _v440_offres)
                    # `maintenant` reste None : le palier tarifaire est donc
                    # recalculé à CET instant, à chaque message. Aucun cache.
                    context += "\n\n" + v440_contexte_metier(
                        _v440_offres, _v440_ciblee, _v440_motif,
                        maintenant=None, twint_disponible=_v440_twint)
                    logger.info("[V440] %d offre(s), %d tour(s), twint=%s — %s | prix actif: %s",
                                len(_v440_offres), len(_v440_hist), _v440_twint, _v440_motif,
                                v440_prix_actif(_v440_ciblee) if _v440_ciblee else "—")
                except Exception as _e_v440:
                    # Le contexte est un PLUS : s'il échoue, on répond comme avant
                    # plutôt que de ne pas répondre du tout.
                    logger.error("[V440] contexte métier ignoré (%s) — flux nu",
                                 _e_v440)

                # `systemPrompt` reste lu tel quel, et n'est jamais réécrit en base.
                full_system_prompt = ai_config.get("systemPrompt", "") + context

                # 4. Appeler l'IA
                try:
                    from openai import OpenAI

                    openai_key = os.environ.get("OPENAI_API_KEY")
                    if not openai_key:
                        logger.error("[META-WEBHOOK] OPENAI_API_KEY not configured")
                        await _save_whatsapp_conversation(
                            from_phone=from_phone,
                            contact_name=client_name or meta_contact_name,
                            incoming_message=incoming_message,
                            ai_response=None
                        )
                        processed += 1
                        continue

                    client = OpenAI(api_key=openai_key)
                    model_name = ai_config.get("model", "gpt-4o-mini")

                    response = await asyncio.to_thread(
                        client.chat.completions.create,
                        model=model_name,
                        messages=(
                            [{"role": "system", "content": full_system_prompt}]
                            + _v440_hist                      # V440 : les tours précédents
                            + [{"role": "user", "content": incoming_message}]
                        ),
                        max_tokens=1000
                    )
                    ai_response = response.choices[0].message.content

                    # === V440 : GARDE DE SORTIE ANTI-INVENTION ===
                    # La consigne du contexte interdit d'inventer une URL ; cette
                    # garde ne lui fait pas confiance et relit le texte sortant.
                    # Toute adresse absente de l'ensemble autorisé est ramenée sur
                    # la racine du site — jamais chez un tiers, jamais vers TWINT.
                    try:
                        ai_response, _v440_retirees = v440_garde_urls(
                            ai_response, v440_urls_autorisees(_v440_offres))
                        if _v440_retirees:
                            logger.warning("[V440] %d URL non autorisée(s) neutralisée(s) : %s",
                                           len(_v440_retirees), _v440_retirees[:3])
                    except Exception as _e_garde:
                        logger.error("[V440] garde de sortie ignorée : %s", _e_garde)

                    response_time = time.time() - start_time

                    # 5. Sauvegarder le log IA
                    log_entry = AILog(
                        fromPhone=from_phone,
                        clientName=client_name,
                        incomingMessage=incoming_message,
                        aiResponse=ai_response,
                        responseTime=response_time
                    ).model_dump()
                    await db.ai_logs.insert_one(log_entry)

                    logger.info(f"[META-WEBHOOK] 🤖 AI responded to {from_phone} in {response_time:.2f}s")

                    # 6. ENVOYER la réponse via Meta Cloud API
                    send_result = await send_whatsapp_direct(
                        to_phone=from_phone,
                        message=ai_response
                    )
                    logger.info(f"[META-WEBHOOK] 📤 Réponse envoyée: {send_result.get('status')}")

                    # 7. Sauvegarder la conversation dans le système de messagerie
                    await _save_whatsapp_conversation(
                        from_phone=from_phone,
                        contact_name=client_name or meta_contact_name,
                        incoming_message=incoming_message,
                        ai_response=ai_response
                    )

                    processed += 1

                except Exception as e:
                    logger.error(f"[META-WEBHOOK] ❌ AI error: {str(e)}")
                    await _save_whatsapp_conversation(
                        from_phone=from_phone,
                        contact_name=client_name or meta_contact_name,
                        incoming_message=incoming_message,
                        ai_response=None
                    )
                    processed += 1

    # Meta exige une réponse 200 OK rapide
    return {"status": "ok", "processed": processed}


async def _save_whatsapp_conversation(from_phone: str, contact_name: str, incoming_message: str, ai_response: str = None):
    """
    Sauvegarde un échange WhatsApp dans le système de conversations privées
    pour qu'il apparaisse dans l'interface de messagerie d'afroboost.com.
    """
    from datetime import datetime, timezone
    import uuid

    try:
        # ID unique basé sur le numéro de téléphone pour le participant WhatsApp
        whatsapp_participant_id = f"whatsapp_{from_phone.replace('+', '')}"
        admin_participant_id = "admin_afroboost"
        display_name = contact_name or from_phone

        # Chercher ou créer la conversation
        existing = await db.private_conversations.find_one({
            "$or": [
                {"participant_1_id": whatsapp_participant_id, "participant_2_id": admin_participant_id},
                {"participant_1_id": admin_participant_id, "participant_2_id": whatsapp_participant_id}
            ]
        }, {"_id": 0})

        if not existing:
            # Créer la conversation
            conv_id = str(uuid.uuid4())
            now = datetime.now(timezone.utc).isoformat()
            conversation = {
                "id": conv_id,
                "participant_1_id": whatsapp_participant_id,
                "participant_1_name": f"📱 {display_name}",
                "participant_2_id": admin_participant_id,
                "participant_2_name": "Afroboost IA",
                "last_message": incoming_message[:100],
                "last_message_at": now,
                "created_at": now,
                "channel": "whatsapp",
                "phone": from_phone
            }
            await db.private_conversations.insert_one(conversation)
            logger.info(f"[META-WEBHOOK] 💬 Nouvelle conversation créée: {conv_id}")
        else:
            conv_id = existing["id"]

        now = datetime.now(timezone.utc).isoformat()

        # Sauvegarder le message entrant du client
        incoming_msg = {
            "id": str(uuid.uuid4()),
            "conversation_id": conv_id,
            "sender_id": whatsapp_participant_id,
            "sender_name": f"📱 {display_name}",
            "recipient_id": admin_participant_id,
            "recipient_name": "Afroboost IA",
            "content": incoming_message,
            "created_at": now,
            "is_deleted": False,
            "channel": "whatsapp"
        }
        await db.private_messages.insert_one(incoming_msg)

        # Sauvegarder la réponse IA si elle existe
        if ai_response:
            ai_msg = {
                "id": str(uuid.uuid4()),
                "conversation_id": conv_id,
                "sender_id": admin_participant_id,
                "sender_name": "Afroboost IA",
                "recipient_id": whatsapp_participant_id,
                "recipient_name": f"📱 {display_name}",
                "content": ai_response,
                "created_at": datetime.now(timezone.utc).isoformat(),
                "is_deleted": False,
                "channel": "whatsapp"
            }
            await db.private_messages.insert_one(ai_msg)

        # Mettre à jour le dernier message de la conversation
        last_content = ai_response[:100] if ai_response else incoming_message[:100]
        await db.private_conversations.update_one(
            {"id": conv_id},
            {"$set": {
                "last_message": last_content,
                "last_message_at": datetime.now(timezone.utc).isoformat(),
                "participant_1_name": f"📱 {display_name}"  # Mettre à jour le nom si on l'a
            }}
        )

        logger.info(f"[META-WEBHOOK] 💾 Conversation sauvegardée: {conv_id}")

    except Exception as e:
        logger.error(f"[META-WEBHOOK] ❌ Erreur sauvegarde conversation: {str(e)}")


# --- Endpoint pour envoyer WhatsApp depuis le frontend (Liaison IA -> Twilio) ---
class SendWhatsAppRequest(BaseModel):
    to: str
    message: str
    mediaUrl: str = None

# === FONCTION UTILITAIRE WHATSAPP — V161: Meta Cloud API + Twilio fallback ===
async def _get_whatsapp_config():
    """
    Récupère la configuration WhatsApp. Priorité:
    1. Variables d'environnement Meta (.env) — PRODUCTION
    2. Configuration Meta en base de données
    3. Variables d'environnement Twilio (.env) — LEGACY fallback
    4. Configuration Twilio en base de données — LEGACY fallback

    Retourne: dict avec api_mode + credentials
    """
    # PRIORITÉ 1: Meta via variables d'environnement
    if META_WHATSAPP_TOKEN and META_WHATSAPP_PHONE_ID:
        logger.info(f"[WHATSAPP] ✅ Mode Meta Cloud API (.env) - Phone ID: {META_WHATSAPP_PHONE_ID}")
        return {
            "api_mode": "meta",
            "access_token": META_WHATSAPP_TOKEN,
            "phone_number_id": META_WHATSAPP_PHONE_ID,
            "api_version": META_WHATSAPP_API_VERSION
        }

    # PRIORITÉ 2: Config en base de données
    whatsapp_config = await db.whatsapp_config.find_one({"id": "whatsapp_config"}, {"_id": 0})
    if whatsapp_config:
        api_mode = whatsapp_config.get("apiMode", "meta")

        if api_mode == "meta":
            token = whatsapp_config.get("metaAccessToken", "")
            phone_id = whatsapp_config.get("metaPhoneNumberId", "")
            if token and phone_id:
                logger.info(f"[WHATSAPP] ✅ Mode Meta Cloud API (DB) - Phone ID: {phone_id}")
                return {
                    "api_mode": "meta",
                    "access_token": token,
                    "phone_number_id": phone_id,
                    "api_version": META_WHATSAPP_API_VERSION
                }

        # Legacy Twilio fallback (DB)
        account_sid = whatsapp_config.get("accountSid", "")
        auth_token = whatsapp_config.get("authToken", "")
        from_number = whatsapp_config.get("fromNumber", "")
        if account_sid and auth_token and from_number:
            logger.info(f"[WHATSAPP] ⚠️ Mode Twilio legacy (DB) - Numéro: {from_number}")
            return {
                "api_mode": "twilio",
                "account_sid": account_sid,
                "auth_token": auth_token,
                "from_number": from_number
            }

    # PRIORITÉ 3: Twilio via variables d'environnement (legacy)
    if TWILIO_ACCOUNT_SID and TWILIO_AUTH_TOKEN and TWILIO_FROM_NUMBER:
        logger.info(f"[WHATSAPP] ⚠️ Mode Twilio legacy (.env) - Numéro: {TWILIO_FROM_NUMBER}")
        return {
            "api_mode": "twilio",
            "account_sid": TWILIO_ACCOUNT_SID,
            "auth_token": TWILIO_AUTH_TOKEN,
            "from_number": TWILIO_FROM_NUMBER
        }

    return None


async def _send_whatsapp_meta(to_phone: str, message: str, media_url: str, config: dict, campaign_id: str = None, campaign_name: str = None, cta_url: str = None, cta_text: str = None) -> dict:
    """Envoi via Meta WhatsApp Cloud API (V161) — V163.2: Support CTA URL interactif"""
    import httpx

    access_token = config["access_token"]
    phone_number_id = config["phone_number_id"]
    api_version = config.get("api_version", "v21.0")

    # Formater le numéro (retirer + et espaces, garder uniquement les chiffres)
    clean_to = to_phone.replace(" ", "").replace("-", "").replace("+", "")
    if clean_to.startswith("0"):
        clean_to = "41" + clean_to[1:]  # Suisse par défaut

    meta_url = f"https://graph.facebook.com/{api_version}/{phone_number_id}/messages"
    headers = {
        "Authorization": f"Bearer {access_token}",
        "Content-Type": "application/json"
    }

    logger.info(f"[WHATSAPP-META] 📤 Envoi vers {clean_to}")

    try:
        async with httpx.AsyncClient(timeout=30.0) as client:
            # V162.3: SÉCURITÉ — Vérifier que media_url n'est pas un lien de PAGE web
            # Les liens de pages web envoyés comme "document" deviennent des fichiers HTML
            # MAIS les URLs CDN (images/vidéos hébergées) doivent passer comme média
            if media_url:
                media_lower_check = media_url.lower()
                # URLs CDN légitimes à ne PAS bloquer (miniatures, images hébergées)
                cdn_safe = ['cdninstagram.com', 'fbcdn.net', 'img.youtube.com',
                            'i.ytimg.com', 'scontent', 'pbs.twimg.com']
                is_cdn = any(cdn in media_lower_check for cdn in cdn_safe)

                if not is_cdn:
                    web_pages = ['instagram.com/p/', 'instagram.com/reel/', 'instagram.com/tv/',
                                 'youtube.com/watch', 'youtube.com/shorts/', 'youtu.be/',
                                 'tiktok.com/', 'facebook.com/', 'twitter.com/', 'x.com/',
                                 'drive.google.com']
                    if any(page in media_lower_check for page in web_pages):
                        logger.warning(f"[WHATSAPP-META] ⚠️ Lien de page web détecté: {media_url[:80]} — converti en texte")
                        message = f"{message}\n\n🔗 {media_url}" if message else media_url
                        media_url = None

            # V163.6: Si CTA URL + miniature → message interactif avec bouton cliquable
            # Format: grande image header + texte + bouton "Voir sur Instagram" cliquable
            if cta_url and media_url:
                cta_display = cta_text or "Voir"
                # Le body ne peut pas dépasser 1024 chars et le display_text 20 chars
                if len(cta_display) > 20:
                    cta_display = cta_display[:20]
                body_text = message[:1024] if message else "Découvrir"

                interactive_payload = {
                    "messaging_product": "whatsapp",
                    "to": clean_to,
                    "type": "interactive",
                    "interactive": {
                        "type": "cta_url",
                        "header": {
                            "type": "image",
                            "image": {
                                "link": media_url
                            }
                        },
                        "body": {
                            "text": body_text
                        },
                        "action": {
                            "name": "cta_url",
                            "parameters": {
                                "display_text": cta_display,
                                "url": cta_url
                            }
                        }
                    }
                }
                import json as json_log
                logger.info(f"[WHATSAPP-META] 🔗 Envoi CTA URL interactif: {cta_display} → {cta_url[:80]}")
                logger.info(f"[WHATSAPP-META] 🔗 Image header: {media_url[:100]}")
                logger.info(f"[WHATSAPP-META] 🔗 Payload CTA: {json_log.dumps(interactive_payload, ensure_ascii=False)[:500]}")

                response = await client.post(meta_url, headers=headers, json=interactive_payload)
                result = response.json()
                logger.info(f"[WHATSAPP-META] 🔗 CTA Response status={response.status_code}: {json_log.dumps(result, ensure_ascii=False)[:300]}")

                if response.status_code < 400:
                    msg_id = result.get("messages", [{}])[0].get("id", "")
                    logger.info(f"[WHATSAPP-META] ✅ CTA URL envoyé avec succès - ID: {msg_id}")
                    return {"status": "success", "sid": msg_id, "to": clean_to}
                else:
                    # Fallback: si CTA URL échoue, envoyer image + texte avec lien cliquable
                    error_detail = result.get("error", {})
                    error_code = error_detail.get("code", "")
                    error_msg = error_detail.get("message", "")
                    logger.error(f"[WHATSAPP-META] ❌ CTA URL ÉCHOUÉ code={error_code}: {error_msg}")
                    logger.error(f"[WHATSAPP-META] ❌ Full error: {json_log.dumps(result, ensure_ascii=False)[:500]}")
                    # Fallback: image + lien dans le texte
                    message = f"{message}\n\n👉 {cta_url}"
                    # Continue vers l'envoi média classique ci-dessous

            # Si média, envoyer le média
            if media_url:
                # Détecter le type de média
                media_lower = media_url.lower()
                if any(ext in media_lower for ext in ['.jpg', '.jpeg', '.png', '.gif', '.webp']):
                    media_type = "image"
                elif any(ext in media_lower for ext in ['.mp4', '.3gp']):
                    media_type = "video"
                elif any(ext in media_lower for ext in ['.mp3', '.ogg', '.wav', '.aac']):
                    media_type = "audio"
                else:
                    media_type = "document"

                media_payload = {
                    "messaging_product": "whatsapp",
                    "to": clean_to,
                    "type": media_type,
                    media_type: {
                        "link": media_url,
                        "caption": message if media_type in ["image", "video", "document"] else None
                    }
                }
                # Nettoyer None du caption
                if media_payload[media_type].get("caption") is None:
                    del media_payload[media_type]["caption"]
                    # Envoyer texte séparément si audio

                response = await client.post(meta_url, headers=headers, json=media_payload)
                result = response.json()

                if response.status_code >= 400:
                    error_detail = result.get("error", {})
                    error_msg = error_detail.get("message", str(result))
                    error_code = error_detail.get("code", response.status_code)
                    logger.error(f"[WHATSAPP-META] ❌ Erreur média [{error_code}]: {error_msg}")

                    try:
                        await db.campaign_errors.insert_one({
                            "campaign_id": campaign_id or "direct_send",
                            "campaign_name": campaign_name or "Envoi Direct",
                            "error_type": "meta_api_error",
                            "error_code": str(error_code),
                            "error_message": error_msg,
                            "channel": "whatsapp",
                            "to_phone": clean_to,
                            "http_status": response.status_code,
                            "created_at": datetime.now(timezone.utc).isoformat()
                        })
                    except Exception:
                        pass

                    return {"status": "error", "error": error_msg, "error_code": str(error_code)}

                # Si audio, envoyer le texte séparément
                if media_type == "audio" and message:
                    text_payload = {
                        "messaging_product": "whatsapp",
                        "to": clean_to,
                        "type": "text",
                        "text": {"body": message, "preview_url": True}
                    }
                    await client.post(meta_url, headers=headers, json=text_payload)

                msg_id = result.get("messages", [{}])[0].get("id", "")
                logger.info(f"[WHATSAPP-META] ✅ Envoyé avec média - ID: {msg_id}")
                return {"status": "success", "sid": msg_id, "to": clean_to}

            else:
                # Message texte simple — V162: preview_url active les aperçus de liens
                text_payload = {
                    "messaging_product": "whatsapp",
                    "to": clean_to,
                    "type": "text",
                    "text": {
                        "body": message,
                        "preview_url": True
                    }
                }

                response = await client.post(meta_url, headers=headers, json=text_payload)
                result = response.json()

                if response.status_code >= 400:
                    error_detail = result.get("error", {})
                    error_msg = error_detail.get("message", str(result))
                    error_code = error_detail.get("code", response.status_code)
                    logger.error(f"[WHATSAPP-META] ❌ Erreur [{error_code}]: {error_msg}")

                    try:
                        await db.campaign_errors.insert_one({
                            "campaign_id": campaign_id or "direct_send",
                            "campaign_name": campaign_name or "Envoi Direct",
                            "error_type": "meta_api_error",
                            "error_code": str(error_code),
                            "error_message": error_msg,
                            "channel": "whatsapp",
                            "to_phone": clean_to,
                            "http_status": response.status_code,
                            "created_at": datetime.now(timezone.utc).isoformat()
                        })
                    except Exception:
                        pass

                    return {"status": "error", "error": error_msg, "error_code": str(error_code)}

                msg_id = result.get("messages", [{}])[0].get("id", "")
                logger.info(f"[WHATSAPP-META] ✅ Envoyé - ID: {msg_id}")
                return {"status": "success", "sid": msg_id, "to": clean_to}

    except Exception as e:
        logger.error(f"[WHATSAPP-META] ❌ Exception: {str(e)}")
        try:
            await db.campaign_errors.insert_one({
                "campaign_id": campaign_id or "direct_send",
                "campaign_name": campaign_name or "Envoi Direct",
                "error_type": "exception",
                "error_code": "EXCEPTION",
                "error_message": str(e),
                "channel": "whatsapp",
                "to_phone": clean_to,
                "created_at": datetime.now(timezone.utc).isoformat()
            })
        except Exception:
            pass
        return {"status": "error", "error": str(e), "error_code": "EXCEPTION"}


async def _send_whatsapp_twilio(to_phone: str, message: str, media_url: str, config: dict, campaign_id: str = None, campaign_name: str = None) -> dict:
    """Envoi via Twilio (legacy fallback)"""
    import httpx

    account_sid = config["account_sid"]
    auth_token = config["auth_token"]
    from_number = config["from_number"]

    clean_to = to_phone.replace(" ", "").replace("-", "")
    if not clean_to.startswith("+"):
        clean_to = "+41" + clean_to.lstrip("0") if clean_to.startswith("0") else "+" + clean_to

    clean_from = from_number if from_number.startswith("+") else "+" + from_number
    twilio_url = f"https://api.twilio.com/2010-04-01/Accounts/{account_sid}/Messages.json"

    # V162.3: Même protection que Meta — bloquer les pages web, pas les CDN
    if media_url:
        media_lower_tw = media_url.lower()
        cdn_safe_tw = ['cdninstagram.com', 'fbcdn.net', 'img.youtube.com',
                       'i.ytimg.com', 'scontent', 'pbs.twimg.com']
        is_cdn_tw = any(cdn in media_lower_tw for cdn in cdn_safe_tw)
        if not is_cdn_tw:
            web_pages_tw = ['instagram.com/p/', 'instagram.com/reel/', 'instagram.com/tv/',
                            'youtube.com/watch', 'youtube.com/shorts/', 'youtu.be/',
                            'tiktok.com/', 'facebook.com/', 'twitter.com/', 'x.com/',
                            'drive.google.com']
            if any(page in media_lower_tw for page in web_pages_tw):
                logger.warning(f"[WHATSAPP-TWILIO] ⚠️ Lien de page web détecté: {media_url[:80]} — converti en texte")
                message = f"{message}\n\n🔗 {media_url}" if message else media_url
                media_url = None

    data = {"From": f"whatsapp:{clean_from}", "To": f"whatsapp:{clean_to}", "Body": message}
    if media_url:
        data["MediaUrl"] = media_url

    logger.info(f"[WHATSAPP-TWILIO] 📤 Envoi via {clean_from} vers {clean_to}")

    try:
        async with httpx.AsyncClient(timeout=30.0) as client:
            response = await client.post(twilio_url, data=data, auth=(account_sid, auth_token))
            result = response.json()

            if response.status_code >= 400:
                error_msg = result.get("message", "Unknown error")
                error_code = result.get("code", response.status_code)
                logger.error(f"[WHATSAPP-TWILIO] ❌ Erreur [{error_code}]: {error_msg}")
                try:
                    await db.campaign_errors.insert_one({
                        "campaign_id": campaign_id or "direct_send",
                        "campaign_name": campaign_name or "Envoi Direct",
                        "error_type": "twilio_api_error",
                        "error_code": str(error_code),
                        "error_message": error_msg,
                        "channel": "whatsapp",
                        "to_phone": clean_to,
                        "from_phone": clean_from,
                        "http_status": response.status_code,
                        "created_at": datetime.now(timezone.utc).isoformat()
                    })
                except Exception:
                    pass
                return {"status": "error", "error": error_msg, "error_code": str(error_code)}

            sid = result.get("sid", "")
            logger.info(f"[WHATSAPP-TWILIO] ✅ Envoyé - SID: {sid}")
            return {"status": "success", "sid": sid, "to": clean_to, "from": clean_from}

    except Exception as e:
        logger.error(f"[WHATSAPP-TWILIO] ❌ Exception: {str(e)}")
        return {"status": "error", "error": str(e), "error_code": "EXCEPTION"}


async def _send_whatsapp_campaign_template(to_phone: str, campaign_message: str, media_url: str = None, cta_url: str = None, cta_text: str = None, campaign_id: str = None, campaign_name: str = None) -> dict:
    """
    V164: Envoie un message de campagne via le template WhatsApp approuvé 'afroboost_campagne'.
    Template: "Afroboost vous informe: {{1}}. Rendez-vous sur afroboost.com"

    Les messages template sont OBLIGATOIRES pour contacter des utilisateurs qui n'ont
    jamais écrit au numéro business (conversations initiées par l'entreprise).
    """
    import httpx

    config = await _get_whatsapp_config()
    if not config or config["api_mode"] != "meta":
        logger.warning("[WHATSAPP-CAMPAIGN] ❌ Config Meta manquante — fallback message direct")
        return await send_whatsapp_direct(to_phone, campaign_message, media_url, campaign_id, campaign_name, cta_url, cta_text)

    access_token = config["access_token"]
    phone_number_id = config["phone_number_id"]
    api_version = config.get("api_version", "v21.0")

    clean_to = to_phone.replace(" ", "").replace("-", "").replace("+", "")
    if clean_to.startswith("0"):
        clean_to = "41" + clean_to[1:]

    meta_url = f"https://graph.facebook.com/{api_version}/{phone_number_id}/messages"
    headers = {
        "Authorization": f"Bearer {access_token}",
        "Content-Type": "application/json"
    }

    # V168: APPROCHE UNIQUE — Mettre TOUT le message dans la variable {{1}} du template
    # Le template "afroboost_campagne" = "Afroboost vous informe: {{1}}. Rendez-vous sur afroboost.com"
    # La variable {{1}} accepte jusqu'à 1024 caractères, on y met le message complet (nettoyé)
    import re as re_tpl
    import json as json_log

    # Préparer le message COMPLET pour la variable {{1}} du template
    full_text = (campaign_message or "Découvrez nos nouveautés").strip()

    # V171: Ajouter le lien CTA si fourni — SANS protocole (Meta bloque https://)
    if cta_url:
        cta_label = cta_text or "En savoir plus"
        clean_url = re_tpl.sub(r'https?://(www\.)?', '', cta_url)
        full_text += f" - {cta_label}: {clean_url}"

    # V171: Revenir au nettoyage V168.1 qui MARCHAIT (message à 13:57)
    # Supprimer emojis
    template_var = re_tpl.sub(
        r'[\U0001F600-\U0001F64F\U0001F300-\U0001F5FF\U0001F680-\U0001F6FF'
        r'\U0001F1E0-\U0001F1FF\U00002702-\U000027B0\U000024C2-\U0001F251'
        r'\U0001F900-\U0001F9FF\U0001FA00-\U0001FAFF\U00002600-\U000026FF'
        r'\U0000FE00-\U0000FE0F\U0000200D]+', '', full_text
    )
    # V171.1: Retirer SEULEMENT le protocole (https://www.) mais GARDER le domaine
    # "https://www.afroboost.com/?link=15e88d" → "afroboost.com/?link=15e88d" (cliquable!)
    template_var = re_tpl.sub(r'https?://(www\.)?', '', template_var)
    # V379 : PONCTUATION plutôt que tirets. Une variable de template ne peut
    # contenir ni saut de ligne ni tabulation (Meta rejette le message) : il faut
    # donc aplatir le texte. Le remplacement par « - » donnait une bouillie
    # (« en beauté ! - Petit changement : - Mise à jour… »). On regarde désormais
    # ce qui PRÉCÈDE le saut de ligne : si la phrase est déjà ponctuée, un simple
    # espace suffit ; sinon on ferme par un point. Le sens et le rythme sont
    # conservés, sans caractère parasite.
    # On capture le dernier caractère NON BLANC avant le saut de ligne : les emojis
    # ayant déjà été retirés, il reste souvent une espace, et « Bonjour Marie \n »
    # serait devenu « Bonjour Marie . » (espace avant le point) sans cette précaution.
    def _v379_recoller(m):
        avant = m.group(1)
        if avant and avant in ".!?:;…":
            return avant + " "
        return (avant or "") + ". "
    template_var = re_tpl.sub(r'([^\s]?)[ \t]*\n+[ \t]*', _v379_recoller, template_var)
    # Remplacer tirets spéciaux
    template_var = template_var.replace('—', '-').replace('–', '-')
    # Remplacer les caractères gras Unicode par leurs équivalents ASCII
    bold_map = {}
    for i, c in enumerate('ABCDEFGHIJKLMNOPQRSTUVWXYZ'):
        bold_map[chr(0x1D5D4 + i)] = c
    for i, c in enumerate('abcdefghijklmnopqrstuvwxyz'):
        bold_map[chr(0x1D5EE + i)] = c
    for old_c, new_c in bold_map.items():
        template_var = template_var.replace(old_c, new_c)
    # Garder UNIQUEMENT lettres, chiffres, ponctuation basique, accents
    template_var = re_tpl.sub(r'[^\w\s\.,;:!\?\'-/()àâäéèêëïîôùûüçœæÀÂÄÉÈÊËÏÎÔÙÛÜÇŒÆ°€@&=%+]', '', template_var)
    template_var = re_tpl.sub(r'\s{2,}', ' ', template_var).strip()
    # Limiter à 1024 chars (limite Meta pour les variables)
    template_var = template_var[:1024] if template_var else "Decouvrez nos nouveautes"

    logger.info(f"[WHATSAPP-CAMPAIGN] Variable template: {template_var}")

    # ÉTAPE 1: Envoyer le template (ouvre la fenêtre de conversation 24h)
    template_payload = {
        "messaging_product": "whatsapp",
        "to": clean_to,
        "type": "template",
        "template": {
            "name": "afroboost_campagne",
            "language": {"code": "fr"},
            "components": [
                {
                    "type": "body",
                    "parameters": [
                        {"type": "text", "text": template_var}
                    ]
                }
            ]
        }
    }

    logger.info(f"[WHATSAPP-CAMPAIGN] ÉTAPE 1: Template vers {clean_to}")

    try:
        async with httpx.AsyncClient(timeout=30.0) as client:
            response = await client.post(meta_url, headers=headers, json=template_payload)
            result = response.json()
            logger.info(f"[WHATSAPP-CAMPAIGN] Template response: {response.status_code} - {json_log.dumps(result, ensure_ascii=False)[:300]}")

            if response.status_code >= 400:
                error_detail = result.get("error", {})
                error_code = error_detail.get("code", "")
                error_msg = error_detail.get("message", str(result))
                logger.error(f"[WHATSAPP-CAMPAIGN] Template error [{error_code}]: {error_msg}")
                try:
                    await db.campaign_errors.insert_one({
                        "campaign_id": campaign_id or "direct_send",
                        "campaign_name": campaign_name or "Campagne",
                        "error_type": "template_error",
                        "error_code": str(error_code),
                        "error_message": error_msg,
                        "channel": "whatsapp",
                        "to_phone": clean_to,
                        "http_status": response.status_code,
                        "created_at": datetime.now(timezone.utc).isoformat()
                    })
                except Exception:
                    pass
                return {"status": "error", "error": error_msg, "error_code": str(error_code)}

            msg_id = result.get("messages", [{}])[0].get("id", "")
            logger.info(f"[WHATSAPP-CAMPAIGN] V168 Template OK - ID: {msg_id} - Variable ({len(template_var)} chars)")

            return {"status": "success", "sid": msg_id, "to": clean_to}

    except Exception as e:
        logger.error(f"[WHATSAPP-CAMPAIGN] Exception: {str(e)}")
        return {"status": "error", "error": str(e), "error_code": "EXCEPTION"}


async def send_whatsapp_direct(to_phone: str, message: str, media_url: str = None, campaign_id: str = None, campaign_name: str = None, cta_url: str = None, cta_text: str = None) -> dict:
    """
    V161: Fonction unifiée pour envoyer un message WhatsApp.
    Route automatiquement vers Meta Cloud API ou Twilio selon la config.
    V163.2: Support CTA URL — miniature cliquable qui redirige vers le lien.
    """
    config = await _get_whatsapp_config()

    if not config:
        logger.warning("[WHATSAPP] ❌ Aucune configuration WhatsApp — mode simulation")
        return {"status": "simulated", "message": f"WhatsApp simulé pour: {to_phone}", "simulated": True}

    if config["api_mode"] == "meta":
        return await _send_whatsapp_meta(to_phone, message, media_url, config, campaign_id, campaign_name, cta_url=cta_url, cta_text=cta_text)
    else:
        return await _send_whatsapp_twilio(to_phone, message, media_url, config, campaign_id, campaign_name)
@api_router.post("/send-whatsapp")
async def send_whatsapp_message(payload: SendWhatsAppRequest, request: Request):
    """
    Endpoint pour envoyer un message WhatsApp.
    Utilise la config Twilio avec PRIORITÉ aux variables .env.

    V442 — CETTE ROUTE ÉTAIT OUVERTE À TOUT LE MONDE. Vérifié en production le
    16/08/2026 : un `curl` anonyme atteignait la validation Pydantic
    (`422 Field required: to, message`), donc un appel avec un corps COMPLET
    aurait ENVOYÉ un vrai WhatsApp depuis le numéro business d'Afroboost.
    Conséquences possibles : spam facturé au compte, chute de la note de
    qualité, et surtout suspension du WABA par Meta.

    Ses deux routes sœurs `/send-whatsapp-template` et `/create-whatsapp-template`
    ont été fermées par V435 le 12/08 ; celle-ci a été oubliée. Preuve de
    l'asymétrie, mesurée le même jour sur la production :
        POST /api/send-whatsapp           -> 422 (aucune garde)
        POST /api/send-whatsapp-template  -> 403 (garde V435)
    On pose donc ICI la garde IDENTIQUE à celle de la jumelle. Le chemin d'envoi
    moderne (`POST /private/whatsapp/envoyer`, V434) l'utilise déjà lui aussi :
    les trois portes qui mènent au même numéro business sont enfin les mêmes.

    Pourquoi `_v411_exiger_super_admin` et pas une garde plus large : c'est la
    seule qui n'accepte JAMAIS `X-User-Email`. `require_auth` et
    `_v263_authenticated_coach` gardent un repli inconditionnel sur cet en-tête
    falsifiable, et `_v319_coach_identity` ne s'en protège que si le drapeau
    `REQUIRE_COACH_JWT` est ON — un état de base de données modifiable à chaud,
    dont l'`except` retombe volontairement sur le mode permissif. Une porte qui
    ouvre le numéro business ne peut pas dépendre d'un réglage.

    ⚠️ Le paramètre du corps s'appelait `request`, ce qui interdisait d'injecter
    l'objet `Request` de Starlette — c'est-à-dire, littéralement, ce qui rendait
    toute authentification IMPOSSIBLE sur cette route. Il est renommé `payload`.
    Le contrat de l'API est INCHANGÉ : FastAPI lie le corps par le TYPE (modèle
    Pydantic), jamais par le nom du paramètre, et un modèle unique reste au
    premier niveau du JSON. Vérifié sur l'`openapi.json` de la production, où
    `create_course(course: CourseCreate, request: Request)` expose bien
    `CourseCreate` au premier niveau et `parameters: null`. Les appelants
    continuent d'envoyer `{"to": …, "message": …, "mediaUrl": …}`.

    Le moteur d'envoi lui-même (`send_whatsapp_direct`) n'est PAS touché, et les
    envois internes ne le sont pas non plus : campagnes, webhook entrant, réponse
    manuelle du coach et renouvellements V195 appellent la FONCTION en Python,
    jamais cette route HTTP.
    """
    _v411_exiger_super_admin(request, "envoi WhatsApp direct (route héritée V161)")
    return await send_whatsapp_direct(
        to_phone=payload.to,
        message=payload.message,
        media_url=payload.mediaUrl
    )

@api_router.post("/send-whatsapp-template")
async def send_whatsapp_template(data: dict, request: Request):
    """V163.8: Envoyer un message template WhatsApp (requis pour les premiers messages business)

    V435 — CETTE ROUTE ÉTAIT OUVERTE À TOUT LE MONDE. Vérifié en production le
    12/08 : un `curl` anonyme atteignait la validation (`400 Numéro 'to' requis`),
    donc un appel complet aurait ENVOYÉ un WhatsApp depuis le numéro business
    d'Afroboost. Conséquences possibles : spam facturé au compte, et surtout
    suspension du WABA par Meta — ce qui couperait la campagne en cours.
    On exige désormais le même jeton super-admin signé que les fils privés.
    """
    _v411_exiger_super_admin(request, "envoi de modèle WhatsApp (route héritée)")
    import httpx
    to_phone = data.get("to", "")
    template_name = data.get("template", "hello_world")
    template_lang = data.get("language", "en_US")
    template_params = data.get("params", [])

    if not to_phone:
        raise HTTPException(status_code=400, detail="Numéro 'to' requis")

    config = await _get_whatsapp_config()
    if config["api_mode"] != "meta":
        raise HTTPException(status_code=400, detail="Mode Meta requis")

    access_token = config["access_token"]
    phone_number_id = config["phone_number_id"]
    api_version = config.get("api_version", "v21.0")

    clean_to = to_phone.replace(" ", "").replace("-", "").replace("+", "")
    if clean_to.startswith("0"):
        clean_to = "41" + clean_to[1:]

    meta_url = f"https://graph.facebook.com/{api_version}/{phone_number_id}/messages"
    headers = {
        "Authorization": f"Bearer {access_token}",
        "Content-Type": "application/json"
    }

    # Construire le payload template
    template_payload = {
        "messaging_product": "whatsapp",
        "to": clean_to,
        "type": "template",
        "template": {
            "name": template_name,
            "language": {"code": template_lang}
        }
    }

    # Ajouter les paramètres si fournis
    if template_params:
        template_payload["template"]["components"] = [{
            "type": "body",
            "parameters": [{"type": "text", "text": p} for p in template_params]
        }]

    import json as json_tpl
    logger.info(f"[WHATSAPP-TEMPLATE] 📤 Envoi template '{template_name}' à {clean_to}")
    logger.info(f"[WHATSAPP-TEMPLATE] 📤 Payload: {json_tpl.dumps(template_payload, ensure_ascii=False)[:500]}")

    async with httpx.AsyncClient(timeout=30.0) as client:
        response = await client.post(meta_url, headers=headers, json=template_payload)
        result = response.json()
        logger.info(f"[WHATSAPP-TEMPLATE] Response {response.status_code}: {json_tpl.dumps(result, ensure_ascii=False)[:500]}")

        if response.status_code < 400:
            msg_id = result.get("messages", [{}])[0].get("id", "")
            return {"status": "success", "sid": msg_id, "to": clean_to, "template": template_name}
        else:
            error = result.get("error", {})
            return {"status": "error", "code": error.get("code"), "message": error.get("message"), "to": clean_to}

