# --- Get Session Participants (for community chat) ---
@api_router.get("/chat/sessions/{session_id}/participants")
async def get_session_participants(session_id: str):
    """Récupère les détails des participants d'une session"""
    session = await db.chat_sessions.find_one({"id": session_id}, {"_id": 0})
    if not session:
        raise HTTPException(status_code=404, detail="Session non trouvée")
    
    participant_ids = session.get("participant_ids", [])
    participants = []
    
    for pid in participant_ids:
        participant = await db.chat_participants.find_one({"id": pid}, {"_id": 0})
        if participant:
            participants.append({
                "id": participant.get("id"),
                "name": participant.get("name"),
                "last_seen_at": participant.get("last_seen_at")
            })
    
    return participants

# === WEB PUSH NOTIFICATIONS ===

@api_router.get("/push/vapid-key")
async def get_vapid_public_key():
    """Retourne la clé publique VAPID pour l'inscription côté client"""
    return {"publicKey": VAPID_PUBLIC_KEY}

@api_router.post("/push/subscribe")
async def subscribe_push(request: Request):
    """Enregistre une souscription push. Si endpoint existe deja pour autre user, le reassigner."""
    body = await request.json()
    participant_id = body.get("participant_id")
    subscription = body.get("subscription")
    if not participant_id or not subscription:
        raise HTTPException(status_code=400, detail="participant_id et subscription requis")
    endpoint = subscription.get("endpoint", "")
    # Securite: si endpoint existe pour AUTRE user, le reassigner au nouveau
    if endpoint:
        await db.push_subscriptions.update_one({"subscription.endpoint": endpoint}, {"$set": {"participant_id": participant_id, "subscription": subscription, "active": True, "updated_at": datetime.now(timezone.utc).isoformat()}}, upsert=True)
    else:
        await db.push_subscriptions.update_one({"participant_id": participant_id}, {"$set": {"subscription": subscription, "active": True}}, upsert=True)
    logger.debug(f"[PUSH] Subscribe OK: {participant_id[:8]}...")
    return {"success": True}

@api_router.delete("/push/subscribe/{participant_id}")
async def unsubscribe_push(participant_id: str):
    """Desactive la souscription push d'un participant"""
    await db.push_subscriptions.update_one({"participant_id": participant_id}, {"$set": {"active": False}})
    return {"success": True}

async def send_push_notification(participant_id: str, title: str, body: str, data: dict = None, session_id: str = None):
    """Envoie une notification push a un participant (sauf si socket actif)."""
    if not WEBPUSH_AVAILABLE or not VAPID_PRIVATE_KEY:
        return False
    # Verifier si socket actif (chat ouvert) - evite vibration inutile
    # Socket.IO désactivé en mode Vercel Serverless - envoyer toujours la notification
    # if session_id:
    #     try:
    #         room_sids = list(sio.manager.rooms.get('/', {}).get(session_id, set()))
    #         if room_sids:
    #             logger.debug(f"[PUSH] Skip - socket actif")
    #             return False
    #     except Exception:
    #         pass
    # V245: un participant peut avoir PLUSIEURS souscriptions (le frontend
    # re-souscrit sans dedupliquer). L'ancien `find_one` n'en testait qu'une :
    # si c'etait une souscription expiree, l'envoi echouait alors qu'une autre,
    # fraiche, aurait pu aboutir. On les essaie TOUTES et on s'arrete au premier
    # succes ; chaque endpoint mort (404/410) est desactive individuellement par
    # son propre endpoint, pas en bloc sur le participant_id.
    # V433: sans tri, MongoDB rend l'ordre naturel (= ordre d'insertion), donc
    # `.to_list(20)` ne retenait que les 20 souscriptions les PLUS ANCIENNES.
    # Mesure du 12/08/2026 sur le compte coach (183 souscriptions actives) :
    # les 20 essayees avaient 120 a 151 jours, toutes mortes, tandis que la plus
    # fraiche (0 jour) n'etait JAMAIS tentee -> aucune notification ne partait.
    # On trie donc du plus recent au plus ancien. Le filtre est inchange : seul
    # l'ORDRE D'ESSAI change, pas l'ensemble des souscriptions retenues. Les
    # documents sans `updated_at` sont classes en dernier par MongoDB, ce qui
    # est le repli voulu (essayes apres ceux qui sont dates).
    subs = await db.push_subscriptions.find(
        {"participant_id": participant_id, "active": True}, {"_id": 0}
    ).sort("updated_at", -1).to_list(20)
    if not subs:
        return False

    # === V437 : notifier jusqu'a 3 APPAREILS, plus un seul ===
    #
    # V433 avait corrige l'ORDRE (les plus recents d'abord) mais la boucle
    # s'arretait au PREMIER succes. Or un coach a plusieurs appareils : n'en
    # notifier qu'un, choisi par un tri a la seconde pres, revient a tirer au
    # sort lequel sonnera.
    #
    # Mesure du 13/08/2026 : sur les 185 abonnements du compte coach, le
    # navigateur de bureau s'etait reabonne 29 SECONDES apres le telephone. Il
    # est passe en tete, FCM l'a accepte, la boucle s'est arretee — et le
    # Samsung, au rang 2, n'a jamais ete sollicite. Le push etait pourtant
    # « reussi » cote serveur.
    #
    # On vise donc les 3 plus recents, endpoints DEDUPLIQUES (un meme appareil
    # ne doit jamais recevoir deux fois le meme push dans un seul appel), et on
    # ne parcourt JAMAIS les 185 : la borne protege des envois inutiles vers des
    # endpoints morts.
    V437_MAX_APPAREILS = 3
    _vus = set()
    _cibles = []
    for _s in subs:
        _info = _s.get("subscription") or {}
        _ep = str(_info.get("endpoint") or "").strip()
        if not _ep or _ep in _vus:
            continue
        _vus.add(_ep)
        _cibles.append(_s)
        if len(_cibles) >= V437_MAX_APPAREILS:
            break
    if not _cibles:
        return False
    subs = _cibles
    # V274: le Service Worker lit `url` et `session_id` au niveau RACINE du
    # payload (cf. sw.js). On les y expose : au clic, la notification ouvre le
    # chat (`/?openChat=true` par defaut) au lieu de la seule page d'accueil.
    _push_url = (data or {}).get("url") or "/?openChat=true"
    payload = json.dumps({
        "title": title, "body": body,
        "icon": "/logo192.png", "badge": "/notification-badge-96.png",  # V445 : le badge
        # Android n'est qu'un masque alpha — le logo couleur y donnait un carre blanc.
        # (Le Service Worker code ses propres valeurs en dur et ignore celles-ci ;
        #  on les corrige tout de meme pour qu'aucune des deux ne mente.)
        "url": _push_url, "session_id": session_id,
        "data": data or {},
        "timestamp": datetime.now(timezone.utc).isoformat()
    })
    any_sent = False
    # === V439-DIAG : statut HTTP REEL retourne par FCH pour CHAQUE endpoint ===
    #
    # `webpush()` renvoie un objet portant `.status_code`, et cette valeur etait
    # JETEE. On savait donc qu'aucune exception n'avait ete levee, mais pas quel
    # appareil avait recu quel code : « FCM a accepte » n'etait qu'une deduction
    # tiree de l'absence d'erreur.
    #
    # Diagnostic PUR : aucun comportement ne change, aucun envoi supplementaire.
    # Le but est de trancher entre « FCM refuse » et « FCM accepte mais Android
    # n'affiche pas » — sans toucher au Service Worker tant que ce n'est pas
    # prouve necessaire.
    #
    # AUCUNE DONNEE SENSIBLE : on journalise le RANG dans la liste V437, une
    # empreinte courte de l'endpoint (sha256 tronque, non reversible) et le
    # statut HTTP. Jamais l'endpoint complet, jamais les cles `p256dh`/`auth`,
    # jamais le jeton VAPID.
    import hashlib as _h439
    _rang = 0
    for sub in subs:
        subscription_info = sub.get("subscription")
        if not subscription_info:
            continue
        _endpoint = subscription_info.get("endpoint", "")
        _rang += 1
        _emp = _h439.sha256(_endpoint.encode()).hexdigest()[:10] if _endpoint else "sans-endpoint"
        try:
            # V434: TTL EXPLICITE. pywebpush 2.2.0 met `ttl=0` par defaut et
            # envoie bel et bien l'en-tete `TTL: 0` (__init__.py:349-351,
            # "Generating TTL of 0..."). Or TTL 0 signifie « livre a cet instant
            # precis ou jette » : quand la veille profonde de Samsung ou le Doze
            # d'Android deconnecte le telephone de FCM, Google accepte le message
            # (201 Created) puis le SUPPRIME sans jamais le livrer. Mesure du
            # 12/08/2026 sur le S24 Ultra de Bassi : abonnement valide, VAPID
            # valide, FCM 201 — et aucune notification affichee. 3600 s couvre
            # ces fenetres de veille sans conserver un message devenu inutile
            # pendant des heures.
            _rep439 = webpush(subscription_info=subscription_info, data=payload, vapid_private_key=VAPID_PRIVATE_KEY, vapid_claims={"sub": f"mailto:{VAPID_CLAIMS_EMAIL}"}, ttl=3600)
            logger.info("[PUSH-FCM] rang=%d emp=%s statut=%s", _rang, _emp, getattr(_rep439, "status_code", "?"))
            any_sent = True
            # V437 : PLUS DE `break`. On tente les 3 appareils retenus, meme si
            # le premier a abouti — c'est le comportement voulu (telephone ET
            # navigateur, comme WhatsApp ou Slack). `any_sent` passe a vrai des
            # qu'un seul accepte ; un endpoint en echec n'empeche pas les autres,
            # la gestion 404/410 restant endpoint par endpoint.
        except WebPushException as e:
            _st439 = e.response.status_code if e.response is not None else "exception"
            logger.info("[PUSH-FCM] rang=%d emp=%s statut=%s", _rang, _emp, _st439)
            if e.response is not None and e.response.status_code in [404, 410]:
                # V245: desactiver PAR endpoint, pas tout le participant — sinon
                # une souscription morte tuerait aussi les fraiches du meme pid.
                if _endpoint:
                    await db.push_subscriptions.update_one({"subscription.endpoint": _endpoint}, {"$set": {"active": False}})
                else:
                    await db.push_subscriptions.update_one({"participant_id": participant_id, "subscription": subscription_info}, {"$set": {"active": False}})
                logger.debug(f"[PUSH] Souscription expiree desactivee (410/404)")
            else:
                logger.error(f"[PUSH] Echec critique: {str(e)}")
        except Exception as e:
            logger.info("[PUSH-FCM] rang=%d emp=%s statut=exception-reseau (%s)", _rang, _emp, type(e).__name__)
            logger.error(f"[PUSH] Erreur: {str(e)}")
    return any_sent

async def send_push_by_email(email: str, title: str, body: str, data: dict = None):
    """V180/V206: Envoie une notification push à tous les participants liés à un email."""
    if not email or not WEBPUSH_AVAILABLE or not VAPID_PRIVATE_KEY:
        return False
    email_lower = email.lower().strip()
    candidate_pids = set()
    # V206: Chercher directement dans push_subscriptions par email ET par coach_ prefix
    try:
        async for ps in db.push_subscriptions.find({"email": email_lower}, {"_id": 0, "participant_id": 1}):
            if ps.get("participant_id"):
                candidate_pids.add(ps["participant_id"])
    except Exception:
        pass
    # V206: Aussi chercher avec le préfixe coach_ (enregistré par le dashboard)
    candidate_pids.add(f"coach_{email_lower}")
    # V181: Chercher dans chat_participants ET users (CRM)
    try:
        async for p in db.chat_participants.find({"email": email_lower}, {"_id": 0, "id": 1}):
            if p.get("id"):
                candidate_pids.add(p["id"])
    except Exception:
        pass
    try:
        async for u in db.users.find({"email": email_lower}, {"_id": 0, "id": 1}):
            if u.get("id"):
                candidate_pids.add(u["id"])
    except Exception:
        pass
    # V246: trace du flux push pour diagnostic en production.
    logger.info(f"[PUSH-DEBUG] envoi a {email_lower} — {len(candidate_pids)} pid(s) candidat(s)")
    sent = 0
    for pid in candidate_pids:
        if not pid:
            continue
        if await send_push_notification(pid, title, body, data):
            sent += 1
    logger.info(f"[PUSH-DEBUG] resultat pour {email_lower}: {sent} envoi(s) reussi(s) sur {len(candidate_pids)} pid(s) — « {title} »")
    return sent > 0


# V183: Endpoint broadcast pour annoncer un nouveau cours/info à tous les abonnés
@api_router.post("/push/broadcast")
async def push_broadcast(request: Request):
    """V183: Envoie une notification push à tous les abonnés actifs (annonces, nouveau cours)."""
    body = await request.json()
    title = (body.get("title") or "").strip()
    message = (body.get("body") or "").strip()
    coach_id = body.get("coach_id") or DEFAULT_COACH_ID
    if not title or not message:
        raise HTTPException(status_code=400, detail="title et body requis")
    caller_email = (request.headers.get("X-User-Email", "") or "").lower().strip()
    if not is_super_admin(caller_email):
        raise HTTPException(status_code=403, detail="Réservé super admin")
    try:
        subs = await db.push_subscriptions.find({"active": True}, {"_id": 0, "participant_id": 1}).to_list(2000)
    except Exception as e:
        logger.error(f"[BROADCAST-V183] erreur lecture subs: {e}")
        raise HTTPException(status_code=500, detail="Erreur DB")
    sent = 0
    for s in subs:
        pid = s.get("participant_id")
        if not pid:
            continue
        try:
            if await send_push_notification(pid, title, message, {"type": "broadcast", "coach_id": coach_id}):
                sent += 1
        except Exception:
            continue
    logger.info(f"[BROADCAST-V183] {sent}/{len(subs)} notifs envoyées (titre: {title})")
    return {"success": True, "sent": sent, "total": len(subs)}


# === N1B-1 : SOCLE — un marqueur d'envoi PAR RAPPEL ===
#
# `reminder_sent` est un BOOLEEN UNIQUE par reservation. Il suffisait tant qu'il
# n'existait qu'un seul rappel, mais il rend tout second rappel impossible : le
# premier envoi bloquerait definitivement le suivant (24 h avant PUIS le jour du
# cours, par exemple).
#
# On introduit donc `reminders_sent`, un DICTIONNAIRE {cle_de_rappel: horodatage}.
# Chaque rappel configure portera sa propre cle, ce qui rend l'idempotence
# independante rappel par rappel.
#
# CE LOT NE CHANGE AUCUN COMPORTEMENT. Il pose la structure et rien d'autre :
#   - le rappel historique garde la cle `defaut` ;
#   - l'ancien booleen CONTINUE d'etre ecrit pour cette cle, donc toute requete
#     ou tout code qui le lit se comporte exactement comme avant ;
#   - une reservation d'AVANT ce lot, qui ne porte que le booleen, est reconnue
#     comme deja envoyee (retrocompatibilite verifiee sur les 2 documents
#     concernes en base).
# Les nouveaux modes (X heures avant, jour J a HH:MM) ne sont PAS branches ici.
N1B_CLE_HERITEE = "defaut"


def n1b_deja_envoye(reservation: dict, cle: str) -> bool:
    """Ce rappel precis a-t-il deja ete envoye pour cette reservation ?"""
    _envois = reservation.get("reminders_sent")
    if isinstance(_envois, dict) and _envois.get(cle):
        return True
    # Retrocompat : avant N1B-1, seul le booleen existait.
    if cle == N1B_CLE_HERITEE and reservation.get("reminder_sent") is True:
        return True
    return False


async def n1b_marquer_envoye(reservation_id: str, cle: str, quand: str) -> None:
    """Marque CE rappel comme envoye, sans toucher aux autres.

    Le point-cle de la retrocompatibilite : pour la cle historique, on continue
    d'ecrire `reminder_sent` / `reminder_sent_at` a l'identique. Aucune lecture
    existante ne change de resultat.
    """
    _maj = {f"reminders_sent.{cle}": quand}
    if cle == N1B_CLE_HERITEE:
        _maj["reminder_sent"] = True
        _maj["reminder_sent_at"] = quand
    await db.reservations.update_one({"id": reservation_id}, {"$set": _maj})


# === RAPPELS V2 : DEUX CANAUX, SUIVIS SEPAREMENT ===
#
# Jusqu'ici un rappel etait une chose unique : un push. `reminders_sent` portait
# donc une simple chaine par regle -> {cle: horodatage}.
#
# Le rappel devient double, push ET e-mail, et les deux doivent vivre leur vie
# separement : l'un peut echouer sans condamner l'autre, l'un peut etre refuse
# par l'abonne sans priver l'autre. Le marqueur devient donc un sous-document
# par canal :
#
#     reminders_sent: {"defaut": {"push": "2026-...", "email": "2026-..."}}
#
# AUCUNE migration de masse n'est faite : les deux formes cohabitent en base.
# Une chaine rencontree signifie « le push historique est parti » — et rien de
# plus, puisque l'e-mail n'existait pas quand elle a ete ecrite.
RV2_CANAL_PUSH = "push"
RV2_CANAL_EMAIL = "email"
RV2_CANAUX = (RV2_CANAL_PUSH, RV2_CANAL_EMAIL)

# `notifications@afroboost.com` n'est pas une boite relevee. Une reponse d'un
# abonne a son rappel doit atterrir chez quelqu'un.
RV2_REPLY_TO = os.environ.get("AFROBOOST_REPLY_TO_RAPPELS", "contact.artboost@gmail.com")

RV2_JOURS = ("lundi", "mardi", "mercredi", "jeudi", "vendredi", "samedi", "dimanche")
RV2_MOIS = ("janvier", "fevrier", "mars", "avril", "mai", "juin",
            "juillet", "aout", "septembre", "octobre", "novembre", "decembre")


def rv2_deja_envoye(reservation: dict, cle: str, canal: str) -> bool:
    """Ce rappel est-il deja parti SUR CE CANAL ?

    Trois formes de marqueur cohabitent, de la plus recente a la plus ancienne :
      1. sous-document par canal   -> on lit le canal demande ;
      2. chaine (avant ce lot)     -> le push est parti, l'e-mail non ;
      3. booleen `reminder_sent`   -> idem, pour la seule cle historique.
    """
    _envois = reservation.get("reminders_sent")
    if isinstance(_envois, dict):
        _valeur = _envois.get(cle)
        if isinstance(_valeur, dict):
            return bool(_valeur.get(canal))
        if _valeur:
            return canal == RV2_CANAL_PUSH
    if (canal == RV2_CANAL_PUSH and cle == N1B_CLE_HERITEE
            and reservation.get("reminder_sent") is True):
        return True
    return False


async def rv2_normaliser_marqueur(reservation: dict, cle: str) -> None:
    """Convertit un marqueur herite (chaine) en sous-document {push: horodatage}.

    Sans cela, un `$set` sur `reminders_sent.<cle>.email` echouerait : MongoDB
    refuse de creer un champ a l'interieur d'une chaine. La conversion est
    conditionnee a la valeur exacte relue, donc deux crons concurrents ne
    peuvent pas se marcher dessus : le perdant retrouve un sous-document deja
    pret, ce qui est precisement ce qu'il voulait.
    """
    _envois = reservation.get("reminders_sent")
    if not isinstance(_envois, dict):
        return
    _ancien = _envois.get(cle)
    if not isinstance(_ancien, str) or not _ancien:
        return
    _chemin = "reminders_sent.%s" % cle
    await db.reservations.update_one(
        {"id": reservation.get("id"), _chemin: _ancien},
        {"$set": {_chemin: {RV2_CANAL_PUSH: _ancien}}},
    )
    _envois[cle] = {RV2_CANAL_PUSH: _ancien}


async def rv2_reserver_canal(reservation_id: str, cle: str, canal: str, quand: str) -> bool:
    """Pose le marqueur AVANT l'envoi, et dit si CE processus a gagne le droit.

    C'est le mecanisme deja eprouve par `_rc_reserver_jeton` du flux de
    reservation : le filtre exige l'ABSENCE du champ, donc MongoDB ne
    l'accorde qu'a un seul appelant, meme si dix crons demarrent ensemble.
    """
    _chemin = "reminders_sent.%s.%s" % (cle, canal)
    _res = await db.reservations.update_one(
        {"id": reservation_id, _chemin: {"$exists": False}},
        {"$set": {_chemin: quand}},
    )
    return bool(getattr(_res, "matched_count", 0))


async def rv2_liberer_canal(reservation_id: str, cle: str, canal: str) -> None:
    """Retire le marqueur apres un echec : le canal redevient reessayable."""
    _chemin = "reminders_sent.%s.%s" % (cle, canal)
    try:
        await db.reservations.update_one({"id": reservation_id}, {"$unset": {_chemin: ""}})
    except Exception as _e:
        logger.error("[RV2] marqueur %s non libere sur la resa %s : %s",
                     _chemin, reservation_id, _e)


async def rv2_canal_autorise(email: str, canal: str) -> bool:
    """L'abonne accepte-t-il les rappels avant cours SUR CE CANAL ?

    Trois echelons, du plus precis au plus general :
      1. `before_class_<canal>` -> preference de canal, elle tranche ;
      2. `before_class`         -> choix historique, il vaut pour les DEUX
                                   canaux : un abonne qui s'etait desabonne des
                                   rappels ne se les voit pas revenir par
                                   e-mail ;
      3. rien du tout           -> vrai, comme tout le systeme V286 (opt-out).
    """
    if not email:
        return True
    try:
        _doc = await db.notification_preferences.find_one(
            {"email": email.lower().strip(), "role": "subscriber"},
            {"_id": 0, "preferences": 1})
    except Exception:
        return True
    _prefs = (_doc or {}).get("preferences")
    if not isinstance(_prefs, dict):
        return True
    _cle_canal = "before_class_%s" % canal
    if _cle_canal in _prefs:
        return bool(_prefs[_cle_canal])
    if "before_class" in _prefs:
        return bool(_prefs["before_class"])
    return True


def rv2_email_valide(email: str) -> bool:
    """Filtre minimal : ni vide, ni manifestement inexploitable."""
    _e = (email or "").strip()
    if "@" not in _e or _e.startswith("@") or _e.endswith("@"):
        return False
    if " " in _e:
        return False
    _domaine = _e.rsplit("@", 1)[1]
    return ("." in _domaine and not _domaine.startswith(".")
            and not _domaine.endswith("."))


def rv2_date_lisible(quand_local) -> str:
    """« mardi 18 aout ». La DATE seule : aucune heure ne sort jamais d'ici."""
    try:
        return "%s %d %s" % (RV2_JOURS[quand_local.weekday()], quand_local.day,
                             RV2_MOIS[quand_local.month - 1])
    except Exception:
        return ""


def rv2_contenu_rappel(prenom: str, course_name: str, date_lisible: str,
                       heure: str, accent: str):
    """Rend le triplet (sujet, html, texte) du rappel avant cours.

    `heure` vient EXCLUSIVEMENT de `reservations.courseTime`. Si elle est vide,
    l'e-mail ne parle pas d'heure : il n'en invente aucune, et surtout il ne va
    pas la chercher dans `reservations.datetime`, dont on sait qu'il porte, sur
    une partie du parc, l'horodatage de la RESERVATION et non celui du cours.

    Le sujet ne commence pas par un emoji : c'est un signal de filtrage connu
    chez Gmail, et la meme precaution est deja prise sur l'e-mail de newsletter.
    """
    _cours = (course_name or "ton cours").strip()
    _heure = (heure or "").strip()
    _date = (date_lisible or "").strip()

    if _date:
        _sujet = "Rappel : %s — %s" % (_cours, _date)
    else:
        _sujet = "Rappel : %s" % _cours

    if _date and _heure:
        _quand = "%s à %s" % (_date, _heure)
    elif _date:
        _quand = _date
    elif _heure:
        _quand = "à %s" % _heure
    else:
        _quand = ""

    _bonjour = ("Bonjour %s," % prenom.strip()) if (prenom or "").strip() else "Bonjour,"

    _ligne_quand_html = ""
    if _quand:
        _ligne_quand_html = (
            '<p style="color:rgba(255,255,255,0.8);line-height:1.6;margin:0 0 8px;">'
            'C&rsquo;est <strong style="color:%s;">%s</strong>.</p>' % (accent, _quand))

    _corps_html = (
        '<div style="padding:24px;color:#fff;">'
        '<p style="font-size:16px;margin:0 0 12px;">%s</p>'
        '<p style="color:rgba(255,255,255,0.8);line-height:1.6;margin:0 0 8px;">'
        'Petit rappel : tu es inscrit(e) à <strong style="color:%s;">%s</strong>.</p>'
        '%s'
        '<p style="color:rgba(255,255,255,0.6);line-height:1.6;margin:12px 0 0;font-size:13px;">'
        'À tout de suite, et pense à arriver un peu en avance.</p>'
        '</div>' % (_bonjour, accent, _cours, _ligne_quand_html))

    _html = _email_wrapper("linear-gradient(135deg,#9333EA,%s)" % accent,
                           _corps_html, accent)

    _lignes = [_bonjour, "",
               "Petit rappel : tu es inscrit(e) à %s." % _cours]
    if _quand:
        _lignes.append("C'est %s." % _quand)
    _lignes += ["", "À tout de suite, et pense à arriver un peu en avance.",
                "", "Afroboost — Move, Groove, Boost"]
    _texte = "\n".join(_lignes) + "\n"
    return _sujet, _html, _texte


async def rv2_envoyer_email_rappel(destinataire: str, prenom: str, course_name: str,
                                   date_lisible: str, heure: str, accent: str) -> bool:
    """Envoie le rappel par e-mail. Vrai SEULEMENT si Resend a accepte.

    Aucune couche nouvelle : meme transport, meme garde et meme gabarit que les
    autres e-mails transactionnels du fichier. Sans cle API, on renvoie faux —
    le marqueur sera donc relache et le canal reste reessayable.
    """
    if not RESEND_AVAILABLE or not RESEND_API_KEY:
        logger.info("[RV2] Resend non configure — aucun e-mail de rappel envoye")
        return False
    _sujet, _html, _texte = rv2_contenu_rappel(prenom, course_name, date_lisible,
                                               heure, accent)
    try:
        await asyncio.to_thread(resend.Emails.send, {
            "from": "Afroboost <notifications@afroboost.com>",
            "to": [destinataire],
            "reply_to": RV2_REPLY_TO,
            "subject": _sujet,
            "html": _html,
            "text": _texte,
        })
        return True
    except Exception as _e:
        logger.warning("[RV2] e-mail de rappel refuse pour %s : %s", destinataire, _e)
        return False


# === N1B-2 : LE MOTEUR SAIT LIRE PLUSIEURS REGLES DE RAPPEL ===
#
# Deux familles de regles, volontairement distinctes :
#   A. `relative` — X minutes AVANT le cours (60, 180, 1440, 2880).
#   B. `same_day` — a heure fixe le JOUR du cours, en Europe/Zurich (07:00...).
# Exemple metier : cours mardi 19:00 -> rappel lundi 19:00 (relative 1440)
# PUIS rappel mardi 07:00 (same_day 7). Deux cles distinctes, deux envois
# independants, aucun ecrasement.
#
# CE LOT NE CHANGE RIEN EN PRODUCTION. Aucun coach ne possede de configuration ;
# la regle par defaut est le rappel historique, et sa cle reste `defaut` — donc
# les reservations deja notifiees ne peuvent pas etre re-notifiees.
# Le reglage par le coach viendra avec N1B-3 ; ici, rien ne l'ecrit.
N1B2_MAX_REGLES = 2
N1B2_DELAIS_AUTORISES = (60, 180, 1440, 2880)   # 1 h, 3 h, 24 h, 48 h
# N1B-3B1 : demi-heures autorisees pour `same_day`. La cadence du cron est passee
# a 30 min le 13/08/2026 (crontab VPS, `0,30 * * * *`) — c'est elle qui rend
# HH:30 realisable. Toute valeur plus fine resterait une illusion.
N1B2_MINUTES_AUTORISEES = (0, 30)
N1B2_REGLES_DEFAUT = ({"type": "relative", "minutes": 60},)
# Demi-fenetre : le cron passe toutes les 60 min, la fenetre fait donc 60 min
# (+/- 30). Toute precision plus fine serait une illusion tant que la frequence
# du cron n'a pas change — ce sera la question de N1B-3.
N1B2_DEMI_FENETRE_MIN = 30
# Au-dela, aucune regle ne peut se declencher : 48 h + la demi-fenetre.
N1B2_HORIZON_MIN = 2880 + N1B2_DEMI_FENETRE_MIN


def n1b2_cle(regle: dict) -> str:
    """Cle d'idempotence d'une regle — stable, et unique par regle.

    Le delai de 60 min garde la cle HISTORIQUE `defaut`. C'est le point qui
    evite un second rappel sur toutes les reservations deja traitees.
    """
    if regle.get("type") == "same_day":
        # N1B-3B1 : la minute entre dans la cle. Avec `minute` absente ou nulle,
        # la chaine produite est IDENTIQUE a celle de N1B-2 (`same_day:07:00`) :
        # une regle a l'heure pleine garde donc exactement la meme cle, et rien
        # de deja marque ne peut etre renvoye.
        return "same_day:%02d:%02d" % (int(regle.get("heure", 0)),
                                       int(regle.get("minute", 0)))
    _m = int(regle.get("minutes", 0))
    if _m == 60:
        return N1B_CLE_HERITEE
    return "relative:%dm" % _m


def n1b2_titre(cle: str) -> str:
    """Titre du push. Celui de la cle historique est INCHANGE, au caractere pres.

    Les autres libelles sont derives mecaniquement ; ils sont inatteignables
    tant qu'aucune regle n'est configurable (N1B-3).
    """
    if cle.startswith("same_day:"):
        # N1B-3B2 : libelle C4, tranche par le coach. « Ton cours » disparait au
        # profit de la marque — le rappel du jour meme est celui qu'on lit le
        # plus souvent sur un ecran verrouille, il doit se reconnaitre seul.
        return "📅 Afroboost, c'est aujourd'hui"
    return {
        N1B_CLE_HERITEE: "📅 Ton cours commence dans 1h",
        "relative:180m": "📅 Ton cours commence dans 3h",
        "relative:1440m": "📅 Ton cours, c'est demain",
        "relative:2880m": "📅 Ton cours, c'est après-demain",
    }.get(cle, "📅 Ton cours commence dans 1h")


def n1b2_corps(cle: str, nom: str, heure: str) -> str:
    """Corps du push. Celui de la cle historique est INCHANGE, au caractere pres.

    Chaque message est autonome : il porte le jour ET l'heure, pour rester juste
    meme lu seul sur un ecran verrouille, ou le titre est souvent tronque.
    Quand `courseTime` est vide, la portion horaire disparait sans laisser de
    ponctuation orpheline — d'ou le morceau ` a HH:MM` assemble, jamais colle.
    """
    _h = (" à %s" % heure) if heure else ""
    if cle == N1B_CLE_HERITEE:
        return "%s%s — prépare-toi !" % (nom, _h)
    if cle.startswith("same_day:"):
        return "%s aujourd'hui%s. À tout à l'heure 🎧🔥" % (nom, _h)
    if cle == "relative:180m":
        return "%s%s — ton moment Afroboost approche 🎧" % (nom, _h)
    if cle == "relative:1440m":
        return "%s demain%s. On se retrouve chez Afroboost 🎧" % (nom, _h)
    if cle == "relative:2880m":
        return "%s après-demain%s. Pense à garder ce moment pour toi 🎧" % (nom, _h)
    return "%s%s — prépare-toi !" % (nom, _h)


def n1b2_cible(regle: dict, instant_cours, zurich):
    """Instant UTC ou ce rappel doit partir, ou None si la regle ne s'applique pas."""
    if regle.get("type") == "same_day":
        # L'heure fixe se lit sur la date LOCALE du cours : un cours du mardi
        # 19:00 a Zurich donne bien le mardi 07:00 a Zurich, ete comme hiver.
        _local = instant_cours.astimezone(zurich)
        try:
            _c = _local.replace(hour=int(regle.get("heure", 0)),
                                minute=int(regle.get("minute", 0)),
                                second=0, microsecond=0)
        except (ValueError, TypeError):
            return None
        # Une heure fixe posterieure au debut du cours n'a aucun sens : on ne
        # rappelle jamais un cours deja commence.
        if _c >= _local:
            return None
        return _c.astimezone(timezone.utc)
    from datetime import timedelta as _td2
    return instant_cours - _td2(minutes=int(regle.get("minutes", 0)))


def n1b2_valider_regles(brut):
    """Regles sures issues d'une configuration, ou None si elle est inexploitable.

    Tout ou rien, volontairement : une configuration partiellement fausse fait
    RETOMBER sur le defaut plutot que d'envoyer un rappel de travers ou aucun.
    """
    if not isinstance(brut, list) or not brut or len(brut) > N1B2_MAX_REGLES:
        return None
    _sures, _vues = [], set()
    for _r in brut:
        if not isinstance(_r, dict):
            return None
        _t = _r.get("type")
        if _t == "relative":
            _m = _r.get("minutes")
            if isinstance(_m, bool) or not isinstance(_m, int) or _m not in N1B2_DELAIS_AUTORISES:
                return None
            _sure = {"type": "relative", "minutes": _m}
        elif _t == "same_day":
            _h = _r.get("heure")
            if isinstance(_h, bool) or not isinstance(_h, int) or not (0 <= _h <= 23):
                return None
            # N1B-3B1 : `minute` absente vaut 0 — une regle ecrite au format
            # N1B-2 reste donc valide et produit la meme cle.
            _m = _r.get("minute", 0)
            if isinstance(_m, bool) or not isinstance(_m, int) or _m not in N1B2_MINUTES_AUTORISEES:
                return None
            _sure = {"type": "same_day", "heure": _h, "minute": _m}
        else:
            return None
        _c = n1b2_cle(_sure)
        if _c in _vues:            # deux regles de meme cle s'ecraseraient
            return None
        _vues.add(_c)
        _sures.append(_sure)
    return _sures


# === N1B-3B2 : DEUX RAPPELS NE SE MARCHENT JAMAIS DESSUS ===
#
# Deux regles parfaitement valides prises SEPAREMENT peuvent viser le meme
# instant pour un cours donne : « 60 min avant » et « le jour meme a 07:00 »
# tombent tous les deux a 07:00 pour un cours de 08:00. L'abonne recevrait deux
# notifications a la meme minute — c'est exactement ce qu'on ne veut pas.
#
# La garde est posee DEUX FOIS, et ce n'est pas une redondance :
#   - a la SAUVEGARDE, pour le dire au coach en clair, avec ses vrais cours ;
#   - au RUNTIME, parce qu'un cours cree APRES la sauvegarde ferait apparaitre
#     une collision que personne n'aurait pu annoncer.
# Le runtime est donc la seule garantie REELLE ; la sauvegarde n'est qu'un
# avertissement utile, et elle ne bloque pas.
N1B3B2_ECART_MIN = 60          # deux cibles plus proches que cela = collision
N1B3B2_HORIZON_JOURS = 14      # profondeur de l'apercu des cours a la sauvegarde


def n1b3b2_plan(regles, instant_cours, zurich):
    """Rappels reellement envoyables pour UNE occurrence, collisions retirees.

    Renvoie `(gardees, absorbees)` :
      - `gardees`   : [(cible, cle)] ;
      - `absorbees` : [(cible, cle, cible_gardee, cle_gardee)].

    Deux proprietes tiennent tout le reste :

    1. On garde le PREMIER chronologiquement, et on compare chaque candidat a la
       derniere cible RETENUE — jamais a la precedente absorbee. Sinon trois
       rappels en chaine (07:00, 07:30, 08:00) laisseraient passer 07:00 et
       08:00... a 60 min d'ecart exactement, c'est voulu ; mais 07:00 / 07:20 /
       07:40 ne doit en laisser qu'UN.
    2. La decision ne lit PAS `reminders_sent`. Elle ne depend que du cours et
       des regles, donc elle rend le meme verdict a chaque passage du cron :
       une regle absorbee l'est definitivement pour cette occurrence, et aucun
       passage ulterieur ne peut la rattraper.
    """
    _cibles = []
    for _rg in regles:
        _c = n1b2_cible(_rg, instant_cours, zurich)
        if _c:
            _cibles.append((_c, n1b2_cle(_rg)))
    # Tri par cible PUIS par cle. La cle departage les egalites parfaites — et
    # elles existent : « 60 min avant » et « jour meme a 07:00 » visent tous
    # deux 07:00 pour un cours de 08:00. Trier sur la seule cible laisserait
    # l'ORDRE D'ECRITURE des regles decider, si bien que reordonner les deux
    # memes regles dans l'interface changerait le message recu par l'abonne.
    _cibles.sort(key=lambda _x: (_x[0], _x[1]))
    _seuil = timedelta(minutes=N1B3B2_ECART_MIN)
    _gardees, _absorbees = [], []
    for _c, _cle in _cibles:
        if _gardees and (_c - _gardees[-1][0]) < _seuil:
            _absorbees.append((_c, _cle, _gardees[-1][0], _gardees[-1][1]))
        else:
            _gardees.append((_c, _cle))
    return _gardees, _absorbees


def n1b3b2_regles_trop_proches(regles):
    """Message de REFUS si deux `same_day` sont a moins de 60 min, sinon "".

    Ce controle-la ne depend d'AUCUN cours : deux heures fixes le meme jour sont
    rapprochees pour tous les cours a la fois, il est donc juste de refuser.
    Les delais relatifs, eux, sont espaces d'au moins 120 min par construction
    (60 / 180 / 1440 / 2880) ; et un relatif face a un `same_day` ne se juge
    qu'a la lumiere d'un cours reel — c'est l'affaire de `n1b3b2_collisions`.

    Le doublon EXACT est deja refuse en amont par `n1b2_valider_regles` : deux
    regles identiques produisent la meme cle. Ici on attrape l'ecart de 30 min.
    """
    _mins = sorted(int(_r.get("heure", 0)) * 60 + int(_r.get("minute", 0))
                   for _r in regles if _r.get("type") == "same_day")
    for _a, _b in zip(_mins, _mins[1:]):
        if (_b - _a) < N1B3B2_ECART_MIN:
            return ("Deux rappels le jour même à %02d:%02d et %02d:%02d, "
                    "c'est moins d'une heure d'écart. Espace-les davantage."
                    % (_a // 60, _a % 60, _b // 60, _b % 60))
    return ""


def n1b3b2_collisions(regles, occurrences, zurich):
    """Collisions concretes avec les cours a venir, dites en clair au coach.

    `occurrences` : [{"label": "mardi", "instant": datetime aware}] — un cours
    hebdomadaire revient plusieurs fois dans la fenetre, mais produit toujours
    la meme phrase : on dedoublonne pour ne pas repeter dix fois la meme chose.

    Ces messages AVERTISSENT, ils ne bloquent pas : le coach peut vouloir cette
    configuration pour ses autres cours, et le runtime absorbera proprement le
    rappel en trop sur celui-ci.
    """
    _messages, _vus = [], set()
    for _occ in occurrences:
        _instant = _occ.get("instant")
        if not _instant:
            continue
        _, _absorbees = n1b3b2_plan(regles, _instant, zurich)
        _jour = _occ.get("label") or "cours"
        _h_cours = _instant.astimezone(zurich).strftime("%H:%M")
        for _cible, _cle, _cible_g, _cle_g in _absorbees:
            _h1 = _cible_g.astimezone(zurich).strftime("%H:%M")
            _h2 = _cible.astimezone(zurich).strftime("%H:%M")
            _sig = (_jour, _h_cours, _h1, _h2)
            if _sig in _vus:
                continue
            _vus.add(_sig)
            if _h1 == _h2:
                _messages.append("Ton cours du %s à %s recevrait deux rappels à %s."
                                 % (_jour, _h_cours, _h1))
            else:
                _messages.append("Ton cours du %s à %s recevrait deux rappels rapprochés, "
                                 "à %s et %s." % (_jour, _h_cours, _h1, _h2))
    return _messages


async def n1b2_regles_du_coach(coach_id: str, cache: dict):
    """Regles du coach, ou le defaut. Lecture seule, mise en cache par passage."""
    if not coach_id:
        return list(N1B2_REGLES_DEFAUT)
    if coach_id in cache:
        return cache[coach_id]
    _regles = list(N1B2_REGLES_DEFAUT)
    try:
        _p = await db.coach_profiles.find_one({"email": coach_id},
                                              {"_id": 0, "reminder_rules": 1})
        if _p and _p.get("reminder_rules") is not None:
            _v = n1b2_valider_regles(_p.get("reminder_rules"))
            if _v:
                _regles = _v
            else:
                logger.warning("[N1B-2] regles invalides pour %s — repli sur le defaut", coach_id)
    except Exception as e:
        logger.warning("[N1B-2] lecture des regles impossible pour %s: %s", coach_id, e)
    cache[coach_id] = _regles
    return _regles


# === N1B-3B2 : LE COACH PEUT ENFIN ENREGISTRER SES REGLES ===
#
# Jusqu'ici AUCUN code du depot n'ecrivait `coach_profiles.reminder_rules` : le
# moteur multi-regles etait lu mais jamais alimente, donc inerte. Ces deux
# routes sont le premier — et le seul — ecrivain.
#
# Ce que ces routes NE font PAS : elles ne touchent a aucun autre champ du
# profil. Le `$set` ne porte que sur `reminder_rules`, donc une sauvegarde de
# rappels n'ecrase jamais photo, anniversaire ou preferences.
async def _n1b3b2_coach_appelant(request: Request) -> str:
    """Coach authentifie, ou leve 401/403. Meme chemin que le reste du dashboard.

    On reprend `_v263_authenticated_coach` (JWT signe, repli X-User-Email du
    mode transitoire V265) plutot qu'une regle neuve : le dashboard du
    proprietaire n'emet pas toujours de JWT, et exiger le jeton ici rendrait la
    page inutilisable pour lui — c'est exactement l'incident V310c.
    """
    _e = await _v263_authenticated_coach(request)
    if not _e:
        raise HTTPException(status_code=401, detail="Authentification requise")
    if not await _v309_is_coach_or_admin(_e):
        raise HTTPException(status_code=403, detail="Réservé aux coachs")
    return _e


async def _n1b3b2_occurrences_du_coach(email: str):
    """Prochaines occurrences des cours du coach, pour l'avertissement de collision.

    Lecture seule et sans consequence : si elle echoue, la sauvegarde reste
    valable — on perd l'avertissement, pas la configuration.
    """
    from zoneinfo import ZoneInfo as _ZI
    _zh = _ZI("Europe/Zurich")
    _filtre = {"archived": {"$ne": True}}
    if not is_super_admin(email):
        _filtre["coach_id"] = email
    _occ = []
    for _c in await db.courses.find(_filtre, {"_id": 0}).to_list(100):
        for _o in _v184_next_occurrences(_c, days_ahead=N1B3B2_HORIZON_JOURS):
            try:
                # `_v184_next_occurrences` renvoie un ISO NAIF, en heure suisse
                # (cf. V196) : on le date explicitement avant toute comparaison.
                _dt = datetime.fromisoformat(_o["datetime"]).replace(tzinfo=_zh)
            except (ValueError, TypeError, KeyError):
                continue
            _occ.append({"label": _o.get("weekday_label") or "",
                         "instant": _dt.astimezone(timezone.utc)})
    return _occ, _zh


@api_router.get("/coach/reminder-rules")
async def n1b3b2_lire_regles(request: Request):
    """Regles de rappel du coach appelant, ou le defaut s'il n'en a pas."""
    _email = await _n1b3b2_coach_appelant(request)
    _p = await db.coach_profiles.find_one({"email": _email},
                                          {"_id": 0, "reminder_rules": 1})
    _brut = (_p or {}).get("reminder_rules")
    _sures = n1b2_valider_regles(_brut) if _brut is not None else None
    return {"rules": _sures or list(N1B2_REGLES_DEFAUT),
            "par_defaut": not bool(_sures)}


@api_router.put("/coach/reminder-rules")
async def n1b3b2_ecrire_regles(request: Request):
    """Enregistre les regles de rappel du coach appelant.

    Trois verdicts, volontairement distincts :
      - 400 si la configuration est invalide (type inconnu, delai hors liste,
        doublon exact, plus de deux regles) — `n1b2_valider_regles` ;
      - 400 si deux `same_day` sont a moins de 60 min — vrai pour TOUS les
        cours, donc refusable sans rien connaitre du planning ;
      - 200 avec `avertissements` si une collision concrete apparait sur un
        cours reel. On n'interdit pas : la meme configuration peut etre la
        bonne pour les autres cours, et le runtime absorbera le rappel en trop.
    """
    _email = await _n1b3b2_coach_appelant(request)
    try:
        _body = await request.json()
    except Exception:
        raise HTTPException(status_code=400, detail="Corps de requête illisible")
    _brut = _body.get("rules") if isinstance(_body, dict) else None
    _sures = n1b2_valider_regles(_brut)
    if not _sures:
        raise HTTPException(
            status_code=400,
            detail="Configuration de rappels invalide : au plus %d règles, "
                   "délais autorisés %s minutes, heure fixe entre 00 et 23 "
                   "aux minutes %s, et jamais deux fois le même rappel."
                   % (N1B2_MAX_REGLES, list(N1B2_DELAIS_AUTORISES),
                      list(N1B2_MINUTES_AUTORISEES)))
    _refus = n1b3b2_regles_trop_proches(_sures)
    if _refus:
        raise HTTPException(status_code=400, detail=_refus)

    _avertissements = []
    try:
        _occ, _zh = await _n1b3b2_occurrences_du_coach(_email)
        _avertissements = n1b3b2_collisions(_sures, _occ, _zh)
    except Exception as _e:
        # L'avertissement est un confort, pas une condition : on enregistre.
        logger.warning("[N1B-3B2] collisions non calculables pour %s: %s", _email, _e)

    await db.coach_profiles.update_one(
        {"email": _email},
        {"$set": {"email": _email, "reminder_rules": _sures,
                  "reminder_rules_updated_at": datetime.now(timezone.utc).isoformat()}},
        upsert=True
    )
    logger.info("[N1B-3B2] regles enregistrees pour %s: %s (%d avertissement(s))",
                _email, _sures, len(_avertissements))
    return {"success": True, "rules": _sures, "avertissements": _avertissements}


@api_router.get("/coach/courses")
async def rv3_cours_configurables(request: Request):
    """Les cours qu'un COACH peut ADMINISTRER. Ce n'est pas la liste publique.

    Deux contextes, deux regles, et les confondre a produit un vrai bug : le
    coach voyait six brouillons nommes « Nouveau cours » et ne voyait PAS les
    seances du mercredi et du dimanche que ses offres vendent reellement. Il a
    donc regle ses rappels sur un cours que personne ne peut reserver.

    La cause : la liste venait de `GET /courses`, qui filtre `archived` parce
    qu'elle sert d'abord la VITRINE. Or « archive » ne veut pas dire « n'existe
    plus » : les deux vraies seances recurrentes sont archivees, rattachees a
    trois offres publiques, et portent `agenda_abonne`.

    La regle retenue ici ne parle donc jamais de `visible`, qui est un reglage
    de PUBLICATION et n'a rien a dire sur ce qu'un coach peut administrer :

        configurable  =  non archive
                      OU rattache a au moins une offre
                      OU marque `agenda_abonne`

    Un cours archive, sans aucune offre et sans `agenda_abonne`, sort de la
    liste : plus rien ne prouve qu'il serve encore a quoi que ce soit. Les
    brouillons, eux, ne sont pas archives et restent donc administrables — les
    retirer serait une decision de menage, pas de code.

    Chaque cours repart ENTIER, augmente de ses offres et de leur etat de
    publication : cette liste alimente aussi bien la carte des rappels que
    l'ecran de gestion, qui a besoin de `mapsUrl`, `playlist` et du reste. Une
    projection etroite priverait le second de ses champs sans prevenir.

    Rien ici ne PUBLIE quoi que ce soit : `visible` et `archived` repartent tels
    qu'ils sont, et c'est la lecture publique — `sessions_agenda` — qui decide
    seule de ce qu'un visiteur voit.
    """
    _email = await _n1b3b2_coach_appelant(request)
    _tout = is_super_admin(_email)
    _filtre = {} if _tout else {"coach_id": _email.strip().lower()}
    try:
        _cours = await db.courses.find(_filtre, {"_id": 0}).to_list(300)
    except Exception as _e:
        logger.warning("[RV3] cours du coach illisibles : %s", _e)
        raise HTTPException(status_code=503, detail="Liste des cours indisponible")
    try:
        _offres = await db.offers.find(
            {}, {"_id": 0, "id": 1, "name": 1, "visible": 1, "linked_course_ids": 1}
        ).to_list(300)
    except Exception:
        _offres = []

    _par_cours = {}
    for _o in _offres:
        for _cid in (_o.get("linked_course_ids") or []):
            if not _cid:
                continue
            _par_cours.setdefault(_cid, []).append({
                "id": _o.get("id"), "name": _o.get("name"),
                "publique": _o.get("visible") is not False,
            })

    _sortie = []
    for _c in _cours:
        _liees = _par_cours.get(_c.get("id"), [])
        if _c.get("archived") is True and not _liees and not _c.get("agenda_abonne"):
            continue
        _vue = dict(_c)
        _vue["offres"] = _liees
        _vue["agenda_abonne"] = bool(_c.get("agenda_abonne"))
        # L'alias est recalcule a la lecture, comme le fait `GET /courses` :
        # l'ecran de gestion renvoie l'objet entier, il ne doit pas repartir
        # avec une adresse perimee dans un champ et la bonne dans l'autre.
        if _vue.get("locationName"):
            _vue["location"] = _vue["locationName"]
        _sortie.append(_vue)
    return _sortie


@api_router.put("/coach/courses/{course_id}/reminders")
async def rv3_ecrire_rappels_du_cours(course_id: str, request: Request):
    """Active ou coupe les rappels d'UN cours, et fixe ses regles.

    Route distincte du `PUT /courses/{id}` generique, et ce n'est pas un
    doublon : ce dernier accepte un dictionnaire brut sans rien valider, et il
    ne verifie pas que l'appelant possede le cours. Une configuration qui
    declenche de vrais envois merite mieux que cela.

    Couper les rappels ne DETRUIT pas les regles : le coach qui reactive
    retrouve son reglage. C'est `reminders_enabled` seul qui decide.
    """
    _email = await _n1b3b2_coach_appelant(request)
    _cours = await db.courses.find_one(
        {"id": course_id}, {"_id": 0, "id": 1, "name": 1, "coach_id": 1, "archived": 1})
    if not _cours:
        raise HTTPException(status_code=404, detail="Cours non trouvé")
    _proprio = (_cours.get("coach_id") or "").strip().lower()
    if _proprio and _proprio != _email.strip().lower() and not is_super_admin(_email):
        raise HTTPException(status_code=403, detail="Ce cours ne vous appartient pas.")
    try:
        _body = await request.json()
    except Exception:
        raise HTTPException(status_code=400, detail="Corps de requête illisible")
    if not isinstance(_body, dict):
        raise HTTPException(status_code=400, detail="Corps de requête illisible")

    _actif = _body.get("enabled") is True
    _maj = {"reminders_enabled": _actif,
            "reminders_updated_at": datetime.now(timezone.utc).isoformat()}
    _sures = None
    if _actif:
        # Activer sans regle exploitable n'aurait aucun effet a l'execution :
        # autant le refuser ici, ou le coach peut encore corriger.
        _sures = n1b2_valider_regles(_body.get("rules"))
        if not _sures:
            raise HTTPException(
                status_code=400,
                detail="Configuration de rappels invalide : au plus %d règles, "
                       "délais autorisés %s minutes, heure fixe entre 00 et 23 "
                       "aux minutes %s, et jamais deux fois le même rappel."
                       % (N1B2_MAX_REGLES, list(N1B2_DELAIS_AUTORISES),
                          list(N1B2_MINUTES_AUTORISEES)))
        _refus = n1b3b2_regles_trop_proches(_sures)
        if _refus:
            raise HTTPException(status_code=400, detail=_refus)
        _maj["reminder_rules"] = _sures

    await db.courses.update_one({"id": course_id}, {"$set": _maj})
    logger.info("[RV3] rappels %s sur le cours %s (%s) par %s",
                "ACTIVES" if _actif else "coupes", course_id,
                _cours.get("name"), _email)
    return {"success": True, "id": course_id,
            "reminders_enabled": _actif, "rules": _sures or []}


# ═══════════════════════════════════════════════════════════════════════════
# ESSAI-3 — LE FUNNEL D'ESSAI GRATUIT, VU PAR LE COACH
#
# Quatre etages, tous lus dans la base metier ; PostHog n'est pas interroge.
#
#   ACCORDE   un forfait dont le code porte les marqueurs d'ESSAI-2
#   RESERVE   au moins une reservation rattachee a ce forfait
#   PRESENT   au moins une de ces reservations est `validated`
#   CONVERTI  `converted_at`, le marqueur atomique pose par ESSAI-2
#
# LE 4e ETAGE NE SE RECONSTRUIT PAS. `converted_at` n'existe que depuis le
# 17/08/2026 ; avant, rien ne distingue de facon sure un achat qui SUIT une
# presence d'un achat quelconque — `total_paid` n'est meme pas ecrit par le
# chemin Stripe, qui est pourtant le seul reellement encaissant. Plutot que
# d'inventer une seconde definition qui contredirait la premiere, l'ecran
# affiche la date depuis laquelle la mesure vaut. Un funnel honnete et
# incomplet est plus utile qu'un funnel complet et faux.
# ═══════════════════════════════════════════════════════════════════════════

# Date de deploiement du marqueur `converted_at` (commit 062a79e). Elle n'est
# PAS derivable des donnees : tant qu'aucune conversion n'a eu lieu,
# `min(converted_at)` est vide et ne dirait rien de la fiabilite.
ESSAI3_CONVERSION_DEPUIS = "2026-08-17"

# En dessous, aucun diagnostic n'est affiche : sur 4 essais, « votre perte est
# entre la reservation et la presence » ne serait qu'un accident d'echantillon.
ESSAI3_ECHANTILLON_MINIMUM = 10

ESSAI3_PERIODES = {"7d": 7, "30d": 30, "90d": 90, "all": None}

# Borne de securite de la lecture. Elle n'est pas censee etre atteinte : elle
# vaut cent fois le nombre d'essais jamais accordes. Si elle l'etait, le journal
# le dirait plutot que de laisser croire a un funnel complet.
ESSAI3_PLAFOND = 5000

# Un essai anterieur a ESSAI-0 n'a pas d'`offer_id`. Il compte dans « Toutes
# les offres » — son statut d'essai, lui, est certain — et reste joignable par
# cette cle plutot que d'etre attribue d'office a une offre qu'on ignore.
ESSAI3_OFFRE_INCONNUE = "__sans_offre__"


def _essai3_taux(numerateur: int, denominateur: int):
    """Jamais NaN, jamais Infinity : sans denominateur, le taux n'existe pas.

    `None` et 0.0 ne disent pas la meme chose — « pas encore mesurable » n'est
    pas « aucun ne passe » — et l'ecran les rend differemment (« — » vs « 0 % »).
    """
    if not denominateur:
        return None
    return round(float(numerateur) / float(denominateur), 4)


def _essai3_jours(depuis_iso: str, jusqu_iso: str):
    """Delai en jours entre deux instants ISO, ou None si l'un manque.

    Aucune valeur de repli : un essai sans horodatage exploitable sort de la
    moyenne au lieu d'y entrer pour 0 jour, ce qui la tirerait vers le bas.
    """
    if not depuis_iso or not jusqu_iso:
        return None
    try:
        _d = datetime.fromisoformat(str(depuis_iso).replace("Z", "+00:00"))
        _f = datetime.fromisoformat(str(jusqu_iso).replace("Z", "+00:00"))
    except (ValueError, TypeError):
        return None
    if _d.tzinfo is None:
        _d = _d.replace(tzinfo=timezone.utc)
    if _f.tzinfo is None:
        _f = _f.replace(tzinfo=timezone.utc)
    _ecart = (_f - _d).total_seconds() / 86400.0
    return round(_ecart, 2) if _ecart >= 0 else None


def _essai3_mediane(valeurs: list):
    if not valeurs:
        return None
    _v = sorted(valeurs)
    _n = len(_v)
    _m = _v[_n // 2] if _n % 2 else (_v[_n // 2 - 1] + _v[_n // 2]) / 2.0
    return round(float(_m), 2)


def _essai3_diagnostic(granted: int, booked: int, attended: int, converted: int):
    """Une observation deterministe, ou aucune. Pas d'IA, pas de hasard.

    La regle est le minimum des trois taux DEFINIS. Un taux sans denominateur
    n'est pas candidat : ne pas avoir de reservation ne prouve pas que la
    presence est le probleme.
    """
    if not granted:
        return {"cle": "aucune_donnee", "etape": None}
    if granted < ESSAI3_ECHANTILLON_MINIMUM:
        return {"cle": "echantillon_faible", "etape": None}
    _candidats = []
    for _cle, _num, _den in (
        ("accorde_reserve", booked, granted),
        ("reserve_present", attended, booked),
        ("present_converti", converted, attended),
    ):
        _t = _essai3_taux(_num, _den)
        if _t is not None:
            _candidats.append((_t, _cle))
    if not _candidats:
        return {"cle": "aucune_donnee", "etape": None}
    _candidats.sort(key=lambda x: x[0])
    return {"cle": _candidats[0][1], "etape": _candidats[0][1]}


async def _essai3_cohorte(coach_email: str, depuis_iso: str):
    """La cohorte : les essais ACCORDES pendant la periode, et leur devenir.

    C'est bien la date d'octroi qui selectionne, jamais celle de la conversion.
    Sans quoi une personne accordee il y a 40 jours et convertie hier gonflerait
    le denominateur de « 30 jours » sans y avoir jamais ete accordee, et le taux
    dirait n'importe quoi.

    UNE SEULE requete d'agregation, quel que soit le nombre d'essais : les
    reservations et les codes sont joints par `$lookup`, pas relus un par un.
    """
    from api.routes.shared import ESSAI2_FILTRE_GRATUIT as _GRATUIT

    _match = {}
    if not is_super_admin(coach_email):
        _match["coach_id"] = coach_email.strip().lower()
    if depuis_iso:
        # `created_at` est une chaine ISO chez les DEUX ecrivains d'octroi
        # (checkout et preuve sociale) : la comparaison lexicographique est
        # exacte, et un document qui porterait une Date serait ignore plutot
        # que mal compte.
        _match["created_at"] = {"$gte": depuis_iso}

    _pipeline = [
        {"$match": _match},
        {"$lookup": {
            "from": "discount_codes",
            "let": {"c": "$code"},
            "pipeline": [
                {"$match": {"$expr": {"$eq": ["$code", "$$c"]}}},
                {"$match": _GRATUIT},
                {"$limit": 1},
                {"$project": {"_id": 1}},
            ],
            "as": "_gratuit",
        }},
        # Ici seulement on sait qu'il s'agit d'un ESSAI : c'est le code, pas le
        # nom de l'offre, qui le dit. `offer_name` a deja derive.
        {"$match": {"_gratuit.0": {"$exists": True}}},
        {"$lookup": {
            "from": "reservations",
            "let": {"sid": "$id", "code": "$code"},
            "pipeline": [
                {"$match": {"$expr": {"$or": [
                    {"$eq": ["$subscriptionId", "$$sid"]},
                    {"$eq": ["$promoCode", "$$code"]},
                    {"$eq": ["$discountCode", "$$code"]},
                ]}}},
                {"$project": {"_id": 0, "validated": 1, "validatedAt": 1}},
            ],
            "as": "_res",
        }},
        # Aucune donnee personnelle ne quitte la base : ni email, ni nom, ni
        # telephone, ni code d'acces. Seulement des compteurs et des dates.
        {"$project": {
            "_id": 0,
            "offer_id": 1,
            "created_at": 1,
            "converted_at": 1,
            "reservations": {"$size": "$_res"},
            "presences": {"$filter": {
                "input": "$_res", "as": "r",
                "cond": {"$eq": ["$$r.validated", True]},
            }},
        }},
    ]
    _lignes = await db.subscriptions.aggregate(_pipeline).to_list(ESSAI3_PLAFOND)
    if len(_lignes) >= ESSAI3_PLAFOND:
        # Un plafond SILENCIEUX ferait passer un funnel tronque pour un funnel
        # complet. On le dit, meme si ce volume est hors d'atteinte aujourd'hui.
        logger.warning("[ESSAI-3] cohorte plafonnee a %d essais — les chiffres "
                       "affiches sont tronques", ESSAI3_PLAFOND)
    return _lignes


@api_router.get("/coach/funnel/free-trial")
async def essai3_funnel_essai_gratuit(request: Request, period: str = "30d",
                                      offer_id: str = ""):
    """Le funnel d'essai gratuit du coach authentifie.

    ISOLATION PAR LE SERVEUR. Le filtre `coach_id` est pose ici, sur le coach
    tire du jeton — jamais sur un identifiant fourni par le navigateur. Un coach
    ne peut donc pas demander le funnel d'un autre : il n'a aucun endroit ou
    l'ecrire. L'administrateur, lui, voit l'ensemble, comme partout ailleurs.
    """
    _email = await _n1b3b2_coach_appelant(request)

    _p = (period or "30d").strip().lower()
    if _p not in ESSAI3_PERIODES:
        _p = "30d"
    _jours = ESSAI3_PERIODES[_p]
    _depuis = ""
    if _jours:
        _depuis = (datetime.now(timezone.utc) - timedelta(days=_jours)).isoformat()

    try:
        _lignes = await _essai3_cohorte(_email, _depuis)
    except Exception as _err:
        # Une liste vide serait une AFFIRMATION : « ce coach n'a aucun essai ».
        # On refuse explicitement plutot que de laisser croire a un zero.
        logger.error("[ESSAI-3] funnel illisible pour %s : %s", _email, _err)
        raise HTTPException(status_code=503,
                            detail="Funnel momentanement indisponible")

    # Les offres presentes dans la cohorte COMPLETE : le menu ne doit pas se
    # vider quand on selectionne une offre. Le filtre s'applique apres.
    _ids = sorted({str(l.get("offer_id") or "") for l in _lignes})
    _reels = [i for i in _ids if i]
    _noms = {}
    if _reels:
        try:
            for _o in await db.offers.find({"id": {"$in": _reels}},
                                           {"_id": 0, "id": 1, "name": 1}).to_list(200):
                _noms[_o.get("id")] = _o.get("name") or ""
        except Exception as _err:
            logger.warning("[ESSAI-3] noms d'offres illisibles : %s", _err)
    _offres = [{"id": i, "name": _noms.get(i) or "Offre supprimée"} for i in _reels]
    if any(not str(l.get("offer_id") or "") for l in _lignes):
        _offres.append({"id": ESSAI3_OFFRE_INCONNUE, "name": "Offre inconnue"})

    _choix = (offer_id or "").strip()
    if _choix == ESSAI3_OFFRE_INCONNUE:
        _lignes = [l for l in _lignes if not str(l.get("offer_id") or "")]
    elif _choix:
        _lignes = [l for l in _lignes if str(l.get("offer_id") or "") == _choix]

    _granted = len(_lignes)
    _booked = 0
    _attended = 0
    _converted = 0
    _delais = []
    for _l in _lignes:
        if int(_l.get("reservations") or 0) > 0:
            _booked += 1
        _pres = [p for p in (_l.get("presences") or []) if p]
        _quand_present = ""
        if _pres:
            _attended += 1
            _dates = sorted(str(p.get("validatedAt") or "") for p in _pres if p.get("validatedAt"))
            _quand_present = _dates[0] if _dates else ""
        _conv = str(_l.get("converted_at") or "")
        if _conv and _pres:
            # UN FUNNEL EST EMBOITE : chaque etage est un sous-ensemble du
            # precedent, sinon un taux depasse 100 % et l'ecran ment. ESSAI-2
            # n'ecrit `converted_at` qu'apres une presence, donc le cas ne
            # devrait pas exister — s'il existe, la donnee est abimee et c'est
            # la presence qui manque, pas la conversion qui est en trop.
            _converted += 1
            _d = _essai3_jours(_quand_present, _conv)
            if _d is not None:
                _delais.append(_d)
        elif _conv:
            logger.warning("[ESSAI-3] conversion sans presence sur un essai — "
                           "ignoree dans le funnel (donnee incoherente)")

    _plus_ancien = min((str(l.get("created_at") or "") for l in _lignes if l.get("created_at")),
                       default="")

    return {
        "period": _p,
        "offer_id": _choix,
        "offers": _offres,
        "cohort": {
            # La periode selectionne les essais ACCORDES entre ces bornes ; on
            # suit ensuite CES essais-la, ou qu'ils en soient aujourd'hui.
            "anchor": "granted_at",
            "since": _depuis,
            "oldest_grant": _plus_ancien,
        },
        "granted": _granted,
        "booked": _booked,
        "attended": _attended,
        "converted": _converted,
        "rates": {
            "booking": _essai3_taux(_booked, _granted),
            "attendance": _essai3_taux(_attended, _booked),
            "conversion": _essai3_taux(_converted, _attended),
            "overall": _essai3_taux(_converted, _granted),
        },
        "conversion_delay": {
            "average_days": (round(sum(_delais) / len(_delais), 2) if _delais else None),
            "median_days": _essai3_mediane(_delais),
            "sample_size": len(_delais),
        },
        "diagnostic": _essai3_diagnostic(_granted, _booked, _attended, _converted),
        "coverage": {
            # Le 4e etage ne remonte pas avant cette date : `converted_at` est
            # ne avec ESSAI-2. L'ecran le dit au lieu d'afficher un zero muet.
            "conversion_measured_since": ESSAI3_CONVERSION_DEPUIS,
            "partial": bool(_plus_ancien and _plus_ancien[:10] < ESSAI3_CONVERSION_DEPUIS),
            "min_sample_for_diagnostic": ESSAI3_ECHANTILLON_MINIMUM,
        },
    }



# ═══════════════════════════════════════════════════════════════════════════
# ESSAI-5a-1 — LES CONDITIONS DE PARTICIPATION, ET LA PREUVE QU'ELLES ONT
#              ETE ACCEPTEES
#
# Ce qui existait : une case a cocher sur la vitrine, qui deverrouillait un
# bouton. Elle pointait vers un texte VIDE, elle n'etait jamais transmise, et
# elle ne couvrait que 18 des 132 reservations reelles — l'espace abonne et le
# ChatWidget, qui en portent 113, n'en avaient aucune. Autrement dit : aucune
# preuve de consentement n'existait pour aucune reservation.
#
# LA GARDE NE S'ALLUME QUE S'IL Y A UN TEXTE. Tant qu'aucune condition n'est
# publiee, rien n'est exige : deployer ce lot ne casse donc aucune reservation.
# Le jour ou le coach ecrit ses conditions, la garde s'active d'elle-meme, sur
# les trois chemins a la fois. L'ordre de livraison est ainsi porte par le code
# plutot que par une consigne qu'on pourrait oublier.
# ═══════════════════════════════════════════════════════════════════════════

# Delai d'annulation d'une seance PAYANTE. Une premiere seance decouverte n'y
# est pas soumise : seule une presence confirmee la consomme.
T1_DELAI_ANNULATION_H = 24

T1_RAISON_REFUS = "terms_not_accepted"
T1_MESSAGE_REFUS = ("Merci d'accepter les conditions de participation "
                    "pour confirmer votre réservation.")


def t1_empreinte(texte: str) -> str:
    """L'identifiant d'une version EST son contenu.

    Deux proprietes gratuites : reenregistrer le meme texte ne cree pas une
    version de plus, et un texte modifie en cree forcement une nouvelle. Une
    version ne peut donc pas etre alteree sans changer d'identifiant — ce qui
    est exactement ce qu'on demande a une preuve.
    """
    import hashlib
    return hashlib.sha256((texte or "").strip().encode("utf-8")).hexdigest()[:12]


async def t1_version_active(coach_id: str = ""):
    """(version, texte) des conditions en vigueur, ou ("", "") s'il n'y en a pas.

    La version est ENREGISTREE au passage si elle ne l'etait pas encore. Une
    ecriture sur un chemin de lecture se justifie ici : elle est idempotente
    (la cle est l'empreinte du contenu) et c'est le seul moyen de garantir
    qu'une version acceptee reste relisable meme apres que le coach a change
    son texte.
    """
    _coach = (coach_id or DEFAULT_COACH_ID).strip().lower()
    try:
        # `id: "concept"` est la cle employee partout ailleurs (l.320, l.14141) ;
        # le repli sur le premier document couvre les bases anterieures.
        _concept = (await db.concept.find_one({"id": "concept"}, {"_id": 0, "termsText": 1})
                    or await db.concept.find_one({}, {"_id": 0, "termsText": 1}) or {})
    except Exception as _err:
        logger.warning("[T1] conditions illisibles : %s", _err)
        return "", ""
    _texte = str(_concept.get("termsText") or "").strip()
    if not _texte:
        return "", ""
    # ESSAI-5a-1C — UN SEUL DOCUMENT, DEUX BLOCS. Le socle s'applique a toute
    # reservation ; le bloc captation ne s'affiche que pour un cours concerne.
    # La version porte sur les DEUX : ce ne sont pas deux documents juridiques
    # independants, et ajouter le bloc plus tard cree donc une version NEUVE
    # sans rien reecrire de ce qui a deja ete accepte.
    _bloc = str(_concept.get("termsTextRecording") or "").strip()
    _version = t1_empreinte(_texte + "\n\n" + _bloc if _bloc else _texte)
    try:
        await db.terms_versions.update_one(
            {"version": _version},
            {"$setOnInsert": {"version": _version, "text": _texte,
                              "text_recording": _bloc,
                              "coach_id": _coach,
                              "created_at": datetime.now(timezone.utc).isoformat()}},
            upsert=True,
        )
    except Exception as _err:
        # La version n'a pas pu etre archivee : on refuse d'exiger une
        # acceptation dont on ne pourrait pas prouver le contenu plus tard.
        logger.error("[T1] version %s non archivee : %s", _version, _err)
        return "", ""
    return _version, _texte


async def t1_bloc_captation(coach_id: str = "") -> str:
    """Le texte « photos et videos », ou "" s'il n'est pas publie.

    C'est LUI qui commande, pas la case du Wizard : tant qu'aucun texte
    n'explique ce qu'on fait des images, aucune seance ne doit annoncer de
    captation — sinon on demanderait une autorisation que rien ne definit.
    """
    try:
        _c = (await db.concept.find_one({"id": "concept"}, {"_id": 0, "termsTextRecording": 1})
              or await db.concept.find_one({}, {"_id": 0, "termsTextRecording": 1}) or {})
    except Exception as _err:
        logger.warning("[T1] bloc captation illisible : %s", _err)
        return ""
    return str(_c.get("termsTextRecording") or "").strip()


async def t1_captation_applicable(course_id: str = "", coach_id: str = "") -> bool:
    """DEUX conditions, et il les faut toutes les deux :

    le cours est marque « susceptible d'etre filme » ET le bloc captation est
    publie. Une seule des deux ne suffit pas — une case cochee sans texte
    afficherait une mention que rien ne couvre, et un texte publie sans case
    l'imposerait a des seances qui ne sont pas filmees.
    """
    if not await t1_bloc_captation(coach_id):
        return False
    return await t1_cours_filme(course_id)


async def t1_cours_filme(course_id: str = "") -> bool:
    """Ce cours est-il annonce comme susceptible d'etre filme ?

    Lu dans la base, JAMAIS dans la requete : le navigateur n'a pas voix au
    chapitre sur ce qui a ete annonce.
    """
    _cid = str(course_id or "").strip()
    if not _cid:
        return False
    try:
        _c = await db.courses.find_one({"id": _cid}, {"_id": 0, "filmed": 1})
    except Exception as _err:
        logger.warning("[T1] cours %s illisible : %s", _cid, _err)
        return False
    return bool((_c or {}).get("filmed") is True)


async def t1_preuve(accepte, course_id: str = "", coach_id: str = "") -> dict:
    """Les quatre champs de preuve, ou un refus. A appeler AVANT toute ecriture.

    Le client n'envoie qu'une chose : « j'accepte ». La version, l'heure et
    l'etat filme du cours sont tous determines ici, par le serveur.

    `filmed_at_booking` fige l'etat annonce AU MOMENT de la reservation : si le
    coach passe le cours en « filme » le mois prochain, les reservations deja
    consenties gardent `False`. Un booleen suffit a ne pas falsifier
    l'historique — inutile d'inventer davantage.
    """
    _version, _ = await t1_version_active(coach_id)
    if not _version:
        # Aucune condition publiee : rien a accepter, rien a exiger.
        return {}
    if accepte is not True:
        raise HTTPException(
            status_code=409,
            detail=T1_MESSAGE_REFUS,
            headers={"X-Refus-Raison": T1_RAISON_REFUS},
        )
    return {
        "terms_accepted": True,
        "terms_version": _version,
        "terms_accepted_at": datetime.now(timezone.utc).isoformat(),
        # ESSAI-5a-1C — ce champ dit « le bloc captation faisait-il partie de ce
        # que cette personne a accepte », et non « le cours etait-il coche ».
        # C'est la seule lecture qui ait une valeur de preuve.
        "filmed_at_booking": await t1_captation_applicable(course_id, coach_id),
    }


async def t1_restituer_essais_non_honores(code: str) -> int:
    """Rend le credit d'un essai RESERVE mais jamais honore. Renvoie le nombre rendu.

    LA REGLE PRODUIT : reserve n'est pas consomme, annule non plus, ne pas venir
    non plus. SEULE UNE PRESENCE CONFIRMEE consomme l'essai.

    Le decompte reste fait a la reservation — et c'est voulu : c'est lui qui
    garantit « une seule reservation d'essai active a la fois », sans compteur
    supplementaire. Ce qui change, c'est qu'il n'est plus definitif : quand
    l'occurrence est passee sans validation, le credit revient ici.

    IDEMPOTENT PAR CONSTRUCTION : le drapeau `trial_credit_restored` est pose par
    une ecriture CONDITIONNELLE sur sa propre absence, et le credit n'est rendu
    que si cette ecriture a gagne. Deux appels simultanes ne rendent qu'un credit.

    La reservation n'est PAS supprimee : elle reste dans le funnel comme une
    reservation d'essai qui n'a pas ete honoree, ce qui est precisement
    l'information qu'ESSAI-3 doit pouvoir montrer.
    """
    _code = (code or "").strip().upper()
    if not _code:
        return 0
    try:
        from api.routes.shared import ESSAI2_FILTRE_GRATUIT as _GRATUIT
        _q = {"code": _code}
        _q.update(_GRATUIT)
        if not await db.discount_codes.find_one(_q, {"_id": 1}):
            return 0          # pas un essai : la regle payante s'applique
    except Exception as _err:
        logger.warning("[T1] nature du code %s indeterminee : %s", _code[:4], _err)
        return 0

    _maintenant = datetime.now(timezone.utc).isoformat()
    try:
        _passees = await db.reservations.find({
            "$or": [{"promoCode": _code}, {"discountCode": _code}],
            "validated": {"$ne": True},
            "trial_credit_restored": {"$exists": False},
            "datetime": {"$lt": _maintenant},
        }, {"_id": 0, "id": 1, "quantity": 1}).to_list(20)
    except Exception as _err:
        logger.warning("[T1] reservations d'essai illisibles : %s", _err)
        return 0

    _rendus = 0
    for _r in _passees:
        try:
            _pris = await db.reservations.update_one(
                {"id": _r.get("id"), "trial_credit_restored": {"$exists": False}},
                {"$set": {"trial_credit_restored": _maintenant}},
            )
            if not getattr(_pris, "matched_count", 0):
                continue      # un autre appel l'a deja rendu
            _q = max(1, int(_r.get("quantity") or 1))
            await db.subscriptions.update_one(
                {"code": _code},
                {"$inc": {"remaining_sessions": _q, "used_sessions": -_q},
                 "$set": {"status": "active",
                          "updated_at": _maintenant}},
            )
            await db.discount_codes.update_one({"code": _code}, {"$inc": {"used": -_q}})
            _rendus += _q
            logger.info("[T1] essai non honore : %d credit(s) rendu(s) sur %s…",
                        _q, _code[:4])
        except Exception as _err:
            logger.error("[T1] restitution impossible pour %s : %s", _r.get("id"), _err)
    return _rendus



@api_router.get("/terms/active")
async def t1_conditions_actives(request: Request, course_id: str = ""):
    """Les conditions a afficher, et si CE cours annonce une captation.

    Publique et anonyme : c'est un texte destine a etre lu avant de reserver.
    Elle ne rend que ce qui s'affiche — aucune identite, aucun coach, aucun
    identifiant interne (meme regle que la liste blanche des commentaires).
    """
    _coach = request.query_params.get("coach_id", "") or ""
    _version, _texte = await t1_version_active(_coach)
    _captation = await t1_captation_applicable(course_id, _coach) if _version else False
    if _captation:
        _texte = _texte + "\n\n" + await t1_bloc_captation(_coach)
    return {
        "version": _version,
        "text": _texte,
        "filmed": _captation,
        "required": bool(_version),
    }



# ═══════════════════════════════════════════════════════════════════════════
# ESSAI-5a-1D — CE QUE L'ECRAN DIT D'UN ESSAI, ET CE QU'IL EN EST
#
# La regle metier : reserver ne consomme pas l'essai, seule la presence le
# consomme. Le compteur, lui, est bien decremente des la reservation — et il
# DOIT l'etre : c'est lui qui garantit « une seule reservation gratuite active
# a la fois », sans compteur supplementaire.
#
# Consequence a l'ecran, tant que la reservation tient : « Seances restantes
# 0 / 1 », un bandeau « Plus de seances disponibles » et un bouton grise. Trois
# signaux qui disent « c'est fini » a quelqu'un dont le droit est intact.
#
# On ne change donc pas le compteur, on l'INTERPRETE. L'etat est DERIVE des
# documents existants — aucune nouvelle source de verite, aucune ecriture.
# ═══════════════════════════════════════════════════════════════════════════

T2_ESSAI_DISPONIBLE = "available"
T2_ESSAI_RESERVE = "booked"
T2_ESSAI_EFFECTUE = "done"


async def t2_etat_essai(code: str, reservations: list, remaining) -> dict:
    """L'etat d'un essai gratuit, ou `{"is_trial": False}` pour tout le reste.

    Trois lectures, toutes sur des donnees deja chargees :
      - le code est-il un code d'essai (meme regle qu'ESSAI-2) ;
      - une de ses reservations est-elle VALIDEE -> l'essai est effectue ;
      - une de ses reservations est-elle encore A VENIR -> l'essai est reserve.

    Un forfait PAYANT ressort `is_trial: False` et l'ecran ne change pas d'un
    pixel : le compteur de PULSE x10 continue d'afficher son vrai reste.
    """
    _code = (code or "").strip().upper()
    if not _code:
        return {"is_trial": False}
    try:
        from api.routes.shared import ESSAI2_FILTRE_GRATUIT as _GRATUIT
        _q = {"code": _code}
        _q.update(_GRATUIT)
        if not await db.discount_codes.find_one(_q, {"_id": 1}):
            return {"is_trial": False}
    except Exception as _err:
        # Dans le doute, on ne requalifie rien : l'ecran garde son comportement
        # historique, qui est correct pour un forfait payant.
        logger.warning("[T2] nature du code %s indeterminee : %s", _code[:4], _err)
        return {"is_trial": False}

    _maintenant = datetime.now(timezone.utc).isoformat()
    _validee = None
    _a_venir = None
    for _r in (reservations or []):
        if _r.get("validated") is True:
            _validee = _r
            break
        _quand = str(_r.get("datetime") or "")
        if _quand and _quand > _maintenant and _a_venir is None:
            _a_venir = _r

    if _validee:
        _etat = T2_ESSAI_EFFECTUE
        _seance = _validee
    elif _a_venir:
        _etat = T2_ESSAI_RESERVE
        _seance = _a_venir
    else:
        # Ni presence, ni reservation a venir : le droit est disponible. Le
        # compteur peut encore afficher 0 le temps qu'une seance passee soit
        # cloturee — c'est `t1_restituer_essais_non_honores` qui s'en charge a
        # la prochaine tentative de reservation.
        _etat = T2_ESSAI_DISPONIBLE
        _seance = None

    return {
        "is_trial": True,
        "state": _etat,
        # `remaining` reste expose tel quel a cote : on n'efface aucune donnee,
        # on ajoute la lecture qui lui donne son sens.
        "remaining_raw": remaining,
        "next_session": ({
            "courseName": _seance.get("courseName") or "",
            "datetime": _seance.get("datetime") or "",
            "courseTime": _seance.get("courseTime") or "",
        } if _seance else None),
    }



# ═══════════════════════════════════════════════════════════════════════════
# ESSAI-5a-2 — TEMOIGNAGES AUTHENTIQUES
#
# Un temoignage humain n'a rien a voir avec les 88 commentaires generes par IA
# qui peuplent le mur actuel. Ils cohabitent dans `db.comments` mais ne se
# melangent jamais : seul ce qui porte `source: participant_testimonial` est
# un temoignage, et rien d'autre ne le portera.
#
# TROIS REGLES QUI NE BOUGENT PAS :
#   1. le temoignage est FACULTATIF — refuser n'a aucun effet sur l'essai,
#      la reservation, le prix, les rappels ou le funnel ;
#   2. rien n'est public sans consentement ET sans approbation du coach ;
#   3. detenir un code ne prouve pas qu'on a participe. La preuve doit etre
#      ANTERIEURE au forfait courant, sinon tout nouveau participant serait
#      pris pour un ancien des sa premiere minute.
# ═══════════════════════════════════════════════════════════════════════════

T3_MARQUEUR = "participant_testimonial"
T3_PENDING = "pending"
T3_APPROVED = "approved"
T3_HIDDEN = "hidden"
T3_ETATS = (T3_PENDING, T3_APPROVED, T3_HIDDEN)

# Ce que le public voit d'un temoignage. Liste BLANCHE, comme celle des
# commentaires (P0) — mais plus stricte : le prenom lui-meme n'en fait partie
# que si la personne l'a autorise, ce qui se decide a la lecture.
T3_CHAMPS_PUBLICS = ("id", "text", "created_at")

T3_LONGUEUR_MAX = 1500


async def t3_deja_temoigne(code: str) -> dict:
    """Cette personne a-t-elle deja soumis un temoignage ? (etat compris)"""
    _code = (code or "").strip().upper()
    if not _code:
        return {}
    try:
        _d = await db.comments.find_one(
            {"participant_code": _code, "source": T3_MARQUEUR},
            {"_id": 0, "moderation_status": 1, "created_at": 1},
            sort=[("created_at", -1)])
        return _d or {}
    except Exception as _err:
        logger.warning("[T3] temoignage existant illisible : %s", _err)
        return {}


T3_TYPES_CONTACT = ("participant", "prospect", "partner", "other")


async def t3_contact_type(email: str) -> str:
    """Le type declare de ce contact, ou "" s'il n'est pas classe.

    Valeur STOCKEE en anglais, libelle affiche en francais : on ne melange pas
    les deux, sinon renommer un libelle casserait la donnee.
    """
    _mail = (email or "").strip().lower()
    if not _mail:
        return ""
    try:
        _c = await db.chat_participants.find_one(
            {"email": {"$regex": "^%s$" % re.escape(_mail), "$options": "i"}},
            {"_id": 0, "contact_type": 1})
    except Exception as _err:
        logger.warning("[T3] type de contact illisible : %s", _err)
        return ""
    _t = str((_c or {}).get("contact_type") or "").strip().lower()
    return _t if _t in T3_TYPES_CONTACT else ""


async def t3_eligibilite(code: str, email: str, forfait_cree_le: str = "") -> dict:
    """Cette personne a-t-elle deja vecu Afroboost ? La reponse vient du COACH.

    UNE SEULE SOURCE : `chat_participants.contact_type == "participant"`, posee
    a la main depuis la page Contacts. Rien n'est deduit — ni de l'adresse, ni
    du code, ni d'une reservation, ni d'un forfait, ni d'une source marketing.

    POURQUOI PAS UNE DEDUCTION. Afroboost existait avant le site : la base ne
    peut pas savoir qui a deja danse. Toute regle automatique se tromperait
    dans les deux sens — en oubliant les anciens d'avant le site, et en prenant
    pour un ancien un nouveau venu qui possede deja un code depuis une minute.
    Le coach, lui, sait.

    CHAMP ABSENT = NON CLASSE = AUCUNE INVITATION. Un systeme silencieux vaut
    mieux qu'un mauvais classement : tant que rien n'est classe, personne n'est
    sollicite.
    """
    _code = (code or "").strip().upper()
    _deja = await t3_deja_temoigne(_code)
    _type = await t3_contact_type(email)
    return {
        "eligible": _type == "participant",
        "contact_type": _type or None,
        "already_submitted": bool(_deja),
        "status": _deja.get("moderation_status") if _deja else None,
    }


def t3_public(doc: dict) -> dict:
    """Ce qu'un temoignage montre au public, et rien de plus.

    Le prenom n'est ajoute QUE si la personne l'a autorise separement du texte :
    consentir a publier ses mots n'est pas consentir a publier son identite.
    """
    _d = doc or {}
    _sortie = {_c: _d[_c] for _c in T3_CHAMPS_PUBLICS if _c in _d}
    if _d.get("consent_identity") is True:
        _prenom = str(_d.get("user_name") or "").strip().split(" ")[0]
        if _prenom:
            _sortie["user_name"] = _prenom
    return _sortie



@api_router.post("/testimonials")
async def t3_soumettre(request: Request):
    """Un participant soumet SON temoignage. Rien n'est publie ici.

    L'IDENTITE VIENT DE LA BASE, JAMAIS DU CORPS. `_v261_resolve_subscriber`
    rend le nom enregistre : c'est ce qui empeche quelqu'un de publier sous
    l'identite d'un autre — le meme garde-fou que le mur de publications.
    """
    try:
        _b = await request.json()
    except Exception:
        raise HTTPException(status_code=400, detail="Requête invalide")

    _code = str((_b or {}).get("code") or "").strip().upper()
    _texte = str((_b or {}).get("text") or "").strip()
    _consent = (_b or {}).get("consent_publication") is True
    _consent_id = (_b or {}).get("consent_identity") is True
    _consent_texte = str((_b or {}).get("consent_text") or "").strip()[:400]
    _offre = str((_b or {}).get("offer_id") or "").strip()[:64]

    if not _texte:
        raise HTTPException(status_code=400, detail="Le témoignage est vide.")
    if len(_texte) > T3_LONGUEUR_MAX:
        raise HTTPException(status_code=400, detail="Témoignage trop long.")

    _ok, _nom, _coach = await _v261_resolve_subscriber(_code)
    if not _ok:
        # Meme reponse qu'un code absent : on ne renseigne pas qui existe.
        raise HTTPException(status_code=403, detail="Code d'accès invalide.")

    if await t3_deja_temoigne(_code):
        raise HTTPException(status_code=409, detail="Vous avez déjà partagé votre expérience.")

    _now = datetime.now(timezone.utc).isoformat()
    _doc = {
        "id": "temoignage_%s_%s" % (datetime.now(timezone.utc).strftime("%Y%m%d%H%M%S"),
                                    _random.randint(100, 999)),
        # Le marqueur POSITIF qui separe ce document des 88 commentaires IA.
        "source": T3_MARQUEUR,
        "is_review": True,
        "is_ai": False,
        # `is_visible` reste FAUX : aucune publication automatique. C'est le
        # defaut inverse de `POST /reviews`, et c'est voulu.
        "is_visible": False,
        "moderation_status": T3_PENDING,
        "text": _texte,
        # Le nom vient de la base. Le corps de la requete ne peut pas le dicter.
        "user_name": _nom or "",
        "participant_code": _code,
        "coach_id": _coach or DEFAULT_COACH_ID,
        "offer_id": _offre,
        "consent_publication": _consent,
        "consent_identity": _consent_id,
        "consented_at": _now if _consent else None,
        "consent_text_version": _consent_texte,
        "recognition": str((_b or {}).get("recognition") or "")[:24],
        "created_at": _now,
    }
    await db.comments.insert_one(_doc)
    # Le code n'apparait pas dans le journal : c'est le mot de passe de
    # l'espace abonne (cf. P0).
    logger.info("[T3] témoignage reçu (%s…), en attente de modération", _code[:4])
    try:
        from api.routes.shared import posthog_capture as _ph
        await _ph("testimonial_submitted", email="", props={
            "offer_id": _offre, "length": len(_texte),
            "consent_publication": _consent, "consent_identity": _consent_id,
            "recognition": _doc["recognition"],
        })
    except Exception as _err:
        logger.warning("[T3] mesure ignorée : %s", _err)
    return {"success": True, "status": T3_PENDING}


@api_router.get("/testimonials")
async def t3_publics(request: Request, offer_id: str = "", limit: int = 12):
    """Les temoignages visibles du public. Trois conditions, toutes exigees.

    Ne sortent que les documents qui portent le marqueur, dont la personne a
    autorise la publication, ET que le coach a approuves. Un `pending` ou un
    `hidden` n'apparait jamais. Aucun commentaire IA ne peut passer : ils ne
    portent pas le marqueur.
    """
    _q = {
        "source": T3_MARQUEUR,
        "consent_publication": True,
        "moderation_status": T3_APPROVED,
        "is_visible": True,
    }
    _coach = request.query_params.get("coach_id", "").strip().lower()
    if _coach:
        _q["coach_id"] = _coach
    if offer_id:
        _q["offer_id"] = offer_id
    try:
        # Projection MongoDB : les champs sensibles ne quittent pas la base.
        # `consent_identity` en sort pour decider du prenom, et est retire
        # ensuite par `t3_public` — il n'est jamais rendu.
        _rows = await db.comments.find(_q, {
            "_id": 0, "id": 1, "text": 1, "created_at": 1,
            "user_name": 1, "consent_identity": 1,
        }).sort("created_at", -1).to_list(max(1, min(int(limit or 12), 50)))
    except Exception as _err:
        logger.error("[T3] témoignages publics illisibles : %s", _err)
        raise HTTPException(status_code=503, detail="Témoignages momentanément indisponibles")
    return {"testimonials": [t3_public(_r) for _r in _rows]}


@api_router.get("/coach/testimonials")
async def t3_liste_coach(request: Request, status: str = ""):
    """Les temoignages a moderer. Reservee au coach, jamais publique."""
    _email = await _n1b3b2_coach_appelant(request)
    _q = {"source": T3_MARQUEUR}
    if not is_super_admin(_email):
        _q["coach_id"] = _email.strip().lower()
    if status in T3_ETATS:
        _q["moderation_status"] = status
    try:
        _rows = await db.comments.find(_q, {
            "_id": 0, "id": 1, "text": 1, "created_at": 1, "user_name": 1,
            "moderation_status": 1, "consent_publication": 1,
            "consent_identity": 1, "recognition": 1, "offer_id": 1,
        }).sort("created_at", -1).to_list(200)
    except Exception as _err:
        logger.error("[T3] témoignages du coach illisibles : %s", _err)
        raise HTTPException(status_code=503, detail="Témoignages momentanément indisponibles")
    # `participant_code` n'est PAS projete : le coach n'en a pas besoin pour
    # moderer, et c'est le mot de passe de la personne.
    return {"testimonials": _rows,
            "counts": {_e: sum(1 for r in _rows if r.get("moderation_status") == _e)
                       for _e in T3_ETATS}}


@api_router.put("/coach/testimonials/{temoignage_id}/moderation")
async def t3_moderer(temoignage_id: str, request: Request):
    """Approuver ou masquer. AUCUNE publication automatique.

    Un temoignage masque ne redevient jamais public tout seul : seul un appel
    explicite a `approved` l'y ramene.
    """
    _email = await _n1b3b2_coach_appelant(request)
    try:
        _b = await request.json()
    except Exception:
        _b = {}
    _etat = str((_b or {}).get("status") or "").strip()
    if _etat not in T3_ETATS:
        raise HTTPException(status_code=400, detail="État de modération inconnu")

    _q = {"id": temoignage_id, "source": T3_MARQUEUR}
    if not is_super_admin(_email):
        _q["coach_id"] = _email.strip().lower()
    _doc = await db.comments.find_one(_q, {"_id": 0, "consent_publication": 1})
    if not _doc:
        raise HTTPException(status_code=404, detail="Témoignage introuvable")

    # `is_visible` suit l'etat ET le consentement : approuver un temoignage non
    # consenti ne le rend pas public. Les deux conditions sont exigees a
    # l'ecriture ET a la lecture — une seule des deux serait un pari.
    _visible = bool(_etat == T3_APPROVED and _doc.get("consent_publication") is True)
    await db.comments.update_one({"id": temoignage_id}, {"$set": {
        "moderation_status": _etat,
        "is_visible": _visible,
        "moderated_at": datetime.now(timezone.utc).isoformat(),
        "moderated_by": _email,
    }})
    logger.info("[T3] témoignage %s -> %s par %s", temoignage_id, _etat, _email)
    if _etat == T3_APPROVED:
        try:
            from api.routes.shared import posthog_capture as _ph
            await _ph("testimonial_approved", email="", props={"published": _visible})
        except Exception as _err:
            logger.warning("[T3] mesure ignorée : %s", _err)
    return {"success": True, "status": _etat, "is_visible": _visible}



@api_router.put("/contacts/{contact_id}/type")
async def t3_classer_contact(contact_id: str, request: Request):
    """Le coach classe un contact. C'est la SEULE facon de devenir participant.

    Aucun classement automatique n'existe, et c'est deliberе : la base ne peut
    pas savoir qui a deja danse avant l'existence du site. Une valeur vide
    declasse le contact, ce qui doit rester possible — se tromper doit pouvoir
    se defaire.
    """
    _email = await _n1b3b2_coach_appelant(request)
    try:
        _b = await request.json()
    except Exception:
        _b = {}
    _type = str((_b or {}).get("contact_type") or "").strip().lower()
    if _type and _type not in T3_TYPES_CONTACT:
        raise HTTPException(status_code=400, detail="Type de contact inconnu")

    _filtre = {"id": contact_id}
    if not is_super_admin(_email):
        _filtre["coach_id"] = _email.strip().lower()
    if _type:
        _maj = {"$set": {"contact_type": _type,
                         "contact_type_set_at": datetime.now(timezone.utc).isoformat(),
                         "contact_type_set_by": _email}}
    else:
        # Declasser retire le champ : « absent » et « autre » ne veulent pas
        # dire la meme chose, et on ne doit pas les confondre.
        _maj = {"$unset": {"contact_type": "", "contact_type_set_at": "",
                           "contact_type_set_by": ""}}
    _res = await db.chat_participants.update_one(_filtre, _maj)
    if not getattr(_res, "matched_count", 0):
        raise HTTPException(status_code=404, detail="Contact introuvable")
    logger.info("[T3] contact %s classe %s par %s", contact_id, _type or "(aucun)", _email)
    return {"success": True, "contact_type": _type or None}


@api_router.get("/coach/contacts/suggestions-participant")
async def t3_suggestions_participant(request: Request):
    """LECTURE SEULE — qui pourrait etre classe « participant », et pourquoi.

    Ne modifie RIEN. Le coach reste seul decisionnaire ; cette route se contente
    de rapprocher deux choses que la base sait deja : un contact non classe, et
    une presence REELLEMENT confirmee a son nom.

    Les cas ambigus ne donnent aucune suggestion : une reservation non validee
    n'est pas une participation, et on ne proposera jamais de la traiter comme
    telle.
    """
    _email = await _n1b3b2_coach_appelant(request)
    try:
        _q = {"validated": True}
        if not is_super_admin(_email):
            _q["coach_id"] = _email.strip().lower()
        _presences = await db.reservations.find(
            _q, {"_id": 0, "userEmail": 1, "validatedAt": 1}).to_list(1000)
    except Exception as _err:
        logger.error("[T3] presences illisibles : %s", _err)
        raise HTTPException(status_code=503, detail="Suggestions momentanément indisponibles")

    _par_mail = {}
    for _r in _presences:
        _m = str(_r.get("userEmail") or "").strip().lower()
        if not _m:
            continue
        _quand = str(_r.get("validatedAt") or "")
        if _m not in _par_mail or _quand < _par_mail[_m]:
            _par_mail[_m] = _quand

    _suggestions = []
    for _m, _quand in sorted(_par_mail.items()):
        try:
            _c = await db.chat_participants.find_one(
                {"email": {"$regex": "^%s$" % re.escape(_m), "$options": "i"}},
                {"_id": 0, "id": 1, "name": 1, "contact_type": 1})
        except Exception:
            _c = None
        if not _c:
            continue                      # pas de contact : rien a classer
        if str(_c.get("contact_type") or "").strip():
            continue                      # deja classe : on ne propose rien
        _suggestions.append({
            "contact_id": _c.get("id"),
            "name": _c.get("name") or "",
            "suggestion": "participant",
            "raison": "présence confirmée",
            "depuis": _quand[:10],
        })
    return {"suggestions": _suggestions,
            "total_presences": len(_par_mail),
            "note": "Lecture seule — aucune classification n'a été écrite."}



@api_router.get("/coach/contacts/dry-run-participant")
async def t3_dry_run_participant(request: Request, groupe: str = "", ids: int = 0):
    """SIMULATION — qui deviendrait « participant » si l'on basculait le stock.

    STRICTEMENT EN LECTURE. Aucun `contact_type` n'est ecrit, aucun document
    n'est modifie. Cette route existe parce que `GET /chat/participants` est
    plafonnee a 1000 documents : on ne peut pas compter la base depuis le
    client, et decider d'une bascule sur un echantillon tronque serait decider
    a l'aveugle.

    Elle croise trois choses que la base sait deja :
      - l'origine du contact (`source`), qui dit COMMENT il est entre ;
      - son etat commercial (`isSubscriber`, `subscriptionCode`), qui n'est PAS
        une preuve de participation — on peut etre abonne sans etre jamais venu,
        et etre venu sans etre abonne ;
      - une presence REELLEMENT confirmee (`reservations.validated`), seule
        preuve forte que la personne a vecu Afroboost.
    """
    _email = await _n1b3b2_coach_appelant(request)
    _filtre = {} if is_super_admin(_email) else {"coach_id": _email.strip().lower()}

    # ── Les presences confirmees, par adresse. Une seule lecture.
    _presents = set()
    try:
        _q = {"validated": True}
        if not is_super_admin(_email):
            _q["coach_id"] = _email.strip().lower()
        async for _r in db.reservations.find(_q, {"_id": 0, "userEmail": 1}):
            _m = str(_r.get("userEmail") or "").strip().lower()
            if _m:
                _presents.add(_m)
    except Exception as _err:
        logger.warning("[DRY] presences illisibles : %s", _err)

    _bascule = "2026-08-17T19:22:33+00:00"   # deploiement d'ESSAI-5a-2
    # Le groupe VERT : les seules sources qui prouvent un abonnement obtenu,
    # donc un engagement reel. Les 5 presences confirmees y sont toutes.
    _SOURCES_VERT = ("espace_onboarding", "chat_login")
    _liste_vert = []
    _par_source = {}
    _total = 0
    _abonnes = 0
    _classes = 0
    _avec_presence = 0
    _posterieurs = 0

    try:
        # Pas de `to_list` : on parcourt le curseur, donc AUCUN plafond.
        async for _c in db.chat_participants.find(_filtre, {
                # `id` etait absent de cette projection : les identifiants
                # rendus valaient tous None, et les 22 classements ont ete
                # refuses en 404 — sans rien ecrire, la garde ayant tenu.
                "_id": 0, "id": 1, "source": 1, "email": 1, "created_at": 1,
                "isSubscriber": 1, "subscriptionCode": 1, "code": 1,
                "contact_type": 1, "categories": 1}):
            _total += 1
            _src = str(_c.get("source") or "(aucune)")
            _s = _par_source.setdefault(_src, {
                "total": 0, "abonnes": 0, "presences": 0,
                "deja_classes": 0, "posterieurs": 0, "candidats": 0,
                "avec_email": 0, "avec_categorie": 0})
            _s["total"] += 1

            _mail = str(_c.get("email") or "").strip().lower()
            if _mail:
                _s["avec_email"] += 1
            if _c.get("categories"):
                _s["avec_categorie"] += 1

            _est_abonne = bool(_c.get("isSubscriber") is True
                               or str(_c.get("subscriptionCode") or "").strip()
                               or str(_c.get("code") or "").strip())
            if _est_abonne:
                _abonnes += 1
                _s["abonnes"] += 1

            _a_presence = bool(_mail and _mail in _presents)
            if _a_presence:
                _avec_presence += 1
                _s["presences"] += 1

            _deja = bool(str(_c.get("contact_type") or "").strip())
            if _deja:
                _classes += 1
                _s["deja_classes"] += 1

            _apres = str(_c.get("created_at") or "") >= _bascule
            if _apres:
                _posterieurs += 1
                _s["posterieurs"] += 1

            # Candidat = stock historique, non classe. L'abonnement n'exclut
            # PAS : « participant » decrit une relation, « abonne » un etat
            # commercial, et les deux peuvent coexister.
            if not _deja and not _apres:
                _s["candidats"] += 1

            # `?groupe=vert&ids=1` rend les identifiants a classer. LECTURE
            # SEULE : c'est la seule facon de les obtenir, la route publique
            # des contacts etant plafonnee a 1000 documents.
            if (groupe == "vert" and ids and not _deja and not _apres
                    and _src in _SOURCES_VERT):
                _liste_vert.append({
                    "id": _c.get("id"), "source": _src,
                    "abonne": _est_abonne, "presence": _a_presence,
                    "contact_type_avant": _c.get("contact_type"),
                })
    except Exception as _err:
        logger.error("[DRY] contacts illisibles : %s", _err)
        raise HTTPException(status_code=503, detail="Simulation momentanément indisponible")

    return {
        "dry_run": True,
        "aucune_ecriture": True,
        "bascule_reference": _bascule,
        "total_contacts": _total,
        "abonnes_actuels": _abonnes,
        "avec_presence_confirmee": _avec_presence,
        "deja_classes": _classes,
        "crees_apres_bascule": _posterieurs,
        "candidats_stock_historique": sum(s["candidats"] for s in _par_source.values()),
        "par_source": dict(sorted(_par_source.items(),
                                  key=lambda kv: -kv[1]["total"])),
        "presences_distinctes_total": len(_presents),
        "note": "Lecture seule — aucun contact_type n'a été écrit.",
        "groupe_vert": _liste_vert if (groupe == "vert" and ids) else None,
        "sources_vert": list(_SOURCES_VERT),
    }



# ═══════════════════════════════════════════════════════════════════════════
# CONTACTS V2 — QUATRE DIMENSIONS, TROIS DERIVEES
#
# Ce qui se confondait dans un seul ecran se separe ici :
#
#   RELATION           `contact_type`, pose a la main par le coach   (STOCKE)
#   STATUT COMMERCIAL  actif / ancien / non abonne                   (DERIVE)
#   CANAL              e-mail, WhatsApp, telephone disponibles       (DERIVE)
#   ZONE               pays deduit de l'indicatif E.164              (DERIVE)
#
# Et une cinquieme, qu'on ne confondra pas avec le canal :
#
#   CONSENTEMENT       autorise / refuse / INCONNU, PAR CANAL        (DERIVE)
#
# AVOIR UN NUMERO N'EST PAS AVOIR LE DROIT D'ECRIRE. Le consentement vient de
# la collection `subscribers` (opt-in V332), seule a porter une preuve datee
# avec le texte accepte. Sans trace, l'etat est INCONNU — jamais « autorise ».
# Aucun consentement n'est fabrique, aucun backfill n'est fait.
# ═══════════════════════════════════════════════════════════════════════════

# Indicatifs telephoniques -> (code pays, zone). Le pays est conserve pour
# pouvoir filtrer finement (Cameroun, Senegal…) tandis que l'ecran regroupe
# par zone. Liste volontairement courte : ce qui n'y figure pas ressort
# « autre », jamais devine.
C2_INDICATIFS = {
    "41": ("CH", "suisse"),
    "33": ("FR", "europe"), "32": ("BE", "europe"), "49": ("DE", "europe"),
    "39": ("IT", "europe"), "34": ("ES", "europe"), "44": ("GB", "europe"),
    "351": ("PT", "europe"), "31": ("NL", "europe"), "43": ("AT", "europe"),
    "352": ("LU", "europe"), "377": ("MC", "europe"),
    "237": ("CM", "afrique"), "221": ("SN", "afrique"), "225": ("CI", "afrique"),
    "223": ("ML", "afrique"), "226": ("BF", "afrique"), "227": ("NE", "afrique"),
    "228": ("TG", "afrique"), "229": ("BJ", "afrique"), "233": ("GH", "afrique"),
    "234": ("NG", "afrique"), "236": ("CF", "afrique"), "241": ("GA", "afrique"),
    "242": ("CG", "afrique"), "243": ("CD", "afrique"), "212": ("MA", "afrique"),
    "213": ("DZ", "afrique"), "216": ("TN", "afrique"), "220": ("GM", "afrique"),
    "224": ("GN", "afrique"), "235": ("TD", "afrique"), "254": ("KE", "afrique"),
    "27": ("ZA", "afrique"),
}

C2_ZONES = ("suisse", "europe", "afrique", "autre", "inconnue")
C2_STATUTS = ("actif", "ancien", "non_abonne")
C2_CONSENTEMENTS = ("autorise", "refuse", "inconnu")


def c2_pays_zone(numero: str):
    """(pays, zone) depuis un numero, ou (None, "inconnue").

    UN INDICATIF MALFORME N'EST JAMAIS UN PAYS CERTAIN. Un numero national
    (« 079… ») ne dit rien du pays : deux pays ecrivent leurs numeros
    localement de la meme facon. Dans le doute, « inconnue » — c'est une
    information, pas un echec.
    """
    _n = str(numero or "").strip().replace(" ", "").replace(".", "").replace("-", "")
    if _n.startswith("00"):
        _n = "+" + _n[2:]
    if not _n.startswith("+"):
        return None, "inconnue"
    _chiffres = "".join(c for c in _n[1:] if c.isdigit())
    if len(_chiffres) < 8:
        return None, "inconnue"
    for _l in (3, 2, 1):
        _p = _chiffres[:_l]
        if _p in C2_INDICATIFS:
            _pays, _zone = C2_INDICATIFS[_p]
            return _pays, _zone
    return None, "autre"


def c2_canaux(contact: dict) -> dict:
    """Les canaux DISPONIBLES — ce qui ne dit rien du droit de s'en servir."""
    _c = contact or {}
    _num = str(_c.get("whatsapp") or "").strip() or str(_c.get("phone") or "").strip()
    return {
        "email": bool(str(_c.get("email") or "").strip()),
        "whatsapp": bool(str(_c.get("whatsapp") or "").strip()),
        "telephone": bool(_num),
    }


def c2_consentement(statut_optin) -> str:
    """`confirmed` -> autorise, `opted_out` -> refuse, tout le reste inconnu.

    `pending` reste INCONNU : une inscription non confirmee n'est pas une
    autorisation. Et l'absence de document ne vaut jamais accord.
    """
    _s = str(statut_optin or "").strip().lower()
    if _s == "confirmed":
        return "autorise"
    if _s == "opted_out":
        return "refuse"
    return "inconnu"


async def c2_index_abonnements() -> dict:
    """email -> "actif" | "ancien". Absent = non abonne.

    La verite vient de `subscriptions` et de `forfait_utilisable`, jamais du
    drapeau `isSubscriber` : celui-ci est ecrit une seule fois a l'activation
    et n'est JAMAIS remis a faux — un abonne de mars dont le forfait a expire
    le porte encore. S'y fier afficherait « actif » a d'anciens abonnes.
    """
    from api.routes.shared import forfait_utilisable as _utilisable
    _index = {}
    try:
        async for _s in db.subscriptions.find({}, {
                "_id": 0, "email": 1, "status": 1, "expires_at": 1,
                "remaining_sessions": 1, "total_sessions": 1}):
            _m = str(_s.get("email") or "").strip().lower()
            if not _m:
                continue
            _ok = False
            try:
                _ok = bool(_utilisable(_s)[0])
            except Exception:
                _ok = False
            if _ok:
                _index[_m] = "actif"
            elif _index.get(_m) != "actif":
                _index[_m] = "ancien"
    except Exception as _err:
        logger.warning("[C2] abonnements illisibles : %s", _err)
    return _index


async def c2_index_consentements() -> dict:
    """(canal, valeur normalisee) -> statut opt-in. Une seule lecture."""
    _index = {}
    try:
        async for _s in db.subscribers.find({}, {
                "_id": 0, "channel": 1, "value": 1, "status": 1}):
            _canal = str(_s.get("channel") or "").strip().lower()
            _val = str(_s.get("value") or "").strip().lower()
            if _canal == "whatsapp":
                _val = "".join(c for c in _val if c.isdigit())
            if _canal and _val:
                _index[(_canal, _val)] = _s.get("status")
    except Exception as _err:
        logger.warning("[C2] consentements illisibles : %s", _err)
    return _index


def c2_enrichir(contact: dict, abonnements: dict, consentements: dict) -> dict:
    """Ajoute les quatre dimensions derivees a une fiche contact."""
    _c = contact or {}
    _mail = str(_c.get("email") or "").strip().lower()
    _num = str(_c.get("whatsapp") or "").strip() or str(_c.get("phone") or "").strip()
    _pays, _zone = c2_pays_zone(_num)
    _chiffres = "".join(ch for ch in _num if ch.isdigit())
    _c["statut_abonnement"] = abonnements.get(_mail, "non_abonne") if _mail else "non_abonne"
    _c["pays"] = _pays
    _c["zone"] = _zone
    _c["canaux"] = c2_canaux(_c)
    _c["consentement"] = {
        "email": c2_consentement(consentements.get(("email", _mail))) if _mail else "inconnu",
        "whatsapp": c2_consentement(consentements.get(("whatsapp", _chiffres))) if _chiffres else "inconnu",
    }
    return _c



# V183: Cron rappel 1h avant un cours réservé
@api_router.get("/cron/reservation-reminders")
async def cron_reservation_reminders():
    """V183: Cron horaire — envoie un rappel 1h avant chaque cours réservé."""
    from datetime import timedelta as _td
    from zoneinfo import ZoneInfo as _ZoneInfo
    now = datetime.now(timezone.utc)

    # === V435 : le rappel partait APRES le debut du cours ===
    #
    # L'ancienne requete comparait des CHAINES : les bornes etaient construites
    # en UTC (`(now+45min).isoformat()`) et confrontees telles quelles au champ
    # `datetime`. Or deux formats coexistent en base (mesure du 12/08/2026 sur
    # les 125 reservations) :
    #     57  « 2026-03-11T17:01:14.738Z »  -> UTC explicite
    #     67  « 2026-05-13T18:30:00 »       -> NAIF, en heure suisse
    # Les dates naives etaient donc lues comme de l'UTC : decalage de 2 h, et le
    # rappel « 1 h avant » atterrissait 90 MINUTES APRES le debut du cours. Les
    # 67 concernees etaient toutes dans ce cas, sans exception.
    #
    # Un decalage fixe ne suffirait pas : il serait faux la moitie de l'annee.
    # On interprete donc une date naive dans `Europe/Zurich`, qui gere seule le
    # passage ete/hiver, avant de comparer de VRAIS instants.
    #
    # Second defaut, independant : la fenetre faisait 30 min alors que le cron
    # passe toutes les 60 min — une reservation sur deux pouvait tomber entre
    # deux passages. Elle fait desormais 60 min, exactement la periode du cron :
    # couverture continue, sans recouvrement. Delai reel : 30 a 90 min.
    #
    # La borne basse est TOUJOURS dans le futur (`now + 30 min`) : un cours deja
    # commence ne peut jamais etre rattrape.
    #
    # N1B-2 : la fenetre n'est plus calee sur le cours mais sur la CIBLE de
    # chaque regle (`cible - 30 < maintenant <= cible + 30`). Pour la regle
    # historique — 60 min avant — les deux formulations sont EQUIVALENTES au
    # borne pres : cible = cours - 60, donc la condition redonne exactement
    # `maintenant + 30 <= cours < maintenant + 90`. Comportement inchange.
    _zurich = _ZoneInfo("Europe/Zurich")
    _demi = _td(minutes=N1B2_DEMI_FENETRE_MIN)
    _horizon = now + _td(minutes=N1B2_HORIZON_MIN)

    def _v435_instant_du_cours(valeur):
        """Instant REEL du cours en UTC, ou None si la date est inexploitable."""
        if not isinstance(valeur, str) or not valeur.strip():
            return None
        try:
            dt = datetime.fromisoformat(valeur.strip().replace("Z", "+00:00"))
        except ValueError:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=_zurich)
        return dt.astimezone(timezone.utc)

    try:
        # Pre-filtre large cote base (les deux formats commencent par AAAA-MM-JJ,
        # la comparaison de prefixe est donc sure) : on ne remonte que les jours
        # utiles, puis on tranche en Python sur de vraies dates.
        _plancher = (now - _td(days=1)).strftime("%Y-%m-%d")
        # N1B-1 : l'exclusion ne peut plus se faire sur le seul booleen — elle
        # depend desormais de la CLE du rappel. On remonte donc les candidats par
        # date, et on tranche en Python via `n1b_deja_envoye`. Le resultat est
        # identique a l'ancien filtre pour la cle historique.
        _candidates = await db.reservations.find({
            "datetime": {"$gte": _plancher}
        }, {"_id": 0}).to_list(2000)
        if len(_candidates) >= 2000:
            # Pas de troncature silencieuse.
            logger.warning("[REMINDER-V435] plafond de 2000 candidats atteint — couverture partielle")
        # RAPPELS V2 NIVEAU 1 : la configuration vit sur LE COURS, plus sur le
        # coach. Un cours est donc lu au plus UNE fois par passage, quel que
        # soit le nombre de reservations qui s'y rattachent.
        _cache_cours: dict = {}
        _lectures_cours = [0]

        async def _rv3_cours_de(_resa):
            """Le cours d'une reservation, mis en cache par passage."""
            _cid = str(_resa.get("courseId") or "").strip()
            if not _cid:
                return None
            if _cid in _cache_cours:
                return _cache_cours[_cid]
            _c = None
            try:
                _lectures_cours[0] += 1
                _c = await db.courses.find_one(
                    {"id": _cid},
                    {"_id": 0, "id": 1, "name": 1, "archived": 1,
                     "reminders_enabled": 1, "reminder_rules": 1})
            except Exception as _e:
                logger.warning("[RV3] cours %s illisible : %s", _cid, _e)
            _cache_cours[_cid] = _c
            return _c

        async def _rv3_regles_de(_resa):
            """Les regles de CE cours, ou [] s'il n'envoie pas de rappels.

            AUCUN repli sur une configuration globale du coach. Un cours qui n'a
            pas ete active explicitement n'envoie rien : le champ absent vaut
            NON, ce qui laisse tout le parc historique muet au deploiement, et
            rend la selection du coach reellement decisive.

            Active mais sans regle exploitable est traite pareil. On n'invente
            pas une regle, et on ne va pas en chercher une que le coach n'a pas
            vue a l'ecran : il verrait des rappels partir sans savoir d'ou.
            """
            _c = await _rv3_cours_de(_resa)
            if not _c:
                return []
            if _c.get("archived") is True:
                return []
            if _c.get("reminders_enabled") is not True:
                return []
            _regles = n1b2_valider_regles(_c.get("reminder_rules"))
            if not _regles:
                logger.warning(
                    "[RV3] cours %s actif mais sans regle exploitable — aucun rappel",
                    _c.get("id"))
                return []
            return _regles

        taches = []
        for _r in _candidates:
            _quand = _v435_instant_du_cours(_r.get("datetime"))
            # Un cours DEJA COMMENCE n'est jamais rattrape ; au-dela de l'horizon,
            # aucune regle ne peut encore se declencher.
            if not _quand or _quand <= now or _quand > _horizon:
                continue
            _regles_r = await _rv3_regles_de(_r)
            if not _regles_r:
                continue
            # N1B-3B2 : les cibles sont RECALCULEES pour cette occurrence reelle,
            # et les rappels rapproches sont ecartes AVANT toute autre decision.
            # Le calcul ne lit pas `reminders_sent` : il rend donc le meme verdict
            # a chaque passage, ce qui interdit tout rattrapage de la regle
            # absorbee — y compris si le rappel garde a echoue.
            _gardees, _absorbees = n1b3b2_plan(_regles_r, _quand, _zurich)
            for _cible, _cle in _gardees:
                # RAPPELS V2 : on n'ecarte la tache que si les DEUX canaux sont
                # deja partis. Un push reussi ne doit plus condamner l'e-mail.
                if all(rv2_deja_envoye(_r, _cle, _c) for _c in RV2_CANAUX):
                    continue
                # Borne BASSE exclue, borne haute incluse : sans cela, une cible
                # tombant pile sur la limite serait retenue par deux passages
                # consecutifs. Semi-ouverte, elle appartient a un seul creneau.
                if (_cible - _demi) < now <= (_cible + _demi):
                    taches.append((_r, _cle))
                    # La trace de l'absorption est accrochee a l'envoi REEL du
                    # rappel absorbant : une ligne par notification effectivement
                    # partie. Journaliser sur la seule fenetre de l'absorbee en
                    # produirait une a chaque passage du cron, pour chaque
                    # reservation future — un journal illisible.
                    for _ca, _cla, _cg, _clg in _absorbees:
                        if _clg != _cle:
                            continue
                        logger.info(
                            "[N1B-3B2] resa %s : rappel « %s » absorbe par « %s » — %d min "
                            "d'ecart, seuil %d min. Non envoye, et aucun rattrapage.",
                            _r.get("id"), _cla, _clg,
                            int((_ca - _cg).total_seconds() // 60), N1B3B2_ECART_MIN)
    except Exception as e:
        logger.error(f"[REMINDER-V183] erreur lecture résa: {e}")
        return {"checked": 0, "sent": 0, "error": str(e)}
    sent = 0
    _par_canal = {RV2_CANAL_PUSH: 0, RV2_CANAL_EMAIL: 0}
    # La couleur de marque est relue UNE fois pour tout le passage : un e-mail ne
    # lit pas les variables CSS, et rien ne justifie de refaire cette lecture a
    # chaque reservation.
    try:
        _accent = await _v259_primary_color()
    except Exception:
        _accent = _V259_DEFAULT_COLOR
    for r, _cle_regle in taches:
        email = (r.get("userEmail") or "").lower().strip()
        if not email:
            continue
        _rid = r.get("id")
        course_name = r.get("courseName") or r.get("offerName") or "ton cours"
        # L'heure affichee vient de `courseTime`, et de NULLE PART ailleurs.
        # `datetime` sert a DECLENCHER le rappel, jamais a l'afficher : sur une
        # partie du parc il porte l'horodatage de la RESERVATION, pas du cours.
        course_time = r.get("courseTime") or ""
        _prenom = (r.get("userName") or "").strip().split(" ")[0][:40]
        # La DATE, elle, vient de l'instant deja calcule pour declencher : c'est
        # la seule chose que le moteur tient pour vraie sur ce cours.
        _date_lisible = ""
        _instant = _v435_instant_du_cours(r.get("datetime"))
        if _instant:
            _date_lisible = rv2_date_lisible(_instant.astimezone(_zurich))
        # Un marqueur herite est une chaine : aucun sous-champ ne peut y etre
        # cree. On le convertit AVANT de reserver quoi que ce soit.
        try:
            await rv2_normaliser_marqueur(r, _cle_regle)
        except Exception as e:
            logger.warning(f"[RV2] résa {_rid} : marqueur non normalisé ({e})")
            continue
        for _canal in RV2_CANAUX:
            if rv2_deja_envoye(r, _cle_regle, _canal):
                continue
            if _canal == RV2_CANAL_EMAIL and not rv2_email_valide(email):
                continue
            try:
                if not await rv2_canal_autorise(email, _canal):
                    logger.debug(f"[RV2] rappel {_canal} désactivé pour {email}")
                    continue
                # Marquage AVANT envoi. Le filtre exige l'absence du champ :
                # deux crons simultanes ne peuvent pas gagner tous les deux, et
                # le perdant passe simplement son chemin.
                if not await rv2_reserver_canal(_rid, _cle_regle, _canal, now.isoformat()):
                    continue
            except Exception as e:
                logger.warning(f"[RV2] résa {_rid} canal {_canal} : {e}")
                continue
            ok = False
            try:
                if _canal == RV2_CANAL_PUSH:
                    ok = await send_push_by_email(
                        email,
                        n1b2_titre(_cle_regle),
                        n1b2_corps(_cle_regle, course_name, course_time),
                        {"type": "course_reminder", "reservation_id": _rid}
                    )
                else:
                    ok = await rv2_envoyer_email_rappel(
                        email, _prenom, course_name, _date_lisible, course_time, _accent)
            except Exception as e:
                logger.warning(f"[REMINDER-V183] résa {_rid} ({_canal}): {e}")
                ok = False
            if ok:
                sent += 1
                _par_canal[_canal] += 1
                # Le booleen historique continue d'etre ecrit a l'identique pour
                # le push de la cle d'origine : aucune lecture existante ne
                # change de resultat.
                if _canal == RV2_CANAL_PUSH and _cle_regle == N1B_CLE_HERITEE:
                    try:
                        await db.reservations.update_one(
                            {"id": _rid},
                            {"$set": {"reminder_sent": True,
                                      "reminder_sent_at": now.isoformat()}})
                    except Exception as e:
                        logger.warning(f"[RV2] résa {_rid} : booléen hérité non écrit ({e})")
            else:
                # Echec : on retire le marqueur pose juste avant. Le canal
                # redevient reessayable au passage suivant tant que la fenetre
                # du cours est ouverte — et l'AUTRE canal n'en sait rien.
                await rv2_liberer_canal(_rid, _cle_regle, _canal)
    logger.info(f"[REMINDER-V183] {sent}/{len(taches)} rappels envoyés "
                f"(push {_par_canal[RV2_CANAL_PUSH]}, email {_par_canal[RV2_CANAL_EMAIL]}) "
                f"— {_lectures_cours[0]} lecture(s) de cours pour {len(_candidates)} candidat(s)")
    return {"checked": len(taches), "sent": sent,
            "push": _par_canal[RV2_CANAL_PUSH], "email": _par_canal[RV2_CANAL_EMAIL]}


