# === v9.4.2: ENDPOINT CAMPAGNE MASSE (BACKGROUND TASK) ===
@api_router.post("/campaigns/send-bulk-email")
async def send_bulk_campaign_email(request: Request, background_tasks: BackgroundTasks):
    """
    Envoie des emails de campagne à plusieurs destinataires en tâche de fond.
    Garantit que l'interface ne soit jamais bloquée (asynchrone).
    v9.4.2: Chaque email est envoyé de manière indépendante.
    """
    body = await request.json()
    recipients = body.get("recipients", [])  # [{email, name}, ...]
    subject = body.get("subject", "Message d'Afroboost")
    message = body.get("message", "")
    media_url = body.get("media_url", None)
    coach_email = request.headers.get("X-User-Email", "").lower().strip()
    
    if not recipients:
        raise HTTPException(status_code=400, detail="Aucun destinataire")
    if not message:
        raise HTTPException(status_code=400, detail="Message requis")
    
    # Vérification des crédits pour tous les emails
    total_credits_needed = len(recipients)
    if coach_email and not is_super_admin(coach_email):
        credit_check = await check_credits(coach_email)
        current_credits = credit_check.get("credits", 0)
        if current_credits < total_credits_needed:
            raise HTTPException(
                status_code=402, 
                detail=f"Crédits insuffisants. Requis: {total_credits_needed}, Disponibles: {current_credits}"
            )
    
    # Fonction d'envoi en arrière-plan
    # V259: couleur de marque relue en base (un email ne lit pas les variables CSS)
    primary_color = await _v259_primary_color()
    primary_rgb = _v259_primary_rgb(primary_color)
    async def send_emails_background(recipients_list, subj, msg, media, coach):
        results = {"sent": 0, "failed": 0, "errors": []}
        for recipient in recipients_list:
            try:
                to_email = recipient.get("email")
                to_name = recipient.get("name", "")
                if not to_email:
                    continue
                
                # Personnaliser le message avec le prénom
                personalized_msg = msg.replace("{prénom}", to_name).replace("{prenom}", to_name)
                
                # Préparer l'email
                if not RESEND_AVAILABLE or not RESEND_API_KEY:
                    results["failed"] += 1
                    results["errors"].append(f"{to_email}: Resend non configuré")
                    continue
                
                # Construire le HTML (version simplifiée)
                html_content = f'''<!DOCTYPE html>
<html><head><meta charset="UTF-8"></head>
<body style="margin:0;padding:0;background:#0f0f0f;">
<table width="100%" cellpadding="0" cellspacing="0" border="0" style="background:#0f0f0f;">
<tr><td align="center" style="padding:20px;">
<table width="600" cellpadding="0" cellspacing="0" border="0" style="background:#1a1a1a;border-radius:12px;">
<tr><td style="padding:30px;">
<h1 style="color:{primary_color};margin:0;font-size:24px;">Afroboost</h1>
<p style="color:#ffffff;margin-top:20px;line-height:1.6;">{personalized_msg.replace(chr(10), '<br>')}</p>
</td></tr>
<tr><td style="padding:15px;border-top:1px solid #333;text-align:center;">
<a href="https://afroboost.com" style="color:#9333EA;font-size:12px;">afroboost.com</a>
</td></tr>
</table>
</td></tr>
</table>
</body></html>'''
                
                params = {
                    "from": "Afroboost <notifications@afroboost.com>",
                    "to": [to_email],
                    "subject": subj,
                    "html": html_content
                }
                
                await asyncio.to_thread(resend.Emails.send, params)
                results["sent"] += 1
                
                # Déduire le crédit
                if coach and not is_super_admin(coach):
                    await deduct_credit(coach, f"email campagne à {to_email}")
                
                # Petit délai entre les emails pour éviter le rate limiting
                await asyncio.sleep(0.2)
                
            except Exception as e:
                results["failed"] += 1
                results["errors"].append(f"{to_email}: {str(e)}")
                logger.error(f"Bulk email failed for {to_email}: {e}")
        
        logger.info(f"[BULK EMAIL] Terminé: {results['sent']} envoyés, {results['failed']} échoués")
        return results
    
    # Lancer en arrière-plan
    background_tasks.add_task(send_emails_background, recipients, subject, message, media_url, coach_email)
    
    return {
        "success": True,
        "message": f"Envoi de {len(recipients)} emails lancé en arrière-plan",
        "total_recipients": len(recipients),
        "status": "processing"
    }

@api_router.post("/push/send")
async def send_push_to_participant(request: Request):
    """
    Endpoint pour envoyer manuellement une notification push.
    
    Body attendu:
    {
        "participant_id": "xxx",
        "title": "Nouveau message",
        "body": "Vous avez une réponse...",
        "send_email_backup": true
    }
    """
    # === C17-K : AUTHENTIFICATION + AUTORISATION + ISOLATION ===
    # Cette route etait OUVERTE : n'importe qui pouvait viser un participant_id,
    # pousser du texte arbitraire, et — pire — declencher `send_backup_email`,
    # qui envoie un VRAI e-mail Resend aux couleurs d'Afroboost contenant le
    # texte de l'appelant. Il suffisait de viser quelqu'un sans abonnement push
    # actif pour forcer ce repli : c'etait un vecteur d'usurpation par e-mail.
    #
    # Aucun chemin interne ne passe par ici : les notifications backend
    # (C17-D new_lead, messages de chat, diffusions) appellent
    # `send_push_notification()` EN DIRECT. Fermer la route ne peut donc
    # regresser ni C17-D, ni V433 (tri), ni V434 (TTL).
    #
    # Deux appelants legitimes, et deux seulement :
    #   1. super-admin SIGNE  -> diagnostic complet, texte libre, e-mail possible
    #   2. abonne SIGNE       -> auto-test sur SON PROPRE participant uniquement,
    #                            texte impose par le serveur, jamais d'e-mail
    # Aucune branche « JWT coach » n'est ajoutee : le JWT coach est casse
    # (`[V319] identite coach REFUSEE` en boucle en production) et la reparer
    # n'appartient pas a ce lot.
    from api.routes.shared import super_admin_signe, subscriber_from_request, normaliser_email

    body = await request.json()
    participant_id = (body.get("participant_id") or "").strip()
    if not participant_id:
        raise HTTPException(status_code=400, detail="participant_id requis")

    _admin = super_admin_signe(request)
    if _admin:
        # Usage diagnostic : le super-admin garde la main complete.
        title = body.get("title", "Afroboost")
        message_body = body.get("body", "Vous avez un nouveau message")
        # V-defaut inverse : l'e-mail de secours ne part plus JAMAIS tout seul.
        send_email_backup = bool(body.get("send_email_backup", False))
    else:
        _abonne = subscriber_from_request(request)
        if not _abonne:
            logger.warning("[C17-K] /push/send refuse — aucune identite signee")
            raise HTTPException(status_code=403, detail="Authentification requise")
        # ISOLATION : l'abonne ne peut viser que SON propre participant. On ne
        # fait jamais confiance au participant_id fourni : on le RESOUT contre
        # l'e-mail prouve par le jeton signe.
        _email_jeton = normaliser_email(_abonne.get("email"))
        _p = await db.chat_participants.find_one({"id": participant_id}, {"_id": 0, "email": 1})
        if not _email_jeton or not _p or normaliser_email(_p.get("email")) != _email_jeton:
            logger.warning("[C17-K] /push/send refuse — le participant vise n'appartient pas a l'abonne")
            raise HTTPException(status_code=403, detail="Destinataire non autorise")
        # Texte IMPOSE : aucun contenu fourni par le client n'est relaye.
        title = "Afroboost"
        message_body = "Notifications activees. Tu es bien connecte."
        send_email_backup = False

    # Essayer d'envoyer la notification push
    push_sent = await send_push_notification(participant_id, title, message_body)
    
    email_sent = False
    if not push_sent and send_email_backup:
        # Planifier l'email de backup après 5 minutes
        # Pour l'instant, on l'envoie directement si push échoue
        email_sent = await send_backup_email(participant_id, message_body)
    
    return {
        "push_sent": push_sent,
        "email_sent": email_sent,
        "participant_id": participant_id
    }
# === v87: CRON ENDPOINT — Vérifie et lance les campagnes programmées ===
# v87: Helper pour parser scheduledAt (gère Z, +00:00, et naïf)
def _parse_scheduled_at(scheduled_at_str: str) -> datetime:
    """Parse un scheduledAt ISO string vers un datetime UTC aware."""
    if not scheduled_at_str:
        return None
    try:
        s = scheduled_at_str.strip()
        # Gérer le suffix Z (JavaScript toISOString())
        if s.endswith('Z'):
            s = s[:-1] + '+00:00'
        dt = datetime.fromisoformat(s)
        # Si naïf (pas de timezone), on assume UTC
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=timezone.utc)
        return dt
    except Exception:
        return None

@api_router.get("/whatsapp-diagnostic")
async def whatsapp_diagnostic():
    """V164.4: Diagnostic complet du setup WhatsApp Cloud API"""
    import httpx
    config = await _get_whatsapp_config()
    if not config or config["api_mode"] != "meta":
        return {"error": "Config Meta manquante"}

    access_token = config["access_token"]
    phone_number_id = config["phone_number_id"]
    api_version = config.get("api_version", "v21.0")

    results = {}

    async with httpx.AsyncClient(timeout=15.0) as client:
        # 1. Vérifier le statut du numéro de téléphone
        phone_url = f"https://graph.facebook.com/{api_version}/{phone_number_id}"
        phone_resp = await client.get(phone_url, params={
            "access_token": access_token,
            "fields": "display_phone_number,verified_name,quality_rating,platform_type,name_status,is_official_business_account,account_mode,messaging_limit_tier,status"
        })
        results["phone_number"] = phone_resp.json()

        # 2. Vérifier le WABA
        waba_id = "1615280896432370"
        waba_url = f"https://graph.facebook.com/{api_version}/{waba_id}"
        waba_resp = await client.get(waba_url, params={
            "access_token": access_token,
            "fields": "name,currency,message_template_namespace,account_review_status,business_verification_status,on_behalf_of_business_info"
        })
        results["waba"] = waba_resp.json()

        # 3. Vérifier le statut de l'app
        app_url = f"https://graph.facebook.com/{api_version}/1656270458951182"
        app_resp = await client.get(app_url, params={
            "access_token": access_token,
            "fields": "name,status,category"
        })
        results["app"] = app_resp.json()

        # 4. Vérifier les templates disponibles
        tpl_url = f"https://graph.facebook.com/{api_version}/{waba_id}/message_templates"
        tpl_resp = await client.get(tpl_url, params={
            "access_token": access_token,
            "fields": "name,status,language,category",
            "limit": 10
        })
        results["templates"] = tpl_resp.json()

    results["config_info"] = {
        "phone_number_id": phone_number_id,
        "api_version": api_version,
        "token_length": len(access_token),
        "token_prefix": access_token[:20] + "..."
    }

    return results


@api_router.get("/whatsapp-app-info")
async def whatsapp_app_info():
    """V377 — À QUELLE APP META appartient le jeton qui envoie les campagnes ?

    LECTURE SEULE, AUCUN message envoyé. Répond à une question qu'on ne peut pas
    trancher depuis le tableau de bord quand plusieurs apps portent le même nom :
    plusieurs « Afroboost Api » coexistent, la plupart en mode Développement, et un
    jeton issu d'une app en développement ne livre les TEMPLATES qu'aux numéros de
    test — ce qui expliquerait des campagnes acceptées par Meta mais jamais reçues.

    Le jeton n'est JAMAIS renvoyé : seuls son app_id, son type et sa validité.
    """
    import httpx
    config = await _get_whatsapp_config()
    if not config or config.get("api_mode") != "meta":
        return {"error": "Config Meta absente"}
    jeton = config["access_token"]
    version = config.get("api_version", "v21.0")
    phone_id = config.get("phone_number_id")
    resultats = {"phone_number_id": phone_id, "api_version": version}

    async with httpx.AsyncClient(timeout=20.0) as client:
        # 1) À quelle app ce jeton appartient-il ?
        r = await client.get(f"https://graph.facebook.com/{version}/debug_token",
                             params={"input_token": jeton, "access_token": jeton})
        brut = (r.json() or {}).get("data", {}) if r.status_code == 200 else r.json()
        resultats["jeton"] = {
            "app_id": brut.get("app_id"),
            "application": brut.get("application"),
            "type": brut.get("type"),
            "valide": brut.get("is_valid"),
            "expire_le": brut.get("expires_at"),
            "permissions": (brut.get("scopes") or [])[:12],
            "erreur": brut.get("error"),
        }
        # 2) À quel WABA ce numéro est-il rattaché ? (source : Meta, pas le code)
        r2 = await client.get(f"https://graph.facebook.com/{version}/{phone_id}",
                              params={"access_token": jeton,
                                      "fields": "id,display_phone_number,verified_name"})
        resultats["numero"] = r2.json()
        # 3) Les numéros que ce WABA déclare — confirme (ou non) le rattachement.
        waba = "1615280896432370"
        r3 = await client.get(f"https://graph.facebook.com/{version}/{waba}/phone_numbers",
                              params={"access_token": jeton,
                                      "fields": "id,display_phone_number,quality_rating"})
        resultats["waba_interroge"] = waba
        resultats["numeros_du_waba"] = r3.json()
        # 4) Les apps abonnées à ce WABA (celle qui reçoit les webhooks).
        r4 = await client.get(f"https://graph.facebook.com/{version}/{waba}/subscribed_apps",
                              params={"access_token": jeton})
        resultats["apps_abonnees"] = r4.json()

    return resultats


