# === V305 : GET /api/reservations/ended-for-review — ENDPOINT MANQUANT ===
# Le ChatWidget l'appelait (v107) mais il n'existait pas -> le catch-all SPA
# renvoyait index.html (HTML) -> `.json()` échouait en BOUCLE
# (« [V107] Check ended session failed: Unexpected token '<' »), participant au
# martèlement du serveur. Il renvoie désormais un JSON VALIDE. Logique minimale et
# sûre : on cherche une réservation de cet abonné dont l'occurrence est passée
# récemment (dernières 6 h). En cas de doute -> has_ended_session:false (jamais
# d'erreur, jamais de fausse sollicitation d'avis).
@api_router.get("/reservations/ended-for-review")
async def reservations_ended_for_review(request: Request):
    email = (request.query_params.get("email", "") or "").strip().lower()
    code = (request.query_params.get("code", "") or "").strip().upper()
    # V305 (sécu) : ANTI-ÉNUMÉRATION. On ne renseigne l'appelant que s'il PROUVE son
    # droit — code abonné VALIDE (le secret, modèle « capability » du site) OU identité
    # coach/admin. Sinon réponse neutre {has_ended_session:false} (JSON valide, aucune
    # fuite, pas de boucle). Empêche de sonder un email sans posséder de code valide.
    _authorized = False
    _coach_id = await _v263_authenticated_coach(request)
    if _coach_id:
        _authorized = True
    elif code:
        _ok, _n, _cid = await _v261_resolve_subscriber(code)
        _authorized = bool(_ok)
    if not _authorized:
        return {"has_ended_session": False, "session_name": None}
    if not email and not code:
        return {"has_ended_session": False, "session_name": None}
    try:
        import re
        now = datetime.now(timezone.utc)
        window_start = (now - timedelta(hours=6)).isoformat()
        q = {"$or": []}
        if email:
            q["$or"].append({"userEmail": {"$regex": f"^{re.escape(email)}$", "$options": "i"}})
        if code:
            q["$or"].append({"promoCode": code})
        if not q["$or"]:
            return {"has_ended_session": False, "session_name": None}
        # Réservation récente (datetime dans les 6 dernières heures) = séance passée.
        resa = await db.reservations.find_one(
            {"$and": [q, {"datetime": {"$gte": window_start, "$lte": now.isoformat()}}]},
            {"_id": 0, "courseName": 1, "offerName": 1},
            sort=[("datetime", -1)],
        )
        if resa:
            return {"has_ended_session": True, "session_name": resa.get("courseName") or resa.get("offerName") or "votre séance"}
    except Exception as e:
        logger.warning(f"[V305] ended-for-review ignoré: {e}")
    return {"has_ended_session": False, "session_name": None}


# === v88: POST /api/reviews/request — Coach envoie manuellement une demande d'avis ===
@api_router.post("/reviews/request")
async def send_review_request(request: Request):
    """V88: Le coach envoie manuellement une demande d'avis aux participants d'un cours."""
    body = await request.json()
    coach_email = (body.get("coach_email", "") or "").strip().lower()
    course_id = (body.get("course_id", "") or "").strip()
    course_name = (body.get("course_name", "") or "").strip()

    if not coach_email:
        raise HTTPException(status_code=400, detail="coach_email requis")

    # Trouver les abonnés actifs du coach
    now = datetime.now(timezone.utc)
    subscribers = await db.users.find({
        "coach_id": coach_email,
        "subscription.end_date": {"$gte": now.isoformat()}
    }).to_list(200)

    sent_count = 0
    for sub in subscribers:
        code = sub.get("code", "")
        name = sub.get("name", sub.get("first_name", ""))
        if not code:
            continue
        # Ne pas envoyer si déjà un avis
        existing = await db.comments.find_one({"participant_code": code, "is_review": True, "coach_id": coach_email})
        if existing:
            continue
        # Envoyer un message review_request dans le chat
        msg = {
            "id": f"review_req_{now.strftime('%Y%m%d%H%M%S')}_{_random.randint(100,999)}_{code}",
            "session_id": f"{coach_email}__{code}",
            "sender": "bot",
            "sender_name": "Afroboost",
            "text": f"🔥 Bravo pour ta session {course_name or 'Afroboost'} {name} ! Comment as-tu trouvé le cours ?",
            "type": "review_request",
            "timestamp": now.isoformat(),
            "read": False
        }
        await db.messages.insert_one(msg)
        sent_count += 1

    logger.info(f"[V88] Demande d'avis manuelle envoyée à {sent_count} abonnés par {coach_email}")
    return {"success": True, "sent_count": sent_count}

