# === v9.2.7: PARAMÈTRES GLOBAUX PLATEFORME (Super Admin Only) ===

# v9.5.6: Utilise la fonction is_super_admin() pour la vérification

@api_router.get("/platform-settings")
async def get_platform_settings(request: Request):
    """Récupérer les paramètres globaux de la plateforme"""
    user_email = request.headers.get('X-User-Email', '').lower()
    is_admin = is_super_admin(user_email)  # v9.5.6
    
    # Récupérer ou créer les settings
    settings = await db.platform_settings.find_one({"_id": "global"})
    if not settings:
        settings = {
            "_id": "global",
            "partner_access_enabled": True,  # Accès partenaires activé par défaut
            "maintenance_mode": False,       # Mode maintenance désactivé par défaut
            # v12.1: Prix des services en crédits (configurables par Super Admin)
            "service_prices": {
                "campaign": 1,       # Coût d'une campagne
                "ai_conversation": 1, # Coût d'une conversation IA
                "promo_code": 1       # Coût de génération d'un code promo
            },
            "updated_at": datetime.now(timezone.utc).isoformat(),
            "updated_by": user_email
        }
        await db.platform_settings.insert_one(settings)
    
    # v12.1: Assurer que service_prices existe
    service_prices = settings.get("service_prices", {
        "campaign": 1,
        "ai_conversation": 1,
        "promo_code": 1
    })
    
    return {
        "partner_access_enabled": settings.get("partner_access_enabled", True),
        "maintenance_mode": settings.get("maintenance_mode", False),
        "service_prices": service_prices,  # v12.1
        "is_super_admin": is_admin,
        "updated_at": settings.get("updated_at"),
        "updated_by": settings.get("updated_by")
    }

@api_router.put("/platform-settings")
async def update_platform_settings(request: Request):
    """Mettre à jour les paramètres globaux (Super Admin uniquement)"""
    # V262: identite verifiee AVANT le controle super admin — sans quoi le
    # controle portait sur une valeur que l'appelant choisissait lui-meme.
    user_email = require_auth(request).lower()
    
    # Vérification Super Admin v9.5.6
    if not is_super_admin(user_email):
        raise HTTPException(status_code=403, detail="Accès réservé au Super Admin")
    
    try:
        data = await request.json()
    except:
        raise HTTPException(status_code=400, detail="Format JSON invalide")
    
    update_fields = {
        "updated_at": datetime.now(timezone.utc).isoformat(),
        "updated_by": user_email
    }
    
    # Mise à jour des toggles
    if "partner_access_enabled" in data:
        update_fields["partner_access_enabled"] = bool(data["partner_access_enabled"])
    if "maintenance_mode" in data:
        update_fields["maintenance_mode"] = bool(data["maintenance_mode"])
    
    # Staff access code
    if "staff_access_code" in data:
        update_fields["staff_access_code"] = str(data["staff_access_code"]).strip()

    # v12.1: Mise à jour des prix des services
    if "service_prices" in data:
        service_prices = data["service_prices"]
        update_fields["service_prices"] = {
            "campaign": max(0, int(service_prices.get("campaign", 1))),
            "ai_conversation": max(0, int(service_prices.get("ai_conversation", 1))),
            "promo_code": max(0, int(service_prices.get("promo_code", 1)))
        }
        logger.info(f"[PLATFORM-SETTINGS] Service prices updated: {update_fields['service_prices']}")
    
    # Upsert settings
    result = await db.platform_settings.update_one(
        {"_id": "global"},
        {"$set": update_fields},
        upsert=True
    )
    
    # Récupérer les settings mis à jour
    settings = await db.platform_settings.find_one({"_id": "global"})
    
    logger.info(f"[PLATFORM-SETTINGS] Updated by {user_email}: {update_fields}")
    
    return {
        "success": True,
        "partner_access_enabled": settings.get("partner_access_enabled", True),
        "maintenance_mode": settings.get("maintenance_mode", False),
        "service_prices": settings.get("service_prices", {"campaign": 1, "ai_conversation": 1, "promo_code": 1}),
        "updated_at": settings.get("updated_at"),
        "message": "Paramètres mis à jour"
    }

# === v162m: DASHBOARD — Toutes les transactions (reservations + souscriptions + achats) ===
@api_router.get("/dashboard/all-transactions")
async def get_all_transactions(request: Request, page: int = 1, limit: int = 50):
    """Retourne toutes les transactions: reservations, souscriptions Stripe, achats produits"""
    # V311i — GROUPE 2 : JWT-strict. Les données FINANCIÈRES ne sont plus accessibles
    # que via un JWT SIGNÉ (X-User-Email, usurpable, n'accorde plus aucun droit).
    # Le propriétaire a un jeton signé (badge vert) -> l'intercepteur l'envoie sur
    # cet appel -> sa vue financière reste complète (super-admin = tout).
    caller_email = _v311_coach_email_from_jwt(request)
    if not caller_email or not await _v309_is_coach_or_admin(caller_email):
        raise HTTPException(status_code=403, detail="Authentification coach requise — reconnectez-vous")

    all_items = []

    # 1. Reservations (from reservations collection)
    res_query = {} if is_super_admin(caller_email) else {"coach_id": caller_email} if caller_email else {"coach_id": "__no_access__"}
    reservations = await db.reservations.find(res_query, {"_id": 0}).sort("createdAt", -1).to_list(200)
    for r in reservations:
        r["_tx_type"] = "reservation"
        r["_tx_date"] = r.get("createdAt", "")
        r["_tx_name"] = r.get("userName", "Inconnu")
        r["_tx_email"] = r.get("userEmail", "")
        r["_tx_offer"] = r.get("courseName") or r.get("offerName", "")
        r["_tx_price"] = r.get("totalPrice", 0)
        r["_tx_status"] = "valid\u00e9" if r.get("validated") else "en attente"
        all_items.append(r)

    # 2. Subscriptions (from subscriptions collection — Stripe auto-created)
    # V237: isolation. Les souscriptions et les paiements etaient jusqu'ici
    # renvoyes SANS filtre, alors que les reservations juste au-dessus etaient
    # deja isolees — chaque coach voyait donc les abonnes et les paiements de
    # tous les autres.
    #
    # `coach_id: {$exists: False}` est inclus dans le filtre coach : les
    # documents anterieurs a V237 n'ont pas encore ete migres, et les exclure
    # ferait DISPARAITRE d'un coup l'historique de chaque coach. Une fois
    # /admin/migrate-subscriptions-coach-id passe, ce cas ne se presente plus.
    if is_super_admin(caller_email):
        sub_query = {}
        pay_query = {"payment_status": "paid"}
    elif caller_email:
        _legacy_or = [{"coach_id": caller_email}, {"coach_id": {"$exists": False}}]
        sub_query = {"$or": _legacy_or}
        pay_query = {"payment_status": "paid", "$or": _legacy_or}
    else:
        sub_query = {"id": "__no_access__"}
        pay_query = {"id": "__no_access__"}

    subscriptions = await db.subscriptions.find(sub_query, {"_id": 0}).sort("created_at", -1).to_list(200)
    for s in subscriptions:
        # Avoid duplicates: skip if a reservation already exists with this subscription ID
        sub_id = s.get("id", "")
        already_in_reservations = any(
            ri.get("subscriptionId") == sub_id for ri in reservations
        )
        s["_tx_type"] = "subscription"
        s["_tx_date"] = s.get("created_at", "")
        s["_tx_name"] = s.get("name", "Inconnu")
        s["_tx_email"] = s.get("email", "")
        s["_tx_offer"] = s.get("offer_name", "")
        s["_tx_price"] = 0
        s["_tx_status"] = s.get("status", "active")
        s["_tx_sessions"] = f"{s.get('remaining_sessions', 0)}/{s.get('total_sessions', 0)}"
        s["_tx_code"] = s.get("code", "")
        # V236: champs NUMERIQUES pour la barre de progression et les boutons
        # +/-. `_tx_sessions` reste une chaine ("7/10") et n'est pas touche —
        # l'affichage existant s'en sert tel quel. Une comparaison numerique sur
        # cette chaine serait toujours fausse, d'ou ces trois champs distincts.
        try:
            s["_tx_remaining"] = int(s.get("remaining_sessions") or 0)
        except (TypeError, ValueError):
            s["_tx_remaining"] = 0
        try:
            s["_tx_total"] = int(s.get("total_sessions") or 0)
        except (TypeError, ValueError):
            s["_tx_total"] = 0
        s["_tx_sub_id"] = sub_id
        if not already_in_reservations:
            all_items.append(s)

    # 3. Payment transactions (completed Stripe payments)
    payments = await db.payment_transactions.find(
        pay_query,  # V237: isole par coach_id (voir le commentaire ci-dessus)
        {"_id": 0}
    ).sort("created_at", -1).to_list(200)
    for p in payments:
        # Only add if not already represented by a subscription or reservation
        session_id = p.get("session_id", "")
        meta = p.get("metadata", {})
        p["_tx_type"] = "payment"
        p["_tx_date"] = p.get("created_at", "")
        p["_tx_name"] = meta.get("customer_name", "Client")
        p["_tx_email"] = meta.get("customer_email", "")
        p["_tx_offer"] = meta.get("product_name", "Paiement Stripe")
        p["_tx_price"] = (p.get("amount_total", 0) or 0) / 100
        p["_tx_status"] = "pay\u00e9"
        all_items.append(p)

    # Sort all by date descending
    def sort_key(item):
        d = item.get("_tx_date", "")
        if isinstance(d, str):
            return d
        try:
            return d.isoformat()
        except:
            return ""

    all_items.sort(key=sort_key, reverse=True)

    # Paginate
    total = len(all_items)
    start = (page - 1) * limit
    page_items = all_items[start:start + limit]

    return {
        "data": page_items,
        "pagination": {
            "page": page,
            "limit": limit,
            "total": total,
            "pages": (total + limit - 1) // limit
        },
        "counts": {
            "reservations": len(reservations),
            "subscriptions": len(subscriptions),
            "payments": len(payments)
        }
    }

# === COACH PROFILE: Photo + Date de naissance ===
@api_router.get("/coach-profile")
async def get_coach_profile(request: Request):
    """Récupère le profil du coach (photo, date de naissance)"""
    email = request.headers.get("X-User-Email", "").lower().strip()
    if not email:
        return {"photo_url": "", "birthday": "", "display_name": ""}
    profile = await db.coach_profiles.find_one({"email": email}, {"_id": 0})
    if not profile:
        return {"email": email, "photo_url": "", "birthday": "", "display_name": ""}
    return profile

@api_router.put("/coach-profile")
async def update_coach_profile(request: Request):
    """Met à jour le profil du coach (photo_url, birthday, display_name)"""
    email = request.headers.get("X-User-Email", "").lower().strip()
    if not email:
        raise HTTPException(status_code=401, detail="Email requis")
    data = await request.json()
    update = {"email": email, "updated_at": datetime.now(timezone.utc).isoformat()}
    if "photo_url" in data:
        update["photo_url"] = data["photo_url"]
    if "birthday" in data:
        update["birthday"] = data["birthday"]
    if "display_name" in data:
        update["display_name"] = data["display_name"]
    # V294 : préférences coach synchronisées PC/mobile (source de vérité backend).
    # Merge CLÉ PAR CLÉ (chemin pointé) -> une mise à jour partielle n'écrase jamais
    # les autres préférences déjà stockées (son, silence auto, langue de traduction…).
    if isinstance(data.get("preferences"), dict):
        for k, v in data["preferences"].items():
            update["preferences." + str(k)] = v
    await db.coach_profiles.update_one({"email": email}, {"$set": update}, upsert=True)
    # V289 : refléter la photo dans db.users SI un doc existe déjà (upsert=False
    # pour NE PAS recréer de doc fantôme sans name — cf. fix 500 /users). La
    # recherche photo des publications interroge de toute façon coach_profiles.
    if "photo_url" in update:
        await db.users.update_one(
            {"email": email},
            {"$set": {"photo_url": update["photo_url"], "photoUrl": update["photo_url"]}},
            upsert=False
        )
    profile = await db.coach_profiles.find_one({"email": email}, {"_id": 0})
    return {"success": True, "profile": profile}


# === V294 : infos abonné persistées au BACKEND (source de vérité PC/mobile) ===
# Le localStorage du navigateur est PAR APPAREIL et volatile : whatsapp / date de
# naissance étaient « redemandés » à chaque nouvel appareil ou vidage de cache.
# Ces deux endpoints font du backend la source de vérité, indexée par le CODE
# abonné (tous formats acceptés depuis V293, cf. _v261_resolve_subscriber).
@api_router.get("/subscriber-info/{code}")
async def v294_get_subscriber_info(code: str):
    """V294 : renvoie { exists, name, whatsapp, email, birthday } pour un code abonné.

    Le code EST déjà le justificatif d'accès de l'abonné (comme /subscriber/{code}),
    donc pas d'auth supplémentaire. Si aucune info n'a encore été enregistrée, on
    tente au moins de renvoyer le nom connu via l'abonnement (jamais redemandé).
    """
    code_norm = (code or "").strip().upper()
    if not code_norm or len(code_norm) < 3:
        return {"exists": False, "name": "", "whatsapp": "", "email": "", "birthday": ""}
    doc = await db.subscriber_infos.find_one({"code": code_norm}, {"_id": 0})
    if doc:
        return {
            "exists": True,
            "name": doc.get("name", ""),
            "whatsapp": doc.get("whatsapp", ""),
            "email": doc.get("email", ""),
            "birthday": doc.get("birthday", ""),
        }
    # Repli : nom déjà connu via l'abonnement actif (le formulaire pré-remplit le nom)
    ok, name, _cid = await _v261_resolve_subscriber(code_norm)
    return {"exists": bool(ok), "name": (name or "") if ok else "", "whatsapp": "", "email": "", "birthday": ""}


@api_router.put("/subscriber-info/{code}")
async def v294_put_subscriber_info(code: str, request: Request):
    """V294 : enregistre les infos d'un abonné { name, whatsapp, email, birthday }.

    Le code doit correspondre à un abonnement ACTIF (via _v261_resolve_subscriber,
    V293 — tous formats de codes clients). Champs AJOUTÉS uniquement : on ne pose un
    champ QUE s'il est fourni ET non vide, donc jamais d'écrasement par du vide.
    """
    code_norm = (code or "").strip().upper()
    ok, _name, coach_id = await _v261_resolve_subscriber(code_norm)
    if not ok:
        raise HTTPException(status_code=403, detail="Code abonné invalide ou inactif")
    data = await request.json()
    update = {
        "code": code_norm,
        "coach_id": coach_id or DEFAULT_COACH_ID,
        "updated_at": datetime.now(timezone.utc).isoformat(),
    }
    for field in ("name", "whatsapp", "email", "birthday"):
        raw = data.get(field)
        val = raw.strip() if isinstance(raw, str) else raw
        if val:
            update[field] = val
    await db.subscriber_infos.update_one({"code": code_norm}, {"$set": update}, upsert=True)
    doc = await db.subscriber_infos.find_one({"code": code_norm}, {"_id": 0})
    return {"success": True, "info": doc}


# === V296 : JETON D'APPAREIL ABONNÉ (connexion rapide ET sécurisée) ===
# L'abonné entre son code UNE fois par appareil : on lui rend un jeton signé
# (type "subscriber") qui prouve ensuite qu'il détient un code valide, sans avoir
# à réexposer le code. Sert aussi à l'échange SILENCIEUX pour les appareils déjà
# connectés (leur code localStorage -> jeton, sans que l'abonné refasse quoi que
# ce soit). Si JWT_SECRET n'est pas posé, `token` est vide et tous les chemins
# existants continuent tels quels (aucune régression).
@api_router.post("/subscriber/token")
async def v296_subscriber_token(request: Request):
    """Délivre un jeton d'appareil pour un abonné dont le CODE est valide et actif.

    Le code est lu dans le CORPS (POST), pas en query string, pour ne pas finir
    dans les journaux/Referer.

    V390 — PRISE DE COMPTE (3e porte, la plus grave). L'e-mail était traité comme
    « un simple attribut du jeton », NON VÉRIFIÉ. On signait donc n'importe quel
    couple (code valide, e-mail arbitraire). Or `/chat/smart-entry` fait ensuite
    confiance à `token.email` pour accorder l'accès (`_may_write`). Conséquence,
    prouvée en production le 7 août 2026 : **tout abonné légitime pouvait entrer
    chez n'importe quel autre** en présentant SON PROPRE code avec l'ADRESSE de sa
    victime — il lui suffisait de connaître son e-mail.
        POST /subscriber/token {code: <son code à lui>, email: <victime>} -> 200
        POST /chat/smart-entry  + ce jeton                                -> COMPTE OUVERT
    Le « modèle capability » ne tenait plus dès lors que le jeton portait une
    IDENTITÉ : une capacité ne doit jamais désigner quelqu'un d'autre que soi.

    Le code et l'e-mail doivent désormais désigner LA MÊME personne : si le code
    porte un `assignedEmail`, il doit correspondre. Même règle que
    `/discount-codes/validate` (« Code réservé à un autre compte »), qui, lui,
    faisait déjà cette vérification — d'où l'incohérence."""
    try:
        body = await request.json()
    except Exception:
        body = {}
    code = (body.get("code") or "").strip().upper()
    email = (body.get("email") or "").strip().lower()
    ok, name, _cid = await _v261_resolve_subscriber(code)
    if not ok:
        raise HTTPException(status_code=403, detail="Code abonné invalide ou inactif")

    # V390 : le code doit APPARTENIR à l'e-mail demandé. Un code non assigné
    # (`assignedEmail` vide) reste utilisable tel quel — c'est le cas des codes
    # collectifs, et il n'ouvre alors le compte de personne en particulier.
    # C9-B : `_c9b_appariement` ne devient vrai que si le contrôle ci-dessous a
    # REELLEMENT tourné ET conclu positivement. C'est la seule condition qui
    # autorisera un pseudonyme analytique. Volontairement initialisé a False :
    # les trois cas ambigus (code absent de `discount_codes`, e-mail vide, code
    # collectif sans `assignedEmail`) le laissent faux et n'identifient personne.
    _c9b_appariement = False
    if email:
        _dc = await db.discount_codes.find_one(
            {"code": {"$regex": f"^{re.escape(code)}$", "$options": "i"}},
            # C9-B : `active` est ajoute a la PROJECTION seulement. Le refus V390
            # ci-dessous garde exactement le meme comportement ; c'est uniquement
            # la PERMISSION d'identifier qui exigera un document actif.
            {"_id": 0, "assignedEmail": 1, "active": 1},
        )
        _assigne = ((_dc or {}).get("assignedEmail") or "").strip().lower()
        if _assigne and _assigne != email:
            logger.warning(
                f"[V390] Jeton REFUSE : code {code} assigne a {_assigne}, demande pour {email}"
            )
            raise HTTPException(status_code=403, detail="Code réservé à un autre compte")
        # Le document doit etre ACTIF. Un meme code peut porter plusieurs
        # documents en base (constate en production), et `find_one` en rend un
        # sans tri : sans ce filtre, l'appariement pourrait s'appuyer sur une
        # vieille ligne desactivee. Pour un verdict irreversible, on exige que la
        # ligne lue soit celle qui vaut encore.
        _c9b_appariement = (bool(_assigne) and _assigne == email
                            and (_dc or {}).get("active") is True)
    from api.routes.shared import make_subscriber_token, jwt_secret_is_set
    token = make_subscriber_token(code, email)

    # === C9-B : PSEUDONYME ANALYTIQUE, ET RIEN D'AUTRE ===
    #
    # POURQUOI ICI, ET PAS EN FIN DE TUNNEL. L'e-mail saisi au tunnel n'est
    # jamais verifie — pas meme un `@`. Identifier dessus ferait qu'une faute de
    # frappe cree une personne fantome captant tout l'historique anonyme, et une
    # fusion PostHog est IRREVERSIBLE. Ici, l'appelant a du presenter un code
    # individuel dont la base atteste qu'il appartient a cette adresse.
    #
    # CE QUE CELA PROUVE, EXACTEMENT : la possession d'un code individuel apparie
    # a cet e-mail. PAS le controle de la boite (le code circule, ne tourne pas,
    # n'expire pas, et `/subscriber-info/{code}` livre l'adresse a qui le detient).
    # Compromis assume — cf. le bilan C9-B.
    #
    # `analytics_id` est un sha256 sale tronque : non reversible, et le sel ne
    # quitte JAMAIS le serveur. Le navigateur ne recalcule rien, il recoit.
    # C'est strictement moins revelateur que ce que cette reponse contient deja
    # (`name`) et que le JWT ci-dessus, qui porte l'e-mail en clair.
    #
    # LE PROPRIETAIRE N'ENTRE JAMAIS DANS SON PROPRE ENTONNOIR. Le navigateur
    # ecarte deja les sessions coach, mais cette liste-la vit cote CLIENT et peut
    # etre contournee (localStorage vide, navigateur neuf). Le refus est donc pose
    # ICI aussi : c'est le serveur qui tranche, comme partout ailleurs dans ce
    # dépôt. Sans lui, l'historique du dashboard fusionnerait dans une fiche
    # client au premier test du parcours abonne par Bassi.
    _c9b_id = ""
    try:
        if _c9b_appariement and not is_super_admin(email) \
                and (await get_feature_flags()).get("POSTHOG_IDENTIFY_ENABLED"):
            from api.routes.shared import posthog_id as _c9b_pseudo
            _c9b_id = _c9b_pseudo(email)
    except Exception as _c9be:
        # Jamais bloquant : la mesure ne doit pas empecher un abonne d'entrer.
        logger.warning(f"[C9-B] pseudonyme ignore: {type(_c9be).__name__}")
        _c9b_id = ""
    # secret absent -> token '' : le frontend garde le chemin actuel, rien ne casse.
    return {"success": True, "token": token, "name": name,
            "secret_set": jwt_secret_is_set(), "analytics_id": _c9b_id}


# === STAFF ACCESS: Code d'accès pour scanner uniquement ===
@api_router.post("/staff/login")
async def staff_login(request: Request):
    """Connexion staff avec un code d'accès simple (pas d'accès chat/réglages)"""
    data = await request.json()
    code = data.get("code", "").strip()
    if not code:
        raise HTTPException(status_code=400, detail="Code requis")
    # Vérifier le code staff dans platform_settings
    settings = await db.platform_settings.find_one({"_id": "global"}, {"_id": 0})
    staff_code = (settings or {}).get("staff_access_code", "")
    if not staff_code or code != staff_code:
        raise HTTPException(status_code=403, detail="Code invalide")
    return {"success": True, "role": "staff", "permissions": ["scan_qr", "view_reservations"]}


@api_router.post("/staff/forgot-code")
async def forgot_staff_code(request: Request):
    """V256 / V257: renvoie le code staff par email au coach qui le demande.

    PERIMETRE D'ACCES — V257 l'ELARGIT a tout compte coach enregistre
    (`coaches`, avec repli sur `coach_auth`), la V256 le reservant au Super
    Admin. Consequence a connaitre : le code staff est unique a toute la
    plateforme, donc chaque coach partenaire peut desormais l'obtenir, alors que
    seul le Super Admin peut le CHANGER (PUT /platform-settings). Le risque
    reste contenu — ce code ne fait que basculer une session DEJA authentifiee
    entre mode complet et mode restreint, il n'ouvre aucun compte — mais la
    lecture n'est plus alignee sur l'ecriture.

    DESTINATAIRE — jamais une adresse fournie par la requete. L'envoi part vers
    l'email IDENTIFIE, qui vient d'etre retrouve en base. Le header
    X-User-Email etant falsifiable, c'est ce qui empeche un tiers de se faire
    livrer le code : au pire il declenche un envoi vers la boite du coach
    legitime, qui est aussi son signal d'alerte.

    Le corps de la requete n'est pas lu : il n'y a rien a y mettre.
    """
    email = request.headers.get("X-User-Email", "").lower().strip() or _email_from_jwt(request)
    if not email:
        raise HTTPException(status_code=401, detail="Authentification requise")
    # V257: Super Admin, OU coach enregistre (`coaches` puis repli `coach_auth`,
    # les deux collections ne sont pas toujours peuplees ensemble).
    if not is_super_admin(email):
        known = await db.coaches.find_one({"email": email}, {"_id": 0, "email": 1})
        if not known:
            known = await db.coach_auth.find_one({"email": email}, {"_id": 0, "email": 1})
        if not known:
            # V257b: derniere collection d'authentification possible. Une
            # collection absente renvoie simplement None, sans erreur.
            known = await db.users_auth.find_one({"email": email}, {"_id": 0, "email": 1})
        if not known:
            raise HTTPException(status_code=403, detail="Accès refusé")

    settings = await db.platform_settings.find_one({"_id": "global"}, {"_id": 0})
    staff_code = ((settings or {}).get("staff_access_code") or "").strip()
    if not staff_code:
        raise HTTPException(status_code=404, detail="Aucun code staff n'est configuré")

    if not (RESEND_AVAILABLE and RESEND_API_KEY):
        logger.error("[V256] Envoi du code staff impossible : Resend non configure")
        raise HTTPException(status_code=503, detail="Service d'email indisponible")

    # V257: charte Afroboost — fond sombre, accent #D91CD2.
    # V259: couleur de marque relue en base (un email ne lit pas les variables CSS)
    primary_color = await _v259_primary_color()
    primary_rgb = _v259_primary_rgb(primary_color)
    html = f"""
    <div style="font-family:Arial,sans-serif;max-width:420px;margin:0 auto;padding:24px;background:#0a0a1a;border-radius:12px;">
        <h2 style="color:{primary_color};text-align:center;margin:0 0 12px;">Code Staff Afroboost</h2>
        <p style="color:#ccc;font-size:14px;text-align:center;">Voici le code staff actuellement actif :</p>
        <div style="background:#1a1a2e;color:#fff;padding:20px;border-radius:8px;text-align:center;font-size:28px;font-weight:bold;letter-spacing:6px;margin:20px 0;border:1px solid {primary_color};">
            {staff_code}
        </div>
        <p style="color:#888;font-size:12px;text-align:center;">Ce code donne accès aux réservations et au scanner QR. Ne le partagez qu'avec votre équipe sur place.</p>
        <p style="color:#666;font-size:12px;text-align:center;">Si vous n'êtes pas à l'origine de cette demande, ignorez cet email.</p>
    </div>
    """
    try:
        await asyncio.to_thread(resend.Emails.send, {
            "from": "Afroboost <notifications@afroboost.com>",
            "to": [email],
            "subject": "Votre code Staff Afroboost",
            "html": html
        })
    except Exception as e:
        # Le code NE DOIT PAS repartir dans la reponse HTTP en cas d'echec :
        # l'email est le seul canal, c'est ce qui garantit que seul le
        # proprietaire de la boite le lit.
        logger.error(f"[V256] Erreur envoi code staff a {email}: {e}")
        raise HTTPException(status_code=500, detail="L'email n'a pas pu être envoyé")

    logger.info(f"[V256] Code staff renvoye par email a {email}")
    return {"status": "ok", "message": "Code envoyé par email"}

