async def _v197b_seed_quick_replies_if_empty():
    """V197b: Insère les réponses par défaut si la collection est vide."""
    try:
        count = await db.bot_quick_replies.count_documents({})
        if count > 0:
            return 0
        now = datetime.utcnow().isoformat()
        docs = []
        for r in V197B_DEFAULT_QUICK_REPLIES:
            docs.append({**r, "updated_at": now, "updated_by": "seed"})
        await db.bot_quick_replies.insert_many(docs)
        return len(docs)
    except Exception as e:
        logger.warning(f"[V197b] seed quick replies failed: {e}")
        return 0


# V305 : icône SVG d'un chip déduite de l'id (puis mots-clés du label). JAMAIS d'emoji.
_V305_QR_ICON_BY_ID = {
    "cours_horaires": "calendar", "prix_abonnements": "price", "essai_gratuit": "gift",
    "contact": "phone", "devenir_coach": "coach", "devenir_partenaire": "handshake",
}


def _v305_qr_icon(reply: dict) -> str:
    if reply.get("icon"):
        return reply["icon"]
    rid = reply.get("id", "")
    if rid in _V305_QR_ICON_BY_ID:
        return _V305_QR_ICON_BY_ID[rid]
    lbl = (reply.get("label", "") or "").lower()
    if any(k in lbl for k in ["cours", "horaire", "planning", "agenda", "séance", "seance"]):
        return "calendar"
    if any(k in lbl for k in ["prix", "tarif", "abonnement", "payer"]):
        return "price"
    if any(k in lbl for k in ["essai", "gratuit", "découvrir", "decouvrir"]):
        return "gift"
    if any(k in lbl for k in ["contact", "joindre", "appeler", "whatsapp"]):
        return "phone"
    if "coach" in lbl or "formation" in lbl:
        return "coach"
    if "partenaire" in lbl or "partner" in lbl:
        return "handshake"
    return "help"


@api_router.get("/bot/quick-replies")
async def v197b_get_quick_replies():
    """V197b: Liste publique des quick replies actifs (chargés par le ChatWidget)."""
    # Auto-seed à la première requête (au cas où le startup ne s'est pas exécuté)
    await _v197b_seed_quick_replies_if_empty()
    replies = await db.bot_quick_replies.find(
        {"active": True}, {"_id": 0}
    ).sort("order", 1).to_list(None)
    # V305 : garantir un champ `icon` (SVG) sur CHAQUE chip -> plus d'emoji côté UI.
    for r in replies:
        r["icon"] = _v305_qr_icon(r)
    return replies


@api_router.post("/v305-fix-quickreply-icons")
async def v305_fix_quickreply_icons():
    """V305 : migration idempotente — écrit un champ `icon` (déduit de l'id/label) sur
    tous les documents bot_quick_replies qui n'en ont pas. Publique et sans entrée
    (enrichissement, aucune donnée supprimée)."""
    await _v197b_seed_quick_replies_if_empty()
    docs = await db.bot_quick_replies.find({}, {"_id": 1, "id": 1, "label": 1, "icon": 1}).to_list(None)
    fixed = 0
    for d in docs:
        if not d.get("icon"):
            await db.bot_quick_replies.update_one({"_id": d["_id"]}, {"$set": {"icon": _v305_qr_icon(d)}})
            fixed += 1
    return {"status": "ok", "fixed": fixed, "total_checked": len(docs)}


@api_router.get("/bot/quick-replies/all")
async def v197b_get_quick_replies_all(request: Request):
    """V197b: Liste complète (actifs + inactifs) — réservé au coach pour l'éditeur."""
    user_email = request.headers.get("X-User-Email", "").lower().strip()
    if not user_email:
        raise HTTPException(status_code=401, detail="Email requis")
    await _v197b_seed_quick_replies_if_empty()
    replies = await db.bot_quick_replies.find({}, {"_id": 0}).sort("order", 1).to_list(None)
    return replies


@api_router.put("/bot/quick-replies/{reply_id}")
async def v197b_update_quick_reply(reply_id: str, request: Request):
    """V197b: Modifier un quick reply (coach uniquement)."""
    user_email = request.headers.get("X-User-Email", "").lower().strip()
    if not user_email:
        raise HTTPException(status_code=401, detail="Email requis")

    body = await request.json()
    allowed = {"label", "emoji", "response", "order", "active"}
    update_data = {k: v for k, v in body.items() if k in allowed}
    if not update_data:
        raise HTTPException(status_code=400, detail="Aucun champ à mettre à jour")

    update_data["updated_at"] = datetime.utcnow().isoformat()
    update_data["updated_by"] = user_email

    result = await db.bot_quick_replies.update_one(
        {"id": reply_id}, {"$set": update_data}
    )
    if result.matched_count == 0:
        return JSONResponse({"error": "Not found"}, status_code=404)
    return {"success": True}


@api_router.post("/bot/quick-replies/seed")
async def v197b_seed_quick_replies():
    """V197b: Seed manuel (idempotent)."""
    inserted = await _v197b_seed_quick_replies_if_empty()
    count = await db.bot_quick_replies.count_documents({})
    return {"inserted": inserted, "total": count}


# V199: Générateur de factures PDF — utilise reportlab (pure Python, OK Vercel)
@api_router.post("/invoices/generate")
async def v199_generate_invoice(request: Request):
    """V199: Génère un PDF de facture Afroboost et le retourne en streaming.
    Sauvegarde aussi un enregistrement dans la collection `invoices`."""
    try:
        from reportlab.lib.pagesizes import A4
        from reportlab.lib.units import cm
        from reportlab.lib.colors import HexColor
        from reportlab.platypus import SimpleDocTemplate, Table, TableStyle, Paragraph, Spacer, Image
        from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
        from reportlab.lib.enums import TA_CENTER
    except ImportError:
        return JSONResponse({"error": "reportlab non installé"}, status_code=500)

    from io import BytesIO
    from starlette.responses import StreamingResponse

    body = await request.json()

    # V259b: couleur d'accent de la facture, alignee sur la marque du coach.
    # Scopee par coach comme les emails (V259) : le concept est multi-tenant,
    # une facture de partenaire ne doit pas sortir aux couleurs d'un autre.
    #
    # GARDE : `primaryColor` n'est pas valide en base — l'input du dashboard est
    # un selecteur de couleur, mais un PUT direct pourrait y poser n'importe
    # quoi, et `HexColor()` leve sur une valeur illisible. Une couleur fautive
    # ne doit jamais empecher une facture d'etre emise : on retombe alors sur le
    # rose historique, exactement le rendu d'avant la V259b.
    _inv_email = request.headers.get("X-User-Email", "").lower().strip() or _email_from_jwt(request)
    invoice_color = (await _v259_primary_color(_inv_email) or "").strip()
    if not (len(invoice_color) == 7
            and invoice_color[0] == "#"
            and all(c in "0123456789abcdefABCDEF" for c in invoice_color[1:])):
        invoice_color = _V259_DEFAULT_COLOR

    invoice_number = body.get("invoice_number") or f"AF-{datetime.utcnow().strftime('%Y%m%d%H%M%S')}"
    invoice_date = body.get("invoice_date") or datetime.utcnow().strftime("%d.%m.%Y")

    emitter = body.get("emitter") or {}
    emitter_name = emitter.get("name", "Association Afroboosteur")
    emitter_address = emitter.get("address", "Rue de Maillefer 39")
    emitter_city = emitter.get("city", "2000 Neuchâtel")
    emitter_iban = emitter.get("iban", "CH77 0900 0000 1688 2939 4")
    emitter_contact = emitter.get("contact", "Bassi Henri")
    emitter_ide = emitter.get("ide", "CHE-407.097.646")

    recipient = body.get("recipient") or {}
    recipient_name = recipient.get("name", "")
    recipient_address = recipient.get("address", "")
    recipient_city = recipient.get("city", "")

    items = body.get("items") or []
    notes = body.get("notes") or "Paiement à l'avance par virement bancaire.\nUtilisation des séances dès réception du paiement."

    buffer = BytesIO()
    doc = SimpleDocTemplate(
        buffer, pagesize=A4,
        topMargin=2 * cm, bottomMargin=2 * cm,
        leftMargin=2 * cm, rightMargin=2 * cm,
    )

    elements = []
    styles = getSampleStyleSheet()
    title_style = ParagraphStyle('AfroTitle', parent=styles['Heading1'], textColor=HexColor(invoice_color), fontSize=22, spaceAfter=20)  # V259b
    subtitle_style = ParagraphStyle('AfroSubtitle', parent=styles['Heading2'], textColor=HexColor('#333333'), fontSize=14, spaceAfter=10)
    normal_style = ParagraphStyle('AfroNormal', parent=styles['Normal'], fontSize=10, leading=14)
    small_style = ParagraphStyle('AfroSmall', parent=styles['Normal'], fontSize=9, textColor=HexColor('#666666'), leading=12)

    # Logo (cherché dans plusieurs emplacements)
    logo_candidates = [
        os.path.join(os.path.dirname(__file__), 'static', 'logo192.png'),
        os.path.join(os.path.dirname(__file__), '..', 'frontend', 'public', 'logo192.png'),
    ]
    logo_path = None
    for p in logo_candidates:
        if os.path.exists(p):
            logo_path = p
            break

    if logo_path:
        try:
            logo = Image(logo_path, width=50, height=50)
            header_data = [[logo, Paragraph("FACTURE", title_style)]]
            header_table = Table(header_data, colWidths=[60, 400])
            header_table.setStyle(TableStyle([
                ('VALIGN', (0, 0), (-1, -1), 'MIDDLE'),
                ('ALIGN', (0, 0), (0, 0), 'LEFT'),
            ]))
            elements.append(header_table)
        except Exception:
            elements.append(Paragraph("FACTURE", title_style))
    else:
        elements.append(Paragraph("FACTURE", title_style))

    elements.append(Spacer(1, 10))
    elements.append(Paragraph(f"<b>N° :</b> {invoice_number} &nbsp;&nbsp;&nbsp; <b>Date :</b> {invoice_date}", normal_style))
    elements.append(Spacer(1, 20))

    emitter_text = (
        f"<b>Émetteur :</b><br/>"
        f"{emitter_name}<br/>"
        f"{emitter_address}<br/>"
        f"{emitter_city}<br/>"
        f"N° IDE : {emitter_ide}<br/>"
        f"IBAN : {emitter_iban}<br/>"
        f"Contact : {emitter_contact}"
    )
    recipient_text = (
        f"<b>Destinataire :</b><br/>"
        f"{recipient_name or '—'}<br/>"
        f"{recipient_address or ''}<br/>"
        f"{recipient_city or ''}"
    )
    address_table = Table(
        [[Paragraph(emitter_text, normal_style), Paragraph(recipient_text, normal_style)]],
        colWidths=[250, 250],
    )
    address_table.setStyle(TableStyle([
        ('VALIGN', (0, 0), (-1, -1), 'TOP'),
        ('TOPPADDING', (0, 0), (-1, -1), 8),
        ('BOTTOMPADDING', (0, 0), (-1, -1), 8),
    ]))
    elements.append(address_table)
    elements.append(Spacer(1, 25))

    elements.append(Paragraph("Détails de la prestation :", subtitle_style))

    table_data = [["Description", "Quantité", "Prix Unitaire", "Total"]]
    grand_total = 0.0
    for item in items:
        try:
            qty = float(item.get("quantity") or 0)
            unit_price = float(item.get("unit_price") or 0)
            total_val = float(item.get("total") or (qty * unit_price))
        except (TypeError, ValueError):
            qty, unit_price, total_val = 0.0, 0.0, 0.0
        grand_total += total_val
        table_data.append([
            item.get("description", ""),
            f"{qty:g}",
            f"{unit_price:.2f} CHF",
            f"{total_val:.2f} CHF",
        ])
    table_data.append(["", "", "Total à payer :", f"{grand_total:.2f} CHF"])

    table = Table(table_data, colWidths=[220, 60, 100, 100])
    table.setStyle(TableStyle([
        ('BACKGROUND', (0, 0), (-1, 0), HexColor(invoice_color)),  # V259b
        ('TEXTCOLOR', (0, 0), (-1, 0), HexColor('#FFFFFF')),
        ('FONTNAME', (0, 0), (-1, 0), 'Helvetica-Bold'),
        ('FONTSIZE', (0, 0), (-1, 0), 10),
        ('ALIGN', (1, 0), (-1, -1), 'CENTER'),
        ('ALIGN', (0, 0), (0, -1), 'LEFT'),
        ('FONTSIZE', (0, 1), (-1, -1), 9),
        ('ROWBACKGROUNDS', (0, 1), (-1, -2), [HexColor('#FFFFFF'), HexColor('#F8F8F8')]),
        ('GRID', (0, 0), (-1, -2), 0.5, HexColor('#DDDDDD')),
        ('BACKGROUND', (0, -1), (-1, -1), HexColor('#1a1a2e')),
        ('TEXTCOLOR', (0, -1), (-1, -1), HexColor('#FFFFFF')),
        ('FONTNAME', (0, -1), (-1, -1), 'Helvetica-Bold'),
        ('FONTSIZE', (0, -1), (-1, -1), 11),
        ('TOPPADDING', (0, 0), (-1, -1), 8),
        ('BOTTOMPADDING', (0, 0), (-1, -1), 8),
    ]))
    elements.append(table)
    elements.append(Spacer(1, 25))

    if notes:
        elements.append(Paragraph("<b>Modalités de paiement :</b>", subtitle_style))
        for line in notes.split("\n"):
            line = line.strip()
            if line:
                elements.append(Paragraph(f"• {line}", small_style))
        elements.append(Spacer(1, 15))

    elements.append(Spacer(1, 30))
    footer_style = ParagraphStyle('Footer', parent=styles['Normal'], fontSize=8, textColor=HexColor('#999999'), alignment=TA_CENTER)
    elements.append(Paragraph(
        f"{emitter_name} — {emitter_address}, {emitter_city} — IBAN : {emitter_iban}",
        footer_style,
    ))

    doc.build(elements)
    buffer.seek(0)

    # Sauvegarde dans MongoDB (best effort)
    try:
        await db.invoices.insert_one({
            "invoice_number": invoice_number,
            "date": invoice_date,
            "emitter": emitter,
            "recipient": recipient,
            "items": items,
            "total": grand_total,
            "notes": notes,
            "created_at": datetime.utcnow().isoformat(),
        })
    except Exception as e:
        logger.warning(f"[V199] insert invoice failed: {e}")

    return StreamingResponse(
        buffer,
        media_type="application/pdf",
        headers={
            "Content-Disposition": f'attachment; filename="facture_{invoice_number}.pdf"'
        },
    )


